import camelcase from "camelcase";

import {
  type ResponsiveSpacing,
  type SpacingAxis,
  type SpacingType,
} from "./types";

export const generateClassNames = (
  axis: SpacingAxis,
  values: ResponsiveSpacing | undefined,
  type: SpacingType,
): string[] =>
  values
    ? Object.entries(values).map(([breakpoint, size]) => {
        const modifier = camelcase(`${type}-${axis}-${size}-${breakpoint}`);

        return `arc-Spacing--${modifier}`;
      })
    : [];
