import React from "react";

import { type NavigationHeaderNavigationItem } from "../../types/nav-item";

import { NavigationHeaderNavLink } from "../NavigationHeaderNavLink";
import { NavigationHeaderDropdown } from "../NavigationHeaderDropdown";
import { NavigationHeaderMegaMenu } from "../NavigationHeaderMegaMenu";
import { NavigationHeaderCategoryLinks } from "../NavigationHeaderCategoryLinks";
import { NavigationHeaderLevelTwoLinks } from "../NavigationHeaderLevelTwoLinks";

export const NavigationHeaderNavItem = ({
  navItem,
}: NavigationHeaderNavItemProps) => (
  <>
    {navItem.type === "link" && (
      <NavigationHeaderNavLink {...navItem} borderRadiusSize="m" />
    )}

    {navItem.type === "levelTwo" && (
      <NavigationHeaderDropdown
        trigger={navItem.text}
        onClick={navItem.onClick}
        ariaLabel={navItem.ariaLabel}
      >
        <NavigationHeaderLevelTwoLinks links={navItem.items} />
      </NavigationHeaderDropdown>
    )}

    {navItem.type === "categoryLinks" && (
      <NavigationHeaderCategoryLinks
        onOpenChange={navItem.onOpenChange}
        ariaLabel={navItem.ariaLabel}
        onClick={navItem.onClick}
        text={navItem.text}
        panelHeading={navItem.panelHeading}
        items={navItem.items}
      />
    )}

    {navItem.type === "megamenu" && (
      <NavigationHeaderMegaMenu
        onOpenChange={navItem.onOpenChange}
        panelHeading={navItem.panelHeading}
        ariaLabel={navItem.ariaLabel}
        onClick={navItem.onClick}
        text={navItem.text}
        tabs={navItem.tabs}
        featureCards={navItem.featureCards}
      />
    )}
  </>
);

export interface NavigationHeaderNavItemProps {
  /**
   * Navigation item configuration.
   */
  navItem: NavigationHeaderNavigationItem;
}
