import React, { useId, useRef, useState } from "react";

import { type NavigationHeaderCategoryMenuNavItem } from "../../../../types/nav-item";

import { SideMenuLink } from "../SideMenuLink";
import { SideMenuSubMenu } from "../SideMenuSubMenu";
import { NavigationHeaderCollapsingNavList } from "../../../NavigationHeaderCollapsingNavList";

export const SideMenuCategoryLinksItem = ({
  items,
  text,
  backButtonLabel,
  backButtonAriaLabel,
  panelHeading,
}: SideMenuCategoryLinksItemProps) => {
  const id = useId();

  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);

  const onItemClick = () => {
    setIsDrawerOpen(true);
  };

  const onBackClick = () => {
    setIsDrawerOpen(false);
  };

  const onCloseAutoFocus = () => {
    triggerRef.current?.focus();
  };

  return (
    <>
      <SideMenuLink
        aria-haspopup="dialog"
        aria-expanded={isDrawerOpen}
        ref={triggerRef}
        onClick={onItemClick}
        text={text}
      />

      <SideMenuSubMenu
        isOpen={isDrawerOpen}
        heading={panelHeading.heading}
        supportingText={panelHeading.supportingText}
        onBackClick={onBackClick}
        onCloseAutoFocus={onCloseAutoFocus}
        backButtonLabel={backButtonLabel}
        backButtonAriaLabel={backButtonAriaLabel}
      >
        <div className="arc-SideMenuCategoryLinksItem-navItems">
          {items.map((navItem, navItemIndex) => (
            <NavigationHeaderCollapsingNavList
              {...navItem}
              isBottomSpacing
              key={`${id}-side-menu-category-link-item-${navItemIndex}`}
            />
          ))}
        </div>
      </SideMenuSubMenu>
    </>
  );
};

type SideMenuCategoryLinksItemProps = NavigationHeaderCategoryMenuNavItem;
