import React, { type ReactNode, useContext } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { SurfaceContext } from "../Surface";

import { SplitButtonContext } from "./SplitButtonContext";

/** Use `SplitButton` to allow a primary action next to a drop down menu. See the examples section for full example using the `Menu` component. To compose the `SplitButton` correctly, use the `SplitButtonMenu` before `SplitButtonPrimary`. This is for accessible keyboard navigation. */
export const SplitButton = ({
  children,
  isFullWidth = false,
  buttonStyle = "primary",
  size = "m",
  isLoading = false,
  ...props
}: SplitButtonProps) => {
  const { surface } = useContext(SurfaceContext);

  const contextValue = {
    isFullWidth,
    buttonStyle,
    size,
    isLoading,
    surface,
  };

  return (
    <SplitButtonContext.Provider value={contextValue}>
      <div
        role="group"
        className={classNames(
          "arc-SplitButton",
          `arc-SplitButton--${size}`,
          `arc-SplitButton--${buttonStyle}`,
          {
            "arc-SplitButton--isLoading": isLoading,
            "arc-SplitButton--isFullWidth": isFullWidth,
            "arc-SplitButton--onDarkSurface": surface === "dark",
          },
        )}
        {...filterAttrs(props)}
      >
        {children}
      </div>
    </SplitButtonContext.Provider>
  );
};

export interface SplitButtonProps {
  /**
   * Whether the button is in a loading state
   */
  isLoading?: boolean;
  /**
   * The size of the button
   */
  size?: "s" | "m" | "l";
  /**
   * The visual style variant of the `SplitButton`.
   */
  buttonStyle?: "primary" | "secondary" | "tertiary" | "compact";
  /**
   * Place `SplitButtonPrimary` and `SplitButtonMenu` within `SplitButton`.
   */
  children: ReactNode;
  /**
   * Set the `SplitButtonPrimary` to fill the width of the `SplitButton`'s container.
   */
  isFullWidth?: boolean;
}
