import React from "react";

import classNames from "classnames";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";
import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { type AlignmentValue } from "../../Grid.types";

export const GridRow = ({
  direction = "row",
  align = "normal",
  justify = "normal",
  children,
  ...props
}: GridRowProps) => (
  <div
    className={classNames(
      "arc-Grid-row",
      `${suffixModifier("arc-Grid-row--direction", direction)}`,
      `${suffixModifier("arc-Grid-row--justify", justify)}`,
      `${suffixModifier("arc-Grid-row--align", align)}`,
    )}
    {...filterAttrs(props)}
  >
    {children}
  </div>
);

export interface GridRowProps {
  /**
   * Alignment of items in the row
   */
  align?: AlignmentValue;
  /**
   * Direction of the row
   */
  direction?: "column" | "row" | "column-reverse" | "row-reverse";
  /**
   * Justification of items in the row
   */
  justify?: "start" | "center" | "end" | "between" | "around" | "normal";
  /**
   * Content to display in the GridRow
   */
  children: React.ReactNode;
}
