import React, { type ReactNode } from "react";

import classNames from "classnames";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";
import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { type anchorPoints } from "../../../helpers";

export const PosterVideo = ({
  anchor = "C",
  autoPlay = true,
  children,
  loop = true,
  ...props
}: PosterVideoProps) => {
  return (
    <video
      className={classNames({
        "arc-PosterVideo": true,
        [suffixModifier("arc-PosterVideo--anchor", anchor)]: anchor,
      })}
      autoPlay={autoPlay}
      muted
      loop={loop}
      {...filterAttrs(props)}
    >
      {children}
    </video>
  );
};

export interface PosterVideoProps {
  /**
   * Anchor point for the PosterVideo,
   */
  anchor?: (typeof anchorPoints)[number];

  /**
   * Should the PosterVideo autoplay?
   */
  autoPlay?: boolean;

  /**
   * HTML video sources for the PosterVideo. [See MDN](https://developer.mozilla.org/en-US/docs/Web/HTML/Element/video).
   */
  children: ReactNode;

  /**
   * Should the PosterVideo loop?
   */
  loop?: boolean;
}
