/**
 * Optionally define ariaDescribedBy if errorMessage or helper exist.
 */
export const useAriaDescribedby = ({
  id,
  idError = `${id}-error`,
  idHelper = `${id}-helper`,
  idDisclosure = `${id}-disclosure`,
  errorMessage,
  helper,
  disclosureText,
}: {
  id?: string;
  idError?: string;
  idDisclosure?: string;
  idHelper?: string;
  errorMessage?: any;
  helper?: any;
  disclosureText?: string;
}) => {
  if (!id) {
    return {
      ariaDescribedby: undefined,
      idHelper: undefined,
      idError: undefined,
      idDisclosure: undefined,
    };
  }

  const ariaDescribedbyArr = [];

  if (errorMessage) {
    ariaDescribedbyArr.push(idError);
  }

  if (helper) {
    ariaDescribedbyArr.push(idHelper);
  }

  if (disclosureText) {
    ariaDescribedbyArr.push(idDisclosure);
  }

  const ariaDescribedby =
    ariaDescribedbyArr.length > 0 ? ariaDescribedbyArr.join(" ") : undefined;

  return { ariaDescribedby, idError, idHelper, idDisclosure };
};
