import React, {
  type HTMLAttributes,
  type Ref,
  useCallback,
  useContext,
} from "react";

import classNames from "classnames";

import isLastDayOfMonth from "date-fns/isLastDayOfMonth";
import isFirstDayOfMonth from "date-fns/isFirstDayOfMonth";
import isBefore from "date-fns/isBefore";
import isAfter from "date-fns/isAfter";
import getDate from "date-fns/getDate";
import isEqual from "date-fns/isEqual";
import format from "date-fns/format";

import { Text } from "../../../Text";

import { containsDate, isDay, isDisabledDate } from "../../helpers";
import { WeekDays } from "../../types";
import { ArcCalendarContext } from "../../Calendar.provider";
import { VisuallyHidden } from "../../../VisuallyHidden";

export const CalendarDayNumber = ({
  ref: autoFocusRef,
  date,
  shouldRender,
  isFocusWithinDayGrid,
}: CalendarDayNumberProps) => {
  const context = useContext(ArcCalendarContext);
  const isFocusDate = context && isEqual(date, context.focusDate);

  const tableCellRef = useCallback(
    (el: HTMLTableCellElement | null) => {
      if (el && isFocusDate && isFocusWithinDayGrid) {
        el.focus();
      }
    },
    [isFocusDate, isFocusWithinDayGrid],
  );

  if (!context) {
    return null;
  }

  const handleRefs = (el: HTMLTableCellElement) => {
    tableCellRef(el);

    if (autoFocusRef && typeof autoFocusRef === "function") {
      autoFocusRef(el);
    }
  };

  const {
    disabledDates,
    selectedDate,
    selectionType,
    selectedRange,
    highlightedRange,
    todayDate,
    onDayNumberClick,
    onDayNumberHover,
    minDate,
    maxDate,
  } = context;

  const highlightedRangeStart = highlightedRange[0];
  const highlightedRangeEnd = highlightedRange[1];

  const isSelectedDate =
    selectionType === "single"
      ? isEqual(date, selectedDate)
      : selectedRange.length &&
        containsDate(
          selectedRange.filter((date) => Boolean(date)),
          date,
        );

  const isTodayDate = isEqual(date, todayDate);

  const dateIsWithinHighlightedRange =
    selectionType === "range" &&
    highlightedRange.length === 2 &&
    !isAfter(date, highlightedRangeEnd) &&
    !isBefore(date, highlightedRangeStart);

  const isRoundedLeft =
    selectionType === "range" &&
    (isDay(date, WeekDays.MONDAY) ||
      isFirstDayOfMonth(date) ||
      isEqual(date, highlightedRangeStart));

  const isRoundedRight =
    selectionType === "range" &&
    (isDay(date, WeekDays.SUNDAY) ||
      isLastDayOfMonth(date) ||
      isEqual(date, highlightedRangeEnd));

  const conditionalClasses = {
    "arc-CalendarDayNumber--selected": isSelectedDate,
    "arc-CalendarDayNumber--todayDate": isTodayDate,
    "arc-CalendarDayNumber--hightlightedRange": dateIsWithinHighlightedRange,
    "arc-CalendarDayNumber--hightlightedRangeRoundedLeft": isRoundedLeft,
    "arc-CalendarDayNumber--hightlightedRangeRoundedRight": isRoundedRight,
  };

  const isAriaSelected =
    isSelectedDate ||
    (dateIsWithinHighlightedRange && selectedRange.length === 2);

  const tableCellProps: HTMLAttributes<HTMLTableCellElement> = {
    className: classNames("arc-CalendarDayNumber", conditionalClasses),
    tabIndex: isFocusDate && shouldRender ? 0 : -1,
    "aria-current": isTodayDate ? "date" : undefined,
    "aria-selected": isAriaSelected,
    "aria-disabled": isDisabledDate(date, disabledDates, minDate, maxDate),
    onClick: onDayNumberClick(date),
    onMouseEnter: onDayNumberHover(date),
  };

  return (
    <td
      ref={handleRefs}
      data-date={date.getTime()}
      {...(shouldRender ? tableCellProps : {})}
      role="gridcell"
    >
      {shouldRender && (
        <>
          <VisuallyHidden>{format(date, "MMMM do, yyyy")}</VisuallyHidden>

          <div className="arc-CalendarDayNumber-buttonOuter">
            <div className="arc-CalendarDayNumber-buttonInner">
              <Text size="s">
                <span aria-hidden>{getDate(date)}</span>
              </Text>
            </div>
          </div>
        </>
      )}
    </td>
  );
};

interface CalendarDayNumberProps {
  /**
   * Ref to the table cell element
   */
  ref?: Ref<HTMLTableCellElement>;
  /**
   * Whether the day number should be rendered
   */
  shouldRender: boolean;
  /**
   * Whether focus is within the day grid
   */
  isFocusWithinDayGrid: boolean;
  /**
   * The date to display
   */
  date: Date;
}
