import React, { memo, useId, useRef } from "react";

import classNames from "classnames";

import { useUniqueString } from "../../../../hooks";

import { ArcBreakpoints } from "../../../../helpers/arc-breakpoints";

import { NavigationHeaderNavItem } from "../NavigationHeaderNavItem";

import {
  type NavigationHeaderExtraNavigationItem,
  type NavigationHeaderNavigationItem,
} from "../../types/nav-item";

import { type NavBarBackground } from "../../types/navbar-background";
import { type MediaQuery } from "../../types/media-query";

import { MeatBall } from "../../svg/MeatBall";

import {
  type NavigationHeaderStyleElementCSS,
  NavigationHeaderStyleElement,
} from "../NavigationHeaderStyleElement";

import {
  NavigationHeaderSideMenu,
  SideMenuNavItem,
  SideMenuNavList,
} from "../NavigationHeaderSideMenu";

export const NavigationHeaderNavList = memo(
  ({
    navItems,
    background,
    extraMenuTooltip,
    extraNavItems = [],
    extraMenuAriaLabel,
  }: NavigationHeaderNavListProps) => {
    const id = useId();

    const navListItemClassName = useUniqueString(
      "arc-NavigationHeaderNavList-item",
    );

    const sideMenuClassName = useUniqueString(
      "arc-NavigationHeaderNavList-sideMenu",
    );

    const sideMenuNavItemClassName = useUniqueString(
      "arc-NavigationHeaderNavList-sideMenuItem",
    );

    const ref = useRef<HTMLUListElement>(null);

    const largestElementBreakpoint = (
      navItems: Array<NavigationHeaderNavigationItem>,
    ): number => {
      return Math.max(
        ...navItems.map((navItem) => {
          if (navItem.visibleFrom) {
            return typeof navItem.visibleFrom === "number"
              ? navItem.visibleFrom
              : ArcBreakpoints[navItem.visibleFrom];
          }

          return 0;
        }),
      );
    };

    const extraMenuBreakpoint: MediaQuery = extraNavItems.length
      ? { type: "max", breakpoint: 0 }
      : { type: "min", breakpoint: largestElementBreakpoint(navItems) };

    return (
      <div className="arc-NavigationHeaderNavList-container">
        {/* 
          This is to ensure there are no cumulative layout shifts on SSR because of the dynamic media queries.
          matchMedia can cause flickering when it returns a different value than the default state the server used. 
          This is plain old css so the styles will appear correctly on first paint.
          The items these styles are applied to will still appear in the server rendered HTML for SEO purposes.
          */}
        <NavigationHeaderStyleElement
          css={[
            {
              className: sideMenuClassName,
              mediaQuery: extraMenuBreakpoint,
              declarations: {
                display: "none",
              },
            },
            {
              className: navListItemClassName,
              declarations: {
                display: "none",
              },
            },
            ...navItems.reduce<NavigationHeaderStyleElementCSS[]>(
              (acc, navItem, i) => {
                return [
                  ...acc,
                  {
                    mediaQuery: {
                      type: "min",
                      breakpoint: navItem.visibleFrom || 0,
                    },
                    className: `${sideMenuNavItemClassName}-${i}`,
                    declarations: {
                      display: "none",
                    },
                  },
                  {
                    mediaQuery: {
                      type: "min",
                      breakpoint: navItem.visibleFrom || 0,
                    },
                    className: `${navListItemClassName}-${i}`,
                    declarations: {
                      display: "block",
                    },
                  },
                ];
              },
              [],
            ),
          ]}
        />

        <ul ref={ref} className="arc-NavigationHeaderNavList">
          {navItems.map((navItem, i) => (
            <li
              key={`${id}-navigation-header-navitem-${i}`}
              className={classNames(
                navListItemClassName,
                `${navListItemClassName}-${i}`,
              )}
            >
              <div
                className={classNames({
                  "arc-NavigationHeaderNavList-itemContent--separator":
                    navItem.isSeparator,
                })}
              >
                <NavigationHeaderNavItem navItem={navItem} />
              </div>
            </li>
          ))}
        </ul>

        <div className={sideMenuClassName}>
          <NavigationHeaderSideMenu
            showLogo={false}
            menuPosition="left"
            pathway="match"
            triggerAriaLabel={extraMenuAriaLabel}
            trigger={<MeatBall />}
            tooltip={extraMenuTooltip}
            background={background}
          >
            <SideMenuNavList>
              {extraNavItems?.map((navItem, navItemIndex) => (
                <React.Fragment key={`${id}-side-nav-item-${navItemIndex}`}>
                  <li>
                    <SideMenuNavItem navItem={navItem} />
                  </li>
                </React.Fragment>
              ))}

              {navItems?.map((navItem, navItemIndex) => (
                <React.Fragment
                  key={`${id}-side-main-nav-item-${navItemIndex}`}
                >
                  <li
                    className={classNames(
                      sideMenuNavItemClassName,
                      `${sideMenuNavItemClassName}-${navItemIndex}`,
                    )}
                  >
                    <SideMenuNavItem navItem={navItem} />
                  </li>
                </React.Fragment>
              ))}
            </SideMenuNavList>
          </NavigationHeaderSideMenu>
        </div>
      </div>
    );
  },
);

export interface NavigationHeaderNavListProps {
  /**
   * Background color of the navigation bar.
   */
  background: NavBarBackground;

  /**
   * Nav items for `NavigationHeader`.
   */
  navItems: Array<NavigationHeaderNavigationItem>;
  /**
   * extra menu items for `NavigationHeader`.
   */
  extraNavItems?: Array<NavigationHeaderExtraNavigationItem>;
  /**
   * extra menu tooltip text.
   */
  extraMenuTooltip?: string;
  /**
   * extra menu trigger aria label.
   */
  extraMenuAriaLabel?: string;
}
