import React, {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  useContext,
  type KeyboardEvent,
  type ReactNode,
} from "react";

import classNames from "classnames";
import EmblaClassNames from "embla-carousel-class-names";
import useEmblaCarousel from "embla-carousel-react";
import Autoplay from "embla-carousel-autoplay";
import { type EmblaCarouselType } from "embla-carousel";

import { useMediaQuery } from "../../hooks";

import { SurfaceContext } from "../Surface";

import { ThemeIcon } from "../ThemeIcon";

import { SkipLink, SkipLinkItem } from "../SkipLink";

import {
  L_BREAKPOINT,
  M_BREAKPOINT,
  S_BREAKPOINT,
  XL_BREAKPOINT,
  XS_BREAKPOINT,
} from "./constants/breakpoints";

import { getOptions } from "./helpers/get-options";
import { getSlideWidth } from "./helpers/get-slide-width";

import { CarouselDotButton } from "./components/CarouselDotButton";

import { KeyNames } from "./types/keynames";
import { type Responsive } from "./types/responsive";

export const Carousel = ({
  children,
  responsive,
  itemsToScroll = 1,
  itemsPerSlide = 1,
  controlsPosition = "bottom",
  behavior = "default",
  overflow = "hidden",
  withGutter = true,
  loop = false,
  isPartialVisible = false,
  autoplay,
  isPlaying,
  fade,
}: CarouselProps) => {
  const id = useId();

  const { surface } = useContext(SurfaceContext);

  const autoPlayOptions = autoplay
    ? {
        playOnInit: true,
        delay: 3000,
        stopOnInteraction: true,
        stopOnMouseEnter: false,
        stopOnFocusIn: true,
        stopOnLastSnap: false,
        ...autoplay,
      }
    : undefined;

  const [emblaRef, emblaApi] = useEmblaCarousel(
    {
      ...getOptions(itemsToScroll, loop, responsive),
      ...(fade ? { inViewThreshold: 0.74 } : {}),
    },
    [
      ...(autoPlayOptions ? [Autoplay(autoPlayOptions)] : []),
      ...(fade
        ? [
            EmblaClassNames({
              inView: "arc-Carousel-slide--isInView",
            }),
          ]
        : []),
    ],
  );

  useEffect(() => {
    if (!emblaApi || !autoplay) return;

    const autoplayPlugin = emblaApi?.plugins()?.autoplay;

    if (isPlaying) {
      autoplayPlugin.play();
    }
    if (isPlaying == false) {
      autoplayPlugin.stop();
    }
  }, [emblaApi, isPlaying, autoplay]);

  const [dotButtonFocusIndex, setCarouselDotButtonFocusIndex] = useState<
    number | undefined
  >();

  const navRef = useRef<HTMLDivElement | null>(null);
  const prevButtonRef = useRef<HTMLButtonElement | null>(null);

  const [visibleSlideIndex, setVisibleSlideIndex] = useState(0);
  const [prevButtonEnabled, setPrevButtonEnabled] = useState(true);
  const [nextButtonEnabled, setNextButtonEnabled] = useState(true);

  const isMinWidthArcBreakpointXs = useMediaQuery(XS_BREAKPOINT);
  const isMinWidthArcBreakpointS = useMediaQuery(S_BREAKPOINT);
  const isMinWidthArcBreakpointM = useMediaQuery(M_BREAKPOINT);
  const isMinWidthArcBreakpointL = useMediaQuery(L_BREAKPOINT);
  const isMinWidthArcBreakpointXl = useMediaQuery(XL_BREAKPOINT);

  const slideWidth = getSlideWidth({
    screenSizes: {
      xl: isMinWidthArcBreakpointXl,
      l: isMinWidthArcBreakpointL,
      m: isMinWidthArcBreakpointM,
      s: isMinWidthArcBreakpointS,
      xs: isMinWidthArcBreakpointXs,
    },
    itemsPerSlide,
    isPartialVisible,
    responsive,
    children,
  });

  const scrollSnaps = Array.from({
    length: emblaApi?.scrollSnapList().length || 0,
  }).map((_, i) => i);

  const scrollPrev = useCallback(() => emblaApi?.scrollPrev(), [emblaApi]);
  const scrollNext = useCallback(() => emblaApi?.scrollNext(), [emblaApi]);

  const onSelect = useCallback((emblaApi: EmblaCarouselType) => {
    setVisibleSlideIndex(emblaApi.selectedScrollSnap());
    setPrevButtonEnabled(emblaApi.canScrollPrev());
    setNextButtonEnabled(emblaApi.canScrollNext());
  }, []);

  const onCarouselDotButtonClick = useCallback(
    (index: number) => {
      if (!emblaApi) return;
      emblaApi.scrollTo(index);
    },
    [emblaApi],
  );

  const onSlideKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (e.key === KeyNames.Escape) {
      prevButtonEnabled
        ? prevButtonRef.current?.focus()
        : setCarouselDotButtonFocusIndex(0);
    }
  };

  const onCarouselDotButtonKeyDown =
    (index: number) => (e: KeyboardEvent<HTMLButtonElement>) => {
      if (e.key === KeyNames.ArrowLeft) {
        setCarouselDotButtonFocusIndex(
          index === 0 ? scrollSnaps.length - 1 : index - 1,
        );
      }

      if (e.key === KeyNames.ArrowRight) {
        setCarouselDotButtonFocusIndex(
          index + 1 === scrollSnaps.length ? 0 : index + 1,
        );
      }
    };

  useEffect(() => {
    if (!emblaApi) return;

    onSelect(emblaApi);

    emblaApi.on("reInit", onSelect).on("select", onSelect);
  }, [emblaApi, onSelect]);

  useEffect(() => {
    if (!emblaApi || behavior === "adaptive") return;

    emblaApi.scrollTo(0);
  }, [
    emblaApi,
    isMinWidthArcBreakpointXs,
    isMinWidthArcBreakpointS,
    isMinWidthArcBreakpointM,
    isMinWidthArcBreakpointL,
    isMinWidthArcBreakpointXl,
    behavior,
  ]);

  const handleSkipLinkClick = (e: React.MouseEvent<HTMLAnchorElement>) => {
    e.preventDefault();
    const target = prevButtonEnabled
      ? navRef.current?.querySelector<HTMLElement>(
          ".arc-Carousel-navButton:not(.arc-Carousel-navButton--hidden)",
        )
      : navRef.current?.querySelector<HTMLElement>(
          ".arc-Carousel-dot--selected",
        );

    target?.focus();
  };

  return (
    <div
      className={classNames("arc-Carousel", {
        "arc-Carousel--relative": controlsPosition === "middle",
        "arc-Carousel--onDarkSurface": surface === "dark",
      })}
    >
      {(prevButtonEnabled || nextButtonEnabled) && (
        <SkipLink>
          <SkipLinkItem
            label="Skip To Carousel Navigation Controls"
            href="#"
            onClick={handleSkipLinkClick}
          />
        </SkipLink>
      )}
      <div
        className={classNames("arc-Carousel-container", {
          "arc-Carousel-container--showOverflow": overflow === "visible",
        })}
      >
        <div
          ref={emblaRef}
          className={classNames("arc-Carousel-viewport", {
            "arc-Carousel-viewport--gutter": withGutter,
          })}
        >
          <div
            className="arc-Carousel-slider"
            role="region"
            aria-roledescription="carousel"
          >
            {React.Children.map(children, (child, i) => (
              <div
                onKeyDown={onSlideKeyDown}
                className={classNames("arc-Carousel-slide", {
                  "arc-Carousel-slide--fade": fade,
                })}
                key={`${id}-option-${i}`}
                role="group"
                aria-roledescription="slide"
                {...(behavior === "default" && {
                  style: {
                    flex: `0 0 ${slideWidth}%`,
                    width: `${slideWidth}%`,
                  },
                })}
              >
                {child}
              </div>
            ))}
          </div>
        </div>
      </div>
      <div
        ref={navRef}
        className={classNames("arc-Carousel-nav", {
          "arc-Carousel-nav--middle": controlsPosition === "middle",
        })}
      >
        <button
          data-testid="previous-button"
          ref={prevButtonRef}
          className={classNames("arc-Carousel-navButton", {
            "arc-Carousel-navButton--hidden": !prevButtonEnabled,
          })}
          onClick={scrollPrev}
          aria-label={`Show slide ${visibleSlideIndex}`}
        >
          <ThemeIcon size={32} icon="carouselLeft" />
        </button>

        <div
          className={classNames("arc-Carousel-dotContainer", {
            "arc-Carousel-dotContainer--hidden":
              !prevButtonEnabled && !nextButtonEnabled,
          })}
          role="tablist"
        >
          {scrollSnaps.map((scrollSnapIndex) => (
            <CarouselDotButton
              key={`${id}-dot-${scrollSnapIndex}`}
              focusIndex={dotButtonFocusIndex}
              scrollSnapIndex={scrollSnapIndex}
              visibleSlideIndex={visibleSlideIndex}
              onKeyDown={onCarouselDotButtonKeyDown}
              onClick={onCarouselDotButtonClick}
            />
          ))}
        </div>
        <button
          data-testid="next-button"
          className={classNames("arc-Carousel-navButton", {
            "arc-Carousel-navButton--hidden": !nextButtonEnabled,
          })}
          onClick={scrollNext}
          aria-label={`Show slide ${
            loop && visibleSlideIndex === scrollSnaps.length - 1
              ? 1
              : visibleSlideIndex + 2
          }`}
        >
          <ThemeIcon size={32} icon="carouselRight" />
        </button>
      </div>
    </div>
  );
};

export type CarouselAutoplayControls = {
  play: () => void;
  pause: () => void;
  isPlaying: () => boolean;
  toggle: () => void;
};

export interface CarouselProps {
  /**
   * Items for the carousel.
   */
  children: ReactNode;

  /**
   * Position of the left and right arrows
   */
  controlsPosition?: "bottom" | "middle";
  /**
   * Adds a gap between the slides.
   */
  withGutter?: boolean;
  /**
   * How many slides to scroll on each navigation.
   */
  itemsToScroll?: number;
  /**
   * How many items to show for each slide.
   */
  itemsPerSlide?: number;
  /**
   * Shows some of the first item in the next slide if true.
   */
  isPartialVisible?: boolean;
  /**
   * Allows the carousel to scroll infinitely.
   */
  loop?: boolean;
  /**
   * Configure the carousel options for different breakpoints.
   */
  responsive?: Responsive;
  /**
   * Autoplay configuration. Pass an empty object to use default options.
   */
  autoplay?: {
    /**
     * Time in milliseconds between auto scrolls.
     */
    delay?: number;
    /**
     * Start autoplay on initialization.
     */
    playOnInit?: boolean;
    /**
     * Stops autoplay on user interaction (click/tap).
     */
    stopOnInteraction?: boolean;
    /**
     * Stops autoplay when mouse enters carousel.
     */
    stopOnMouseEnter?: boolean;
    /**
     * Stops autoplay when carousel receives focus.
     */
    stopOnFocusIn?: boolean;
    /**
     * Stops autoplay when reaching the last slide.
     */
    stopOnLastSnap?: boolean;
  };
  /**
   * Use isPlaying to control the state of autoplay.
   */
  isPlaying?: boolean;
  /**
   * Enable fade transition between slides.
   */
  fade?: boolean;
  /**
   * Carousel behavior mode. "default" uses itemsPerSlide to control visible cards. "adaptive" maintains fixed card widths and shows more cards as screen size increases, ignoring itemsPerSlide and isPartialVisible.
   */
  behavior?: "default" | "adaptive";
  /**
   * Controls the overflow behavior of the carousel container. "hidden" clips content outside the viewport, "visible" allows content to overflow.
   */
  overflow?: "hidden" | "visible";
}
