import React, { useContext, type Ref } from "react";

import classNames from "classnames";
import { Trigger } from "@radix-ui/react-tabs";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { Icon } from "../../../Icon";
import { SurfaceContext } from "../../../Surface";

export const TabsItem = ({
  label,
  value,
  icon,
  iconActive,
  ref,
  onClick,
  onFocus,
  ...props
}: TabsItemProps) => {
  const { surface } = useContext(SurfaceContext);
  return (
    <Trigger
      className={classNames("arc-TabsItem-trigger", {
        "arc-TabsItem-trigger--onDarkSurface": surface === "dark",
        "arc-TabsItem-trigger--hasIcon": icon || iconActive,
      })}
      value={value}
      ref={ref}
      onClick={onClick}
      onFocus={onFocus}
      {...filterAttrs(props)}
    >
      {icon && (
        <div
          className="arc-TabsItem-triggerIcon"
          data-testid="arc-TabsItem-TriggerIcon"
        >
          <Icon icon={icon} />
        </div>
      )}

      {iconActive && (
        <div
          className="arc-TabsItem-triggerIcon arc-TabsItem-triggerIcon--active"
          data-testid="arc-TabsItem-TriggerIconActive"
        >
          <Icon icon={iconActive} />
        </div>
      )}
      <span className="arc-TabsItem-triggerText">{label}</span>
    </Trigger>
  );
};

export interface TabsItemProps {
  /**
   * Ref to the underlying button element.
   */
  ref?: Ref<HTMLButtonElement>;

  /**
   * Label to display on the Tab
   */
  label: string;

  /**
   * Value to link `Tab` to `TabContent`
   */
  value: string;

  /**
   * Determine what icon to display within the Tab.
   */
  icon?: string;

  /**
   * Determine what to display when `Tab` is active
   */
  iconActive?: string;

  /**
   * Click handler
   */
  onClick?: () => void;

  /**
   * Focus handler
   */
  onFocus?: () => void;
}
