import React, { type ReactNode, useContext, useState } from "react";

import classNames from "classnames";

import { SurfaceContext } from "../../../Surface";
import { VisuallyHidden } from "../../../VisuallyHidden";

/** Group `FilterControl` components to add controls to `Filter` component. */
export const FilterControl = ({
  children,
  onClick,
  isSelected = false,
}: FilterControlProps) => {
  const { surface } = useContext(SurfaceContext);
  const [selected, setSelected] = useState(isSelected);

  const onClickHandler = () => {
    onClick && onClick();
    setSelected((previousValue) => !previousValue);
  };

  return (
    <button
      className={classNames("arc-FilterControl", {
        "arc-FilterControl--onDarkSurface": surface === "dark",
        "arc-FilterControl--selected": selected,
      })}
      onClick={onClickHandler}
      tabIndex={0}
      aria-pressed={selected}
    >
      <div className="arc-FilterControl-text">
        <VisuallyHidden>Filter by</VisuallyHidden> {children}
      </div>
    </button>
  );
};

export interface FilterControlProps {
  /**
   * Name of the `<FilterControl />`
   */
  children: ReactNode;

  /**
   * Determine if the `<FilterControl />` is selected
   */
  isSelected?: boolean;

  /**
   * onClick handler
   */
  onClick?: () => void;
}
