import React, { type ReactNode } from "react";

import { Content } from "@radix-ui/react-tabs";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

export const ContentSwitcherContent = ({
  children,
  value,
  hidden = undefined,
  forceMount = true,
  ...props
}: ContentSwitcherContentProps) => {
  return (
    <Content
      className="arc-ContentSwitcherContent"
      value={value}
      tabIndex={-1}
      forceMount={forceMount ? true : undefined}
      hidden={hidden}
      {...filterAttrs(props)}
    >
      <div className="arc-ContentSwitcherContent-wrapper">{children}</div>
    </Content>
  );
};

export interface ContentSwitcherContentProps {
  /**
   * Content to display
   */
  children: ReactNode;

  /**
   * This value links the `ContentSwitcherContent` with `ContentSwitcherTab`
   */
  value: string;

  /**
   * Apply a hidden attribute to `ContentSwitcherContent`. Inactive content is already visually hidden however this can be used to add a semantic hidden attribute.
   */
  hidden?: boolean;

  /**
   * Force the contents of `ContentSwitcherContent` to be mounted and rendered in the DOM.
   */
  forceMount?: boolean;
}
