import React, { type ReactNode } from "react";

import { Title } from "@radix-ui/react-dialog";
import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { Heading, type HeadingProps } from "../../../components/Heading";

import { Rule } from "../../Rule";

export const DrawerHeader = ({
  title,
  isFixed = false,
  isResponsive,
  children,
  isFullBleed = false,
  titleWordWrap = false,
  ...props
}: DrawerHeaderProps) => {
  return (
    <>
      <div
        className={classNames("arc-DrawerHeader", {
          "arc-DrawerHeader--isFixed": isFixed,
          "arc-DrawerHeader--isFullBleed": isFullBleed,
        })}
        {...filterAttrs(props)}
      >
        <div className="arc-DrawerHeader-content">
          {title && !children && (
            <div className="arc-DrawerHeader-titleContainer">
              <Title asChild>
                <Heading
                  isResponsive={isResponsive}
                  size="m"
                  isWordWrap={titleWordWrap}
                >
                  {title}
                </Heading>
              </Title>
            </div>
          )}
          {children && !title && children}
        </div>
        {isFixed && (
          <div className="arc-DrawerHeader-divider">
            <Rule />
          </div>
        )}
      </div>
    </>
  );
};

export interface DrawerHeaderProps extends Pick<HeadingProps, "isResponsive"> {
  /**
   * Content to display within for the DrawerHeader. Can not be used in conjunction with `title`.
   */
  children?: ReactNode;

  /**
   * Title for the DrawerHeader. Can not be used in conjunction with `children`.

   */
  title?: string;

  /**
   * Determine if the `DrawerHeader` is fixed to the top of the `Drawer`
   */
  isFixed?: boolean;

  /**
   * Removes padding within the DrawerHeader
   */
  isFullBleed?: boolean;
  /**
   * Whether long words in title should be wrapped.
   */
  titleWordWrap?: boolean;
}
