import React, { type ReactNode, useContext } from "react";

import classNames from "classnames";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";

import { SemanticButton } from "../../../../../SemanticButton";
import { SurfaceContext } from "../../../../../Surface";
import { ThemeIcon } from "../../../../../ThemeIcon";

export const SideMenuHeader = ({
  children,
  onCloseClick,
}: SideMenuHeaderProps) => {
  const { surface } = useContext(SurfaceContext);

  return (
    <div className="arc-SideMenuHeader">
      <div className="arc-SideMenuHeader-closeButtonContainer">
        <SemanticButton
          aria-label="close"
          onClick={onCloseClick}
          className={classNames(
            "arc-SideMenuHeader-closeButton",
            suffixModifier("arc-SideMenuHeader-closeButton--on", surface),
          )}
        >
          <ThemeIcon size={32} icon="navigationHeaderClose" />
        </SemanticButton>
      </div>

      <div className="arc-SideMenuHeader-logoContainer">
        <div className="arc-SideMenuHeader-logoWrapper">{children}</div>
      </div>
    </div>
  );
};

interface SideMenuHeaderProps {
  /**
   * Content to display in the header.
   */
  children: ReactNode;
  /**
   * Callback when close button is clicked.
   */
  onCloseClick?: () => void;
}
