import React, { type ReactNode } from "react";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

/**
 * Use `VisuallyHidden` to provide text for screen readers that is visually hidden on screen.
 */
export const VisuallyHidden = ({ children, ...props }: VisuallyHiddenProps) => {
  return (
    <span
      data-testid="visually-hidden"
      className="arc-VisuallyHidden"
      {...filterAttrs(props)}
    >
      {children}
    </span>
  );
};

export interface VisuallyHiddenProps {
  /**
   * Content to be Visually Hidden.
   */
  children?: ReactNode;
}
