import React, { type ComponentType, type SVGProps } from "react";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { VisuallyHidden } from "../VisuallyHidden";

import { GooglePlayIcon } from "./icons/GooglePlay";
import { AppStoreIcon } from "./icons/AppStore";

/**
 * Use `AppButton` for a branded button that links users to download an app.
 */
export const AppButton = ({
  type,
  url,
  screenReaderText,
  ...props
}: AppButtonProps) => {
  const logos: Record<AppButtonType, ComponentType<SVGProps<SVGSVGElement>>> = {
    "google-play": GooglePlayIcon,
    "apple-app-store": AppStoreIcon,
  };

  const Logo = logos[type];

  return (
    <a className="arc-AppButton" href={url} {...filterAttrs(props)}>
      <Logo />

      <VisuallyHidden>{screenReaderText}</VisuallyHidden>
    </a>
  );
};

type AppButtonType = "google-play" | "apple-app-store";

export interface AppButtonProps {
  /**
   * The type of app store button to display.
   */
  type: AppButtonType;

  /**
   * Text to be read by screen readers describing the button action.
   */
  screenReaderText: string;

  /**
   * The URL to link to for downloading the app.
   */
  url: string;
}
