import React, {
  type ReactNode,
  type RefObject,
  useId,
  useState,
  useEffect,
  useRef,
} from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { Text } from "../Text";
import { Icon } from "../Icon";
import { ThemeIcon, type ThemeIconNames } from "../ThemeIcon/ThemeIcon";
import { Link, type LinkProps } from "../Link";
import { VisuallyHidden } from "../VisuallyHidden";
import { Surface } from "../Surface";
import { SemanticHeading, type SemanticHeadingLevel } from "../SemanticHeading";

/**
 * Use `Alert` to inform the user of important changes or actions.
 */
export const Alert = ({
  heading,
  headingLevel,
  description,
  links,
  status = "general",
  isDismissable,
  onDismiss,
  onDismissFocusRef,
  icon,
  isMeasured = false,
  autoFocusOnMount = false,

  role = "alert",
  ...props
}: AlertProps) => {
  const headingId = useId();
  const descriptionId = useId();
  const alertRef = useRef<HTMLDivElement>(null);
  const [isDismissed, setIsDismissed] = useState(false);

  useEffect(() => {
    autoFocusOnMount && alertRef.current?.focus();
  }, [autoFocusOnMount]);

  const onDismissHandler = () => {
    setIsDismissed(true);
    onDismiss && onDismiss();
    onDismissFocusRef?.current?.focus();
  };

  const handleLinkClick = (
    e: React.MouseEvent<Element, MouseEvent>,
    link: AlertLinkProps,
  ) => {
    e.preventDefault();
    link.onClick?.(e);
  };

  const statusIcons: Record<
    AlertStatus,
    Extract<
      ThemeIconNames,
      "alertGeneral" | "alertError" | "alertWarning" | "alertSuccess"
    >
  > = {
    general: "alertGeneral",
    error: "alertError",
    warning: "alertWarning",
    success: "alertSuccess",
  };

  if (isDismissed) {
    return null;
  }

  return (
    <Surface background="light-brand-01" isTransparent>
      <div
        className={classNames("arc-Alert", {
          [`arc-Alert--${status}`]: status !== "general",
        })}
        role={role}
        tabIndex={-1}
        aria-labelledby={headingId}
        aria-describedby={descriptionId}
        ref={alertRef}
        {...filterAttrs(props)}
      >
        {isDismissable && (
          <button
            aria-label="dismiss alert"
            className="arc-Alert-dismiss"
            onClick={onDismissHandler}
            tabIndex={0}
          >
            <ThemeIcon size={24} icon="alertDismiss" />
          </button>
        )}
        <div className="arc-Alert-icon">
          {icon ? (
            <Icon size={24} icon={icon} />
          ) : (
            <ThemeIcon size={24} icon={statusIcons[status]} />
          )}
        </div>

        <div className="arc-Alert-content">
          <SemanticHeading
            className={classNames("arc-Alert-heading", {
              "arc-Alert-heading--isDismissable": isDismissable,
            })}
            id={headingId}
            level={headingLevel}
          >
            <VisuallyHidden>{status} alert.</VisuallyHidden>
            {heading}
          </SemanticHeading>

          {description ? (
            React.isValidElement(description) ? (
              <div className="arc-Alert-description" id={descriptionId}>
                {description}
              </div>
            ) : (
              <div className="arc-Alert-description">
                <Text isMeasured={isMeasured} size="s" id={descriptionId}>
                  {description}
                </Text>
              </div>
            )
          ) : null}

          {links && links.length > 0 && (
            <ul className="arc-Alert-links">
              {links.map((link, index) => (
                <li key={index} className="arc-Alert-link">
                  <Link
                    href={link.href}
                    aria-label={link.screenReaderText}
                    target={link.target}
                    size="s"
                    {...(link.onClick && {
                      onClick: (e) => handleLinkClick(e, link),
                      isButton: true,
                    })}
                  >
                    {link.children ?? ""}
                  </Link>
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>
    </Surface>
  );
};

export type AlertLinkProps = Omit<LinkProps, "size" | "isImplied">;

export interface AlertProps {
  /**
   * Determine a heading for `<Alert />`
   */
  heading: string;
  /**
   * Determine a level for the heading`
   */
  headingLevel: SemanticHeadingLevel;
  /**
   * Determine a description for `<Alert />`
   */
  description?: string | ReactNode;

  /**
   * Should the description width be constrained to a typographic measure?
   */
  isMeasured?: boolean;

  /**
   * Determine array of links for `<Alert />`. link type `LinkProps` omit `size` & `isImplied`.
   */
  links?: AlertLinkProps[];

  /**
   * Determine a icon to display within `<Alert />`. This overrides the default icons.
   */
  icon?: string;

  /**
   * Determine the type of alert
   */
  status?: AlertStatus;

  /**
   * Determine showing a dismiss icon within `<Alert />`
   */
  isDismissable?: boolean;

  /**
   * Execute a function when dismiss is envoked
   */
  onDismiss?: () => void;

  /**
   * Focus will be set on the alert when the component mounts, defaults to false.
   */
  autoFocusOnMount?: boolean;

  /**
   * Optional alternative role to allow the alert to not be read out by screen readers.
   */
  role?: "alert" | "presentation";

  /**
   * Element to focus when the `Alert` is dismissed
   */
  onDismissFocusRef?: RefObject<HTMLElement | null | undefined>;
}

type AlertStatus = "general" | "error" | "warning" | "success";
