import React from "react";

import classNames from "classnames";

import { ThemeIcon, type ThemeIconNames } from "../../../ThemeIcon";

export const CalendarNavButton = ({
  isDisabled,
  onClick,
  direction,
  ariaLabel,
}: CalendarNavButtonProps) => {
  const icons: Record<IconDirection, ThemeIconNames> = {
    previous: "calendarLeft",
    next: "calendarRight",
  };

  return (
    <button
      aria-label={ariaLabel}
      disabled={isDisabled}
      onClick={onClick}
      type="button"
      className={classNames("arc-CalendarNavButton", {
        "arc-CalendarNavButton--previous": direction === "previous",
        "arc-CalendarNavButton--next": direction === "next",
      })}
    >
      <div className="arc-CalendarNavButton-icon">
        <ThemeIcon icon={icons[direction]} />
      </div>
    </button>
  );
};

type IconDirection = "previous" | "next";

interface CalendarNavButtonProps {
  /**
   * Aria label for accessibility
   */
  ariaLabel: string;
  /**
   * Whether the button is disabled
   */
  isDisabled?: boolean;
  /**
   * Direction of navigation
   */
  direction: IconDirection;
  /**
   * Click handler
   */
  onClick: () => void;
}
