import React from "react";

import classNames from "classnames";

import { type ComboBoxOption } from "../../types/combobox-option";

import { ComboBoxRegularOption } from "../ComboBoxRegularOption";
import { ComboBoxCustomOption } from "../ComboBoxCustomOption";
import { ComboBoxNoResults } from "../ComboBoxNoResults";

export const ComboBoxOptions = ({
  options,
  listBoxId,
  onMouseMove,
  onMouseDown,
  isMultiSelectable,
  noResultsSupportingCopy,
  customOptionSupportingCopy,
  selectedOptions,
  singleSelectedOption,
  highlightedOptionIndex,
  setOptionRef,
  limitReached,
  value,
}: ComboBoxOptionsProps) => {
  const isHighlighted = (index: number, currentHighlightIndex?: number) =>
    index === currentHighlightIndex;

  const isSingleSelected = (
    option: ComboBoxOption,
    selectedOption: ComboBoxOption,
  ) => option.text === selectedOption.text;

  const isMultiSelected = (
    option: ComboBoxOption,
    selectedOptions: ComboBoxOption[],
  ) =>
    selectedOptions.some(
      (selectedOption) => option.text === selectedOption.text,
    );

  const isOptionDisabled = (
    option: ComboBoxOption,
    selectedOptions: ComboBoxOption[],
  ) => limitReached && !isMultiSelected(option, selectedOptions);

  return (
    <>
      {options.length ? (
        options.map((option, i) => (
          <li
            key={option.text}
            role="option"
            id={`${listBoxId}-${i}`}
            ref={setOptionRef(i)}
            onMouseMove={onMouseMove(i)}
            onMouseDown={onMouseDown(option)}
            aria-disabled={isOptionDisabled(option, selectedOptions)}
            aria-selected={
              isMultiSelectable
                ? isMultiSelected(option, selectedOptions)
                : isSingleSelected(option, singleSelectedOption)
            }
            className={classNames("arc-ComboBoxOptions-listItem", {
              "arc-ComboBoxOptions-listItem--disabled": isOptionDisabled(
                option,
                selectedOptions,
              ),
            })}
          >
            {option.isCustom ? (
              <ComboBoxCustomOption
                option={option}
                optionsLength={options.length}
                customOptionSupportingCopy={customOptionSupportingCopy}
                selectedOptions={selectedOptions}
                isHighlighted={isHighlighted(i, highlightedOptionIndex)}
                isSelected={isSingleSelected(option, singleSelectedOption)}
              />
            ) : (
              <ComboBoxRegularOption
                option={option}
                isDisabled={isOptionDisabled(option, selectedOptions)}
                isMultiSelectable={isMultiSelectable}
                isHighlighted={isHighlighted(i, highlightedOptionIndex)}
                isMultiSelected={isMultiSelected(option, selectedOptions)}
                isSingleSelected={isSingleSelected(
                  option,
                  singleSelectedOption,
                )}
              />
            )}
          </li>
        ))
      ) : (
        <ComboBoxNoResults
          noResultsSupportingCopy={noResultsSupportingCopy}
          value={value}
        />
      )}
    </>
  );
};

interface ComboBoxOptionsProps {
  options: ComboBoxOption[];
  listBoxId: string;
  value: string;
  isMultiSelectable: boolean;
  selectedOptions: ComboBoxOption[];
  singleSelectedOption: ComboBoxOption;
  limitReached: boolean;
  highlightedOptionIndex?: number;
  noResultsSupportingCopy?: string;
  customOptionSupportingCopy?: string;
  setOptionRef: (i: number) => (el: HTMLLIElement) => void;
  onMouseMove: (index?: number) => () => void;
  onMouseDown: (
    itemOption: ComboBoxOption,
  ) => (e: React.MouseEvent<HTMLLIElement, MouseEvent>) => void;
}
