import React from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { Heading } from "../../../../../Heading";
import { Text } from "../../../../../Text";
import { Surface } from "../../../../../Surface";
import { VerticalSpace } from "../../../../../VerticalSpace";
import { Hidden } from "../../../../../Hidden";

import {
  NavigationHeaderActionLoginDropdownLoginTile,
  type NavigationHeaderActionLoginDropdownLoginTileProps,
} from "../NavigationHeaderActionLoginDropdownLoginTile";

import { UKImage } from "./svgs/UK";
import { InternationalImage } from "./svgs/International";

export const NavigationHeaderActionLoginDropdown = ({
  heading,
  description,
  tileOne,
  tileTwo,
  isMobile = false,
  ...props
}: NavigationHeaderActionLoginDropdownProps) => {
  return (
    <Surface background="light-white" isTransparent>
      <div
        className={classNames("arc-NavigationHeaderActionLoginDropdown", {
          "arc-NavigationHeaderActionLoginDropdown--isDesktop": !isMobile,
        })}
        aria-modal={isMobile ? undefined : "true"}
        {...filterAttrs(props)}
      >
        <div className="arc-NavigationHeaderActionLoginDropdown-titleText">
          <Heading
            size={isMobile ? "xs" : "m"}
            color="brand"
            isResponsive={false}
            level="2"
          >
            {heading}
          </Heading>
          <VerticalSpace size="4" />
          <Text tone="muted" size="s">
            {description}
          </Text>
        </div>
        <Hidden xs s>
          <VerticalSpace size="16" />
        </Hidden>
        <div className="arc-NavigationHeaderActionLoginDropdown-tileWrapper">
          <NavigationHeaderActionLoginDropdownLoginTile
            tileHeading={
              tileOne.tileHeading || "For small and medium businesses"
            }
            tileImage={tileOne.tileImage || <UKImage />}
            primaryButton={tileOne.primaryButton}
            tertiaryButton={tileOne.tertiaryButton}
            isMobile={isMobile}
          />
          <NavigationHeaderActionLoginDropdownLoginTile
            tileHeading={
              tileTwo.tileHeading || "For corporate and international customers"
            }
            tileImage={tileTwo.tileImage || <InternationalImage />}
            primaryButton={tileTwo.primaryButton}
            tertiaryButton={tileTwo.tertiaryButton}
            isMobile={isMobile}
          />
        </div>
      </div>
    </Surface>
  );
};

export interface NavigationHeaderActionLoginDropdownProps {
  /** The main heading text displayed at the top of the dropdown */
  heading?: string;
  /** The descriptive text displayed below the heading */
  description?: string;
  /** Configuration for the first login tile */
  tileOne: NavigationHeaderActionLoginDropdownLoginTileProps;
  /** Configuration for the second login tile */
  tileTwo: NavigationHeaderActionLoginDropdownLoginTileProps;
  /** Whether the tile is being rendered in a mobile context */
  isMobile?: boolean;
}
