import React from "react";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { TemplateBanner, type TemplateBannerProps } from "../TemplateBanner";

/** Use `Banner` to promote key content or products with bold visuals and messaging. */
export const Banner = ({
  heading,
  label,
  text,
  img,
  contentRatio = "1/1",
  contentRatios,
  children,
  minHeight,
  isReversed = false,
  isElevated = false,
  headingLevel = "2",
  type = "light",
  alignment = "center",
  fontStyle = "default",
  headingWordWrap = false,
  headingColor,
  labelColor,
  ...props
}: BannerProps) => {
  return (
    <TemplateBanner
      heading={heading}
      label={label}
      text={text}
      img={img}
      contentRatio={contentRatio}
      contentRatios={contentRatios}
      minHeight={minHeight}
      isReversed={isReversed}
      isElevated={isElevated}
      headingLevel={headingLevel}
      type={type}
      headingSize={"m"}
      fontStyle={fontStyle}
      alignment={alignment}
      headingWordWrap={headingWordWrap}
      headingColor={headingColor}
      labelColor={labelColor}
      {...filterAttrs(props)}
    >
      {children}
    </TemplateBanner>
  );
};

export type BannerProps = Omit<
  TemplateBannerProps,
  "headingSize" | "additionalTopMargin"
>;
