import React from "react";

import { BtIconChevronDownMid } from "@arc-ui/icons/BtIconChevronDownMid";

import { Icon } from "../../../Icon";
import { Heading } from "../../../Heading";
import { type DateSelectValue } from "../../types";

export const CalendarDateSelect = ({
  ariaLabel,
  onChange,
  name,
  value,
  displayValue,
  options,
}: CalendarDateSelectProps) => {
  return (
    <div className="arc-CalendarDateSelect-wrapper">
      <select
        aria-label={ariaLabel}
        onChange={onChange}
        className="arc-CalendarDateSelect"
        value={value}
        name={name}
      >
        {options.map(({ text, value }) => (
          <option
            className="arc-CalendarDateSelect-option"
            key={`arc-calendar-year-select-${value}`}
            value={value}
          >
            {text}
          </option>
        ))}
      </select>
      <div aria-hidden className="arc-CalendarDateSelect-label">
        <Heading size="s">{displayValue || value}</Heading>

        <div className="arc-CalendarDateSelect-icon">
          <Icon size={24} icon={BtIconChevronDownMid} />
        </div>
      </div>
    </div>
  );
};

interface CalendarDateSelectProps {
  /**
   * Name attribute for the select element
   */
  name: string;
  /**
   * Aria label for accessibility
   */
  ariaLabel: string;
  /**
   * Current selected value
   */
  value: DateSelectValue;
  /**
   * Display value override
   */
  displayValue?: string;
  /**
   * Options for the select dropdown
   */
  options: { value: DateSelectValue; text: string | number }[];
  /**
   * Change handler for the select element
   */
  onChange: (e: React.ChangeEvent<HTMLSelectElement>) => void;
}
