import React, { useMemo } from "react";

import classNames from "classnames";

import { type ArcGradient } from "@arc-ui/gradients";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { useMediaQuery } from "../../hooks";

import { Surface, type SurfaceBackgroundColor } from "../Surface";

import {
  ARC_MIN_L_BREAKPOINT,
  ARC_MIN_M_BREAKPOINT,
  ARC_MIN_S_BREAKPOINT,
  ARC_MIN_XL_BREAKPOINT,
  ARC_MIN_XXL_BREAKPOINT,
  type ArcBreakpointSizes,
} from "../../helpers/arc-breakpoints";

import { ClientSideVisible } from "../ClientSideVisible";

import { ScrimFade } from "./components/ScrimFade";

import { getResponsiveConfig } from "./utils/get-responsive-config";

import { type ResponsiveGradient } from "./types/responsive-gradient";
import { type ScrimPosition } from "./types/scrim-position";
import { type GradientBreakpointConfig } from "./types/gradient-breakpoint-config";
import { type ScrimFadeSize } from "./types/scrim-fade-size";

/**
 * Use `GradientPageBackground` as a content wrapper blending multiple colours to add depth, mood or emphasise hero sections, footer sections, or mid-page section backgrounds.
 */
export const GradientPageBackground = ({
  gradient,
  responsiveGradient,
  children,
  scrimFadeSize,
  scrimFadeHeights,
  extendBackgrounds,
  loading,
  scrimFadePosition = "bottom",
  ...props
}: GradientPageBackgroundProps) => {
  const isMinWidthArcBreakpointS = useMediaQuery(ARC_MIN_S_BREAKPOINT);
  const isMinWidthArcBreakpointM = useMediaQuery(ARC_MIN_M_BREAKPOINT);
  const isMinWidthArcBreakpointL = useMediaQuery(ARC_MIN_L_BREAKPOINT);
  const isMinWidthArcBreakpointXl = useMediaQuery(ARC_MIN_XL_BREAKPOINT);
  const isMinWidthArcBreakpointXxl = useMediaQuery(ARC_MIN_XXL_BREAKPOINT);

  const breakpoint = useMemo(() => {
    const breakpoints: Record<ArcBreakpointSizes, boolean> = {
      xs: true,
      s: isMinWidthArcBreakpointS,
      m: isMinWidthArcBreakpointM,
      l: isMinWidthArcBreakpointL,
      xl: isMinWidthArcBreakpointXl,
      xxl: isMinWidthArcBreakpointXxl,
    };

    return (Object.keys(breakpoints) as Array<ArcBreakpointSizes>).findLast(
      (key) => breakpoints[key],
    );
  }, [
    isMinWidthArcBreakpointS,
    isMinWidthArcBreakpointM,
    isMinWidthArcBreakpointL,
    isMinWidthArcBreakpointXl,
    isMinWidthArcBreakpointXxl,
  ]);

  const customGradient = useMemo(
    () => getResponsiveConfig(responsiveGradient, breakpoint),
    [responsiveGradient, breakpoint],
  );

  const scrimFadeHeight = useMemo(
    () => getResponsiveConfig(scrimFadeHeights, breakpoint),
    [breakpoint, scrimFadeHeights],
  );

  const extendBackground = useMemo(
    () => getResponsiveConfig(extendBackgrounds, breakpoint),
    [breakpoint, extendBackgrounds],
  );

  const gradientPathway: Record<ArcGradient["type"], SurfaceBackgroundColor> = {
    light: "light-white",
    dark: "dark-black",
  };

  const extentedBackgroundScrimStyles: Record<
    ScrimPosition,
    React.CSSProperties
  > = {
    top: {
      paddingTop: `${extendBackground}px`,
      marginTop: `-${extendBackground}px`,
    },
    bottom: {
      paddingBottom: `${extendBackground}px`,
      marginBottom: `-${extendBackground}px`,
    },
  };

  return (
    <ClientSideVisible>
      <div
        className={classNames("arc-GradientPageBackground", {
          [`arc-GradientPageBackground--${scrimFadePosition}`]:
            scrimFadePosition,
        })}
        style={{
          ...(extendBackground
            ? extentedBackgroundScrimStyles[scrimFadePosition]
            : {}),
        }}
        {...filterAttrs(props)}
      >
        <div className="arc-GradientPageBackground-svgWrapper">
          <img
            src={customGradient?.svg || gradient?.svg}
            alt=""
            className="arc-GradientPageBackground-svgbg"
            loading={loading}
          />
        </div>

        <div className="arc-GradientPageBackground-content">
          <Surface
            isTransparent
            background={
              customGradient
                ? gradientPathway[customGradient?.type]
                : gradientPathway[gradient?.type || "light"]
            }
          >
            {children}
          </Surface>
        </div>
        {scrimFadeSize && (
          <ScrimFade
            scrimFadeHeight={scrimFadeHeight}
            scrimFadeSize={scrimFadeSize}
            scrimFadePosition={scrimFadePosition}
            preserveAspectRatio="none"
          />
        )}
      </div>
    </ClientSideVisible>
  );
};

export interface GradientPageBackgroundProps {
  /**
   * Gradient for the component. You can import these directly from the @arc-ui/gradients package, or pass your own.
   */
  gradient?: ArcGradient;

  /**
   * Specify a gradient for each arc breakpoint.
   */
  responsiveGradient?: ResponsiveGradient;

  /**
   * Select the gradient fade sizing, default heights "s" 640px, "m" 1024px and "l" 1280px
   */
  scrimFadeSize?: ScrimFadeSize;

  /**
   * Set a custom height at each breakpoint for the gradient fade that will override the scrimFadeSize height. Larger breakpoints will inherit smaller breakpoints if no value is provided.
   */
  scrimFadeHeights?: GradientBreakpointConfig<number>;

  /**
   * Select the gradient fade positioning
   */
  scrimFadePosition?: ScrimPosition;

  /**
   * Set a height at each breakpoint for the gradient to extend beyond it 100% height. Larger breakpoints will inherit smaller breakpoints if no value is provided.
   */
  extendBackgrounds?: GradientBreakpointConfig<number>;

  /**
   * Content to be displayed on top of the gradient
   */
  children?: React.ReactNode;

  /**
   * Loading behaviour of the background gradient image.
   */
  loading?: "lazy" | "eager";
}
