import React from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

/**
 * Use `Skeleton` to display a placeholder preview of your page before the data gets loaded to reduce load-time frustration.
 */
export const Skeleton = ({
  width,
  height,
  isCircle,
  animation = "pulse",
  ...props
}: SkeletonProps) => {
  return (
    <span
      className={classNames("arc-Skeleton", {
        "arc-Skeleton--circle": isCircle,
        [`arc-Skeleton--${animation}`]: animation !== "none",
      })}
      style={{ width, height }}
      {...filterAttrs(props)}
    />
  );
};

export interface SkeletonProps {
  /**
   * Animation for `Skeleton`.
   */
  animation?: "pulse" | "shimmer" | "none";

  /**
   * Make `Skeleton` a circle.
   */
  isCircle?: boolean;

  /**
   * Width of `Skeleton`.
   */
  width?: string | number;

  /**
   * Height of `Skeleton`.
   */
  height?: string | number;
}
