import React from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import {
  type Arrangement,
  type Column,
  type Alignment,
} from "../../Grid.types";

import { BREAKPOINTS } from "../../Grid.constants";

export const GridCol = ({
  order,
  offset,
  align,
  children,
  ...props
}: GridColProps) => {
  return (
    <div
      className={classNames(
        "arc-Grid-col",
        BREAKPOINTS.reduce((acc, bp) => {
          const sizeValue = props?.[bp];
          const orderValue = order?.[bp];
          const offsetValue = offset?.[bp];
          const alignValue = align?.[bp];

          return {
            ...acc,
            [`arc-Grid-col--${bp}${sizeValue}`]: sizeValue !== undefined,
            [`arc-Grid-order--${bp}${orderValue}`]: orderValue !== undefined,
            [`arc-Grid-offset--${bp}${offsetValue}`]: offsetValue !== undefined,
            [`arc-Grid-align--${bp}${alignValue}`]: alignValue !== undefined,
          };
        }, {}),
      )}
      {...filterAttrs(props)}
    >
      {children}
    </div>
  );
};

export interface GridColProps extends Column {
  /**
   * Offset configuration for the column
   */
  offset?: Arrangement;
  /**
   * Order configuration for the column
   */
  order?: Arrangement;
  /**
   * Alignment configuration for the column
   */
  align?: Alignment;
  /**
   * Content to display in the GridCol
   */
  children: React.ReactNode;
}
