import { getHighlightRange } from "../../helpers";

import { type HIGHLIGHT_RANGE_ACTION } from "../types/actions";
import { type StateHandler } from "../types/state-handler";

export const highlightRangeHandler: StateHandler<HIGHLIGHT_RANGE_ACTION> = (
  payload,
  state,
) => {
  return {
    ...state,
    highlightedRange: getHighlightRange({
      date: payload.date,
      range: payload.range,
      minDate: payload.minDate,
      maxDate: payload.maxDate,
    }),
  };
};
