import React from "react";

import { Group } from "@radix-ui/react-dropdown-menu";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

/**
 * Groups related menu items together within a dropdown menu.
 */
export const MenuGroup = ({ children, ...props }: MenuGroupProps) => {
  return (
    <Group className="arc-MenuGroup" {...filterAttrs(props)}>
      {children}
    </Group>
  );
};

export interface MenuGroupProps {
  /**
   *  Menu items grouped together within the menu.
   */
  children: React.ReactNode;
}
