import React, { type Ref, type ReactElement, type ReactNode } from "react";

import { NavigationHeaderButton } from "../../../NavigationHeaderButton";

import { useTriggerHidden } from "../../../../hooks/use-trigger-hide";
import { useSubNavContext } from "../../NavigationHeaderSubnav.provider";

export const NavigationHeaderSubnavTrigger = ({
  children,
  asChild,
  onClick,
  ariaLabel,
  ...props
}: NavigationHeaderSubnavTriggerProps) => {
  const subNavContext = useSubNavContext();

  const onTriggerClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    onClick && onClick(e);
    subNavContext.setIsOpen(!subNavContext.isOpen);
    subNavContext.onOpenChange?.(!subNavContext.isOpen);
  };

  useTriggerHidden({
    triggerEl: subNavContext.triggerRef?.current as HTMLButtonElement,
    onTriggerHidden: () => {
      subNavContext.setIsOpen(false);
      subNavContext.onOpenChange?.(false);
    },
  });

  if (asChild) {
    return React.cloneElement(children as ChildProps, {
      onClick: (e: React.MouseEvent<HTMLButtonElement>) => {
        onTriggerClick(e);
        (children as ChildProps).props.onClick?.(e);
      },
      ref: subNavContext.triggerRef,
      ...props,
      ...(children as ChildProps).props,
    });
  }

  return (
    <NavigationHeaderButton
      aria-label={ariaLabel}
      aria-haspopup="dialog"
      aria-describedby={undefined}
      onClick={onTriggerClick}
      ref={subNavContext.triggerRef}
      aria-expanded={subNavContext.isOpen}
      isActive={subNavContext.isOpen}
    >
      {children}
    </NavigationHeaderButton>
  );
};

type ChildProps = ReactElement<
  Partial<{
    ref: Ref<HTMLButtonElement>;
    onClick: (e: React.MouseEvent<HTMLButtonElement>) => void;
  }>
>;

interface NavigationHeaderSubnavTriggerProps {
  /**
   * Content to display in the trigger.
   */
  children: ReactNode;
  /**
   * Accessible label for the trigger.
   */
  ariaLabel?: string;
  /**
   * Whether to render the trigger as a child component.
   */
  asChild?: boolean;
  /**
   * Click handler for the trigger.
   */
  onClick?: (e: React.MouseEvent<HTMLButtonElement>) => void;
}
