import React, { type Ref, useContext, useRef, useState } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { useAriaDescribedby } from "../../hooks";

import { SurfaceContext } from "../Surface";
import { Text } from "../Text";
import { VisuallyHidden } from "../VisuallyHidden";

import { FormControl, type FormControlProps } from "../FormControl/FormControl";
import { type AutoCompleteTypes } from "../../types/auto-complete-types";

/** Use `TextArea` to allow custom user text entry via keyboard, for long-form and multi-line descriptions */
export const TextArea = ({
  ref,
  defaultValue = "",
  errorMessage,
  helper,
  hideLabel,
  id,
  resize = "manual",
  isDisabled = false,
  isReadOnly = false,
  isRequired = false,
  showCharacterCount = true,
  label,
  labelSize = "m",
  maxLength,
  name,
  onBlur,
  onFocus,
  onChange,
  onClickDisclosure,
  value,
  disclosureTitle,
  disclosureText,
  width,
  autoComplete,
  minHeight = "116px",
  maxHeight,
  isErrorAlert,
  ...props
}: TextAreaProps) => {
  const { surface } = useContext(SurfaceContext);
  const ourRef = useRef<HTMLTextAreaElement | null>(null);
  const [characterCount, setCharacterCount] = useState(
    (value && value.length) || (defaultValue && defaultValue.length) || 0,
  );

  const setSmartHeight = (el: HTMLTextAreaElement) => {
    el.style.height = "auto";
    el.style.height = `${
      parseInt(getComputedStyle(el).getPropertyValue("border-width")) * 2 +
      el.scrollHeight
    }px`;
  };

  const getTextAreaRef = (elementRef: HTMLTextAreaElement | null) => {
    ourRef.current = elementRef;

    if (ref && typeof ref === "object") {
      ref.current = elementRef;
    }

    if (ref && typeof ref === "function") {
      ref(elementRef);
    }
  };

  const handleOnChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    resize === "auto" && ourRef.current && setSmartHeight(ourRef.current);
    onChange && onChange(e);
    setCharacterCount(e.target.value.length);
  };

  // Although this is used within FormControlWrapper, it's deterministic so we can call it here too
  const { ariaDescribedby } = useAriaDescribedby({
    id,
    errorMessage,
    helper,
    disclosureText,
  });

  return (
    <FormControl
      errorMessage={errorMessage}
      helper={helper}
      htmlFor={id}
      isDisabled={isDisabled}
      label={label}
      hideLabel={hideLabel}
      labelSize={labelSize}
      requirementStatus={isRequired ? "required" : "optional"}
      disclosureTitle={disclosureTitle}
      disclosureText={disclosureText}
      onClickDisclosure={onClickDisclosure}
      isErrorAlert={isErrorAlert}
      supplementaryInfo={
        maxLength &&
        showCharacterCount && (
          <>
            <Text tone={isDisabled ? "muted" : "default"}>
              <span className="arc-TextArea-characterCount" aria-live="polite">
                {characterCount} / {maxLength} characters
                {characterCount === maxLength && (
                  <VisuallyHidden>Maximum characters reached</VisuallyHidden>
                )}
              </span>
            </Text>
          </>
        )
      }
      {...filterAttrs(props)}
    >
      <textarea
        id={id}
        className={classNames("arc-TextArea", {
          "arc-TextArea--noResize": resize !== "manual",
          "arc-TextArea--onDarkSurface": surface === "dark",
          "arc-TextArea--invalid": errorMessage,
        })}
        defaultValue={typeof value !== "undefined" ? undefined : defaultValue}
        disabled={isDisabled}
        value={value}
        readOnly={isReadOnly}
        maxLength={maxLength}
        name={name}
        onChange={handleOnChange}
        onBlur={onBlur}
        onFocus={onFocus}
        ref={getTextAreaRef}
        style={{
          width,
          maxHeight,
          minHeight,
          marginTop: hideLabel ? 0 : undefined,
        }}
        aria-describedby={ariaDescribedby}
        autoComplete={autoComplete}
      />
    </FormControl>
  );
};

export interface TextAreaProps extends Omit<
  FormControlProps,
  | "children"
  | "elementType"
  | "htmlFor"
  | "requirementStatus"
  | "helperUnderLabel"
  | "labelPosition"
> {
  /**
   * Ref to the underlying textarea element
   */
  ref?: Ref<HTMLTextAreaElement>;
  /**
   * Uncontrolled default value of the TextArea. If the TextArea is controlled
   * via `value`/`onChange`, `defaultValue` will be ignored.
   *
   * `defaultValue` is not to be used instead of helper text.
   */
  defaultValue?: string;

  /**
   * ID for the TextArea.
   */
  id: string;

  /**
   * Should the control be disabled?
   */
  isDisabled?: boolean;

  /**
   * Should the control be read-only?
   */
  isReadOnly?: boolean;

  /**
   * Should the control be required?
   */
  isRequired?: boolean;

  /**
   * Maximum number of characters.
   */
  maxLength?: number;

  /**
   * Shows the current character count and maxLength. Ignored if maxLength is undefined.
   */
  showCharacterCount?: boolean;

  /**
   * Name of the input.
   */
  name?: string;

  /**
   * `none` will prevent any resizing.
   * `manual` will allow the user to resize the TextArea.
   * `auto` will resize the text area as needed when the user types.
   */
  resize?: "none" | "manual" | "auto";

  /**
   * Function to call when the TextArea loses focus.
   */
  onBlur?: (e: React.FocusEvent<HTMLTextAreaElement>) => void;

  /**
   * Function to call when the TextArea is focused.
   */
  onFocus?: (e: React.FocusEvent<HTMLTextAreaElement>) => void;
  /**
   * Callback function commonly used to update the TextArea's controlled
   * `value`, for example `e => setValue(e.target.value)`.
   */
  onChange?: (e: React.ChangeEvent<HTMLTextAreaElement>) => void;

  /**
   * Current value of the TextArea. Must be controlled via an
   * `onChange` callback function. Otherwise, use `defaultValue` (or `isReadOnly`).
   */
  value?: string;
  /**
   * Sets the width of the TextArea.
   */
  width?: string;

  /**
   *  Sets autoComplete value for TextArea.
   */
  autoComplete?: AutoCompleteTypes;

  /**
   *  Sets minimum height value for TextArea.
   */
  minHeight?: string;

  /**
   *  Sets max-height value for TextArea.
   */
  maxHeight?: string;
}
