import React, {
  useContext,
  useEffect,
  useId,
  useReducer,
  useRef,
  type Ref,
} from "react";

import classNames from "classnames";

import * as Popover from "@radix-ui/react-popover";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";
import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";

import { useAriaDescribedby, useThemeElement } from "../../hooks";
import { type ArcIcon } from "../../types/arc-icon";

import { Icon } from "../Icon";
import { SurfaceContext } from "../Surface";
import { ThemeIcon } from "../ThemeIcon";
import { Tooltip } from "../Tooltip";
import { type FormControlProps, FormControl } from "../FormControl";
import { VerticalSpace, type VerticalSpaceProps } from "../VerticalSpace";

import { reducer } from "./reducer";

import { KeyNames, type InputSize, type FocusHandler } from "./types";

import { type ComboBoxOption } from "./types/combobox-option";
import { ComboBoxTags } from "./components/ComboBoxTags";
import { ComboBoxOptions } from "./components/ComboBoxOptions";
import { convertOptionsToObjects } from "./utils/convertOptionsToObjects";
import { isSelectionKey } from "./utils/isSelectionKey";
import { ComboBoxClearButton } from "./components/ComboBoxClearButton/ComboBoxClearButton";

/** Use `ComboBox` to assist a text input with a dropdown list of options. */
export const ComboBox = ({
  ref,
  name,
  onBlur,
  onFocus,
  label,
  helper,
  id,
  hideLabel,
  isFluid,
  errorMessage,
  disclosureTitle,
  disclosureText,
  onClickDisclosure,
  listBoxAriaLabel,
  prefixIcon,
  onChange,
  noResultsSupportingCopy,
  customOptionSupportingCopy,
  multiSelectLimit,
  options: initialOptions,
  clearButtonTooltip = "Clear input",
  defaultSelectedValues = [],
  defaultValue = "",
  size = "m",
  visibleTagCount = 5,
  isClearButtonEnabled = false,
  isReadOnly = false,
  isMultiSelectable = false,
  isDisabled = false,
  isRequired = false,
  isAutocomplete = false,
  isCustomEntryAllowed = false,
  fuzzyThreshold = 0.45,
  ...props
}: ComboBoxProps) => {
  const listBoxId = useId();
  const { surface } = useContext(SurfaceContext);
  const [themeElement, setThemeElement] = useThemeElement();
  const listItemRefs = useRef<(HTMLLIElement | null)[]>([]);
  const comboBoxContainerRef = useRef<HTMLDivElement | null>(null);
  const tagContainerRef = useRef<HTMLDivElement | null>(null);
  const inputRef = useRef<HTMLInputElement | null>(null);
  const prevOnChangeValueRef = useRef<string | string[]>(null);

  const [
    {
      isExpanded,
      value,
      options,
      showAllTags,
      singleSelectedOption,
      highlightedOptionIndex,
      selectedOptions,
      limitReached,
      isDirty,
      onChangeValue,
    },
    dispatch,
  ] = useReducer(reducer(initialOptions), {
    isExpanded: false,
    showAllTags: false,
    isDirty: Boolean(defaultValue),
    singleSelectedOption: { isCustom: false, text: defaultValue },
    limitReached:
      defaultSelectedValues && multiSelectLimit
        ? defaultSelectedValues.length > multiSelectLimit
        : false,
    value: defaultValue,
    onChangeValue: isMultiSelectable
      ? defaultSelectedValues || null
      : defaultValue || null,
    options: convertOptionsToObjects(initialOptions),
    selectedOptions: isMultiSelectable
      ? convertOptionsToObjects(defaultSelectedValues).slice(
          0,
          multiSelectLimit,
        )
      : [],
  });

  const { ariaDescribedby } = useAriaDescribedby({
    errorMessage,
    id,
    helper,
    disclosureText,
  });

  useEffect(() => {
    const hasValueChanged =
      JSON.stringify(onChangeValue) !==
      JSON.stringify(prevOnChangeValueRef.current);

    if (hasValueChanged && onChange && onChangeValue) {
      prevOnChangeValueRef.current = onChangeValue;
      onChange(onChangeValue);
    }
  }, [onChangeValue, onChange]);

  const hasHighlightedOption = typeof highlightedOptionIndex !== "undefined";
  const listVerticalPadding: VerticalSpaceProps["size"] = "12";
  const isDarkSurface = surface === "dark";
  const canOpenMenu = !isExpanded && !isReadOnly;

  const showClearButton =
    isClearButtonEnabled && isDirty && value && !isDisabled && !isReadOnly;

  const stackAutoCompleteIconFirst =
    selectedOptions.length && isAutocomplete && !showClearButton;

  const getTextInputRef = (elementRef: HTMLInputElement | null) => {
    inputRef.current = elementRef;

    if (ref && typeof ref === "object") {
      ref.current = elementRef;
    }

    if (ref && typeof ref === "function") {
      ref(elementRef);
    }
  };

  const setOptionRef = (index: number) => (el: HTMLLIElement) =>
    (listItemRefs.current[index] = el);

  const setScrollPosition = (listEl: HTMLUListElement) => {
    if (hasHighlightedOption) {
      const listItemEl = listItemRefs.current[highlightedOptionIndex];

      if (listItemEl && listEl) {
        const listItemOffset =
          listItemEl.offsetTop - parseInt(listVerticalPadding);

        const selectedOptionIsBelowOverFlow =
          listItemOffset + listItemEl.offsetHeight >
          listEl.offsetHeight + listEl.scrollTop;

        const selectedOptionIsAboveOverFlow = listItemOffset < listEl.scrollTop;

        if (selectedOptionIsBelowOverFlow) {
          listEl.scrollTop =
            listItemOffset + listItemEl.offsetHeight - listEl.offsetHeight;
        }

        if (selectedOptionIsAboveOverFlow) {
          listEl.scrollTop = listItemOffset;
        }
      }
    }
  };

  const onItemClick =
    (itemOption: ComboBoxOption) =>
    (e: React.MouseEvent<HTMLLIElement, MouseEvent>) => {
      e.preventDefault();

      if (isMultiSelectable) {
        dispatch({
          type: "MULTI_SELECT",
          payload: {
            multiSelectLimit,
            option: itemOption,
          },
        });
      } else {
        dispatch({
          type: "SINGLE_SELECT",
          payload: {
            option: itemOption,
          },
        });
      }

      inputRef.current?.focus();
    };

  const onInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    dispatch({
      type: "INPUT_CHANGE",
      payload: {
        isCustomEntryAllowed,
        isMultiSelectable,
        isAutocomplete,
        value: e.target.value,
        fuzzyThreshold,
      },
    });
  };

  const onMouseDown =
    (preventDefault: boolean) => (e: React.MouseEvent<HTMLDivElement>) => {
      preventDefault && e.preventDefault();

      if (isDisabled) {
        return;
      }

      if (canOpenMenu) {
        dispatch({
          type: "OPEN",
        });
      }

      if (isExpanded) {
        dispatch({
          type: "CLOSE_MENU",
        });
      }

      inputRef.current?.focus();
    };

  const onInteractOutsideDropdown = (e: Event) => {
    if (
      comboBoxContainerRef.current &&
      !comboBoxContainerRef.current.contains(e.currentTarget as Node)
    ) {
      dispatch({
        type: "EXIT_INPUT",
        payload: {
          isMultiSelectable,
          isCustomEntryAllowed,
        },
      });
    }
  };

  const onInputFocus = (e: React.FocusEvent<HTMLInputElement, Element>) => {
    if (canOpenMenu) {
      dispatch({
        type: "OPEN",
      });
    }

    onFocus && onFocus(e);
  };

  const onInputBlur = (e: React.FocusEvent<HTMLInputElement, Element>) => {
    if (
      !isExpanded &&
      !comboBoxContainerRef.current?.contains(e.relatedTarget)
    ) {
      dispatch({
        type: "EXIT_INPUT",
        payload: {
          isMultiSelectable,
          isCustomEntryAllowed,
        },
      });
    }

    onBlur && onBlur(e);
  };

  const onClearButtonBlur = (
    e: React.FocusEvent<HTMLButtonElement, Element>,
  ) => {
    if (
      !isExpanded &&
      !comboBoxContainerRef.current?.contains(e.relatedTarget)
    ) {
      dispatch({
        type: "EXIT_INPUT",
        payload: {
          isMultiSelectable,
          isCustomEntryAllowed,
        },
      });
    }
  };

  const onInputKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (!isReadOnly) {
      if (e.key === KeyNames.Enter) {
        e.preventDefault();
      }

      dispatch({
        type: "KEYDOWN",
        payload: {
          key: e.key as KeyNames,
          isCustomEntryAllowed,
          isMultiSelectable,
          multiSelectLimit,
        },
      });
    }
  };

  const setHighlightedOption = (index?: number) => () => {
    dispatch({
      type: "SET_HIGHLIGHTED_OPTION",
      payload: {
        index,
      },
    });
  };

  const onMultiSelectRemove = (option: ComboBoxOption) => {
    dispatch({
      type: "MULTI_SELECT_REMOVE",
      payload: {
        option,
        multiSelectLimit,
      },
    });

    inputRef.current?.focus();
  };

  const onTagClick =
    (option: ComboBoxOption) => (e: React.MouseEvent<HTMLButtonElement>) => {
      e.preventDefault();
      e.stopPropagation();

      !isReadOnly && onMultiSelectRemove(option);
    };

  const onTagKeyDown =
    (option: ComboBoxOption) => (e: React.KeyboardEvent<HTMLButtonElement>) => {
      if (isSelectionKey(e.key)) {
        e.preventDefault();
        e.stopPropagation();
        !isReadOnly && onMultiSelectRemove(option);
      }
    };

  const onShowAllTagsClick = () => {
    dispatch({
      type: "SHOW_ALL_TAGS",
    });

    if (!isReadOnly) {
      inputRef.current?.focus();
    } else {
      (tagContainerRef.current?.firstChild as HTMLElement).focus();
    }
  };

  const onTagBlur = (e: React.FocusEvent<HTMLButtonElement>) => {
    if (
      isReadOnly &&
      !comboBoxContainerRef.current?.contains(e.relatedTarget)
    ) {
      dispatch({
        type: "EXIT_INPUT",
        payload: {
          isMultiSelectable,
          isCustomEntryAllowed,
        },
      });
    }
  };

  const onClearButtonMouseDown = (e: React.MouseEvent<HTMLButtonElement>) => {
    e.preventDefault();

    dispatch({
      type: "CLEAR",
      payload: {
        isCustomEntryAllowed,
        isMultiSelectable,
      },
    });

    if (!comboBoxContainerRef.current?.contains(document.activeElement)) {
      inputRef.current?.focus();
    }
  };

  const onClearButtonKeydown = (e: React.KeyboardEvent<HTMLButtonElement>) => {
    if (isSelectionKey(e.key)) {
      e.preventDefault();

      dispatch({
        type: "CLEAR",
        payload: {
          isCustomEntryAllowed,
          isMultiSelectable,
        },
      });

      inputRef.current?.focus();
    }
  };

  const onOpenAutoFocus = (e: Event) => {
    e.preventDefault();

    inputRef.current?.focus();
  };

  return (
    <div
      ref={setThemeElement}
      className={classNames(
        "arc-ComboBox",
        suffixModifier("arc-ComboBox--size", size),
        {
          "arc-ComboBox--constrained": !isFluid,
          "arc-ComboBox--invalid": errorMessage,
          "arc-ComboBox--disabled": isDisabled,
          "arc-ComboBox--expanded": isExpanded,
          "arc-ComboBox--autoComplete": isAutocomplete,
          "arc-ComboBox--onDarkSurface": isDarkSurface,
          "arc-ComboBox--readOnly": isReadOnly,
        },
      )}
      {...filterAttrs(props)}
    >
      <div ref={comboBoxContainerRef}>
        <Popover.Root open={isExpanded}>
          <FormControl
            errorMessage={errorMessage}
            helper={helper}
            htmlFor={id}
            isDisabled={isDisabled}
            label={label}
            hideLabel={hideLabel}
            labelSize={size}
            requirementStatus={isRequired ? "required" : "optional"}
            disclosureTitle={disclosureTitle}
            disclosureText={disclosureText}
            onClickDisclosure={onClickDisclosure}
          >
            <Popover.Anchor>
              <div className="arc-ComboBox-container">
                <div
                  className={classNames("arc-ComboBox-inputContainer", {
                    "arc-ComboBox-inputContainer--selectedOptionMode":
                      selectedOptions.length,
                  })}
                >
                  <div className="arc-ComboBox-controls">
                    {selectedOptions.length > 0 && (
                      <ComboBoxTags
                        ref={tagContainerRef}
                        isReadOnly={isReadOnly}
                        inputSize={size}
                        isDisabled={isDisabled}
                        isDarkSurface={isDarkSurface}
                        isError={Boolean(errorMessage)}
                        showAllTags={showAllTags}
                        visibleTagCount={visibleTagCount}
                        selectedOptions={selectedOptions}
                        onShowAllTagsClick={onShowAllTagsClick}
                        onTagBlur={onTagBlur}
                        onTagClick={onTagClick}
                        onTagKeyDown={onTagKeyDown}
                      />
                    )}
                    <div className="arc-ComboBox-inputWrapper">
                      {prefixIcon && (
                        <div
                          onMouseDown={onMouseDown(true)}
                          className="arc-ComboBox-prefixIcon"
                        >
                          <Icon icon={prefixIcon} />
                        </div>
                      )}
                      <input
                        readOnly={isReadOnly}
                        className="arc-ComboBox-input"
                        type="text"
                        role="combobox"
                        autoComplete="off"
                        ref={getTextInputRef}
                        id={id}
                        name={name}
                        onMouseDown={onMouseDown(false)}
                        onFocus={onInputFocus}
                        onBlur={onInputBlur}
                        onChange={onInputChange}
                        onKeyDown={onInputKeyDown}
                        disabled={isDisabled}
                        required={isRequired}
                        value={value}
                        aria-describedby={ariaDescribedby}
                        aria-invalid={errorMessage ? "true" : "false"}
                        aria-autocomplete={isAutocomplete ? "list" : "none"}
                        aria-controls={listBoxId}
                        aria-expanded={isExpanded}
                        aria-activedescendant={
                          hasHighlightedOption
                            ? `${listBoxId}-${highlightedOptionIndex}`
                            : undefined
                        }
                      />
                    </div>
                  </div>
                  <div
                    className={classNames("arc-ComboBox-icons", {
                      "arc-ComboBox-icons--stack": selectedOptions.length,
                      "arc-ComboBox-icons--unreversed":
                        stackAutoCompleteIconFirst,
                    })}
                  >
                    {showClearButton && (
                      <div className="arc-ComboBox-iconContainer">
                        <Tooltip
                          asChild
                          zIndex={102}
                          title={clearButtonTooltip}
                          alignContent="center"
                          delayDuration={500}
                          side="bottom"
                        >
                          <ComboBoxClearButton
                            onBlur={onClearButtonBlur}
                            isDarkSurface={isDarkSurface}
                            inputSize={size}
                            tooltip={clearButtonTooltip}
                            onMouseDown={onClearButtonMouseDown}
                            onKeyDown={onClearButtonKeydown}
                          />
                        </Tooltip>
                      </div>
                    )}

                    {isAutocomplete && (
                      <div
                        onMouseDown={onMouseDown(true)}
                        className={classNames(
                          "arc-ComboBox-iconContainer",
                          "arc-ComboBox-iconContainer--autoComplete",

                          {
                            "arc-ComboBox-iconContainer--rotate": isExpanded,
                          },
                        )}
                      >
                        <div className="arc-ComboBox-autoCompleteIcon">
                          <ThemeIcon icon="comboboxAutoComplete" />
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </Popover.Anchor>
          </FormControl>

          <Popover.Portal container={themeElement}>
            <Popover.Content
              align="start"
              className="arc-ComboBox-popoverContent"
              sideOffset={parseInt(listVerticalPadding)}
              onInteractOutside={onInteractOutsideDropdown}
              onOpenAutoFocus={onOpenAutoFocus}
            >
              <div
                onMouseLeave={setHighlightedOption(undefined)}
                className="arc-ComboBox-listboxContainer"
              >
                <div
                  className={classNames("arc-ComboBox-listBoxInner", {
                    "arc-ComboBox-listBoxInner--onDarkSurface": isDarkSurface,
                  })}
                >
                  <VerticalSpace size={listVerticalPadding} />
                  <ul
                    tabIndex={-1}
                    className="arc-ComboBox-list"
                    role="listbox"
                    ref={setScrollPosition}
                    id={listBoxId}
                    aria-label={listBoxAriaLabel}
                    aria-multiselectable={isMultiSelectable}
                  >
                    <ComboBoxOptions
                      value={value}
                      limitReached={limitReached}
                      customOptionSupportingCopy={customOptionSupportingCopy}
                      noResultsSupportingCopy={noResultsSupportingCopy}
                      setOptionRef={setOptionRef}
                      options={options}
                      listBoxId={listBoxId}
                      isMultiSelectable={isMultiSelectable}
                      selectedOptions={selectedOptions}
                      singleSelectedOption={singleSelectedOption}
                      highlightedOptionIndex={highlightedOptionIndex}
                      onMouseMove={setHighlightedOption}
                      onMouseDown={onItemClick}
                    />
                  </ul>
                  <VerticalSpace size={listVerticalPadding} />
                </div>
              </div>
            </Popover.Content>
          </Popover.Portal>
        </Popover.Root>
      </div>
    </div>
  );
};

export interface ComboBoxProps extends Omit<
  FormControlProps,
  | "children"
  | "elementType"
  | "htmlFor"
  | "requirementStatus"
  | "helperUnderLabel"
  | "supplementaryInfo"
  | "labelPosition"
  | "labelSize"
> {
  /**
   * Ref to the underlying input element.
   */
  ref?: Ref<HTMLInputElement>;
  /**
   * Aria label for the results list.
   */
  listBoxAriaLabel: string;

  /**
   * Size of the `ComboBox` input.
   */
  size?: InputSize;

  /**
   * Options for the `ComboBox`.
   */
  options: string[];

  /**
   * Icon to appear before the input of the `ComboBox`.
   */
  prefixIcon?: ArcIcon;

  /**
   * Input name for the `ComboBox`.
   */
  name?: string;

  /**
   * Makes the `ComboBox` a required field.
   */
  isRequired?: boolean;

  /**
   * Default value for the `ComboBox`.
   */
  defaultValue?: string;

  /**
   * Default selected values for the `ComboBox`. Only applied if `isMultiSelectable` is true.
   */
  defaultSelectedValues?: string[];

  /**
   * Blur event handler for the `ComboBox`.
   */
  onBlur?: FocusHandler;

  /**
   * Focus event handler for the `ComboBox`.
   */
  onFocus?: FocusHandler;

  /**
   * Callback function used to update the `ComboBox`
   * value, for example `e => setValue(e.target.value)`.
   */
  onChange?: (selectedValue: string | string[] | null) => void;

  /**
   * Allows multiple items to be selected if true.
   */
  isMultiSelectable?: boolean;

  /**
   * Allows a limit to the number of options you can select on multi select.
   * If the limit is reached, no more selections will be permitted.
   */
  multiSelectLimit?: number;

  /**
   * Filters results when typing if true.
   */
  isAutocomplete?: boolean;

  /**
   * Makes the `ComboBox` readonly.
   */
  isReadOnly?: boolean;

  /**
   * Current value of the TextInput.
   */
  value?: string;

  /**
   * Sets the `ComboBox` to 100% width.
   */
  isFluid?: boolean;

  /**
   * Allows the user to enter a custom value in the `ComboBox` that isn't one of the provided options.
   */
  isCustomEntryAllowed?: boolean;

  /**
   * Allows a limit to the number of tags visible on multi select.
   * When the limit is reached, a link to reveal the hidden tags will show.
   * If ommitted there is no limit.
   */
  visibleTagCount?: number;

  /**
   * Supporting copy for when no results show.
   */
  noResultsSupportingCopy?: string;

  /**
   * Supporting copy for the custom option on multi select.
   */
  customOptionSupportingCopy?: string;

  /**
   * Enables a button that clears the input to show when it has a value.
   */
  isClearButtonEnabled?: boolean;

  /**
   * Text for the clear input button and tooltip. This is also used for screen readers.
   */
  clearButtonTooltip?: string;

  /**
   * Threshold for fuzzy search matching. A value of 0 requires a perfect match (substring-like behavior),
   * while a value of 1 matches everything. Defaults to 0.45.
   */
  fuzzyThreshold?: number;
}
