import React, { type Ref, type ReactNode } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { handleLinkClick } from "../../../helpers/handle-link-click";

export const BreadcrumbsLink = ({
  onClick,
  href,
  isActive,
  children,
  ref,
  ...props
}: BreadcrumbsLinkProps) => {
  return (
    <>
      {isActive || href === undefined ? (
        <span
          onClick={onClick}
          className={classNames({
            "arc-Breadcrumbs-text": true,
            "arc-Breadcrumbs-text--active": isActive,
          })}
          {...filterAttrs(props)}
        >
          {children}
        </span>
      ) : (
        <a
          {...(onClick && ref
            ? { onClick: onClick }
            : { onClick: handleLinkClick({ handler: onClick }) })}
          className="arc-Breadcrumbs-text"
          ref={ref}
          href={href}
          {...filterAttrs(props)}
        >
          {children}
        </a>
      )}
    </>
  );
};

export interface BreadcrumbsLinkProps {
  /**
   * Ref to the underlying anchor element.
   */
  ref?: Ref<HTMLAnchorElement>;

  /**
   * Render children of `breadcrumbs.link`
   */
  children?: ReactNode;

  /**
   * Where breadcrumb linkshould lead too
   */
  href?: string;

  /**
   * Pass a function to the breadcrumb item
   */
  onClick?: () => void;

  /**
   * Highlights item in breadcrumb (This also removes the a tag and any links)
   */
  isActive?: boolean;

  /**
   * React router property
   */
  navigate?: () => void;
}
