import React from "react";

import { ThemeIcon } from "../../../../../ThemeIcon";

import { useSubNavContext } from "../../../NavigationHeaderSubnav/NavigationHeaderSubnav.provider";

export const SearchMenuCloseButton = () => {
  const { isOpen, setIsOpen, onOpenChange } = useSubNavContext();

  const onClose = () => {
    setIsOpen(!isOpen);
    onOpenChange?.(!isOpen);
  };

  return (
    <button
      aria-label="close"
      onClick={onClose}
      className="arc-SearchMenuCloseButton"
    >
      <ThemeIcon size={32} icon="modalClose" />
    </button>
  );
};
