import React, { useState } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { type HeadingLevel } from "../Heading";

import { Image, type ImageProps } from "../Image";

import { VerticalSpace } from "../VerticalSpace";

import { CardFooter, type CardFooterProps } from "../CardFooter";

import { CardHeading } from "../CardHeading";

import { Text } from "../Text";

/** Use `HorizontalCard` to display card content in a horizontal layout. */
export const HorizontalCard = ({
  text,
  heading,
  headingLevel,
  img,
  metaText,
  url,
  onClick,
  ...props
}: HorizontalCardProps) => {
  const [showHoverState, setShowHoverState] = useState(false);

  const handleShowHoverState = (show: boolean) => () => setShowHoverState(show);

  return (
    <div
      className={classNames("arc-HorizontalCard", {
        "arc-HorizontalCard--outlined": (url || onclick) && showHoverState,
      })}
      {...filterAttrs(props)}
    >
      {img?.src && (
        <div className="arc-HorizontalCard-image">
          <Image fit="cover" anchor="C" {...img} />
        </div>
      )}

      <div className="arc-HorizontalCard-content">
        <VerticalSpace size="12" />
        <CardHeading
          heading={heading}
          headingLevel={headingLevel}
          href={url}
          onClick={onClick}
          onMouseEnter={handleShowHoverState(true)}
          onMouseLeave={handleShowHoverState(false)}
          onFocus={handleShowHoverState(true)}
          onBlur={handleShowHoverState(false)}
          isHovered={showHoverState}
        />

        <VerticalSpace size="12" />

        <Text>{text}</Text>

        <VerticalSpace size="24" />
        <CardFooter
          metaText={metaText}
          buttonIcon="arrow"
          isHovered={showHoverState}
          buttonSize="s"
        />
      </div>
    </div>
  );
};

export interface HorizontalCardProps {
  /**
   * Heading for the HorizontalCard.
   */
  heading: string;

  /**
   * Heading level for the HorizontalCard heading.
   */
  headingLevel?: HeadingLevel;

  /**
   * Text content for the HorizontalCard
   */
  text: string;

  /**
   * Uppercase label for the HorizontalCard.
   */

  label?: string;

  /**
   * Url for the HorizontalCard. Makes the whole card a link.
   */
  url?: string;

  /**
   * Image for the HorizontalCard.
   */
  img?: Pick<
    ImageProps,
    | "src"
    | "alt"
    | "loading"
    | "sizes"
    | "srcSet"
    | "anchor"
    | "fadeOnLoad"
    | "fit"
    | "fetchPriority"
  >;

  /**
   * Text to show adjacent to the cta, can be either a date or text. Its recommended to pass dates as Date objects so the component can render them correctly.
   */
  metaText?: CardFooterProps["metaText"];

  /**
   * Click handler for the HorizontalCard. Only applied when a url is provided.
   */
  onClick?: (e: React.MouseEvent<HTMLAnchorElement>) => void;
}
