import React, { useId } from "react";

import { type NavigationHeaderCategoryMenuNavItem } from "../../types/nav-item";

import { NavigationHeaderPanelHeading } from "../NavigationHeaderPanelHeading";
import { NavigationHeaderCollapsingNavList } from "../NavigationHeaderCollapsingNavList";
import {
  NavigationHeaderSubnav,
  NavigationHeaderSubnavContent,
  NavigationHeaderSubnavTrigger,
} from "../NavigationHeaderSubnav";

export const NavigationHeaderCategoryLinks = ({
  items,
  panelHeading,
  ariaLabel,
  onClick,
  text,
  onOpenChange,
}: NavigationHeaderCategoryLinksProps) => {
  const id = useId();

  return (
    <NavigationHeaderSubnav onOpenChange={onOpenChange}>
      <NavigationHeaderSubnavTrigger ariaLabel={ariaLabel} onClick={onClick}>
        {text}
      </NavigationHeaderSubnavTrigger>

      <NavigationHeaderSubnavContent
        background="lightElevatedTight"
        menuTitle={text}
        description="Use tab keys to navigate. Press Escape to close."
      >
        <div className="arc-NavigationHeaderCategoryLinks">
          <NavigationHeaderPanelHeading {...panelHeading} />

          <div className="arc-NavigationHeaderCategoryLinks-container">
            {items.map((item, i) => (
              <div key={`${id}-NavigationHeader-category-link-item-${i}`}>
                <NavigationHeaderCollapsingNavList
                  {...item}
                  defaultOpen
                  revealLinkIconOnHover
                  autoFocusOnExpand={false}
                  background="light"
                />
              </div>
            ))}
          </div>
        </div>
      </NavigationHeaderSubnavContent>
    </NavigationHeaderSubnav>
  );
};

type NavigationHeaderCategoryLinksProps = Omit<
  NavigationHeaderCategoryMenuNavItem,
  "type" | "visibleFrom"
>;
