import React, { useId, useRef, useState } from "react";

import classNames from "classnames";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";

import { type NavigationHeaderMegaMenuNavItem } from "../../../../types/nav-item";

import { VerticalSpace } from "../../../../../VerticalSpace";
import { Icon } from "../../../../../Icon";
import { Heading } from "../../../../../Heading";
import { Surface } from "../../../../../Surface";
import { SemanticButton } from "../../../../../SemanticButton";

import { SideMenuDisclosure } from "../SideMenuDisclosure";
import { SideMenuSubMenu } from "../SideMenuSubMenu";
import { useNavigationHeaderSideMenuContext } from "../../NavigationHeaderSideMenu.provider";
import { NavigationHeaderFeatureCard } from "../../../NavigationHeaderFeatureCard";
import { NavigationHeaderCollapsingNavList } from "../../../NavigationHeaderCollapsingNavList";
import { NavigationHeaderPanelLink } from "../../../NavigationHeaderPanelLink";

export const MegaMenuSubMenu = ({
  item,
  heading,
  backButtonLabel,
  backButtonAriaLabel,
}: {
  heading: string;
  item: NavigationHeaderMegaMenuNavItem["tabs"][number];
  backButtonLabel?: string;
  backButtonAriaLabel?: string;
}) => {
  const id = useId();
  const triggerRef = useRef<HTMLButtonElement>(null);
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const { menuColorConfig } = useNavigationHeaderSideMenuContext();

  const onItemClick = () => {
    setIsDrawerOpen(true);
  };

  const onBackClick = () => {
    setIsDrawerOpen(false);
  };

  const onCloseAutoFocus = () => {
    triggerRef.current?.focus();
  };

  return (
    <>
      <SemanticButton
        aria-haspopup="dialog"
        aria-expanded={isDrawerOpen}
        ref={triggerRef}
        aria-label={item.triggerText}
        className={classNames(
          "arc-SideMenuMegaMenuItem-button",
          suffixModifier(
            "arc-SideMenuMegaMenuItem-button--on",
            menuColorConfig.menuColorType,
          ),
        )}
        onClick={onItemClick}
      >
        <div className="arc-SideMenuMegaMenuItem-buttonIcon">
          <Icon icon={item.icon} size={32} />
        </div>

        <div className="arc-SideMenuMegaMenuItem-buttonText">
          <Heading size="xxs">{item.triggerText}</Heading>
        </div>
      </SemanticButton>

      <SideMenuSubMenu
        isOpen={isDrawerOpen}
        heading={heading}
        headingSize="s"
        onBackClick={onBackClick}
        onCloseAutoFocus={onCloseAutoFocus}
        backButtonLabel={backButtonLabel}
        backButtonAriaLabel={backButtonAriaLabel}
      >
        <NavigationHeaderPanelLink {...item.panelLink} icon={item.icon} />

        <VerticalSpace size="16" />

        <div className="arc-SideMenuMegaMenuItem-navItems">
          {item.items.map((navItem, navItemIndex) => (
            <NavigationHeaderCollapsingNavList
              {...navItem}
              isBottomSpacing
              key={`${id}-side-mega-menu-drawer-navItem-${navItemIndex}`}
            />
          ))}
        </div>
      </SideMenuSubMenu>
    </>
  );
};

export const SideMenuMegaMenuItem = ({
  featureCards,
  text,
  panelHeading,
  tabs,
  backButtonLabel,
  backButtonAriaLabel,
}: SideMenuMegaMenuItemProps) => {
  const id = useId();

  return (
    <SideMenuDisclosure heading={text}>
      <VerticalSpace size="4" />
      {tabs.map((item, itemIndex) => (
        <MegaMenuSubMenu
          key={`${id}-side-menu-mega-menu-item-${itemIndex}`}
          item={item}
          heading={panelHeading.heading}
          backButtonLabel={backButtonLabel}
          backButtonAriaLabel={backButtonAriaLabel}
        />
      ))}
      {featureCards && (
        <Surface isTransparent background="light-white">
          <div className="arc-SideMenuMegaMenuItem-featureCards">
            <div className="arc-SideMenuMegaMenuItem-featureCardContainer">
              {featureCards.map((card, cardIndex) => (
                <NavigationHeaderFeatureCard
                  title={card.title}
                  href={card.href}
                  isFeatured={card.isFeatured}
                  label={card.label}
                  onClick={card.onClick}
                  key={`${id}-side-menu-mega-menu-card-${cardIndex}`}
                />
              ))}
            </div>
          </div>
        </Surface>
      )}
    </SideMenuDisclosure>
  );
};

type SideMenuMegaMenuItemProps = NavigationHeaderMegaMenuNavItem;
