import React, { type ReactNode } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { type ExtentableContainer } from "../../types/extendable-container";

import { Section } from "../Section";

/**
 * Use `UniversalHeader` to display a group-level page header.
 */
export const UniversalHeader = ({
  children,
  ContentSlot,
  isPill = false,
  isExtended = false,
  isFluid = false,
  ...props
}: UniversalHeaderProps) => {
  return (
    <nav
      className={classNames("arc-UniversalHeader", {
        "arc-UniversalHeader--pill": isPill,
      })}
      aria-label="universal navigation"
      {...filterAttrs(props)}
    >
      <Section isFullWidth={isFluid} isExtended={isExtended}>
        <div className="arc-UniversalHeader-content">
          <ul className="arc-UniversalHeader-items">
            {children}
            {ContentSlot && (
              <li className="arc-UniversalHeader-contentSlot">{ContentSlot}</li>
            )}
          </ul>
        </div>
      </Section>
    </nav>
  );
};

export const UniversalHeaderItem = ({
  children,
  href,
  isActive = false,
  ...props
}: UniversalHeaderItemProps) => {
  return (
    <li {...filterAttrs(props)}>
      <a
        className={classNames({
          "arc-UniversalHeader-link": true,
          "arc-UniversalHeader-link--isActive": isActive,
        })}
        href={href}
        aria-current={isActive ? "page" : undefined}
      >
        {children}
      </a>
    </li>
  );
};

export interface UniversalHeaderItemProps {
  /**
   * Contents of the UniversalHeaderItem.
   */
  children: ReactNode;

  /**
   * A URL to link to when the Item is clicked or touched.
   */
  href: string;

  /**
   * An isActive prop state if the current link is active.
   */
  isActive?: boolean;
}

export interface UniversalHeaderProps extends ExtentableContainer {
  /**
   * Contents of the UniversalHeader Must be
   * UniversalHeaderItem components.
   */
  children: ReactNode;

  /**
   * Set the nav bar to be a pill shape.
   */
  isPill?: boolean;

  /**
   * Sets the UniversalHeader to be full width.
   */
  isFluid?: boolean;

  /**
   * A Slot to accept react node. Any content with this slot will be aligned right.
   */
  ContentSlot?: ReactNode;
}
