import React from "react";

import { Skeleton } from "../../Skeleton";

export const MenuSkeletonItem = ({
  hasLeadingIcon = false,
  hasTrailingIcon = false,
  hasSupportingText = false,
}: MenuSkeletonItemProps) => {
  return (
    <div className="arc-MenuSkeletonItem">
      {hasLeadingIcon && (
        <div className="arc-MenuSkeletonItem-leadingIcon">
          <Skeleton isCircle width={24} height={24} />
        </div>
      )}

      <div className="arc-MenuSkeletonItem-textWrapper">
        <Skeleton height={24} />
        {hasSupportingText && (
          <div className="arc-MenuSkeletonItem-supportingText">
            <Skeleton height={16} />
          </div>
        )}
      </div>

      {hasTrailingIcon && (
        <div className="arc-MenuSkeletonItem-trailingIcon">
          <Skeleton isCircle width={24} height={24} />
        </div>
      )}
    </div>
  );
};

export interface MenuSkeletonItemProps {
  /**
   * Whether to show a skeleton for the leading icon.
   */
  hasLeadingIcon?: boolean;
  /**
   * Whether to show a skeleton for the trailing icon.
   */
  hasTrailingIcon?: boolean;
  /**
   * Whether to show a skeleton for the supporting text.
   */
  hasSupportingText?: boolean;
}
