import React from "react";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { BtIconArrowRight } from "@arc-ui/icons/BtIconArrowRight";

import { ButtonV2, type ButtonV2Props } from "../ButtonV2";

import { Image, type ImageProps } from "../Image";
import { VerticalSpace } from "../VerticalSpace";

/** ThumbnailSignpost` has been **deprecated from arc component package** and moved into the **community-components package**. It can be seen on the community components storybook.
 *
 * Use `ThumbnailSignpost` to highlight key information or navigation points with an accompanying thumbnail image or icon.*/
export const ThumbnailSignpost = ({
  text,
  title,
  img,
  button,
  ...props
}: ThumbnailSignpostProps) => (
  <div className="arc-ThumbnailSignpost" {...filterAttrs(props)}>
    {img?.src && (
      <div className="arc-ThumbnailSignpost-image">
        <Image {...img} />
      </div>
    )}

    <div className="arc-ThumbnailSignpost-content">
      <span className="arc-ThumbnailSignpost-heading">{title}</span>

      <VerticalSpace size="8" />
      {text}
      <ButtonV2 buttonStyle="compact" icon={BtIconArrowRight} {...button} />
    </div>
  </div>
);

export interface ThumbnailSignpostProps {
  /**
   * Title for the ThumbnailSignpost.
   */
  title: string;

  /**
   * Text content for the ThumbnailSignpost.
   */
  text: string;

  /**
   * Button properties in the ThumbnailSignpost.
   */
  button: Partial<
    Pick<
      ButtonV2Props,
      | "onClick"
      | "ariaLabel"
      | "ariaHasPopup"
      | "ariaExpanded"
      | "ariaControls"
      | "target"
      | "href"
    >
  > & {
    label: ButtonV2Props["label"];
  };

  /**
   * Label for the button in the ThumbnailSignpost.
   */
  buttonOnClick?: ButtonV2Props["onClick"];
  /**
   * Image properties for the ThumbnailSignpost.
   */
  img?: Pick<
    ImageProps,
    | "src"
    | "alt"
    | "loading"
    | "sizes"
    | "srcSet"
    | "anchor"
    | "fadeOnLoad"
    | "fetchPriority"
  >;
}
