import { isDateValid } from "./is-date-valid";
import { parseRangeString } from "./parse-range-string";

export const convertRangeStringToDates = (value: string = ""): Date[] => {
  const { start, end } = parseRangeString(value);

  return [
    ...(isDateValid(start.date)
      ? [new Date(`${start.year}-${start.month}-${start.day}`)]
      : []),
    ...(isDateValid(end.date)
      ? [new Date(`${end.year}-${end.month}-${end.day}`)]
      : []),
  ];
};
