import React, { useContext } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { SurfaceContext } from "../Surface/Surface";

/**
 * Use `Rule` to display a horizontal or vertical rule.
 */
export const Rule = ({ orientation = "horizontal", ...props }: RuleProps) => {
  const { surface } = useContext(SurfaceContext);

  return (
    <hr
      className={classNames({
        "arc-Rule": true,
        [`arc-Rule--${orientation}`]: true,
        "arc-Rule--onDarkSurface": surface === "dark",
      })}
      {...filterAttrs(props)}
    />
  );
};

export interface RuleProps {
  orientation?: "horizontal" | "vertical";
}
