import React, { useContext, useState } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { SurfaceContext } from "../Surface";
import { Heading, type HeadingLevel } from "../Heading/Heading";
import { Image, type ImageProps } from "../Image/Image";
import { CardFooter, type CardFooterProps } from "../CardFooter";
import { CardHeading, type CardHeadingSize } from "../CardHeading";
import { VerticalSpace } from "../VerticalSpace";
import { ConditionalWrapper } from "../ConditionalWrapper";

/** Use `ImpactCard` for important content that needs additional hierarchy and prominence.  */
export const ImpactCard = ({
  url,
  onClick,
  heading,
  img,
  label,
  minHeight,
  headingSize = "m",
  headingWordWrap = false,
  linkData = {},
  pathway = "light",
  headingLevel = "2",
  buttonIcon = "arrow",
  labelLevel = "3",
  preserveAspectRatios,
  ...props
}: ImpactCardProps) => {
  const [showHoverState, setShowHoverState] = useState(false);
  const { surface } = useContext(SurfaceContext);

  const handleShowHoverState = (show: boolean) => () => setShowHoverState(show);

  const isDarkPathway = pathway === "dark";

  const aspectRatioClassNames = preserveAspectRatios
    ? Object.entries(preserveAspectRatios)
        .filter(([, value]) => value)
        .map(
          ([breakpoint, ratio]) =>
            `arc-ImpactCard--preserveAspectRatio-${breakpoint}-${ratio}`,
        )
    : [];

  const minHeightStyle = !preserveAspectRatios && {
    minHeight,
  };

  return (
    <ConditionalWrapper
      condition={Boolean(preserveAspectRatios)}
      wrapper={(children) => (
        <div className="arc-ImpactCard--preserveAspectRatioWrapper">
          {children}
        </div>
      )}
    >
      <div
        style={{ ...minHeightStyle }}
        className={classNames("arc-ImpactCard", ...aspectRatioClassNames, {
          "arc-ImpactCard--darkPathway": isDarkPathway,
          "arc-ImpactCard--outlined": url && showHoverState,
          "arc-ImpactCard--isHovered": showHoverState,
          "arc-ImpactCard--onDarkSurface": surface === "dark",
        })}
        {...filterAttrs(props)}
      >
        <div className="arc-ImpactCard-backgroundImageContainer">
          <Image fit="cover" alt="" {...img} />
        </div>

        <div className="arc-ImpactCard-contentContainer">
          {label && (
            <div className="arc-ImpactCard-label">
              <Heading level={labelLevel} fontStyle="overline">
                {label}
              </Heading>
              <VerticalSpace size="16" />
            </div>
          )}

          <CardHeading
            heading={heading}
            size={headingSize}
            headingLevel={headingLevel}
            linkData={linkData}
            href={url}
            onClick={onClick}
            onMouseEnter={handleShowHoverState(true)}
            onMouseLeave={handleShowHoverState(false)}
            onFocus={handleShowHoverState(true)}
            onBlur={handleShowHoverState(false)}
            headingWordWrap={headingWordWrap}
            isHovered={showHoverState && !isDarkPathway}
          />
        </div>
        <CardFooter
          buttonIcon={buttonIcon}
          showButton
          isDarkPathway={isDarkPathway}
          isHovered={showHoverState}
        />
      </div>
    </ConditionalWrapper>
  );
};

type ImpactCardPathway = "light" | "dark";
type AspectRatios = "3-4" | "10-16";

export interface ImpactCardProps {
  /**
   * Heading for the ImpactCard.
   */
  heading: string;

  /**
   * Heading size for the ImpactCard.
   */
  headingSize?: CardHeadingSize;

  /**
   * Whether long words in heading should be wrapped.
   */
  headingWordWrap?: boolean;

  /**
   * Url for the ImpactCard. Makes the whole card a link
   */
  url: string;

  /**
   * Sets a dark or light background for the ImpactCard.
   */
  pathway?: ImpactCardPathway;

  /**
   * Heading level for the ImpactCard heading.
   */
  headingLevel?: HeadingLevel;

  /**
   * Uppercase label for the ImpactCard.
   */
  label?: string;

  /**
   * Sets a minimum height for the ImpactCard.
   */
  minHeight?: number;

  /**
   * Click handler for the ImpactCard.
   */
  onClick?: (e: React.MouseEvent<HTMLAnchorElement>) => void;

  /**
   * Object of `data-` attributes to render on internal anchor element, e.g.
   * `{ data-analytics-link: "My link"}` => `<a data-analytics-link="My link">`.
   */
  linkData?: { [key: string]: string };

  /**
   * Image props for the ImpactCard. Consider avoiding alt if the image is for decorative purposes only.
   */
  img: Pick<
    ImageProps,
    | "src"
    | "alt"
    | "loading"
    | "sizes"
    | "srcSet"
    | "anchor"
    | "fadeOnLoad"
    | "fetchPriority"
  >;

  /**
   * Icon for the ImpactCard CTA button
   */
  buttonIcon?: CardFooterProps["buttonIcon"];

  /**
   * Heading level for the ImpactCard lebel.
   */
  labelLevel?: HeadingLevel;

  /**
   * Preserve aspect ratio of the ImpactCard. Set minHeight depending on Card width. Overwrites minHeight prop value.
   */
  preserveAspectRatios?: {
    xs?: AspectRatios;
    s?: AspectRatios;
    m?: AspectRatios;
    l?: AspectRatios;
    xl?: AspectRatios;
    xxl?: AspectRatios;
    xxxl?: AspectRatios;
  };
}
