import { type ComboBoxOption } from "../types/combobox-option";

export const getKeydownOptionToHighlight = ({
  options,
  isNext,
  highlightedOptionIndex,
}: {
  options: ComboBoxOption[];
  isNext: boolean;
  highlightedOptionIndex?: number;
}) => {
  const currentHighlightIndex = highlightedOptionIndex ?? -1;

  const isAtBoundary = isNext
    ? currentHighlightIndex === options.length - 1
    : currentHighlightIndex <= 0;

  const boundaryIndex = isNext ? 0 : options.length - 1;

  const nextOptionIndex = isNext
    ? currentHighlightIndex + 1
    : currentHighlightIndex - 1;

  return isAtBoundary ? boundaryIndex : nextOptionIndex;
};
