import React, {
  createContext,
  useContext,
  useEffect,
  useRef,
  useState,
  type ReactNode,
  type RefObject,
} from "react";

import classNames from "classnames";

import { ArcSizeBreakpointsL } from "@arc-ui/tokens-arc";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { BtIconChevronRight2Px } from "@arc-ui/icons/BtIconChevronRight2Px";

import { BrandLogo } from "../BrandLogo";
import { type subBrands } from "../BrandLogo/BrandLogo";
import { useMediaQuery } from "../../hooks";
import { Surface } from "../Surface";

import { handleLinkClick } from "../../helpers/handle-link-click";

import { Icon } from "../Icon";

import { SiteHeaderV2MenuButton } from "./components/SiteHeaderV2MenuButton";

const defaultContext: {
  transparent: boolean;
  menubarRef: RefObject<HTMLUListElement | null> | null;
} = { transparent: false, menubarRef: null };
const Context = createContext(defaultContext);
const { Provider } = Context;

/**
 * Use `SiteHeaderV2` to display brand logo and navigation at the top of a page.
 */
export const SiteHeaderV2 = ({
  children,
  basket,
  hasLogin = true,
  isTransparent = false,
  loginHref = "/login",
  logoOnClick,
  loginOnClick,
  loginTitle = "Log in / Register",
  logoHref = "/",
  logoLabel = "Home",
  search,
  subBrand,
  ...props
}: SiteHeaderV2Props) => {
  const [hasClientSideJavaScript, setHasClientSideJavaScript] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const isMinWidthArcBreakpointL = useMediaQuery(
    `(min-width: ${ArcSizeBreakpointsL})`,
  );
  const menubarRef = useRef<HTMLUListElement | null>(null);

  useEffect(() => {
    if (!isMinWidthArcBreakpointL && menuOpen) {
      document.body.classList.add("arc-body--overflowHidden");
    } else {
      document.body.classList.remove("arc-body--overflowHidden");
    }

    return () => {
      document.body.classList.remove("arc-body--overflowHidden");
    };
  }, [isMinWidthArcBreakpointL, menuOpen]);

  useEffect(() => {
    const handleKeydown = (e: KeyboardEvent) => {
      if (e.key === "Escape" || e.keyCode === 27) {
        setMenuOpen(false);
      }
    };

    window.addEventListener("keydown", handleKeydown);

    return () => {
      window.removeEventListener("keydown", handleKeydown);
    };
  }, [setMenuOpen]);

  useEffect(() => {
    menubarRef?.current?.classList?.add("noFocus");
  }, []);

  useEffect(() => {
    const handleClick = (e: Event) => {
      if ((e.target as Element).getAttribute("href")) {
        setMenuOpen(false);
      }
    };

    document.addEventListener("click", handleClick);

    return () => {
      document.removeEventListener("click", handleClick);
    };
  }, [setMenuOpen]);

  useEffect(() => {
    // useEffect does not run in ReactDomServer renders
    setHasClientSideJavaScript(true);
  }, [setHasClientSideJavaScript]);

  return (
    <Provider value={{ transparent: isTransparent, menubarRef }}>
      <div
        className={classNames({
          [`arc-SiteHeaderV2`]: true,
          [`arc-SiteHeaderV2--menuOpen`]: menuOpen,
          [`arc-no-js`]: !hasClientSideJavaScript,
        })}
        {...filterAttrs(props)}
        data-transparent={isTransparent || null}
      >
        <Surface
          background={
            !isTransparent || (menuOpen && !isMinWidthArcBreakpointL)
              ? "dark-brand-01"
              : undefined
          }
        >
          <div className="arc-SiteHeaderV2-inner">
            <a
              className="arc-SiteHeaderV2-brand"
              onClick={handleLinkClick({
                handler: logoOnClick,
              })}
              href={logoHref}
            >
              <BrandLogo label={logoLabel} subBrand={subBrand} />
            </a>
            {children && (
              <nav className="arc-SiteHeaderV2-nav">
                <div className="arc-SiteHeaderV2-menuButton">
                  <SiteHeaderV2MenuButton
                    menuOpen={menuOpen}
                    setMenuOpen={setMenuOpen}
                  />
                </div>
                <div className="arc-SiteHeaderV2-main" tabIndex={-1}>
                  <ul
                    role="menubar"
                    aria-label="navigation"
                    ref={menubarRef}
                    className="arc-SiteHeaderV2-navItems"
                  >
                    {children}
                  </ul>
                  {hasLogin && (
                    <>
                      {loginOnClick ? (
                        <div className="arc-SiteHeaderV2-mobileButtonContainer">
                          <button
                            className="arc-SiteHeaderV2-mobileLogin"
                            onClick={loginOnClick}
                          >
                            {loginTitle}
                            <span className="arc-SiteHeaderV2-mobileChevron">
                              <Icon icon={BtIconChevronRight2Px} />
                            </span>
                          </button>
                        </div>
                      ) : (
                        <div className="arc-SiteHeaderV2-mobileButtonContainer">
                          <a
                            className="arc-SiteHeaderV2-mobileLogin"
                            href={loginHref}
                          >
                            {loginTitle}
                            <span className="arc-SiteHeaderV2-mobileChevron">
                              <Icon icon={BtIconChevronRight2Px} />
                            </span>
                          </a>
                        </div>
                      )}
                    </>
                  )}
                </div>
              </nav>
            )}
            {(basket || hasLogin || search) && (
              <div className="arc-SiteHeaderV2-secondary">
                {search ? (
                  <div className="arc-SiteHeaderV2-search">{search}</div>
                ) : null}
                {basket ? (
                  <div className="arc-SiteHeaderV2-basket">{basket}</div>
                ) : null}
                {hasLogin && (
                  <>
                    {loginOnClick ? (
                      <div
                        className="arc-SiteHeaderV2-loginLink arc-SiteHeaderV2-loginLink--function"
                        onClick={loginOnClick}
                      >
                        {loginTitle}
                      </div>
                    ) : (
                      <a
                        className="arc-SiteHeaderV2-loginLink"
                        href={loginHref}
                      >
                        {loginTitle}
                      </a>
                    )}
                  </>
                )}
              </div>
            )}
          </div>
        </Surface>
      </div>
    </Provider>
  );
};

export function useHeaderV2Context() {
  return useContext(Context);
}

export interface SiteHeaderV2Props {
  /**
   * Contents of the SiteHeaderV2 Must be SiteHeaderV2NavItem or
   * SiteHeaderV2NavItemWithSubNav components.
   */
  children?: ReactNode;

  /**
   * Basket component for the SiteHeaderV2
   */
  basket?: ReactNode;

  /**
   * Should account login links be included in the SiteHeaderV2?
   */
  hasLogin?: boolean;

  /**
   * Should the SiteHeaderV2 have a transparent background?
   */
  isTransparent?: boolean;

  /**
   * A URL to link to when SiteHeaderV2 logo is clicked or touched.
   */
  loginHref?: string;

  /**
   * A Function to run to when SiteHeaderV2 logo is clicked or touched.
   */
  logoOnClick?: () => void;

  /**
   * A Function to run to when SiteHeaderV2 login links are clicked or touched.
   */
  loginOnClick?: () => void;

  /**
   * Text to display in SiteHeaderV2 login links.
   */
  loginTitle?: string;

  /**
   * A URL to link to when the SiteHeaderV2 brand logo link is clicked or touched.
   */
  logoHref?: string;

  /**
   * Accessible text for the SiteHeaderV2 brand logo link.
   */
  logoLabel?: string;

  /**
   * Search component for the SiteHeaderV2
   */
  search?: ReactNode;

  /**
   * Optional sub-brand variant. Only applies to BT.
   */
  subBrand?: (typeof subBrands)[number];
}

export { Context as SiteHeaderV2Context };
