import Fuse from "fuse.js";

import { type ComboBoxOption } from "../types/combobox-option";

/**
 * Internal default score threshold for fuzzy matching.
 * Options with a Fuse.js score above this value (less similar) are excluded.
 */
const FUZZY_SCORE_THRESHOLD = 0.45;

/**
 * Filters options using fuzzy matching.
 * Returns options sorted by relevance (best match first).
 *
 * @param options - The list of options to search through.
 * @param value - The search input value.
 * @param threshold - Fuse.js threshold (0 = exact match, 1 = match anything). Defaults to 0.45.
 */
export const fuzzySearch = (
  options: string[],
  value: string,
  threshold: number = FUZZY_SCORE_THRESHOLD,
): ComboBoxOption[] => {
  if (!value.trim()) {
    return options.map((option) => ({ text: option, isCustom: false }));
  }

  const fuse = new Fuse(options, {
    includeScore: true,
    threshold,
    isCaseSensitive: false,
    shouldSort: true,
    ignoreLocation: true,
  });

  const results = fuse.search(value);

  return results.map((result) => ({
    text: result.item,
    isCustom: false,
  }));
};
