import React, { type Ref } from "react";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import {
  ProgressStepper,
  type ProgressStepperProps,
} from "../ProgressStepper/ProgressStepper";

/** Use `ProgressStepperOverflow` to wrap `ProgressStepperItem`s and allow overflow behaviour. */
export const ProgressStepperOverflow = ({
  ref,
  children,
  size,
  invertLabelPosition,
  offsetLeft = 24,
  ...props
}: ProgressStepperOverflowProps) => {
  return (
    <div
      className="arc-ProgressStepperOverflow"
      style={{ paddingLeft: offsetLeft }}
      {...filterAttrs(props)}
    >
      <ProgressStepper
        ref={ref}
        size={size}
        invertLabelPosition={invertLabelPosition}
        isFluid={false}
      >
        {children}
      </ProgressStepper>
    </div>
  );
};

export interface ProgressStepperOverflowProps extends Omit<
  ProgressStepperProps,
  "isFluid" | "isExpandable" | "direction"
> {
  /**
   * Ref to the underlying ol element.
   */
  ref?: Ref<HTMLOListElement>;
  /**
   * Children of `<ProgressStepperOverflow  />` should only contain `<ProgressStepperItem />`
   */
  children?: React.ReactNode;

  /**
   * Add an offset to the start of the steps.
   */
  offsetLeft?: 0 | 8 | 12 | 16 | 24 | 32 | 40;
}
