import React from "react";

import classNames from "classnames";
import { isDate, format } from "date-fns";

import { ThemeIcon, type ThemeIconNames } from "../ThemeIcon";

/** Use `CardFooter` internally within card components to display supporting actions or information at the bottom of a card. */
export const CardFooter = ({
  metaText,
  buttonIcon = "arrow",
  buttonSize = "m",
  isDarkPathway = false,
  showButton = true,
  isHovered = false,
}: CardFooterProps) => {
  const icons: Record<CardFooterIcon, ThemeIconNames> = {
    arrow: "cardRight",
    play: "cardPlay",
  };

  return (
    <div
      className={classNames("arc-CardFooter", {
        "arc-CardFooter--darkPathway": isDarkPathway,
      })}
    >
      <div className="arc-CardFooter-metaTextContainer">
        {metaText && (
          <div className="arc-CardFooter-metaText">
            {isDate(metaText) ? (
              <time dateTime={format(metaText as Date, "yyyy-MM-dd")}>
                {format(metaText as Date, "d MMMM yyyy")}
              </time>
            ) : (
              <span>{metaText as string}</span>
            )}
          </div>
        )}
      </div>
      {showButton && (
        <div>
          <div
            className={classNames("arc-CardFooter-button", {
              "arc-CardFooter-button--s": buttonSize === "s",
            })}
          >
            <div className="arc-CardFooter-buttonIcon">
              <div
                className={classNames("arc-CardFooter-buttonIconRight", {
                  "arc-CardFooter-buttonIconRight--isHovered": isHovered,
                })}
              >
                <ThemeIcon icon={icons[buttonIcon]} />
              </div>
              <div className="arc-CardFooter-buttonIconLeft">
                <ThemeIcon icon={icons[buttonIcon]} />
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

type CardFooterIcon = "play" | "arrow";

export interface CardFooterProps {
  /**
   * Metadata text or date to display in the footer.
   */
  metaText?: string | Date;
  /**
   * Whether to use dark pathway styling.
   */
  isDarkPathway?: boolean;
  /**
   * Icon to display in the button.
   */
  buttonIcon?: CardFooterIcon;
  /**
   * Size of the button.
   */
  buttonSize?: "m" | "s";
  /**
   * Whether to show the button.
   */
  showButton?: boolean;
  /**
   * Whether the card is in a hovered state.
   */
  isHovered?: boolean;
}
