import React, { type ReactNode } from "react";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

/** Use `SkipLink` to help keyboard-only users skip to the main content on a page. */
export const SkipLink = ({ children, ...props }: SkipLinkProps) => {
  return (
    <div className="arc-SkipLink" {...filterAttrs(props)}>
      {children}
    </div>
  );
};

export interface SkipLinkProps {
  /**
   * Links to display in the SkipLinkItem.
   */
  children?: ReactNode;
}
