import React from "react";

export const SkipLinkItem = ({
  href,
  id,
  label,
  onClick,
}: SkipLinkItemProps) => {
  return (
    <a className="arc-SkipLinkItem" href={href} id={id} onClick={onClick}>
      {label}
    </a>
  );
};

export interface SkipLinkItemProps {
  /**
   * The label to display for SkipLinkItem.
   */
  label: string;
  /**
   * The URL the skip link navigates to.
   */
  href?: string;

  /**
   * The ID attribute of the target element the skip link navigates to.
   */
  id?: string;

  /**
   * Click handler for the skip link.
   */
  onClick?: (e: React.MouseEvent<HTMLAnchorElement, MouseEvent>) => void;
}
