import React, { Suspense, useContext, useEffect, useState } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { Image } from "../Image/Image";
import { Heading, type HeadingLevel } from "../Heading/Heading";
import { Surface, SurfaceContext } from "../Surface";
import { Text } from "../Text";
import { VerticalSpace } from "../VerticalSpace";
import { CardHeading } from "../CardHeading";
import { CardFooter, type CardFooterProps } from "../CardFooter";
import { ConditionalWrapper } from "../ConditionalWrapper";

import { type MediaCardImage, type MediaCardVideo } from "./types";

const VideoPlayer = React.lazy(() =>
  import("../VideoPlayer").then(({ VideoPlayer }) => ({
    default: VideoPlayer,
  })),
);

/**
 * Use `MediaCard` to contain content and an image about a single subject.
 */
export const MediaCard = ({
  media,
  url,
  onClick,
  heading,
  label,
  labelLevel = "3",
  text,
  metaText,
  minHeight,
  buttonIcon = "arrow",
  isContained = true,
  headingLevel = "2",
  headingWordWrap = false,
  preserveAspectRatios,
  ...props
}: MediaCardProps) => {
  const { surface } = useContext(SurfaceContext);
  const [isClient, setIsClient] = useState(false);
  const [showHoverState, setShowHoverState] = useState(false);

  const handleShowHoverState = (show: boolean) => () => setShowHoverState(show);

  useEffect(() => {
    setIsClient(true);
  }, []);

  const CardText = ({ text }: { text: string }) => {
    const paragraphs = text.split(/\\n|\n/).filter((p) => p.trim());

    return paragraphs.map((paragraph, index) => (
      <div key={`informationcard-text-${index}`}>
        {index > 0 && <VerticalSpace size="8" />}
        <Text>{paragraph}</Text>
      </div>
    ));
  };

  const aspectRatioClassNames = preserveAspectRatios
    ? Object.entries(preserveAspectRatios)
        .filter(([, value]) => value)
        .map(
          ([breakpoint, ratio]) =>
            `arc-MediaCard--preserveAspectRatio-${breakpoint}-${ratio}`,
        )
    : [];

  const minHeightStyle = !preserveAspectRatios && {
    minHeight,
  };

  return (
    <ConditionalWrapper
      condition={Boolean(preserveAspectRatios)}
      wrapper={(children) => (
        <div className="arc-MediaCard--preserveAspectRatioWrapper">
          {children}
        </div>
      )}
    >
      <div
        style={{ ...minHeightStyle }}
        className={classNames("arc-MediaCard", ...aspectRatioClassNames, {
          "arc-MediaCard--outlined": url && isContained && showHoverState,
          "arc-MediaCard--contained": isContained,
          "arc-MediaCard--onDarkSurface": surface === "dark",
        })}
        {...filterAttrs(props)}
      >
        <ConditionalWrapper
          condition={isContained}
          wrapper={(children) => (
            <Surface growVertically background="light-white">
              {children}
            </Surface>
          )}
        >
          {media.type === "img" && (
            <div className="arc-MediaCard-mediaContainer">
              <Image {...media} />
            </div>
          )}

          {media.type === "video" && isClient && (
            <div className="arc-MediaCard-mediaContainer">
              <Suspense fallback={null}>
                <VideoPlayer {...media} isSupportingTextHidden />
              </Suspense>
            </div>
          )}

          <div className="arc-MediaCard-content">
            {label && (
              <div className="arc-MediaCard-label">
                <Heading level={labelLevel} fontStyle="overline">
                  {label}
                </Heading>
                <VerticalSpace size="16" />
              </div>
            )}

            <CardHeading
              heading={heading}
              headingLevel={headingLevel}
              href={media.type !== "video" ? url : undefined}
              onClick={media.type !== "video" ? onClick : undefined}
              onMouseEnter={handleShowHoverState(true)}
              onMouseLeave={handleShowHoverState(false)}
              onFocus={handleShowHoverState(true)}
              onBlur={handleShowHoverState(false)}
              headingWordWrap={headingWordWrap}
              isContained={isContained}
              isHovered={showHoverState}
            />
            {!text && <VerticalSpace />}
            <div className="arc-MediaCard-textContainer">
              {text && (
                <>
                  <VerticalSpace size="16" />
                  <CardText text={text} />
                  {(url || metaText) && <VerticalSpace size="24" />}
                </>
              )}
            </div>

            <CardFooter
              buttonIcon={buttonIcon}
              metaText={metaText}
              showButton={isContained && Boolean(url) && media.type !== "video"}
              isHovered={showHoverState}
            />
          </div>
        </ConditionalWrapper>
      </div>
    </ConditionalWrapper>
  );
};

type AspectRatios = "3-4" | "10-16";

export interface MediaCardProps {
  /**
   * Heading for the MediaCard.
   */
  heading: string;

  /**
   * Heading level for the MediaCard heading.
   */
  headingLevel?: HeadingLevel;

  /**
   * Text content for the MediaCard. Use \n to create multiple paragraphs, up to 3 paragraphs.
   */
  text?: string;

  /**
   * Uppercase label for the MediaCard.
   */

  label?: string;

  /**
   * Url for the MediaCard. Makes the whole card a link.
   */
  url?: string;

  /**
   * Text to show adjacent to the cta, can be either a date or text. Its recommended to pass dates as Date objects so the component can render them correctly.
   */
  metaText?: CardFooterProps["metaText"];

  /**
   * MediaCard will have a contained look and feel with a white background if set to true.
   */
  isContained?: boolean;

  /**
   * Image for video embed for the MediaCard. Supported video platforms are YouTube and Vimeo.
   */
  media: MediaCardImage | MediaCardVideo;

  /**
   * Icon for the MediaCard Cta button
   */
  buttonIcon?: CardFooterProps["buttonIcon"];

  /**
   * Sets a minimum height for the MediaCard.
   */
  minHeight?: number;

  /**
   * Click handler for the MediaCard. Only applied when a url is provided.
   */
  onClick?: (e: React.MouseEvent<HTMLAnchorElement>) => void;

  /**
   * Heading level for the MediaCard label.
   */
  labelLevel?: HeadingLevel;

  /**
   * Whether long words in heading should be wrapped.
   */
  headingWordWrap?: boolean;

  /**
   * Preserve aspect ratio of the MediaCard. Set minHeight depending on Card width. Overwrites minHeight prop value.
   */
  preserveAspectRatios?: {
    xs?: AspectRatios;
    s?: AspectRatios;
    m?: AspectRatios;
    l?: AspectRatios;
    xl?: AspectRatios;
    xxl?: AspectRatios;
    xxxl?: AspectRatios;
  };
}
