import subMonths from "date-fns/subMonths";

import { getFocusDate } from "../../helpers";

import { type SHOW_PREVIOUS_DOUBLE_MONTH_ACTION } from "../types/actions";
import { type StateHandler } from "../types/state-handler";

export const showPreviousDoubleMonthHandler: StateHandler<
  SHOW_PREVIOUS_DOUBLE_MONTH_ACTION
> = (payload, state) => {
  return {
    ...state,
    focusDate: getFocusDate({
      date: subMonths(state.focusDate, 2),
      minDate: payload.minDate,
    }),
    displayDate: subMonths(state.displayDate, 2),
  };
};
