import React, { type ReactNode } from "react";

import { Content } from "@radix-ui/react-tabs";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

export const TabsContent = ({
  children,
  value,
  hidden = undefined,
  forceMount = true,
  ...props
}: TabsContentProps) => {
  return (
    <Content
      className="arc-TabsContent"
      value={value}
      forceMount={forceMount ? true : undefined}
      hidden={hidden}
      {...filterAttrs(props)}
    >
      {children}
    </Content>
  );
};

export interface TabsContentProps {
  /**
   * Content to display
   */
  children: ReactNode;

  /**
   * This value links the `TabsContent` with `Tab`
   */
  value: string;

  /**
   * Apply a hidden attribute to `TabsContent`. Inactive content is already visually hidden however this can be used to add a semantic hidden attribute.
   */
  hidden?: boolean;

  /**
   * Force the contents of `TabsContent` to be mounted and rendered in the DOM.
   */
  forceMount?: boolean;
}
