import setMonth from "date-fns/setMonth";

import { getFocusDate } from "../../helpers";

import { type DROPDOWN_CHANGE_MONTH_ACTION } from "../types/actions";
import { type StateHandler } from "../types/state-handler";

export const dropDownChangeMonthHandler: StateHandler<
  DROPDOWN_CHANGE_MONTH_ACTION
> = (payload, state) => {
  return {
    ...state,
    focusDate: getFocusDate({
      date: setMonth(state.focusDate, payload.month),
      minDate: payload.minDate,
      maxDate: payload.maxDate,
    }),
    displayDate: setMonth(state.displayDate, payload.month),
  };
};
