import React, { type ReactNode } from "react";

import classNames from "classnames";

export const DrawerContent = ({
  isFullBleed,
  children,
}: DrawerContentProps) => {
  return (
    <div
      className={classNames("arc-DrawerContent", {
        "arc-DrawerContent--isFullBleed": isFullBleed,
      })}
    >
      <div className="arc-Drawer-section">{children}</div>
    </div>
  );
};

export interface DrawerContentProps {
  /**
   * Display content within the DrawerContent section
   */
  children: ReactNode;
  /**
   * This property removes all arc styling and opens the Drawer to have fully custom content
   */
  isFullBleed?: boolean;
}
