import React, { useContext, type Ref } from "react";

import classNames from "classnames";

import { type ContextProps } from "../../context";
import { SurfaceContext } from "../../../Surface";
import { VisuallyHidden } from "../../../VisuallyHidden";

export const RadioGroupButton = ({
  ref,
  id,
  changeEvent,
  isDisabled,
  size,
  labelSize,
  checked,
  defaultChecked,
  radioButtonAlignment,
  name,
  blurEvent,
  value,
  label,
  helper,
  hideLabel,
  withMargin,
  isError,
}: RadioGroupButtonProps) => {
  const { surface } = useContext(SurfaceContext);

  const idLabel = `${id}-label`;

  return (
    <div
      className={classNames({
        "arc-RadioGroupButton": true,
        "arc-RadioGroupButton--withMargin": withMargin,
        "arc-RadioGroupButton--withMarginSmall": withMargin && size === "s",
        "arc-RadioGroupButton--disabled": isDisabled,
        "arc-RadioGroupButton--small": size === "s",
        "arc-RadioGroupButton--smallLabel": labelSize === "s",
        "arc-RadioGroupButton--onDarkSurface": surface === "dark",
        "arc-RadioGroupButton--invalid": !isDisabled && isError,
      })}
    >
      <label
        className={classNames("arc-RadioGroupButton-label", {
          "arc-RadioGroupButton-label--alignTop":
            radioButtonAlignment === "top",
        })}
        htmlFor={id}
        id={idLabel}
      >
        <input
          className="arc-RadioGroupButton-input"
          checked={checked}
          defaultChecked={defaultChecked}
          disabled={isDisabled}
          id={id}
          name={name}
          onBlur={blurEvent}
          onChange={changeEvent}
          ref={ref}
          type="radio"
          value={value}
          aria-checked={checked}
        />
        <span
          className={classNames({
            "arc-RadioGroupButton-label--marginTop":
              radioButtonAlignment === "top",
          })}
        >
          {hideLabel ? <VisuallyHidden>{label}</VisuallyHidden> : label}
          {helper && (
            <span className="arc-RadioGroupButton-helper">{helper}</span>
          )}
        </span>
      </label>
    </div>
  );
};

export interface RadioGroupButtonProps {
  /**
   * Ref to the underlying input element.
   */
  ref?: Ref<HTMLInputElement>;
  /**
   * ID for the radio button.
   */
  id: string;
  /**
   * Label text for the radio button.
   */
  label: string;
  /**
   * Whether to visually hide the label.
   */
  hideLabel?: boolean;
  /**
   * Name attribute for the radio button.
   */
  name: ContextProps["name"];
  /**
   * Whether to add margin to the radio button.
   */
  withMargin?: boolean;
  /**
   * Whether the radio button is checked by default.
   */
  defaultChecked?: boolean;
  /**
   * Whether the radio button is checked (controlled).
   */
  checked?: boolean;
  /**
   * Value of the radio button.
   */
  value?: string;
  /**
   * Whether the radio button is disabled.
   */
  isDisabled?: boolean;
  /**
   * Helper text for the radio button.
   */
  helper?: string;
  /**
   * Size of the label text.
   */
  labelSize?: ContextProps["size"];
  /**
   * Size of the radio button.
   */
  size?: ContextProps["size"];
  /**
   * Alignment of the radio button.
   */
  radioButtonAlignment?: "top" | "center";
  /**
   * Change event handler.
   */
  changeEvent?: ContextProps["changeEvent"];
  /**
   * Blur event handler.
   */
  blurEvent?: ContextProps["blurEvent"];
  /**
   * Whether the radio button is in an error state.
   */
  isError?: boolean;
}
