import React, { type Ref } from "react";

import { useRadioContext } from "../../context";
import { RadioCard, type RadioCardProps } from "../RadioCard";

/**
 * Radio Card component.
 */
export const RadioCardGroupInput = ({
  ref,
  icon,
  support,
  id,
  isDisabled,
  label,
  value,
  children,
  controlLocation,
  hideButton,
  ...props
}: RadioCardGroupInputProps) => {
  const { name, changeEvent, checkedValue, groupDisabled } = useRadioContext()!;

  const isChecked = checkedValue === value ? true : false;

  const checked = typeof changeEvent !== "function" ? undefined : isChecked;

  const defaultChecked =
    typeof changeEvent !== "function" ? isChecked : undefined;

  return (
    <RadioCard
      icon={icon}
      ref={ref}
      id={id}
      support={support}
      label={label}
      name={name}
      defaultChecked={defaultChecked}
      checked={checked}
      changeEvent={changeEvent}
      value={value}
      isDisabled={isDisabled || groupDisabled}
      controlLocation={controlLocation}
      hideButton={hideButton}
      {...props}
    >
      {children}
    </RadioCard>
  );
};

export interface RadioCardGroupInputProps extends Omit<RadioCardProps, "name"> {
  /**
   * Ref to the underlying input element.
   */
  ref?: Ref<HTMLInputElement>;
  /**
   * Determine the alignment the RadioButton.
   *
   */
  radioButtonAlignment?: "top" | "center";
  /**
   * ID for the Radio Button.
   */
  id: string;
  /**
   * Should the RadioButton label be visually hidden? (it will still be announced by screen readers)
   */
  hideLabel?: boolean;
  /**
   * Should the RadioButton be disabled?
   */
  isDisabled?: boolean;
  /**
   * Helper text for the RadioButton, shown below the label.
   */
  helper?: string;
  /**
   * Label for the RadioButton.
   */
  label: string;
  /**
   * Current value (controlled).
   */
  value: string;
}
