import React, { type ReactNode } from "react";

import classNames from "classnames";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";
import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

/** Use `Badge` as a static, non-interactive way to provide short updates. */
export const Badge = ({
  children,
  state = "default",
  ariaLabel,
  ariaRole,
  ...props
}: BadgeProps) => {
  return (
    <div
      className={classNames(
        "arc-Badge",
        suffixModifier("arc-Badge--state", state),
      )}
      {...(ariaLabel && { "aria-label": ariaLabel })}
      {...(ariaRole && { role: ariaRole })}
      {...filterAttrs(props)}
    >
      {children}
    </div>
  );
};

export interface BadgeProps {
  /**
   * Text to display within Badge
   */
  children: ReactNode;

  /**
   * State of the Badge
   */
  state?: "default" | "error" | "warning" | "success";

  /**
   * Aria label for accessibility
   */
  ariaLabel?: string;

  /**
   * Aria Role for accessibility
   */
  ariaRole?: "status" | "alert";
}
