import React, { type ReactNode } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { handleLinkClick } from "../../../../helpers/handle-link-click";

import { Visible } from "../../../Visible";
import { ThemeIcon } from "../../../ThemeIcon";
import { VerticalSpace } from "../../../VerticalSpace";

export const SiteFooterV2Main = ({
  children,
  columns = 4,
  ...props
}: SiteFooterV2MainProps) => (
  <nav
    className={classNames("arc-SiteFooterV2-main", {
      "arc-SiteFooterV2-main-3Columns": columns === 3,
    })}
    aria-label="Footer navigation links"
    {...filterAttrs(props)}
  >
    {children}
  </nav>
);

export const SiteFooterV2ItemDisclosure = ({
  children,
  title,
  open,
  tabIndex,
  ...props
}: SiteFooterV2DisclosureProps) => (
  <details
    open={open}
    className="arc-SiteFooterV2-disclosure"
    aria-label={title}
    {...filterAttrs(props)}
  >
    <summary className="arc-SiteFooterV2-summary" tabIndex={tabIndex}>
      <span className="arc-SiteFooterV2-icon">
        <ThemeIcon icon="siteFooterExpand" />
      </span>
      <h2 className="arc-SiteFooterV2-itemGroupTitle">{title}</h2>
    </summary>
    <ul className="arc-SiteFooterV2-itemGroup">{children}</ul>
  </details>
);

export const SiteFooterV2ItemGroup = ({
  hideDisclosure,
  ...props
}: SiteFooterV2ItemGroupProps) => {
  return (
    <div>
      <Visible
        data-testid="mobile-disclosure"
        xs={!hideDisclosure}
        s={!hideDisclosure}
      >
        <SiteFooterV2ItemDisclosure {...props} tabIndex={0} />
      </Visible>

      <Visible data-testid="desktop-disclosure" m l xl xxl>
        <SiteFooterV2ItemDisclosure {...props} open tabIndex={-1} />
        <VerticalSpace size="12" />
      </Visible>
    </div>
  );
};

export const SiteFooterV2Item = ({
  children,
  href,
  onClick,
  ...props
}: SiteFooterV2ItemProps) => {
  return (
    <li className="arc-SiteFooterV2-item" {...filterAttrs(props)}>
      <a
        onClick={handleLinkClick({ handler: onClick })}
        className="arc-SiteFooterV2-link"
        href={href}
      >
        {children}
      </a>
    </li>
  );
};

export interface SiteFooterV2MainProps {
  /**
   * Contents of the SiteFooterV2Main. Must be SiteFooterV2ItemGroup components.
   */
  children: ReactNode;

  /**
   * Number of columns to render at L+ breakpoints.
   */
  columns?: 3 | 4;
}

export interface SiteFooterV2ItemGroupProps {
  /**
   * Contents of the SiteFooterV2ItemGroup. Must be SiteFooterV2Item components.
   */
  children?: ReactNode;

  /**
   * Title text for the SiteFooterV2ItemGroup.
   */
  title?: string;

  /**
   * Hide disclosure at medium and small breakpoints.
   */
  hideDisclosure?: boolean;
}

export interface SiteFooterV2DisclosureProps extends Omit<
  SiteFooterV2ItemGroupProps,
  "hideDisclosure"
> {
  tabIndex: number;
  open?: boolean;
}

export interface SiteFooterV2ItemProps {
  /**
   * Contents of the SiteFooterV2Item.
   */
  children: ReactNode;

  /**
   * A URL to link to when the Item is clicked or touched.
   */
  href: string;

  /**
   * On click handler.
   */
  onClick?: () => void;
}
