import React from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import {
  Heading,
  type HeadingLevel,
  type HeadingSize,
} from "../../components/Heading/Heading";

/** Use `CardHeading` internally within card components to display a title, icon, or leading content at the top of a card. */
export const CardHeading = ({
  onClick,
  onMouseEnter,
  onMouseLeave,
  onBlur,
  onFocus,
  href,
  heading,
  size = "m",
  linkData = {},
  headingLevel = "2",
  headingWordWrap = false,
  isContained = true,
  isHovered = false,
  isDarkPathway = false,
}: CardHeadingProps) => {
  return (
    <Heading level={headingLevel} size={size} isWordWrap={headingWordWrap}>
      {href ? (
        <a
          className={classNames("arc-CardHeading-link", {
            "arc-CardHeading--isUncontained": !isContained,
            "arc-CardHeading--isHovered": isHovered,
            "arc-CardHeading--isDarkPathway": isDarkPathway,
          })}
          href={href}
          onClick={onClick}
          onMouseEnter={onMouseEnter}
          onMouseLeave={onMouseLeave}
          onFocus={onFocus}
          onBlur={onBlur}
          {...filterAttrs(linkData)}
        >
          {heading}
        </a>
      ) : (
        heading
      )}
    </Heading>
  );
};

export type CardHeadingSize = Extract<HeadingSize, "m" | "l">;

export interface CardHeadingProps {
  /**
   * The heading text to display.
   */
  heading: string;
  /**
   * Size of the heading.
   */
  size?: CardHeadingSize;
  /**
   * URL to link to when the heading is clicked.
   */
  href?: string;
  /**
   * Semantic heading level for accessibility.
   */
  headingLevel?: HeadingLevel;
  /**
   * Click handler for the heading link.
   */
  onClick?: (e: React.MouseEvent<HTMLAnchorElement>) => void;
  /**
   * Mouse enter handler for the heading link.
   */
  onMouseEnter?: () => void;
  /**
   * Mouse leave handler for the heading link.
   */
  onMouseLeave?: () => void;
  /**
   * Focus handler for the heading link.
   */
  onFocus?: () => void;
  /**
   * Blur handler for the heading link.
   */
  onBlur?: () => void;
  /**
   * Additional data attributes to pass to the link element.
   */
  linkData?: { [key: string]: string };
  /**
   * Whether long words in heading should be wrapped.
   */
  headingWordWrap?: boolean;
  /**
   * Whether the card is contained.
   */
  isContained?: boolean;
  /**
   * Whether the card heading is in a hovered state.
   */
  isHovered?: boolean;
  /**
   * Whether the card heading is on a dark pathway.
   */
  isDarkPathway?: boolean;
}
