import React, { createContext, useContext } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { useAriaDescribedby } from "../../hooks";
import { SurfaceContext } from "../Surface";
import { DisclosureMini } from "../DisclosureMini";
import { VisuallyHidden } from "../VisuallyHidden";
import { ThemeIcon } from "../ThemeIcon";

type RequirementStatus = "required" | "optional" | "not-applicable";

const defaultContext: { requirementStatus: RequirementStatus | null } = {
  requirementStatus: null,
};

const Context = createContext(defaultContext);
const { Provider } = Context;

/**
 * Use `FormControl` to provide inputs with labels, helper text and error messages
 */
export const FormControl = ({
  children,
  elementType: ElementType = "div",
  errorMessage,
  helper,
  htmlFor,
  supplementaryInfo,
  id,
  label,
  labelSize = "l",
  labelPosition = "top",
  requirementStatus = "optional",
  helperUnderLabel = false,
  isDisabled,
  hideLabel = false,
  disclosureTitle,
  disclosureText,
  onClickDisclosure,
  isErrorAlert = false,
  ...props
}: FormControlProps) => {
  const { surface } = useContext(SurfaceContext);
  const { ariaDescribedby, idError, idHelper, idDisclosure } =
    useAriaDescribedby({
      disclosureText,
      errorMessage,
      helper,
      id: htmlFor || id, // `htmlFor` is preference to keep this deterministic with TextInput
    });

  const LabelType = ElementType === "div" ? "label" : "legend";

  const elementProps: { "aria-describedby"?: string } = {};
  const labelProps: { htmlFor?: string; id?: string } = {};

  if (LabelType === "label") {
    labelProps["htmlFor"] = htmlFor;

    if (htmlFor) {
      labelProps["id"] = `${htmlFor}-label`;
    } else if (id) {
      labelProps["id"] = `${id}-label`;
    }
  } else {
    elementProps["aria-describedby"] = ariaDescribedby;
  }

  const hasInfo = helperUnderLabel
    ? Boolean(errorMessage || disclosureTitle || supplementaryInfo)
    : Boolean(errorMessage || disclosureTitle || helper || supplementaryInfo);

  return (
    <Provider value={{ requirementStatus }}>
      <ElementType
        className={classNames(
          `arc-FormControl`,
          `arc-FormControl--${labelSize}`,
          {
            "arc-FormControl--isDisabled": isDisabled,
            "arc-FormControl--onDarkSurface": surface === "dark",
            "arc-FormControl--sideLabel": labelPosition === "left",
          },
        )}
        id={id}
        {...elementProps}
        {...filterAttrs(props)}
      >
        {hideLabel === true ? (
          <VisuallyHidden>
            <LabelType
              className={classNames("arc-FormControl-label", {
                "arc-FormControl-label--withHelperUnderLabel":
                  helperUnderLabel && helper,
              })}
              {...labelProps}
            >
              {label && (
                <span
                  className={classNames("arc-FormControl-labelText", {
                    "arc-FormControl-labelText--withOptional":
                      requirementStatus === "optional",
                  })}
                >
                  {label}
                </span>
              )}
              {requirementStatus === "optional" && (
                <span className="arc-FormControl-labelOptional">
                  (optional)
                </span>
              )}
            </LabelType>
          </VisuallyHidden>
        ) : (
          <LabelType
            className={classNames("arc-FormControl-label", {
              "arc-FormControl-label--withHelperUnderLabel":
                helperUnderLabel && helper,
            })}
            {...labelProps}
          >
            {label && (
              <span
                className={classNames("arc-FormControl-labelText", {
                  "arc-FormControl-labelText--withOptional":
                    requirementStatus === "optional",
                })}
              >
                {label}
              </span>
            )}
            {requirementStatus === "optional" && (
              <span className="arc-FormControl-labelOptional">(optional)</span>
            )}
            {/* Screen Reader Order of Fieldsets*/}
            {LabelType === "legend" && (errorMessage || helper) && (
              <VisuallyHidden>
                {errorMessage ? `Error. ${errorMessage}` : ""}
                {errorMessage && helper ? ". " : ""}
                {helper}
              </VisuallyHidden>
            )}
          </LabelType>
        )}

        {helperUnderLabel && helper && (
          <div
            className="arc-FormControl-helper arc-FormControl-helper--underLabel"
            id={idHelper}
          >
            {helper}
          </div>
        )}

        {children}

        {/* TODO: arc-FormControl-info is rendering with no content  */}
        <div
          className={classNames("arc-FormControl-info", {
            "arc-FormControl-info--hasContent": hasInfo,
          })}
        >
          {/* Render helper container if (helper and !helperUnderLabel) or errorMessage or disclosure title exist */}
          {((helper && !helperUnderLabel) ||
            errorMessage ||
            disclosureTitle) && (
            <div className="arc-FormControl-helperContainer">
              {errorMessage ? (
                <div
                  className="arc-FormControl-error"
                  id={idError}
                  role={isErrorAlert ? "alert" : undefined}
                >
                  <span className="arc-FormControl-error--icon">
                    <VisuallyHidden>Error.</VisuallyHidden>
                    <ThemeIcon icon="formControlAlert" />
                  </span>
                  {errorMessage}
                </div>
              ) : (
                !helperUnderLabel &&
                (disclosureTitle ? (
                  <DisclosureMini
                    onClick={onClickDisclosure}
                    summary={disclosureTitle}
                    size={labelSize === "m" ? "l" : labelSize}
                    id={idDisclosure}
                  >
                    {disclosureText}
                  </DisclosureMini>
                ) : (
                  helper && (
                    <div className="arc-FormControl-helper" id={idHelper}>
                      {helper}
                    </div>
                  )
                ))
              )}
            </div>
          )}
          {supplementaryInfo && (
            <div className="arc-FormControl-supplementaryInfo">
              {supplementaryInfo}
            </div>
          )}
        </div>
      </ElementType>
    </Provider>
  );
};

export interface FormControlProps {
  /**
   * Render the input or series of inputs
   */
  children: React.ReactNode;
  /**
   * HTML Element type for the FormControl.
   * @default 'div'
   */
  elementType?: "div" | "fieldset";
  /**
   * Error message for the FormControl. Replaces helper when helperUnderLabel is false.
   */
  errorMessage?: string;
  /**
   * Helper text for the FormControl, shown below the label.
   */
  helper?: React.ReactNode;
  /**
   * ID for the input that the FormControl points towards.
   */
  htmlFor?: string;
  /**
   * ID for the FormControl. Used for helper and errorMessage if `htmlFor` is undefined.
   */
  id?: string;
  /**
   * Are all of the inputs in the FormControl required, optional, or is a
   * uniform requirement status for all inputs not applicable?
   */
  requirementStatus?: RequirementStatus;
  /**
   * Label for the FormControl.
   */
  label: string;
  /**
   * Determins if the Label should be in a disabled state
   */
  isDisabled?: boolean;
  /**
   * Label size.
   */
  labelSize?: "l" | "m" | "s";
  /**
   * Position of Label (Switch component only)
   */
  labelPosition?: "top" | "left";
  /**
   *   Use `DisclosureTitle` to display content that is only visible when toggled into
   * an "open" state. This overrides helper text.
   */
  disclosureTitle?: string;
  /**
   * Text to display within the disclosure
   */
  disclosureText?: string;

  /**
   * onClick handler for FormControlDisclosure
   */
  onClickDisclosure?: () => void;

  /**
   * Optional additional information for the FormControl.
   */
  supplementaryInfo?: React.ReactNode;

  /**
   * Position helper text under label. This is set to `false` by default.
   */
  helperUnderLabel?: boolean;

  /**
   * Use `hideLabel` to visually hide the `FormControl` label. This still allows screen readers to have access to labels. This is set to `false` by default.
   */
  hideLabel?: boolean;

  /**
   * Provide the "alert" role to the errorMessage.
   */
  isErrorAlert?: boolean;
}

export { Context as FormControlContext };
