import React, { type JSX, useContext } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { SurfaceContext } from "../Surface";
import { VisuallyHidden } from "../VisuallyHidden";
import { ThemeIcon } from "../ThemeIcon";

/**
 * Use `Link` to direct users to a new page or piece of information.
 */
export const Link = ({
  id,
  href,
  title,
  rel,
  target,
  children,
  onClick,
  screenReaderText,
  isButton = false,
  isImplied = false,
  size = "m",
  ...props
}: LinkProps) => {
  const { surface } = useContext(SurfaceContext);
  const isExternalLink = target === "_blank";
  const textArray = children.split(" ");
  const firstText = textArray.slice(0, -1).join(" ");
  const lastWord = textArray[textArray.length - 1];

  const commonProps = {
    id,
    onClick,
    className: classNames("arc-Link", `arc-Link--${size}`, {
      "arc-Link--onDarkSurface": surface === "dark",
      "arc-Link--onLightSurface": surface !== "dark",
      "arc-Link--isImplied": isImplied,
    }),
  };

  const elementProps = {
    a: {
      ...commonProps,
      href,
      title,
      target,
      rel,
    },
    button: {
      ...commonProps,
    },
    span: {
      ...commonProps,
    },
  };

  const LinkElement: keyof Pick<
    JSX.IntrinsicElements,
    "a" | "button" | "span"
  > = isButton ? "button" : href ? "a" : "span";

  return (
    <LinkElement {...elementProps[LinkElement]} {...filterAttrs(props)}>
      <div
        className={classNames("arc-Link-wrapper", {
          "arc-Link--isButton": isButton,
        })}
      >
        <VisuallyHidden>
          {screenReaderText || children}
          {isExternalLink && " (Opens in new window)"}
        </VisuallyHidden>
        {firstText && (
          <span aria-hidden className="arc-Link-text">
            {firstText}&nbsp;
          </span>
        )}
        <span className="arc-Link-iconWrapper">
          <span aria-hidden className="arc-Link-text">
            {lastWord}
          </span>
          {isExternalLink && (
            <ThemeIcon icon="linkExternal" size={size === "s" ? 20 : 24} />
          )}
        </span>
      </div>
    </LinkElement>
  );
};

export interface LinkProps {
  /**
   * Id attribute for `Link`.
   */
  id?: string;

  /**
   * href attribute for `Link`.
   */
  href?: string;

  /**
   * Screen reader text for `Link`, which is visually hidden.
   */
  screenReaderText?: string;

  /**
   * title attribute for `Link`.
   */
  title?: string;

  /**
   * Rel attribute for `Link`.
   */
  rel?: string;

  /**
   * Configures the size of `Link`.
   */
  size?: "l" | "m" | "s";

  /**
   * Removes underline if true.
   */
  isImplied?: boolean;

  /**
   * Renders as a button element if true.
   */
  isButton?: boolean;

  /**
   * Click handler for `Link`.
   */
  onClick?: (e: React.MouseEvent) => void;

  /**
   * Target for `Link`.
   */
  target?: "_self" | "_blank" | "_parent" | "_top";

  /**
   * Content for `Link`.
   */
  children: string;
}
