import { createContext } from "react";

import { type SelectionType } from "./types";

interface ArcCalendarContextValue {
  minDate?: Date;
  maxDate?: Date;
  displayDate: Date;
  focusDate: Date;
  todayDate: Date;
  highlightedRange: Date[];
  selectionType: SelectionType;
  autoFocusOnMount: boolean;
  selectedDate: Date;
  selectedRange: Date[];
  disabledDates?: Date[];
  onDayNumberClick: (date: Date) => () => void;
  onDayNumberHover: (date: Date) => () => void;
  onKeyboardNavigate: (key: string, shiftKey: boolean) => void;
  onDayGridLeave: () => void;
}

export const ArcCalendarContext = createContext<ArcCalendarContextValue | null>(
  null,
);
