import React, { type ReactNode } from "react";

/** Use `ConditionalWrapper` to conditionally wrap elements in a component or layout based on a given condition. */
export const ConditionalWrapper = ({
  condition,
  wrapper,
  fallback,
  children,
}: ConditionalWrapperProps) => (
  <>
    {condition ? wrapper(children) : fallback ? fallback(children) : children}
  </>
);

export interface ConditionalWrapperProps {
  /**
   * Condition to determine which wrapper to use.
   */
  condition: boolean;
  /**
   * Function to wrap children when condition is true.
   */
  wrapper: (children: ReactNode) => ReactNode;
  /**
   * Optional function to wrap children when condition is false.
   */
  fallback?: (children: ReactNode) => ReactNode;
  /**
   * Content to be conditionally wrapped.
   */
  children: ReactNode;
}
