import React, { type ReactNode, useEffect, useState } from "react";

import { type ReactPlayerProps } from "react-player";
import ReactPlayerYoutube from "react-player/youtube";
import ReactPlayerVimeo from "react-player/vimeo";
import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { VisuallyHidden } from "../VisuallyHidden";
import { VerticalSpace } from "../VerticalSpace";
import { Heading } from "../Heading";
import { Text } from "../Text";

import { Download } from "../Download";
import { DisclosureMini } from "../DisclosureMini";
import { ThemeIcon } from "../ThemeIcon";

/**
 * Use `VideoPlayer` to embed videos from YouTube or Vimeo.
 */
export const VideoPlayer = ({
  title,
  description,
  transcriptLink,
  transcriptContent,
  light,
  url,
  onReady,
  onPlay,
  onStart,
  onPause,
  onBuffer,
  onBufferEnd,
  onError,
  onEnded,
  onClickPreview,
  onDuration,
  onSeek,
  onProgress,
  onPlaybackRateChange,
  onPlaybackQualityChange,
  onEnablePIP,
  onDisablePIP,
  isBorderRadius = false,
  isSupportingTextHidden = false,
  titleWordWrap = false,
  ...props
}: VideoPlayerProps) => {
  const TextWrapper = isSupportingTextHidden ? VisuallyHidden : "div";
  const isVimeo = new URL(url).hostname.includes("vimeo");
  const [isClient, setIsClient] = useState<boolean>(false);

  // https://nextjs.org/docs/messages/react-hydration-error#solution-1-using-useeffect-to-run-on-the-client-only
  useEffect(() => {
    setIsClient(true);
  }, []);

  const playerProps = {
    url,
    light,
    onReady,
    onPlay,
    onStart,
    onPause,
    onBuffer,
    onBufferEnd,
    onError,
    onEnded,
    onClickPreview,
    onDuration,
    onSeek,
    onProgress,
    onPlaybackRateChange,
    onPlaybackQualityChange,
    onEnablePIP,
    onDisablePIP,
    playIcon: (
      <div className="arc-VideoPlayer-iconContainer">
        <div className="arc-VideoPlayer-icon">
          <ThemeIcon icon="videoPlayerPlay" />
        </div>
      </div>
    ),
    playing: Boolean(light),
    controls: true,
    className: "arc-VideoPlayer",
    width: "100%",
    height: "100%",
  };

  return (
    <div {...filterAttrs(props)}>
      <div
        data-testid="arc-video-player"
        data-player={isVimeo ? "vimeo" : "youtube"}
        className={classNames("arc-VideoPlayer-wrapper", {
          "arc-VideoPlayer-wrapper--borderRadius": isBorderRadius,
        })}
      >
        {isVimeo
          ? isClient && (
              <ReactPlayerVimeo
                {...playerProps}
                config={{ playerOptions: { playsinline: true } }}
              />
            )
          : isClient && (
              <ReactPlayerYoutube
                {...playerProps}
                config={{ playerVars: { playsinline: 1 } }}
              />
            )}
      </div>
      <TextWrapper>
        <VerticalSpace size="24" />

        <Heading level="3" size="s" isWordWrap={titleWordWrap}>
          {title}
        </Heading>

        <VerticalSpace size="8" />

        <Text>{description}</Text>
      </TextWrapper>
      {transcriptLink && (
        <>
          <VerticalSpace size="24" />

          <Download
            isCompact
            icon="downloadAccessibility"
            href={transcriptLink.url}
            name={transcriptLink.text}
            type={transcriptLink.format}
            size={transcriptLink.fileSize}
          />
        </>
      )}

      {transcriptContent && (
        <>
          <VerticalSpace size="24" />

          <DisclosureMini summary="Audio Described Transcript">
            <VerticalSpace size="8" />

            <Heading>{transcriptContent.heading.toUpperCase()}</Heading>

            <VerticalSpace size="32" />

            <Text>{transcriptContent.description}</Text>

            <VerticalSpace size="24" />

            {transcriptContent.content.map(({ heading, text }, i) => (
              <div key={`${text}-${i}`}>
                <VerticalSpace size="24" />

                {heading && (
                  <>
                    <Heading isInline>{heading?.toUpperCase()}</Heading>&nbsp;
                  </>
                )}

                <Text isInline>{text}</Text>
              </div>
            ))}
          </DisclosureMini>
        </>
      )}
    </div>
  );
};

type ReactPlayerCallbackProps = Pick<
  ReactPlayerProps,
  | "onReady"
  | "onPlay"
  | "onStart"
  | "onPause"
  | "onBuffer"
  | "onBufferEnd"
  | "onEnded"
  | "onClickPreview"
  | "onEnablePIP"
  | "onDisablePIP"
  | "onError"
  | "onDuration"
  | "onSeek"
  | "onProgress"
> & {
  /**
   * Called when playback rate of the player changes.
   */
  onPlaybackRateChange?: (playbackRate: number) => void;
  /**
   * Called when playback quality of the player changes.
   */
  onPlaybackQualityChange?: (event: unknown) => void;
};

export interface VideoPlayerProps
  extends ReactPlayerCallbackProps, Pick<ReactPlayerProps, "light"> {
  /**
   * URL of the video to play.
   */
  url: string;
  /**
   * Title of the video.
   */
  title: string;
  /**
   * Description of the video.
   */
  description: string | ReactNode;
  /**
   * Apply border radius to the video player.
   */
  isBorderRadius?: boolean;
  /**
   * Link to download the transcript.
   */
  transcriptLink?: {
    url: string;
    text: string;
    fileSize: string;
    format: string;
  };
  /**
   * Content for the audio described transcript.
   */
  transcriptContent?: {
    heading: string;
    description: string;
    content: { heading?: string; text?: string }[];
  };
  /**
   * Hide the supporting text (title and description).
   */
  isSupportingTextHidden?: boolean;
  titleWordWrap?: boolean;
}
