import React, { type Ref, useContext, useRef, useState } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { useAriaDescribedby, useNumericInput } from "../../hooks";
import { FormControl } from "../FormControl";
import { type FormControlProps } from "../FormControl/FormControl";
import { SurfaceContext } from "../Surface";
import { type AutoCompleteTypes } from "../../types/auto-complete-types";

import { TrailingSlot } from "./components/TrailingSlot";

type EventType = React.ChangeEvent<HTMLInputElement>;

/** Use `TextInput` as a single-line field that allows users to enter short text, such as names, email, search queries or passwords. */
const TextInputComponent = ({
  ref,
  defaultValue = "",
  errorMessage,
  helper,
  hideLabel,
  id,
  inputMode,
  isDisabled = false,
  isReadOnly = false,
  isRequired = false,
  label,
  maxLength,
  minLength,
  name,
  onBlur,
  onFocus,
  onChange,
  placeholder,
  onClickDisclosure,
  pattern,
  type = "text",
  showPassword = false,
  value,
  disclosureTitle,
  disclosureText,
  size = "m",
  leadingSlot,
  trailingSlot,
  inputAlignment = "left",
  width,
  autoComplete,
  isLoading,
  isErrorAlert,
  prefix,
  suffix,
  clearButton,
  ...props
}: TextInputComponentProps) => {
  const [showPasswordToggle, setShowPasswordToggle] = useState(false);

  const inputRef = useRef<HTMLInputElement>(null);

  const setInputRef = (node: HTMLInputElement | null) => {
    inputRef.current = node;
    if (typeof ref === "function") {
      ref(node);
    } else if (ref) {
      ref.current = node;
    }
  };

  const inferredInputProps = useNumericInput({
    inputMode,
    pattern,
    type: showPassword && showPasswordToggle ? "text" : type,
  });

  const { surface } = useContext(SurfaceContext);

  // Although this is used within FormControlWrapper, it's deterministic so we can call it here too
  const { ariaDescribedby } = useAriaDescribedby({
    id,
    errorMessage,
    helper,
    disclosureText,
  });

  return (
    <div
      className={classNames({
        "arc-TextInput": true,
        "arc-TextInput--withAdditionalControl": showPassword,
        "arc-TextInput--alignRight": inputAlignment === "right",
        "arc-TextInput--withPasswordToggle": showPassword,
        "arc-TextInput--isDisabled": isDisabled,
        "arc-TextInput--invalid": errorMessage,
        "arc-TextInput--onDarkSurface": surface === "dark",
        "arc-TextInput--withPrefix": leadingSlot || prefix,
        "arc-TextInput--withSuffix": trailingSlot || suffix,
        "arc-TextInput--withClearButton": clearButton,
        [`arc-TextInput--size${size && size.toUpperCase()}`]:
          size && size !== "m",
      })}
      {...filterAttrs(props)}
    >
      <FormControl
        errorMessage={errorMessage}
        helper={helper}
        htmlFor={id}
        isDisabled={isDisabled}
        label={label}
        hideLabel={hideLabel}
        labelSize={size}
        requirementStatus={isRequired ? "required" : "optional"}
        disclosureTitle={disclosureTitle}
        disclosureText={disclosureText}
        onClickDisclosure={onClickDisclosure}
        isErrorAlert={isErrorAlert}
      >
        <div
          className="arc-TextInput-inputWrapper"
          style={{ width, marginTop: hideLabel ? 0 : undefined }}
        >
          {prefix && (
            <span
              className="arc-TextInput-prefix arc-TextInput-affixes"
              aria-hidden
            >
              {prefix}
            </span>
          )}
          {leadingSlot && (
            <span className="arc-TextInput-leadingSlot">{leadingSlot}</span>
          )}
          <input
            placeholder={placeholder}
            aria-describedby={ariaDescribedby}
            aria-invalid={errorMessage ? "true" : "false"}
            className="arc-TextInput-input"
            defaultValue={
              typeof value !== "undefined" ? undefined : defaultValue
            }
            disabled={isDisabled}
            id={id}
            maxLength={maxLength}
            minLength={minLength}
            name={name}
            onChange={onChange}
            onBlur={onBlur}
            onFocus={onFocus}
            readOnly={isReadOnly}
            ref={setInputRef}
            required={isRequired}
            value={typeof value !== "undefined" ? value : undefined}
            autoComplete={autoComplete}
            {...inferredInputProps}
          />
          {(trailingSlot ||
            showPassword ||
            isLoading ||
            clearButton?.onClick) && (
            <TrailingSlot
              id={id}
              showPassword={showPassword}
              isReadOnly={isReadOnly}
              isLoading={isLoading}
              clearButton={clearButton}
              trailingSlot={trailingSlot}
              isPasswordVisible={showPasswordToggle}
              onTogglePassword={() => setShowPasswordToggle((prev) => !prev)}
              size={size}
              isDisabled={isDisabled}
              inputRef={inputRef}
            />
          )}
          {suffix && (
            <span
              className="arc-TextInput-suffix arc-TextInput-affixes"
              aria-hidden
            >
              {suffix}
            </span>
          )}
        </div>
      </FormControl>
    </div>
  );
};

/**
 * Use `TextInput` to allow users to enter short form text.
 */
export const TextInput = (props: TextInputProps) => (
  <TextInputComponent {...props} />
);

export const TextInputWithPlaceHolder = (
  props: TextInputWithPlaceholderProps,
) => <TextInputComponent {...props} />;

export interface TextInputComponentProps extends Omit<
  FormControlProps,
  | "children"
  | "elementType"
  | "htmlFor"
  | "requirementStatus"
  | "helperUnderLabel"
  | "supplementaryInfo"
  | "labelPosition"
  | "labelSize"
> {
  /**
   * Ref to the underlying input element.
   */
  ref?: Ref<HTMLInputElement>;
  /**
   * Uncontrolled default value of the TextInput. If the TextInput is controlled
   * via `value`/`onChange`, `defaultValue` will be ignored.
   *
   * `defaultValue` is not to be used instead of helper text.
   */
  defaultValue?: string;
  /**
   * ID for the TextInput.
   */
  id: string;
  /**
   * Mode for the input. If not defined, inferred by type.
   */
  inputMode?: "email" | "numeric" | "tel" | "url";
  /**
   * Should the control be disabled?
   */
  isDisabled?: boolean;
  /**
   * Should the control be read-only?
   */
  isReadOnly?: boolean;
  /**
   * Indicates whether the TextInput is in a loading state
   */
  isLoading?: boolean;
  /**
   * Render the clearButton in the trailing slot.
   */
  clearButton?: {
    onClick?: () => void;
    tooltipLabel: string;
  };
  /**
   * Enable button to toggle TextInput type from `Selected Type` to `Text`. This will override any `trailingSlot` elements
   */
  showPassword?: boolean;
  /**
   * Add a prefix value within `TextInput`
   */
  prefix?: string;
  /**
   * Add a leadingSlot value within `TextInput`
   */
  leadingSlot?: React.ReactNode;
  /**
   * Add a trailingSlot value within `TextInput`. If `showPassword`, `clearIcon` or `isloading` is true, this value will not be displayed.
   */
  trailingSlot?: React.ReactNode;
  /**
   * Add a suffix value within `TextInput`.
   */
  suffix?: string;
  /**
   * Should the control be required?
   */
  isRequired?: boolean;
  /**
   * Maximum number of characters.
   */
  maxLength?: number;
  /**
   * Minimum number of characters.
   */
  minLength?: number;
  /**
   * Name of the input.
   */
  name?: string;
  /**
   * Function to call when the TextInput loses focus.
   */
  onBlur?: (e: React.FocusEvent<HTMLInputElement, Element>) => void;
  /**
   * Function to call when the TextInput is focused.
   */
  onFocus?: (e: React.FocusEvent<HTMLInputElement, Element>) => void;
  /**
   * Callback function commonly used to update the TextInput's controlled
   * `value`, for example `e => setValue(e.target.value)`.
   */
  onChange?: (e: EventType) => void;
  /**
   * Validation regex pattern.
   */
  pattern?: string;

  /**
   * Size of the input.
   */
  size?: "l" | "m" | "s";

  /**
   * Determine the alignment of the text within the input
   */
  inputAlignment?: "left" | "right";

  /**
   * Type for the input. `number` will be changed to `text` and set the `numeric` inputMode.
   */
  type?: "email" | "number" | "password" | "tel" | "text" | "url";

  /**
   * Current value of the TextInput. Must be controlled via an
   * `onChange` callback function. Otherwise, use `defaultValue` (or `isReadOnly`).
   */
  value?: string;
  /**
   * Placeholder for the input
   */
  placeholder?: string;
  /**
   * Sets the width of the TextInput.
   */
  width?: string;

  /**
   *  Sets autoComplete value for TextInput.
   */
  autoComplete?: AutoCompleteTypes;
}

export type TextInputProps = Omit<TextInputComponentProps, "placeholder">;
export type TextInputWithPlaceholderProps = TextInputComponentProps;
