import React, { type ReactNode, useEffect, useRef, useState } from "react";

import * as RadixDialog from "@radix-ui/react-dialog";

import {
  autoUpdate,
  type MiddlewareState,
  offset,
  size,
  useFloating,
} from "@floating-ui/react";

import { getFocusableElements } from "@arc-ui/helpers/get-focusable-elements";

import { useThemeElement } from "../../../../../../hooks";
import { VerticalSpace } from "../../../../../VerticalSpace";
import { VisuallyHidden } from "../../../../../VisuallyHidden";

import { useNavigationHeaderContext } from "../../../../NavigationHeader.provider";
import { NavigationHeaderContainer } from "../../../NavigationHeaderContainer";
import { type InteractionMode } from "../../../../types/interaction-mode";
import { type ContainerBackgroundColor } from "../../../../types/container-background-color";

import { useSubNavContext } from "../../NavigationHeaderSubnav.provider";

export const NavigationHeaderSubnavContent = ({
  children,
  background,
  menuTitle,
  description,
}: NavigationHeaderSubnavContentProps) => {
  const navigationHeaderContext = useNavigationHeaderContext();
  const subNavContext = useSubNavContext();
  const dialogRef = useRef<HTMLDivElement>(null);
  const childContainerRef = useRef<HTMLDivElement>(null);
  const [themeElement, setThemeElement] = useThemeElement();
  const [interactionMode, setInterActionMode] =
    useState<InteractionMode>("pointer");

  const { isOpen, rootRef, setIsOpen, id } = subNavContext;

  const { refs: subNavRefs, floatingStyles: subNavFloatStyles } = useFloating({
    whileElementsMounted: autoUpdate,
    elements: {
      reference: navigationHeaderContext?.navBarEl,
    },
    placement: "bottom-end",
    middleware: [
      size({
        apply({ rects, elements }: MiddlewareState) {
          Object.assign(elements.floating.style, {
            width: `${rects.reference.width}px`,
          });
        },
      }),
      offset(navigationHeaderContext.isPill ? 8 : 0),
    ],
  });

  // if focus isnt going anywhere else, return it to the trigger
  const onCloseAutoFocus = () => {
    if (
      document.activeElement?.tagName === "BODY" &&
      interactionMode === "keyboard"
    ) {
      subNavContext.triggerRef?.current?.focus();
    }
  };

  // close when escape key is pressed
  const onEscapeKeyDown = () => {
    setInterActionMode("keyboard");
    setIsOpen(false);
    subNavContext.onOpenChange?.(false);
  };

  // close when escape key is pressed
  const onInteractOutside = () => {
    setInterActionMode("pointer");
  };

  // Find the first focusable element.
  const onOpenAutoFocus = (e: Event) => {
    e.preventDefault();

    const firstFocusable = getFocusableElements(
      childContainerRef.current as Node,
    )[0];

    if (firstFocusable) {
      firstFocusable.focus({ preventScroll: true });
    }
  };

  const onContainerMouseDown = () => {
    setInterActionMode("pointer");
  };

  const onContainerKeyDown = () => {
    setInterActionMode("keyboard");
  };

  useEffect(() => {
    if (!isOpen) return;

    const clickListener = (event: Event) => {
      const target = event.target as Element;

      const isThisTriggerClicked =
        rootRef.current && rootRef.current.contains(target);

      const outSideSubnavClicked =
        dialogRef.current && !dialogRef.current.contains(target);

      // dont do anything if the click was on the trigger.
      if (isThisTriggerClicked) {
        return;
      }

      // close if clicking outside the dialog
      if (outSideSubnavClicked) {
        setIsOpen(false);
        subNavContext.onOpenChange?.(false);
      }
    };

    document.addEventListener("click", clickListener);

    return () => {
      document.removeEventListener("click", clickListener);
    };
  }, [isOpen, setIsOpen, rootRef, id, subNavContext]);

  return (
    <div
      ref={setThemeElement}
      onMouseDown={onContainerMouseDown}
      onKeyDown={onContainerKeyDown}
    >
      <RadixDialog.Root open={subNavContext.isOpen} modal={false}>
        <RadixDialog.Portal container={themeElement}>
          <div
            className="arc-NavigationHeaderSubnavContent"
            ref={subNavRefs.setFloating}
            style={subNavFloatStyles}
          >
            <NavigationHeaderContainer
              isExtended={navigationHeaderContext?.isExtended}
              isFluid={navigationHeaderContext?.isFluid}
              isPill={navigationHeaderContext?.isPill}
              backgroundColor={background}
            >
              <RadixDialog.Content
                className="arc-NavigationHeaderSubnavContent-dialog"
                aria-modal="true"
                ref={dialogRef}
                onInteractOutside={onInteractOutside}
                onEscapeKeyDown={onEscapeKeyDown}
                onCloseAutoFocus={onCloseAutoFocus}
                onOpenAutoFocus={onOpenAutoFocus}
              >
                <VisuallyHidden>
                  <RadixDialog.Title>{menuTitle} submenu</RadixDialog.Title>
                  <RadixDialog.Description>
                    {description}
                  </RadixDialog.Description>
                </VisuallyHidden>

                <div ref={childContainerRef}>{children}</div>
              </RadixDialog.Content>
            </NavigationHeaderContainer>
            <VerticalSpace />
          </div>
        </RadixDialog.Portal>
      </RadixDialog.Root>
    </div>
  );
};

export interface NavigationHeaderSubnavContentProps {
  /**
   * Background color for the subnav.
   */
  background: Extract<
    ContainerBackgroundColor,
    "neutral" | "lightElevatedTight"
  >;
  /**
   * Accessible description for the subnav dialog.
   */
  description: string;
  /**
   * Accessible title for subnav dialog.
   */
  menuTitle: string;
  /**
   * Content to display in the subnav.
   */
  children: ReactNode;
}
