import React from "react";

/**
 * Scrollable container that adjusts height based on surrounding menu content.
 */

export const MenuScrollable = ({ children }: MenuScrollableProps) => {
  const scrollableRefFunc = (el: HTMLDivElement | null) => {
    let totalSiblingHeight = 0;

    // get the closest Menu.Content element this will always exist within the menu component
    const contentContainer = el?.closest(".arc-MenuContent-content");
    if (!contentContainer || !el) return;

    // loop over all children in Menu.Content children to get height of each non scrollable element (excluding the scroll element itself)
    Array.from(contentContainer.children).forEach((child) => {
      if (child !== el) {
        totalSiblingHeight += (child as HTMLElement).offsetHeight + 6;
      }
    });

    const availableHeight = `calc(var(--radix-dropdown-menu-content-available-height) - ${totalSiblingHeight}px - 25px)`;

    el.style.height = `${el.scrollHeight}px`;
    el.style.maxHeight = availableHeight;
  };

  return (
    <div ref={scrollableRefFunc} className="arc-MenuScrollable">
      {children}
    </div>
  );
};

export interface MenuScrollableProps {
  /**
   * The content within the scrollable area, typically a list of `MenuItem` components or similar menu elements.
   */
  children: React.ReactNode;
}
