import React, { type ReactNode, useState, useEffect } from "react";

import classNames from "classnames";
import debounce from "lodash/debounce";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { ArcBreakpoints } from "../../helpers/arc-breakpoints";
import { type SurfaceBackgroundColor } from "../Surface";
import { VerticalSpace } from "../VerticalSpace";
import { Box } from "../Box";
import {
  Heading,
  type HeadingSize,
  type HeadingLevel,
  type HeadingColor,
} from "../Heading/Heading";

import {
  Grid,
  GridCol,
  GridRow,
  type AlignmentValue,
  type ColumnValue,
} from "../Grid";

import { BannerImage, type BannerImageProps } from "./components/BannerImage";

/** Use `TemplateBanner` as a base structure for banner components; other banner variants extend or consume this template. */
export const TemplateBanner = ({
  heading,
  fontStyle = "default",
  headingColor = "auto",
  label,
  labelLevel = "3",
  labelColor = "auto",
  text,
  img,
  contentRatio = "1/1",
  contentRatios,
  children,
  alignment = "center",
  additionalTopMargin,
  minHeight = 454,
  minHeightM,
  minHeightL,
  minHeightXL,
  headingSize = "xl",
  isReversed = false,
  isElevated = false,
  headingLevel = "2",
  headingWordWrap = false,
  type = "light",
  ...props
}: TemplateBannerProps) => {
  const [imageError, setImageError] = useState(false);
  const backgrounds: Record<TemplateBannerType, SurfaceBackgroundColor> = {
    dark: "dark-brand-01",
    light: "light-brand-02",
    contained: "light-white",
    "light-neutral-01": "light-neutral-01",
  };

  const baseStyle = getBaseStyle(type);
  const surfaceBackground: SurfaceBackgroundColor = backgrounds[type];

  const imageAlignment: Record<TemplateBannerAlignment, AlignmentValue> = {
    bottom: "end",
    top: "start",
    center: "center",
  };

  const isContained = baseStyle === "contained";
  const borderWidth = isContained && !isElevated ? "thin" : undefined;

  const columnWithImgWidths: Record<ContentRatio, ColumnValue> = {
    "1/0": 12,
    "2/3": 8,
    "1/1": 6,
  };

  const templateBannerStyles = {
    "--template-banner-min-height": `${minHeight}px`,
    "--template-banner-min-height-m": minHeightM ? `${minHeightM}px` : "auto",
    "--template-banner-min-height-l": minHeightL ? `${minHeightL}px` : "auto",
    "--template-banner-min-height-xl": minHeightXL
      ? `${minHeightXL}px`
      : "auto",
  };

  const [contentRatiosPerBreakpoint, setContentRatios] =
    useState<ContentRatio>("1/1");

  const checkContentRatio = debounce(() => {
    if (contentRatios) {
      for (const [key, value] of Object.entries(ArcBreakpoints) as [
        keyof typeof ArcBreakpoints,
        number,
      ][]) {
        if (window.innerWidth > value) {
          const ratio = contentRatios?.[key];
          if (ratio) {
            setContentRatios(ratio);
            return;
          }
        }
      }
    }

    setContentRatios(contentRatio);
  }, 100);

  useEffect(() => {
    checkContentRatio();
    window.addEventListener("resize", checkContentRatio);

    return () => {
      window.removeEventListener("resize", checkContentRatio);

      checkContentRatio.cancel();
    };
  }, [contentRatios, checkContentRatio]);

  const handleBrokenImage = () => {
    setImageError(true);
  };

  return (
    <div
      style={templateBannerStyles as React.CSSProperties}
      className={classNames(
        `arc-TemplateBanner arc-TemplateBanner-background--${baseStyle}`,
        {
          "arc-TemplateBanner--elevation": isElevated,
          "arc-TemplateBanner--minHeightM": minHeightM,
          "arc-TemplateBanner--minHeightL": minHeightL,
          "arc-TemplateBanner--minHeightXL": minHeightXL,
        },
      )}
      {...filterAttrs(props)}
    >
      <Box
        isBorderRadius
        data-testid="arc-TemplateBanner-box"
        borderWidth={borderWidth}
        surface={surfaceBackground}
      >
        <Grid isGutterless isFluid>
          <GridRow
            data-testid="arc-TemplateBanner-gridRow"
            direction={isReversed ? "row-reverse" : "row"}
          >
            <GridCol
              data-testid="arc-TemplateBanner-contentCol"
              align={{
                m: alignment === "start" ? "start" : "center",
                xs:
                  !img || contentRatiosPerBreakpoint === "1/0"
                    ? alignment
                    : "start",
              }}
              xs={12}
              order={{ xs: isContained && isReversed ? 1 : 0, m: 0 }}
              m={img ? columnWithImgWidths[contentRatiosPerBreakpoint] : 12}
            >
              <div
                className={classNames("arc-TemplateBanner-content", {
                  "arc-TemplateBanner-content--additionalTopMargin":
                    additionalTopMargin && alignment === "start",
                })}
              >
                {label && (
                  <>
                    <Heading
                      level={labelLevel}
                      fontStyle="overline"
                      isWordWrap={false}
                      color={labelColor}
                    >
                      {label}
                    </Heading>
                    <VerticalSpace size="8" />
                  </>
                )}
                <Heading
                  level={headingLevel}
                  size={headingSize}
                  fontStyle={fontStyle}
                  isWordWrap={headingWordWrap}
                  color={headingColor}
                >
                  {heading}
                </Heading>
                {text && (
                  <>
                    <VerticalSpace size="16" />
                    <span className="arc-TemplateBanner-text">{text}</span>
                  </>
                )}

                {children && (
                  <span>
                    {heading && <VerticalSpace size="32" />}
                    {children}
                  </span>
                )}
              </div>
            </GridCol>
            {img && contentRatiosPerBreakpoint !== "1/0" && (
              <GridCol
                data-testid="arc-TemplateBanner-imageCol"
                align={
                  imageError
                    ? { xs: "center" }
                    : img.fit !== "cover"
                      ? { m: imageAlignment[img.alignment || "center"] }
                      : undefined
                }
                xs={12}
                {...(contentRatiosPerBreakpoint === "2/3" && img
                  ? { m: 4 }
                  : { m: 6 })}
              >
                <BannerImage
                  onImageError={handleBrokenImage}
                  ariaHidden
                  {...img}
                />
              </GridCol>
            )}
          </GridRow>
        </Grid>
      </Box>
    </div>
  );
};

type TemplateBannerBaseStyle = "light" | "dark" | "contained";

type TemplateBannerType = "light" | "dark" | "contained" | "light-neutral-01";

const getBaseStyle = (type: TemplateBannerType): TemplateBannerBaseStyle => {
  switch (type) {
    case "dark":
      return "dark";
    case "contained":
      return "contained";
    default:
      return "light";
  }
};

type TemplateBannerAlignment = "top" | "bottom" | "center";

interface TemplateBannerImage extends BannerImageProps {
  alignment?: TemplateBannerAlignment;
}

type ContentRatio = "2/3" | "1/1" | "1/0";

export interface contentRatiosProps {
  xs?: ContentRatio;
  s?: ContentRatio;
  m?: ContentRatio;
  l?: ContentRatio;
  xl?: ContentRatio;
  xxl?: ContentRatio;
}

export interface TemplateBannerProps {
  /**
   * Align content for TemplateBanner
   */
  alignment?: "start" | "center";
  /**
   * Heading for the TemplateBanner.
   */
  heading: string;

  /**
   * Image props for the TemplateBanner. Consider avoiding alt if the image is for decorative purposes only.
   */
  img?: TemplateBannerImage;

  /**
   * Provides a minimum height for the TemplateBanner. (px value)
   */
  minHeight?: number;

  /**
   * The minimum height of the TemplateBanner for the M breakpoint. (px value)
   * Active when viewport width is between 768px and 1023px.
   */
  minHeightM?: number;

  /**
   * The minimum height of the TemplateBanner for the L breakpoint. (px value)
   * Active when viewport width is between 1024px and 1279px.
   */
  minHeightL?: number;

  /**
   * The minimum height of the TemplateBanner for the XL breakpoint. (px value)
   * Active when viewport width is 1280px and above
   */
  minHeightXL?: number;

  /**
   * If true the image will appear on the left and the content will be on the right. Doesn't apply to mobile devices.
   */
  isReversed?: boolean;

  /**
   * Adds a gradient box shadow to the TemplateBanner.
   */
  isElevated?: boolean;

  /**
   * Content for the TemplateBanner.
   */
  children?: React.ReactNode;

  /**
   * Heading level for the Banner heading.
   */
  headingLevel?: HeadingLevel;

  /**
   * Heading size for the Banner heading.
   */
  headingSize?: Extract<HeadingSize, "m" | "xl" | "xxl">;

  /**
   * Uppercase label for the TemplateBanner.
   */
  label?: string;

  /**
   * Text content for the TemplateBanner.
   */
  text?: ReactNode;

  /**
   * Sets the background style of the `TemplateBanner`. Defaults to `"light"`.
   * `"light"` uses `light-brand-02` surface, `"dark"` uses `dark-brand-01` surface,
   * `"contained"` uses `light-white` surface, `"light-neutral-01"` uses `light-neutral-01` surface.
   */
  type?: TemplateBannerType;

  /**
   * Defines the ratio of the content area within the banner layout.
   */
  contentRatio?: ContentRatio;

  /**
   * Sets the ratio of the content area within the banner layout at each breakpoint (xs, s, m, l, xl, xxl). inherits from smaller breakpoints
   */
  contentRatios?: contentRatiosProps;

  /**
   * Add Additional top margin to banner
   */
  additionalTopMargin?: boolean;

  /**
   *  If `true`, the element expands to match the full vertical height of its parent container.
   */
  fullHeight?: boolean;

  /**
   * Add a heading level for the label.
   */
  labelLevel?: HeadingLevel;

  /**
   * Changes the Heading font family. Please note `dottee` fonts will only work when theme is set to `ee`
   */
  fontStyle?:
    | "default"
    | "display-standard"
    | "display-condensed"
    | "display-extended";

  /**
   * Whether long words in heading should be wrapped.
   */
  headingWordWrap?: boolean;
  /**
   * The color of the Heading
   */
  headingColor?: HeadingColor;
  /**
   * The color of the Label
   */
  labelColor?: HeadingColor;
}
