import React, { useId, type ReactNode } from "react";

import svgToMiniDataURI from "mini-svg-data-uri";
import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { VisuallyHidden } from "../../../VisuallyHidden";
import { ConditionalWrapper } from "../../../ConditionalWrapper";
import { type ProgressStatus } from "../../progressStatus";

import { Icon } from "../../../Icon";

import { Error } from "../../assets/icons/Error";
import { Warning } from "../../assets/icons/Warning";
import { Complete } from "../../assets/icons/Complete";
import { Current } from "../../assets/icons/Current";

export const ProgressStepperItem = ({
  title,
  titleHref,
  subTitle,
  direction = "horizontal",
  status = "todo",
  size = "large",
  isFluid,
  invertLabelPosition,
  ariaLabel,
  onClick,
  previousStep,
  stepContent,
  isStepContentHidden,
  isViewing,
  ...props
}: ProgressStepperItemProps) => {
  const id = useId();

  const statusIcons: Record<ProgressStatus, string | undefined> = {
    todo: undefined,
    completed: Complete,
    current: Current,
    warning: Warning,
    error: Error,
  };

  const onClickHandler = (event: React.MouseEvent<HTMLAnchorElement>) => {
    event.preventDefault();
    onClick && onClick();
  };

  const statusIcon = statusIcons[status];

  const accessibleStatusLabel = `${status === "todo" ? "to do" : status}${
    isViewing ? " - currently viewing" : ""
  }`;

  return (
    <li
      data-progress-stepper-item-id={id}
      className={classNames(
        "arc-ProgressStepperItem",
        `arc-ProgressStepperItem--${status}`,
        `arc-ProgressStepperItem--${size}`,
        {
          "arc-ProgressStepperItem--vertical": direction === "vertical",
          "arc-ProgressStepperItem--isFluid":
            isFluid && direction !== "vertical",
          "arc-ProgressStepperItem--previousStepCompleted":
            previousStep === "completed",
          [`arc-ProgressStepperItem--hasInteractiveStatus`]:
            onClick || titleHref || status !== "todo",
          "arc-ProgressStepperItem--invertLabelPosition":
            direction !== "vertical" && invertLabelPosition,
        },
      )}
      {...filterAttrs(props)}
    >
      <div className="arc-ProgressStepperItem-iconSection">
        <div
          className="arc-ProgressStepperItem-iconWrapper"
          data-testid="arc-ProgressStepperItem-iconWrapper"
        >
          <span
            className={classNames("arc-ProgressStepperItem-statusIcon", {
              "arc-ProgressStepperItem-statusIcon--small": size === "small",
            })}
          >
            {status === "todo" && !isViewing ? null : isViewing ? (
              <div className="arc-ProgressStepperItem-statusIconInner" />
            ) : (
              status !== "current" && (
                <Icon icon={statusIcon && svgToMiniDataURI(statusIcon)} />
              )
            )}

            {/* Render dot by default on current step when no currentStep is passed */}
            {status === "current" && isViewing === undefined ? (
              <Icon icon={statusIcon && svgToMiniDataURI(statusIcon)} />
            ) : null}
          </span>
        </div>
      </div>
      <div className="arc-ProgressStepperItem-textSection">
        <ConditionalWrapper
          condition={Boolean(titleHref || onClick)}
          wrapper={(children) => (
            <a
              role={!titleHref && onClick ? "button" : undefined}
              href={titleHref}
              className={classNames(
                "arc-ProgressStepperItem-title",
                "arc-ProgressStepperItem-title--link",
              )}
              onClick={onClickHandler}
              aria-label={
                ariaLabel ||
                (status !== "current"
                  ? `${title}, ${accessibleStatusLabel}`
                  : undefined)
              }
              aria-current={status === "current" && "step"}
            >
              {children}
            </a>
          )}
          fallback={(children) => (
            <div className="arc-ProgressStepperItem-title">
              {children}
              <VisuallyHidden>{` - ${accessibleStatusLabel}`}</VisuallyHidden>
            </div>
          )}
        >
          {title}
        </ConditionalWrapper>

        {subTitle && (
          <div className="arc-ProgressStepperItem-subTitle">{subTitle}</div>
        )}

        {stepContent && !isStepContentHidden && direction === "vertical" && (
          <>
            <div className="arc-ProgressStepperItem-nodeItem">
              {stepContent}
            </div>
          </>
        )}
      </div>
    </li>
  );
};

export interface ProgressStepperItemProps {
  /**
   * Determine a title for `<ProgressStepperItem />`
   */
  title: string;

  /**
   * Determine a title for `<ProgressStepperItem />`
   */
  titleHref?: string;

  /**
   * Text to override `linkTitle` with additional, more precise information
   * specifically for screen reader users.
   */
  ariaLabel?: string;

  /**
   * Execute a function on title click `<ProgressStepperItem />`
   */
  onClick?: () => void;

  /**
   * Determine a sub title for `<ProgressStepperItem />`
   */
  subTitle?: string;

  /**
   * Determine a direction for `<ProgressStepperItem />`
   */
  direction?: "horizontal" | "vertical";

  /**
   * Determine a status for `<ProgressStepperItem />`
   */
  status?: ProgressStatus;

  /**
   * Determine the size for `<ProgressStepperItem />`
   */
  size?: "small" | "large";

  /**
   * Determine if `<ProgressStepperItem /> should be Fluid`
   */
  isFluid?: boolean;

  /**
   * Determine the context `<ProgressStepperItem /> should be`
   */
  previousStep?: ProgressStatus;

  /**
   * Determine the `<ProgressStepperItem /> should have a active dot`
   */
  isViewing?: boolean;

  /**
   * DEPRECATED: Determine if `<ProgressStepperItem /> should have expandable content`
   */
  isExpandable?: boolean;

  /**
   * Invert `<ProgressStepperItem />` labels. Only appliciable for `horizontal direction.`
   */
  invertLabelPosition?: boolean;

  /**
   * Determine what content to display in `<ProgressStepperItem />. To use this option isExpandable must be `true``
   */
  stepContent?: ReactNode;

  /**
   * Determine if `stepContent` is hidden
   */
  isStepContentHidden?: boolean;
}
