import React, { useRef } from "react";

import classNames from "classnames";
import * as RadixDialog from "@radix-ui/react-dialog";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { Heading } from "../Heading";
import { ButtonV2, type ButtonV2Props } from "../ButtonV2/ButtonV2";
import { Text } from "../Text";
import { VerticalSpace } from "../VerticalSpace";
import { ThemeIcon } from "../ThemeIcon";
import { Surface } from "../Surface";

import { useThemeElement } from "../../hooks";

/** Use `Modal` to display information that needs immediate action from a user. */
export const Modal = ({
  title,
  description,
  ariaDescribedBy,
  isOpen,
  actions,
  onRequestClose,
  children,
  role = "dialog",
  shouldReturnFocus = true,
  isContentScrollable = false,
  size = "l",
  fullBleed = false,
  customWidths,
  titleWordWrap,
  ...props
}: ModalProps) => {
  const [themeElement, setThemeElement] = useThemeElement();
  const triggerRef = useRef<HTMLElement | null>(null);

  const setTriggerElement = () =>
    shouldReturnFocus &&
    (triggerRef.current = document.activeElement as HTMLElement);

  const focusTriggerElement = () => {
    if (triggerRef.current) {
      triggerRef.current.focus();
    }
  };

  const canShowClose = role !== "alertdialog" && onRequestClose;
  const ariaProps = {
    ...(ariaDescribedBy ? { "aria-describedby": ariaDescribedBy } : {}),
  };

  const closeModal = () => {
    if (role !== "alertdialog" && onRequestClose) {
      onRequestClose();
    }
  };

  return (
    <div ref={setThemeElement}>
      <RadixDialog.Root open={isOpen}>
        <RadixDialog.Portal container={themeElement}>
          <RadixDialog.Overlay className="arc-Modal-overlay">
            <RadixDialog.Content
              {...ariaProps}
              role={role}
              onOpenAutoFocus={setTriggerElement}
              onCloseAutoFocus={focusTriggerElement}
              onEscapeKeyDown={closeModal}
              onInteractOutside={closeModal}
              aria-modal="true"
              className={classNames("arc-Modal-dialog", {
                [`arc-Modal-dialog--${size}`]: !customWidths,
                [`arc-Modal-dialog--xs-span-${customWidths?.xs}`]:
                  customWidths?.xs,
                [`arc-Modal-dialog--s-span-${customWidths?.s}`]:
                  customWidths?.s,
                [`arc-Modal-dialog--m-span-${customWidths?.m}`]:
                  customWidths?.m,
                [`arc-Modal-dialog--l-span-${customWidths?.l}`]:
                  customWidths?.l,
                "arc-Modal-dialog--maxHeightWindow": isContentScrollable,
                "arc-Modal-dialog--fullBleed": fullBleed,
              })}
              {...filterAttrs(props)}
            >
              {canShowClose && (
                <div className="arc-Modal-iconContainer">
                  <button
                    aria-label="close"
                    onClick={closeModal}
                    className="arc-Modal-closeButton"
                  >
                    <ThemeIcon size={32} icon="modalClose" />
                  </button>
                </div>
              )}

              <>
                {title && (
                  <>
                    <div className="arc-Modal-section">
                      <VerticalSpace size="24" />
                      <Surface>
                        <RadixDialog.Title asChild>
                          <Heading
                            level="1"
                            size="m"
                            isWordWrap={titleWordWrap}
                          >
                            {title}
                          </Heading>
                        </RadixDialog.Title>
                      </Surface>
                      <VerticalSpace size="12" />
                    </div>
                  </>
                )}

                <div className="arc-Modal-content">
                  {title && description && (
                    <div className="arc-Modal-section">
                      <Surface>
                        <RadixDialog.Description asChild>
                          <Text>{description}</Text>
                        </RadixDialog.Description>
                      </Surface>
                    </div>
                  )}

                  {children && (
                    <>
                      {description && (
                        <VerticalSpace
                          data-testid="arc-modal-vertical-space"
                          size="32"
                        />
                      )}
                      <div className="arc-Modal-section arc-Modal-custom-section">
                        <Surface>{children}</Surface>
                      </div>
                    </>
                  )}
                </div>
                {!actions && !fullBleed && <VerticalSpace size="24" />}
              </>

              {actions && (
                <>
                  <VerticalSpace size="32" />
                  <div className="arc-Modal-section">
                    <Surface>
                      <div className="arc-Modal-actions">
                        {actions.map((props, i) => (
                          <div
                            key={`arc-modal-button-${i}`}
                            className={classNames("arc-Modal-actionButton", {
                              "arc-Modal-actionButton--compact":
                                props.buttonStyle === "compact",
                            })}
                          >
                            <ButtonV2 isFullWidth {...props} />
                          </div>
                        ))}
                      </div>
                    </Surface>
                  </div>
                  <VerticalSpace size="24" />
                </>
              )}
            </RadixDialog.Content>
          </RadixDialog.Overlay>
        </RadixDialog.Portal>
      </RadixDialog.Root>
    </div>
  );
};

export type modalSpan = 4 | 6 | 8 | 10 | 12;

export interface ModalProps {
  /**
   * Title for the modal. This will be announced by screen readers when the modal opens.
   */
  title?: string;

  /**
   * Role for the modal. use alertdialog if explicit user input is required e.g deleting an account. role alertdialog will remove the ability to close the modal by either the esc key being pressed, clicking the cross icon or clicking outside.
   */
  role?: "dialog" | "alertdialog";

  /**
   * Whether to return focus to the element that was focused before the modal opened. True by default.
   */
  shouldReturnFocus?: boolean;

  /**
   * Description for the modal. This will be announced by screen readers when the modal opens.
   */
  description?: string;

  /**
   * ID for the element description to be announced by screenreaders in addition to the title.
   */
  ariaDescribedBy?: string;

  /**
   * Configurable actions for the modal.
   */
  actions?: Pick<
    ButtonV2Props,
    | "form"
    | "type"
    | "buttonStyle"
    | "icon"
    | "iconPosition"
    | "href"
    | "id"
    | "label"
    | "onClick"
    | "isLoading"
    | "ariaLabel"
    | "rel"
  >[];

  /**
   * Function to be called when the modal has been requested to close by either the esc key being pressed, outside the dialog being clicked or the close button being clicked. The callback must set the open state of the modal to false. This function is ignored if the `role` prop is set to `alertdialog`. You can prevent this behavior with the `dialog` role by ommitting this prop.
   */
  onRequestClose?: () => void;

  /**
   * Size of the modal dialog.
   */
  size?: "l" | "m" | "s";

  /**
   * Set modal open or closed.
   */
  isOpen?: boolean;

  /**
   * Enables the dialog content to be scrolled internally.
   */
  isContentScrollable?: boolean;

  /**
   * Custom content for `Modal`.
   */
  children?: React.ReactNode;

  /**
   * Removes all default padding from the children section of the modal.
   */
  fullBleed?: boolean;

  /**
   * Overrides the default widths of the `size` property. Select the number of columns to span on each breakpoint and above (Even numbers from 4 to 12).
   */
  customWidths?: {
    xs?: modalSpan;
    s?: modalSpan;
    m?: modalSpan;
    l?: modalSpan;
  };

  /**
   * Whether long words in title should be wrapped.
   */
  titleWordWrap?: boolean;
}
