import React, { useRef, useState, type ReactNode } from "react";

import { getFocusableElements } from "@arc-ui/helpers/get-focusable-elements";

import { Popover } from "../../../Popover";
import { Tooltip } from "../../../Tooltip";
import { useInteractionMode } from "../../../../hooks";

import { NavigationHeaderButton } from "../NavigationHeaderButton";
import { useTriggerHidden } from "../../hooks/use-trigger-hide";
import { DELAY_DURATION } from "../../constants/tooltip";

export const NavigationHeaderDropdown = ({
  children,
  trigger,
  ariaLabel,
  tooltip,
  onClick,
}: NavigationHeaderDropdownProps) => {
  const [isOpen, setIsOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const { interactionMode } = useInteractionMode();

  useTriggerHidden({
    triggerEl: triggerRef.current as HTMLElement,
    onTriggerHidden: () => {
      setIsOpen(false);
    },
  });

  // if focus isnt going anywhere else and closed via keyboard, return focus to the trigger
  const onCloseAutoFocus = () => {
    if (
      document.activeElement?.tagName === "BODY" &&
      interactionMode === "keyboard"
    ) {
      triggerRef.current?.focus();
    }
  };

  // Only count it as an outside interaction if the trigger isnt being clicked.
  const handleOutSideInteraction = (event: Event) => {
    if (!triggerRef.current?.contains(event.currentTarget as Node)) {
      setIsOpen(false);
    }
  };

  // Find the first focusable element.
  const focusOnFirstElement = () => {
    getFocusableElements(containerRef.current as Node)[0]?.focus({
      preventScroll: true,
    });
  };

  const toggleVisibility = (e: React.MouseEvent<HTMLButtonElement>) => {
    onClick && onClick(e);
    setIsOpen((isOpen) => !isOpen);
  };

  return (
    <>
      <Popover
        useBespokeTrigger
        constrainToViewport={false}
        align="center"
        background="light"
        arrow={true}
        sideOffset={12}
        alignOffset={0}
        open={isOpen}
        onCloseAutoFocus={onCloseAutoFocus}
        onOpenAutoFocus={focusOnFirstElement}
        onEscapeKeyDown={handleOutSideInteraction}
        onFocusOutside={handleOutSideInteraction}
        onInteractOutside={handleOutSideInteraction}
        onPointerDownOutside={handleOutSideInteraction}
        content={<div ref={containerRef}>{children}</div>}
        className="arc-NavigationHeaderDropdown"
      >
        {tooltip ? (
          <Tooltip
            asChild
            title={tooltip}
            alignContent="center"
            delayDuration={DELAY_DURATION}
            side="bottom"
          >
            <NavigationHeaderButton
              isPadded={false}
              ref={triggerRef}
              aria-label={ariaLabel}
              aria-expanded={isOpen}
              aria-haspopup="dialog"
              aria-describedby={undefined}
              onClick={toggleVisibility}
            >
              {trigger}
            </NavigationHeaderButton>
          </Tooltip>
        ) : (
          <NavigationHeaderButton
            ref={triggerRef}
            aria-label={ariaLabel}
            aria-expanded={isOpen}
            aria-haspopup="dialog"
            isActive={isOpen}
            onClick={toggleVisibility}
          >
            {trigger}
          </NavigationHeaderButton>
        )}
      </Popover>
    </>
  );
};

export interface NavigationHeaderDropdownProps {
  /**
   * Accessible label for the dropdown trigger.
   */
  ariaLabel?: string;
  /**
   * Tooltip text for the dropdown trigger.
   */
  tooltip?: string;
  /**
   * Click handler for the dropdown trigger.
   */
  onClick?: (e: React.MouseEvent<HTMLButtonElement>) => void;
  /**
   * Trigger element for the dropdown.
   */
  trigger: ReactNode;

  /**
   * Content to display in the dropdown.
   */
  children: ReactNode;
}
