import { type EmblaOptionsType } from "embla-carousel";

import { type BreakPoints } from "../types/breakpoints";
import { type Responsive } from "../types/responsive";

import {
  L_BREAKPOINT,
  M_BREAKPOINT,
  S_BREAKPOINT,
  XL_BREAKPOINT,
  XS_BREAKPOINT,
} from "../constants/breakpoints";

export const getOptions = (
  itemsToScroll: number,
  loop: boolean,
  responsive?: Responsive,
): EmblaOptionsType => {
  const breakpoints: [string, BreakPoints][] = [
    [XS_BREAKPOINT, "xs"],
    [S_BREAKPOINT, "s"],
    [M_BREAKPOINT, "m"],
    [L_BREAKPOINT, "l"],
    [XL_BREAKPOINT, "xl"],
  ];

  const breakpointOptions = breakpoints.reduce((acc, [query, breakpoint]) => {
    return {
      ...acc,
      ...{
        ...(responsive?.[breakpoint]
          ? {
              [query]: {
                slidesToScroll: responsive?.[breakpoint]?.itemsToScroll,
              },
            }
          : {}),
      },
    };
  }, {});

  return {
    loop,
    skipSnaps: true,
    align: "start",
    slidesToScroll: itemsToScroll,
    breakpoints: breakpointOptions,
  };
};
