import React, { type ComponentType, useContext, type ReactNode } from "react";

import classNames from "classnames";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";

import { SurfaceContext } from "../../../Surface";
import { SemanticLink } from "../../../SemanticLink";

import { BtLogo } from "../../svg/BtLogo";
import { EeLogo } from "../../svg/EeLogo";
import { BtGlobalFabricLogo } from "../../svg/BtGlobalFabricLogo";
import { BtWholesaleLogo } from "../../svg/BtWholesaleLogo";

export const NavigationHeaderLogo = ({
  brand = "bt",
  href = "/",
  ariaLabel = "Home",
  svg,
  onClick,
}: NavigationHeaderLogoProps) => {
  const { surface } = useContext(SurfaceContext);

  const logos: Record<Brand, ComponentType> = {
    bt: BtLogo,
    ee: EeLogo,
    btGlobalFabric: BtGlobalFabricLogo,
    btWholesale: BtWholesaleLogo,
  };

  const icon = svg || React.createElement(logos[brand]);

  return (
    <SemanticLink
      className={classNames(
        "arc-NavigationHeaderLogo",
        suffixModifier("arc-NavigationHeaderLogo--on", surface),
      )}
      aria-label={ariaLabel}
      onClick={onClick}
      href={href}
    >
      {icon}
    </SemanticLink>
  );
};

export type Brand = "btWholesale" | "btGlobalFabric" | "ee" | "bt";

export interface NavigationHeaderLogoProps {
  /**
   * Accessible label for the logo link.
   */
  ariaLabel?: string;
  /**
   * Brand variant for the logo.
   */
  brand?: Brand;
  /**
   * URL to link to when the logo is clicked.
   */
  href?: string;
  /**
   * Custom SVG to display instead of the default brand logo.
   */
  svg?: ReactNode;
  /**
   * Click handler for the logo link.
   */
  onClick?: (e: React.MouseEvent<HTMLAnchorElement, MouseEvent>) => void;
}
