import React from "react";

import classNames from "classnames";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";

import { ThemeIcon } from "../../../ThemeIcon";
import { type InputSize } from "../../types";

export const ComboBoxClearButton = ({
  ref,
  inputSize,
  tooltip,
  onKeyDown,
  onMouseDown,
  onBlur,
  isDarkSurface,
  ...props
}: ComboBoxClearButtonProps) => (
  <button
    {...props}
    type="button"
    ref={ref}
    aria-label={tooltip}
    onMouseDown={onMouseDown}
    onKeyDown={onKeyDown}
    onBlur={onBlur}
    className={classNames(
      "arc-ComboBoxClearButton",
      suffixModifier("arc-ComboBoxClearButton--size", inputSize),
      {
        "arc-ComboBoxClearButton--onDarkSurface": isDarkSurface,
      },
    )}
  >
    <div className="arc-ComboBoxClearButton-icon">
      <ThemeIcon aria-hidden icon="comboboxClear" />
    </div>
  </button>
);

interface ComboBoxClearButtonProps {
  ref?: React.Ref<HTMLButtonElement>;
  tooltip: string;
  inputSize: InputSize;
  isDarkSurface: boolean;
  onBlur: (e: React.FocusEvent<HTMLButtonElement>) => void;
  onMouseDown: (e: React.MouseEvent<HTMLButtonElement>) => void;
  onKeyDown: (e: React.KeyboardEvent<HTMLButtonElement>) => void;
}
