import React, { type Ref, useEffect, useRef, useState } from "react";

import classNames from "classnames";

import * as Popover from "@radix-ui/react-popover";

import isBefore from "date-fns/isBefore";
import isAfter from "date-fns/isAfter";
import format from "date-fns/format";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { InputIcon } from "../TextInput";
import { type ArcCalendarRangeSelection, Calendar } from "../Calendar";
import { type CalendarProps } from "../Calendar/Calendar";

import { useThemeElement } from "../../hooks";

import {
  TextInputWithPlaceHolder,
  type TextInputWithPlaceholderProps,
} from "../TextInput/TextInput";

import { DATE_FORMAT } from "./constants";

import {
  isDateValid,
  parseDateString,
  isRangeValid,
  formatDate,
  isDisabledDate,
  convertDateStringToDate,
  convertRangeStringToDates,
} from "./helpers";
import { validateRangeOnBlur } from "./helpers/validate-range-on-blur";

/**
 * Use `DatePicker` to clearly present available dates and allow users to choose a way to enter information.
 */
export const DatePicker = ({
  errorMessage,
  helper,
  id,
  label,
  isDisabled,
  isReadOnly,
  isRequired,
  size = "m",
  value = "",
  name,
  onBlur,
  onChange,
  onDateSelect,
  onRangeSelect,
  onClickDisclosure,
  disclosureTitle,
  disclosureText,
  type,
  isFluid = false,
  selectionType = "single",
  disabledDates,
  minDate,
  maxDate,
  ref,
  ...props
}: DatePickerProps) => {
  const [themeElement, setThemeElement] = useThemeElement();
  const [ariaLabel, setAriaLabel] = useState("Choose date");
  const [showCalendar, setShowCalendar] = useState<boolean>(false);
  const buttonRef = useRef<HTMLButtonElement | null>(null);
  const ourRef = useRef<HTMLInputElement | null>(null);
  const previousValidValue = useRef<string | undefined>(value);

  const lowerCaseDateFormat = DATE_FORMAT.toLowerCase();

  const placeHolder =
    selectionType === "range"
      ? `${lowerCaseDateFormat} - ${lowerCaseDateFormat}`
      : lowerCaseDateFormat;

  useEffect(() => {
    if (
      selectionType === "single" &&
      isDateValid(value) &&
      !isDisabledDate(disabledDates, convertDateStringToDate(value))
    ) {
      previousValidValue.current = value;
    }

    if (selectionType === "range" && isRangeValid(value)) {
      const rangeHasDisabledDates = convertRangeStringToDates(value).some(
        (rangeValue) => isDisabledDate(disabledDates, rangeValue),
      );

      if (!rangeHasDisabledDates) {
        previousValidValue.current = value;
      }
    }
  }, [value, disabledDates, selectionType]);

  const getDatePickerRef = (elementRef: HTMLInputElement | null) => {
    ourRef.current = elementRef;

    if (ref && typeof ref === "object") {
      ref.current = elementRef;
    }

    if (ref && typeof ref === "function") {
      ref(elementRef);
    }
  };

  const dispatchChangeEvent = (
    e: React.FocusEvent<HTMLInputElement, Element>,
    value: string,
  ) => {
    onChange &&
      onChange({
        ...e,
        target: {
          ...e.target,
          value,
        },
      });
  };

  const handleRangeSelect = (rangeSelection: ArcCalendarRangeSelection) => {
    const start = formatDate(rangeSelection.start);
    const end = rangeSelection.end ? formatDate(rangeSelection.end) : null;

    onRangeSelect &&
      onRangeSelect({
        ...rangeSelection,
        formattedRange: `${start}${end ? ` - ${end}` : ""}`,
      });

    rangeSelection.isSelectionComplete && setShowCalendar(false);
  };

  const handleDateSelect = (value: Date) => {
    onDateSelect &&
      onDateSelect({
        date: value,
        formattedDate: formatDate(value),
      });

    setShowCalendar(false);
  };

  const handleSingleSelectionBlur = (
    e: React.FocusEvent<HTMLInputElement, Element>,
  ) => {
    if (value && isDateValid(value) && selectionType === "single") {
      const { day, month, year } = parseDateString(value);
      const date = new Date(`${year}-${month}-${day}`);

      const isDateBeforeMinDate = minDate && isBefore(date, minDate);
      const isDateAfterMaxDate = maxDate && isAfter(date, maxDate);
      const isDisabledValue = isDisabledDate(disabledDates, date);

      if (isDateBeforeMinDate) {
        return dispatchChangeEvent(e, `${formatDate(minDate)}`);
      }

      if (isDateAfterMaxDate) {
        return dispatchChangeEvent(e, `${formatDate(maxDate)}`);
      }

      if (isDisabledValue) {
        const date = previousValidValue.current
          ? convertDateStringToDate(previousValidValue.current)
          : new Date();

        return dispatchChangeEvent(e, `${formatDate(date)}`);
      }
    }
  };

  const handleRangeSelectionBlur = (
    e: React.FocusEvent<HTMLInputElement, Element>,
  ) => {
    validateRangeOnBlur({
      value,
      minDate,
      maxDate,
      disabledDates,
      previousValidValue: previousValidValue.current,
      dispatchChangeEvent,
      blurEvent: e,
    });
  };

  const handleBlur = (e: React.FocusEvent<HTMLInputElement, Element>) => {
    onBlur && onBlur(e);

    if (selectionType === "single") {
      handleSingleSelectionBlur(e);
    }

    if (selectionType === "range") {
      handleRangeSelectionBlur(e);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onChange && onChange(e);
  };

  const handleCalendarOpenChange = (isOpen: boolean) => {
    if (document.activeElement) setShowCalendar(isOpen);
  };

  const handleIconClick = () => {
    !ourRef.current?.contains(document.activeElement) &&
      !isDisabled &&
      !isReadOnly &&
      setShowCalendar(true);
  };

  const handleIconFocus = () => {
    if (selectionType === "range" && isRangeValid(value)) {
      const [start, end] = convertRangeStringToDates(value);

      return setAriaLabel(
        `Change dates, currently selected dates are ${format(
          start,
          "EEEE do MMMM, yyyy",
        )} to ${format(end, "EEEE do MMMM, yyyy")}`,
      );
    }

    if (selectionType === "single" && isDateValid(value)) {
      const date = convertDateStringToDate(value);

      return setAriaLabel(
        `Change date, currently selected date is ${format(
          date,
          "EEEE do MMMM, yyyy",
        )}`,
      );
    }

    setAriaLabel("Choose Date");
  };

  const handleCalendarClose = () => {
    if (document.activeElement?.tagName === "BODY") {
      buttonRef.current?.focus();
    }
  };

  const onCancelClick = () => {
    setShowCalendar(false);
  };

  const handleAutoFocus = (e: Event) => {
    e.preventDefault();
  };

  return (
    <div
      ref={setThemeElement}
      className={classNames({
        "arc-DatePicker--constrained": !isFluid,
      })}
    >
      <TextInputWithPlaceHolder
        ref={getDatePickerRef}
        trailingSlot={
          <InputIcon
            themeIcon="datePickerCalendar"
            size={size}
            isReadOnly={isReadOnly}
            isDisabled={isDisabled}
            isButton={{
              ref: buttonRef,
              onClick: handleIconClick,
              onFocus: handleIconFocus,
              label: ariaLabel,
            }}
          />
        }
        placeholder={placeHolder}
        errorMessage={errorMessage}
        helper={helper}
        id={id}
        isDisabled={isDisabled}
        isReadOnly={isReadOnly}
        isRequired={isRequired}
        label={label}
        maxLength={selectionType === "range" ? 23 : 10}
        name={name}
        onBlur={handleBlur}
        onChange={handleChange}
        onClickDisclosure={onClickDisclosure}
        type="text"
        value={value}
        disclosureTitle={disclosureTitle}
        disclosureText={disclosureText}
        size={size}
        {...props}
        {...filterAttrs(props)}
      />

      <Popover.Root
        open={showCalendar}
        onOpenChange={handleCalendarOpenChange}
        {...filterAttrs(props)}
      >
        <Popover.Anchor />
        <Popover.Portal container={themeElement}>
          <Popover.Content
            align="start"
            aria-modal="true"
            aria-label="Choose Date"
            className="arc-DatePicker-modal"
            onOpenAutoFocus={handleAutoFocus}
            onCloseAutoFocus={handleCalendarClose}
          >
            <Calendar
              autoFocusOnMount
              type={type}
              onCancelClick={onCancelClick}
              selectionType={selectionType}
              selectedDate={convertDateStringToDate(value)}
              selectedRange={convertRangeStringToDates(value)}
              disabledDates={disabledDates}
              minDate={minDate}
              maxDate={maxDate}
              onDateSelect={handleDateSelect}
              onRangeSelect={handleRangeSelect}
            />
          </Popover.Content>
        </Popover.Portal>
      </Popover.Root>
    </div>
  );
};

interface DatePickerRangeSelection extends ArcCalendarRangeSelection {
  formattedRange: string;
}

export interface DatePickerProps
  extends
    Omit<
      TextInputWithPlaceholderProps,
      | "defaultValue"
      | "inputMode"
      | "minLength"
      | "maxLength"
      | "pattern"
      | "type"
      | "showPassword"
      | "placeholder"
      | "trailingInputIcon"
      | "prefix"
      | "suffix"
    >,
    Omit<
      CalendarProps,
      "onDateSelect" | "onRangeSelect" | "selectedDate" | "selectedRange"
    > {
  /**
   * Ref to the underlying input element.
   */
  ref?: Ref<HTMLInputElement>;
  /**
   * Whether the DatePicker should take up the full width of its container.
   */
  isFluid?: boolean;
  /**
   * Callback when a single date is selected.
   */
  onDateSelect?: (value: { date: Date; formattedDate: string }) => void;
  /**
   * Callback when a date range is selected.
   */
  onRangeSelect?: (value: DatePickerRangeSelection) => void;
}
