import { convertOptionsToObjects } from "./utils/convertOptionsToObjects";
import { fuzzySearch } from "./utils/fuzzySearch";
import { findOptionIndex } from "./utils/findOptionIndex";
import { getClosestMatchingOptionIndex } from "./utils/getClosestMatchingOptionIndex";
import { getMatchingOption } from "./utils/getMatchingOption";
import { getKeydownOptionToHighlight } from "./utils/getKeydownOptionToHighlight";
import { multiSelectLimitReached } from "./utils/multiSelectLimitReached";
import { convertOptionsToText } from "./utils/convertOptionsToText";
import { getNewMultiSelectOptions } from "./utils/getNewMultiSelectOptions";

import { type Action, type State } from "./types";

export const reducer =
  (initialOptions: string[]) =>
  (state: State, action: Action): State => {
    switch (action.type) {
      case "OPEN": {
        return {
          ...state,
          isExpanded: true,
          highlightedOptionIndex: 0,
        };
      }
      case "CLOSE_MENU": {
        return {
          ...state,
          showAllTags: false,
          isExpanded: false,
          highlightedOptionIndex: undefined,
        };
      }
      case "CLEAR": {
        return {
          ...state,
          value: "",
          singleSelectedOption: action.payload.isCustomEntryAllowed
            ? { isCustom: false, text: "" }
            : state.singleSelectedOption,
          options: convertOptionsToObjects(initialOptions),
          onChangeValue: action.payload.isMultiSelectable
            ? convertOptionsToText(state.selectedOptions)
            : "",
        };
      }
      case "SHOW_ALL_TAGS": {
        return {
          ...state,
          showAllTags: true,
        };
      }
      case "EXIT_INPUT": {
        const { isMultiSelectable, isCustomEntryAllowed } = action.payload;
        const matchingOption = getMatchingOption(state.options, state.value);
        const allOptions = convertOptionsToObjects(initialOptions);

        const isCustomEntrySingleSelect =
          !isMultiSelectable && isCustomEntryAllowed;

        const isConstrainedSingleSelect =
          !isMultiSelectable && !isCustomEntryAllowed;

        const commonState: State = {
          ...state,
          options: allOptions,
          showAllTags: false,
          isExpanded: false,
          highlightedOptionIndex: undefined,
        };

        if (!isMultiSelectable && matchingOption) {
          return {
            ...commonState,
            singleSelectedOption: matchingOption,
            value: matchingOption.text,
            onChangeValue: matchingOption.text,
          };
        }

        if (isCustomEntrySingleSelect && !matchingOption) {
          return {
            ...commonState,
            value: state.value,
            onChangeValue: state.value,
          };
        }

        if (isConstrainedSingleSelect) {
          const newValue = state.singleSelectedOption?.text || "";

          return {
            ...commonState,
            value: newValue,
            onChangeValue: newValue,
          };
        }

        return {
          ...commonState,
          value: "",
          onChangeValue: isMultiSelectable
            ? convertOptionsToText(state.selectedOptions)
            : "",
        };
      }
      case "SET_HIGHLIGHTED_OPTION": {
        const { index } = action.payload;

        return {
          ...state,
          highlightedOptionIndex: index,
        };
      }
      case "INPUT_CHANGE": {
        const {
          value,
          isAutocomplete,
          isCustomEntryAllowed,
          isMultiSelectable,
          fuzzyThreshold,
        } = action.payload;

        const filteredOptions = fuzzySearch(
          initialOptions,
          value,
          fuzzyThreshold,
        );
        const matchingOption = getMatchingOption(state.options, value);

        const showCustomMultiSelectOption =
          Boolean(value.trim()) &&
          isCustomEntryAllowed &&
          isMultiSelectable &&
          !matchingOption;

        const optionsList = isAutocomplete
          ? filteredOptions
          : convertOptionsToObjects(initialOptions);

        const newOptions = showCustomMultiSelectOption
          ? [{ isCustom: true, text: value }, ...optionsList]
          : optionsList;

        const closestMatchingOptionIndex = getClosestMatchingOptionIndex(
          newOptions,
          filteredOptions,
        );

        const singleSelectedOption = isCustomEntryAllowed
          ? { isCustom: false, text: "" }
          : state.singleSelectedOption;

        const highlightedOptionIndex = isAutocomplete
          ? newOptions.length
            ? 0
            : undefined
          : closestMatchingOptionIndex;

        return {
          ...state,
          value,
          onChangeValue: !isMultiSelectable
            ? value
            : convertOptionsToText(state.selectedOptions),
          options: newOptions,
          singleSelectedOption,
          highlightedOptionIndex,
          isDirty: true,
          isExpanded: true,
        };
      }
      case "SINGLE_SELECT": {
        const { option: selectedOption } = action.payload;
        const { options } = state;

        return {
          ...state,
          isExpanded: false,
          isDirty: true,
          singleSelectedOption: selectedOption,
          options: convertOptionsToObjects(initialOptions),
          highlightedOptionIndex: findOptionIndex(options, selectedOption),
          value: selectedOption.text,
          onChangeValue: selectedOption.text,
        };
      }
      case "MULTI_SELECT": {
        const { option: selectedOption, multiSelectLimit } = action.payload;
        const { selectedOptions } = state;
        const { newOptions, limitReached } = getNewMultiSelectOptions(
          selectedOption,
          selectedOptions,
          multiSelectLimit,
        );

        return {
          ...state,
          limitReached,
          selectedOptions: newOptions,
          onChangeValue: convertOptionsToText(newOptions),
        };
      }
      case "MULTI_SELECT_REMOVE": {
        const { option, multiSelectLimit } = action.payload;
        const { selectedOptions } = state;

        const newSelectedOptions = selectedOptions.filter(
          (selectedOption) => option.text !== selectedOption.text,
        );

        const limitReached = multiSelectLimitReached(
          newSelectedOptions,
          multiSelectLimit,
        );

        return {
          ...state,
          limitReached,
          onChangeValue: convertOptionsToText(newSelectedOptions),
          selectedOptions: newSelectedOptions,
        };
      }
      case "KEYDOWN": {
        const { key, isMultiSelectable, multiSelectLimit } = action.payload;

        const { isExpanded, highlightedOptionIndex, options, selectedOptions } =
          state;

        const hasNoHighlightedOption = highlightedOptionIndex === undefined;

        if (key === "Escape" && isExpanded) {
          return {
            ...state,
            showAllTags: false,
            isExpanded: false,
            highlightedOptionIndex: 0,
          };
        }

        if (key === "ArrowDown" && isExpanded) {
          return {
            ...state,
            highlightedOptionIndex: getKeydownOptionToHighlight({
              isNext: true,
              options,
              highlightedOptionIndex,
            }),
          };
        }

        if (key === "ArrowUp" && isExpanded) {
          return {
            ...state,
            highlightedOptionIndex: getKeydownOptionToHighlight({
              isNext: false,
              options,
              highlightedOptionIndex,
            }),
          };
        }

        if (["ArrowDown", "ArrowUp"].includes(key) && !isExpanded) {
          return {
            ...state,
            isExpanded: true,
            highlightedOptionIndex: 0,
          };
        }

        if (key === "Enter" && isExpanded) {
          if (hasNoHighlightedOption) {
            return { ...state, isExpanded: false };
          }

          if (isMultiSelectable) {
            const { newOptions, limitReached } = getNewMultiSelectOptions(
              options[highlightedOptionIndex],
              selectedOptions,
              multiSelectLimit,
            );

            return {
              ...state,
              limitReached,
              onChangeValue: convertOptionsToText(newOptions),
              selectedOptions: newOptions,
            };
          } else {
            const newSelectedOption = options[highlightedOptionIndex];

            return {
              ...state,
              isExpanded: false,
              singleSelectedOption: newSelectedOption,
              options: convertOptionsToObjects(initialOptions),
              onChangeValue: newSelectedOption.text,
              value: newSelectedOption.text,
            };
          }
        }
        return state;
      }
      default:
        return state;
    }
  };
