import React, { useContext, useState } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { Text } from "../Text";
import { Heading, type HeadingLevel } from "../Heading/Heading";
import { SurfaceContext } from "../Surface";
import { CardHeading, type CardHeadingSize } from "../CardHeading";
import { CardFooter, type CardFooterProps } from "../CardFooter";
import { VerticalSpace } from "../VerticalSpace";
import { ConditionalWrapper } from "../ConditionalWrapper";

/** Use `TypographyCard` for content that benefits from larger and energetic typography. */
export const TypographyCard = ({
  url,
  onClick,
  heading,
  metaText,
  label,
  text,
  minHeight,
  headingSize = "m",
  linkData = {},
  pathway = "light",
  buttonIcon = "arrow",
  headingLevel = "2",
  labelLevel = "3",
  headingWordWrap = false,
  preserveAspectRatios,
  ...props
}: TypographyCardProps) => {
  const { surface } = useContext(SurfaceContext);
  const [showHoverState, setShowHoverState] = useState(false);

  const handleShowHoverState = (show: boolean) => () => setShowHoverState(show);
  const isDarkPathway = pathway === "dark";

  const CardText = ({ text }: { text: string }) => {
    const paragraphs = text.split(/\\n|\n/).filter((p) => p.trim());

    return paragraphs.map((paragraph, index) => (
      <div key={`informationcard-text-${index}`}>
        {index > 0 && <VerticalSpace size="8" />}
        <Text>{paragraph}</Text>
      </div>
    ));
  };

  const aspectRatioClassNames = preserveAspectRatios
    ? Object.entries(preserveAspectRatios)
        .filter(([, value]) => value)
        .map(
          ([breakpoint, ratio]) =>
            `arc-TypographyCard--preserveAspectRatio-${breakpoint}-${ratio}`,
        )
    : [];

  const minHeightStyle = !preserveAspectRatios && {
    minHeight,
  };

  return (
    <ConditionalWrapper
      condition={Boolean(preserveAspectRatios)}
      wrapper={(children) => (
        <div className="arc-TypographyCard--preserveAspectRatioWrapper">
          {children}
        </div>
      )}
    >
      <div
        style={{ ...minHeightStyle }}
        className={classNames("arc-TypographyCard", ...aspectRatioClassNames, {
          "arc-TypographyCard--outlined": showHoverState,
          "arc-TypographyCard--darkPathway": isDarkPathway,
          "arc-TypographyCard--lightPathway": !isDarkPathway,
          "arc-TypographyCard--onDarkSurface": surface === "dark",
        })}
        {...filterAttrs(props)}
      >
        <div className="arc-TypographyCard-contentContainer">
          {label && (
            <div className="arc-TypographyCard-label">
              <Heading level={labelLevel} fontStyle="overline">
                {label}
              </Heading>
              <VerticalSpace size="16" />
            </div>
          )}

          <CardHeading
            size={headingSize}
            linkData={linkData}
            heading={heading}
            headingLevel={headingLevel}
            href={url}
            onClick={onClick}
            onMouseEnter={handleShowHoverState(true)}
            onMouseLeave={handleShowHoverState(false)}
            onFocus={handleShowHoverState(true)}
            onBlur={handleShowHoverState(false)}
            headingWordWrap={headingWordWrap}
            isHovered={showHoverState}
            isDarkPathway={isDarkPathway}
          />
          {text && (
            <>
              <VerticalSpace size="16" />
              <CardText text={text} />
            </>
          )}
        </div>

        <CardFooter
          showButton
          isDarkPathway={isDarkPathway}
          buttonIcon={buttonIcon}
          metaText={metaText}
          isHovered={showHoverState}
        />
      </div>
    </ConditionalWrapper>
  );
};

type TypographyCardPathway = "light" | "dark";

type AspectRatios = "3-4" | "10-16";

export interface TypographyCardProps {
  /**
   * Heading for the TypographyCard.
   */
  heading: string;

  /**
   * Heading size for the ImpactCard.
   */
  headingSize?: CardHeadingSize;

  /**
   * Url for the TypographyCard.
   */
  url: string;

  /**
   * Text content for the TypographyCard. Use \n to create multiple paragraphs, up to 3 paragraphs.
   */
  text?: string;

  /**
   * Sets a dark or light background for the TypographyCard.
   */
  pathway?: TypographyCardPathway;

  /**
   * Icon for the TypographyCard Cta button.
   */
  buttonIcon?: CardFooterProps["buttonIcon"];

  /**
   * Heading level for the TypographyCard heading.
   */
  headingLevel?: HeadingLevel;

  /**
   * Uppercase label for the TypographyCard.
   */
  label?: string;

  /**
   * Click handler for the TypographyCard.
   */
  onClick?: (e: React.MouseEvent<HTMLAnchorElement>) => void;

  /**
   * Text to show adjacent to the cta, can be either a date or text. Its recommended to pass dates as Date objects so the component can render them correctly.
   */
  metaText?: CardFooterProps["metaText"];

  /**
   * Sets a minimum height for the TypographyCard.
   */
  minHeight?: number;

  /**
   * Object of `data-` attributes to render on internal anchor element, e.g.
   * `{ data-analytics-link: "My link"}` => `<a data-analytics-link="My link">`.
   */
  linkData?: { [key: string]: string };

  /**
   * Heading level for the TypographyCard label.
   */
  labelLevel?: HeadingLevel;
  /**
   * Whether long words in heading should be wrapped.
   */
  headingWordWrap?: boolean;
  /**
   * Preserve aspect ratio of the TypographyCard. Set minHeight depending on Card width. Overwrites minHeight prop value.
   */
  preserveAspectRatios?: {
    xs?: AspectRatios;
    s?: AspectRatios;
    m?: AspectRatios;
    l?: AspectRatios;
    xl?: AspectRatios;
    xxl?: AspectRatios;
    xxxl?: AspectRatios;
  };
}
