import React, { type ReactElement, useContext, type Ref } from "react";

import classNames from "classnames";

import { capitaliseFirstLetter } from "@arc-ui/helpers/capitalise-first-letter";

import { type ContextProps } from "../../context";
import { SurfaceContext } from "../../../Surface";
import { Icon } from "../../../Icon";

export const RadioCard = ({
  ref,
  id,
  icon,
  label,
  support,
  isDisabled,
  checked,
  defaultChecked,
  changeEvent,
  name,
  blurEvent,
  value,
  children,
  controlLocation = "right",
  hideButton = false,
}: RadioCardProps) => {
  const { surface } = useContext(SurfaceContext);

  const idLabel = `${id}-label`;

  return (
    <div
      className={classNames("arc-RadioCard", {
        "arc-RadioCard--isDisabled": isDisabled,
        "arc-RadioCard--onDarkSurface": surface === "dark",
        "arc-RadioCard--isSelected": checked,
      })}
    >
      <label id={idLabel} htmlFor={id}>
        <input
          className="arc-RadioCard-input"
          id={id}
          checked={checked}
          defaultChecked={defaultChecked}
          disabled={isDisabled}
          onChange={changeEvent}
          onBlur={blurEvent}
          name={name}
          ref={ref}
          type="radio"
          value={value}
          aria-checked={checked}
        />
        <div
          className={`arc-RadioCard-inner arc-RadioCard--control${capitaliseFirstLetter(
            controlLocation,
          )}`}
        >
          {icon && (
            <div className="arc-RadioCard-icon">
              <Icon icon={icon} size={24} />
            </div>
          )}
          <div className="arc-RadioCard-content">
            <span className="arc-RadioCard-label">{label}</span>
            {support && (
              <span className="arc-RadioCard-support">{support}</span>
            )}
          </div>

          {children && (
            <div className="arc-RadioCard-customContent">{children}</div>
          )}

          {!hideButton && (
            <div
              className={classNames("arc-RadioCard-radioIcon", {
                "arc-RadioCard-radioIcon--isSelected": checked,
              })}
            />
          )}
        </div>
      </label>
    </div>
  );
};

export interface RadioCardProps {
  /**
   * Ref to the underlying input element.
   */
  ref?: Ref<HTMLInputElement>;
  /**
   * Custom content to display in the RadioCard.
   */
  children?: ReactElement;
  /**
   * ID for the`RadioCard`.
   */
  id: string;
  /**
   * Should the `RadioCard` be disabled?
   */
  isDisabled?: boolean;
  /**
   * Helper text for the `RadioCard`, shown below the label.
   */
  support?: string;
  /**
   * Label for the `RadioCard`.
   */
  label: string;
  /**
   * Current value (controlled).
   */
  value: string;
  /**
   * Render icon within `RadioCard`
   */
  icon?: string;
  /**
   * Set control location within `RadioCard`.
   */
  controlLocation?: "left" | "right" | "bottom";
  /**
   * Hide the radio button icon from the `RadioCard`.
   */
  hideButton?: boolean;
  /**
   * Should the `RadioCard` be checked by default?
   */
  defaultChecked?: boolean;
  /**
   * State of the checked prop.
   */
  checked?: boolean;
  /**
   * Function called when the RadioCard's value changes.
   */
  changeEvent?: ContextProps["changeEvent"];
  /**
   * Function called when the RadioCard loses focus.
   */
  blurEvent?: ContextProps["blurEvent"];
  /**
   * Reference to radio group name property.
   */
  name: ContextProps["name"];
}
