import { type TextInputProps } from "../../../components/TextInput/TextInput";

/**
 * Infer the correct inputMode, pattern and type if specifying a `number` type.
 */
export const useNumericInput = (
  props: Pick<TextInputProps, "inputMode" | "pattern" | "type">,
) => {
  const type = props.type === "number" ? "text" : props.type;

  let inputMode = props.inputMode;

  if (!props.inputMode) {
    if (props.type === "email") {
      inputMode = "email";
    } else if (props.type === "number") {
      inputMode = "numeric";
    } else if (props.type === "tel") {
      inputMode = "tel";
    } else if (props.type === "url") {
      inputMode = "url";
    }
  }

  let pattern = props.pattern;

  if (!props.pattern && props.type === "number") {
    pattern = "[0-9]*";
  }

  return { inputMode, pattern, type };
};
