import React, { type Ref, useContext } from "react";

import classNames from "classnames";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";
import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { SemanticLink } from "../../../../../SemanticLink";
import { SemanticButton } from "../../../../../SemanticButton";
import { ConditionalWrapper } from "../../../../../ConditionalWrapper";
import { ThemeIcon } from "../../../../../ThemeIcon";
import { SurfaceContext } from "../../../../../Surface";

export const SideMenuLink = ({
  ref,
  href,
  onClick,
  text,
  ...props
}: SideMenuLinkProps) => {
  const { surface } = useContext(SurfaceContext);

  const commonProps: React.HTMLAttributes<HTMLElement> = {
    "aria-label": text,
    onClick: onClick,
    className: classNames(
      "arc-SideMenuLink",
      suffixModifier("arc-SideMenuLink--on", surface),
    ),
    ...filterAttrs(props),
  };

  return (
    <ConditionalWrapper
      condition={Boolean(href)}
      wrapper={(children) => (
        <SemanticLink
          {...commonProps}
          href={href}
          ref={ref as Ref<HTMLAnchorElement>}
        >
          {children}
        </SemanticLink>
      )}
      fallback={(children) => (
        <SemanticButton {...commonProps} ref={ref as Ref<HTMLButtonElement>}>
          {children}
        </SemanticButton>
      )}
    >
      <div className="arc-SideMenuLink-text">{text}</div>

      <span className="arc-SideMenuLink-icon">
        <ThemeIcon icon="navigationHeaderMenuLink" />
      </span>
    </ConditionalWrapper>
  );
};

interface SideMenuLinkProps {
  /**
   * Text to display for the link.
   */
  text: string;
  /**
   * Ref for the link.
   */
  ref?: Ref<HTMLElement>;
  /**
   * URL for the link.
   */
  href?: string;
  /**
   * Click handler for the link.
   */
  onClick?: (e: React.MouseEvent<HTMLAnchorElement, MouseEvent>) => void;
}
