import React, { type ReactNode, type JSX } from "react";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";
import { ArcSizeBreakpointsL } from "@arc-ui/tokens-arc";

import { BtIconChevronRightMid } from "@arc-ui/icons/BtIconChevronRightMid";

import { Icon } from "../../../Icon";
import { ConditionalWrapper } from "../../../ConditionalWrapper";
import { handleLinkClick } from "../../../../helpers/handle-link-click";
import { useMediaQuery } from "../../../../hooks/public/use-media-query";

export const SiteHeaderV2ItemGroup = ({
  children,
  href,
  title,
  subtitle,
  onClick,
  viewAllTitle,
  ...props
}: SiteHeaderV2ItemGroupProps) => {
  const isMinWidthArcBreakpointL = useMediaQuery(
    `(min-width: ${ArcSizeBreakpointsL})`,
  );

  const ElementType: keyof JSX.IntrinsicElements =
    title && !isMinWidthArcBreakpointL ? "details" : "div";
  const ElementTypeSummary: keyof JSX.IntrinsicElements =
    isMinWidthArcBreakpointL ? "div" : "summary";

  return (
    <li className="arc-SiteHeaderV2ItemGroup">
      <ElementType
        className="arc-SiteHeaderV2ItemGroup-details"
        open={Boolean(title && isMinWidthArcBreakpointL)}
        {...filterAttrs(props)}
      >
        {title ? (
          <>
            <ElementTypeSummary
              tabIndex={isMinWidthArcBreakpointL ? -1 : 0}
              className="arc-SiteHeaderV2ItemGroup-summary"
            >
              {href ? (
                <div className="arc-SiteHeaderV2ItemGroup-heading">
                  <ConditionalWrapper
                    condition={isMinWidthArcBreakpointL}
                    wrapper={(children) => (
                      <a
                        onClick={handleLinkClick({
                          handler: onClick,
                        })}
                        className="arc-SiteHeaderV2ItemGroup-title"
                        href={href}
                      >
                        {children}
                      </a>
                    )}
                    fallback={(children) => (
                      <div className="arc-SiteHeaderV2ItemGroup-title">
                        {children}
                      </div>
                    )}
                  >
                    {title}
                  </ConditionalWrapper>
                  <span className="arc-SiteHeaderV2ItemGroup-titleIcon">
                    <Icon icon={BtIconChevronRightMid} />
                  </span>
                </div>
              ) : (
                <div className="arc-SiteHeaderV2ItemGroup-title">{title}</div>
              )}
            </ElementTypeSummary>
            <span className="arc-SiteHeaderV2ItemGroup-subtitle">
              {subtitle}
            </span>
          </>
        ) : null}
        <ul className="arc-SiteHeaderV2ItemGroup-items" role="menubar">
          {children}
          {href && title ? (
            <li className="arc-SiteHeaderV2Item arc-SiteHeaderV2Item--viewAll">
              <a
                className="arc-SiteHeaderV2Item-link"
                onClick={handleLinkClick({
                  handler: onClick,
                })}
                href={href}
              >
                {viewAllTitle || `View all ${title.toLowerCase()}`}
              </a>
            </li>
          ) : null}
        </ul>
      </ElementType>
    </li>
  );
};

export interface SiteHeaderV2ItemGroupProps {
  /**
   * Contents of the ItemGroup Must be Item components.
   */
  children: ReactNode;
  /**
   * Optional subtitle text for the ItemGroup.
   */
  subtitle?: string;
  /**
   * A top-level URL for the ItemGroup to link to.
   */
  href?: string;

  /**
   * Title text to be displayed in the ItemGroup summary.
   */
  title?: string;

  /**
   * Text to display in top-level link inside the ItemGroup in narrow viewports.
   * Only applies if `href` is present. If not provided, top-level link text
   * will be automatically generated from `title`.
   */
  viewAllTitle?: string;

  /**
   * On click handler.
   */
  onClick?: () => void;
}
