import React from "react";

import { VisuallyHidden } from "../../VisuallyHidden";
import { Spinner } from "../../Spinner";

import { InputIcon } from "./InputIcon";

export const TrailingSlot = ({
  id,
  trailingSlot,
  showPassword,
  isPasswordVisible,
  onTogglePassword,
  isLoading,
  clearButton,
  isDisabled,
  isReadOnly,
  size = "m",
  inputRef,
}: TrailingSlotProps) => {
  const spinnerSizeMap: Record<"s" | "m" | "l", number> = {
    s: 16,
    m: 24,
    l: 24,
  };

  const spinnerSize = spinnerSizeMap[size];

  const focusInput = () => {
    inputRef.current?.focus();
  };

  const clearInput = () => {
    if (inputRef.current) {
      inputRef.current.value = "";
      inputRef.current.dispatchEvent(new Event("input", { bubbles: true }));
    }
    clearButton?.onClick?.();
  };

  const onClearButtonKeydown = () => {
    clearInput();
    focusInput();
  };

  return (
    <span className="arc-TextInput-trailingSlot" id={`trailingslot-${id}`}>
      {trailingSlot && !showPassword && !isLoading && !clearButton && (
        <>{trailingSlot}</>
      )}

      {clearButton?.onClick && !showPassword && !isLoading && (
        <InputIcon
          themeIcon="textInputClear"
          isReadOnly={isReadOnly}
          isDisabled={isDisabled}
          tooltip={{
            title: clearButton.tooltipLabel ?? "Clear",
            side: "bottom",
          }}
          isButton={{
            onClick: () => {
              clearInput();
              focusInput();
            },
            label: "Clear Input",
            onKeyDown: onClearButtonKeydown,
          }}
          size={size}
        />
      )}

      {showPassword && !isLoading && (
        <>
          <InputIcon
            isDisabled={isDisabled}
            isReadOnly={isReadOnly}
            themeIcon={
              isPasswordVisible
                ? "textInputShowPassword"
                : "textInputHidePassword"
            }
            tooltip={{
              title: isPasswordVisible ? "Hide password" : "Show password",
            }}
            isButton={{
              onClick: () => {
                if (onTogglePassword) {
                  onTogglePassword();
                }
              },
              label: isPasswordVisible ? "Hide password" : "Show password",
            }}
            size={size}
          />

          <VisuallyHidden>
            <div aria-live="polite">
              <p>
                {isPasswordVisible
                  ? "Your password is shown"
                  : "Your password is hidden"}
              </p>
            </div>
          </VisuallyHidden>
        </>
      )}
      <div aria-live="polite">
        {isLoading && !isDisabled && (
          <div className="arc-TextInput-spinner">
            <Spinner size={spinnerSize} />
            <VisuallyHidden>loading</VisuallyHidden>
          </div>
        )}
      </div>
    </span>
  );
};

export interface TrailingSlotProps {
  id: string;
  trailingSlot?: React.ReactNode;
  showPassword?: boolean;
  isPasswordVisible?: boolean;
  onTogglePassword?: () => void;
  isLoading?: boolean;
  clearButton?: {
    onClick?: () => void;
    tooltipLabel: string;
  };
  isDisabled: boolean;
  isReadOnly: boolean;
  size: "l" | "m" | "s";
  /** Ref to the input element for focus management */
  inputRef: React.RefObject<HTMLInputElement | null>;
}
