import React from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { type BreakpointVisibility } from "../../types/breakpoint-visibility";

/** Use `Hidden` to hide it's children at specific breakpoints */
export const Hidden = ({
  children,
  xs,
  s,
  m,
  l,
  xl,
  xxl,
  ...props
}: HiddenProps) => (
  <div
    className={classNames({
      "arc-Hidden--xs": xs,
      "arc-Hidden--s": s,
      "arc-Hidden--m": m,
      "arc-Hidden--l": l,
      "arc-Hidden--xl": xl,
      "arc-Hidden--xxl": xxl,
    })}
    {...filterAttrs(props)}
  >
    {children}
  </div>
);

export interface HiddenProps extends BreakpointVisibility {
  /**
   * Content to hide at specific breakpoints
   */
  children: React.ReactNode;
}
