import isBefore from "date-fns/isBefore";
import isAfter from "date-fns/isAfter";

export const getFocusDate = ({
  minDate,
  maxDate,
  date,
}: {
  minDate?: Date;
  maxDate?: Date;
  date: Date;
}): Date => {
  const isFocusDateBeforeMinDate = minDate && isBefore(date, minDate);

  const isFocusDateAfterMaxDate = maxDate && isAfter(date, maxDate);

  if (isFocusDateBeforeMinDate) {
    return minDate;
  }

  if (isFocusDateAfterMaxDate) {
    return maxDate;
  }

  return date;
};
