import React, { type ReactNode, useState, useContext } from "react";

import classNames from "classnames";

import { BtIconCrossAlt2Px } from "@arc-ui/icons/BtIconCrossAlt2Px";
import { BtIconCrossAlt2PxFill } from "@arc-ui/icons/BtIconCrossAlt2PxFill";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { SurfaceContext } from "../Surface";

import { Icon } from "../Icon";

/**
 * Use `Tag` to promote features and manage filtering.
 */
export const Tag = ({
  children,
  isRemovable,
  link,
  ariaLabel,
  icon,
  onClick,
  onRemove,
  title,
  ...props
}: TagProps) => {
  const [isRemoved, setIsRemoved] = useState(false);

  const { surface } = useContext(SurfaceContext);

  const onRemoveHandler = () => {
    setIsRemoved((p) => !p);
    onRemove && onRemove();
  };

  return (
    <div
      className={classNames("arc-Tag", {
        "arc-Tag--isRemovable": isRemovable,
        "arc-Tag--hasIcon": icon,
        "arc-Tag--hasLink": link || onClick,
        "arc-Tag--removed": isRemoved,
        "arc-Tag--onDarkSurface": surface === "dark",
      })}
      {...(isRemoved && { "aria-hidden": true })}
      {...filterAttrs(props)}
    >
      {link ? (
        <a
          className="arc-Tag-content"
          href={link}
          tabIndex={0}
          aria-label={ariaLabel}
        >
          {icon && (
            <span className="arc-Tag-icon">
              <Icon data-testid="arc-Tag-icon" icon={icon} />
            </span>
          )}
          <div className="arc-Tag-label" title={title}>
            {children}
          </div>
        </a>
      ) : (
        <>
          {onClick ? (
            <button
              aria-label={ariaLabel}
              className="arc-Tag-content"
              onClick={onClick}
              data-testid="arc-Tag-content"
            >
              {icon && (
                <span className="arc-Tag-icon">
                  <Icon data-testid="arc-Tag-icon" icon={icon} />
                </span>
              )}
              <div className="arc-Tag-label" title={title}>
                {children}
              </div>
            </button>
          ) : (
            <div className="arc-Tag-content" data-testid="arc-Tag-content">
              {icon && (
                <span className="arc-Tag-icon">
                  <Icon data-testid="arc-Tag-icon" icon={icon} />
                </span>
              )}
              <div className="arc-Tag-label" title={title}>
                {children}
              </div>
            </div>
          )}
        </>
      )}

      {isRemovable && (
        <button
          className="arc-Tag-icon arc-Tag-icon--removable"
          onClick={onRemoveHandler}
          data-testid="arc-Tag-icon-removable"
          aria-live="polite"
          aria-roledescription="remove tag"
          aria-label="Remove tag"
        >
          <Icon icon={BtIconCrossAlt2Px} />
          <Icon icon={BtIconCrossAlt2PxFill} />
        </button>
      )}
    </div>
  );
};

export interface TagProps {
  /**
   * Content to render within the Tag
   */
  children: ReactNode;

  /**
   * Determine if the Tag is removable.
   */
  isRemovable?: boolean;

  /**
   * Provide a link for the tag
   */
  link?: string;

  /**
   * Provide a aria label for the tag. Only applies if rendering as a button or a link.
   */
  ariaLabel?: string;

  /**
   * Determine a icon to display within the tag.
   */
  icon?: string;

  /**
   * onClick Handler for Tag
   */
  onClick?: () => void;

  /**
   * Execute function on remove
   */
  onRemove?: () => void;

  /**
   * Specify extra information about the Tag.
   */
  title?: string;
}
