import React, { type Ref, type ReactElement, type ReactNode } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import {
  ProgressStepperItem,
  type ProgressStepperItemProps,
} from "./components/ProgressStepperItem/ProgressStepperItem";

import { type ProgressStatus } from "./progressStatus";

/** Use `ProgressStepper` to provide an overview of a series of steps in a digital journey. */
export const ProgressStepper = ({
  ref,
  children,
  size,
  isFluid,
  direction,
  isExpandable,
  invertLabelPosition,
  currentStep,
  ...props
}: ProgressStepperProps) => {
  const items: any = React.Children.toArray(children);

  const getStepStatus = (
    item: ReactElement<ProgressStepperItemProps>,
  ): ProgressStatus | undefined => {
    return item?.props?.status;
  };

  return (
    <ol
      ref={ref}
      className={classNames("arc-ProgressStepper", {
        "arc-ProgressStepper--vertical": direction === "vertical",
      })}
      {...filterAttrs(props)}
    >
      {items.map(
        (item: ReactElement<ProgressStepperItemProps>, index: number) => (
          <React.Fragment key={`StepperItem-${index}`}>
            <ProgressStepperItem
              title={item.props.title}
              titleHref={item.props.titleHref}
              subTitle={item.props.subTitle}
              status={item.props.status}
              stepContent={item.props.stepContent}
              ariaLabel={item.props.ariaLabel}
              isStepContentHidden={item.props.isStepContentHidden}
              onClick={item.props.onClick}
              isFluid={isFluid}
              invertLabelPosition={invertLabelPosition}
              direction={direction}
              isExpandable={isExpandable}
              size={size}
              isViewing={
                currentStep !== undefined ? currentStep === index : undefined
              }
              previousStep={getStepStatus(items[index - 1])}
              {...filterAttrs(item.props)}
            />
          </React.Fragment>
        ),
      )}
    </ol>
  );
};

export interface ProgressStepperProps {
  /**
   * Ref to the underlying ol element.
   */
  ref?: Ref<HTMLOListElement>;
  /**
   * Children of `<ProgressStepper  />` should only contain `<ProgressStepperItem />`
   */
  children?: ReactNode;

  /**
   * Determine a direction for `<ProgressStepperItem />`
   */
  direction?: "horizontal" | "vertical";

  /**
   * Determine the size for `<ProgressStepperItem />`
   */
  size?: "small" | "large";

  /**
   * Determine if `<ProgressStepperItem />` should be Fluid. Only appliciable for `horizontal direction.`
   */
  isFluid?: boolean;

  /**
   * Invert all labels in `<ProgressStepperItem />`. Only appliciable for `horizontal direction.`
   */
  invertLabelPosition?: boolean;

  /**
   * Detach the active 'dot' indicator from the current status. Pass the index number of the step where the dot should appear.
   */
  currentStep?: number;

  /**
   * <b>DEPRECATED</b>: This will be removed in a future release.
   */
  isExpandable?: boolean;
}
