import React, { type ReactNode, useContext } from "react";

import classNames from "classnames";

import camelcase from "camelcase";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { SurfaceContext } from "../Surface/Surface";
import { SemanticHeading, type SemanticHeadingLevel } from "../SemanticHeading";

/**
 * Use `Heading` to display heading text.
 */
export const Heading = ({
  align = "left",
  casing = "auto",
  color = "auto",
  children,
  level,
  isInline,
  fontStyle = "default",
  isResponsive = true,
  isWordWrap = false,
  size,
  id,
  ...props
}: HeadingProps) => {
  const { surface } = useContext(SurfaceContext);

  return (
    <SemanticHeading
      id={id}
      level={level}
      className={classNames(
        "arc-Heading",
        `arc-Heading--${camelcase(fontStyle)}`,
        {
          "arc-Heading--wrap": isWordWrap,
          "arc-Heading--inline": isInline,
          "arc-Heading--fixedSize": isResponsive === false,
          [suffixModifier("arc-Heading--align", align)]:
            align && align !== "left",
          [`arc-Heading--size${size && size.toUpperCase()}`]: size,
          "arc-Heading--casingNone": casing === "none",
          "arc-Heading--colorBrand": color === "brand",
          "arc-Heading--onDarkSurface": surface === "dark",
          "arc-Heading--isInline": isInline,
        },
      )}
      {...filterAttrs(props)}
    >
      {children}
    </SemanticHeading>
  );
};

export type HeadingCasing = "auto" | "none";

export type HeadingColor = "auto" | "brand";

export type HeadingLevel = SemanticHeadingLevel;

export type HeadingSize =
  | "xxxl"
  | "xxl"
  | "xl"
  | "l"
  | "m"
  | "s"
  | "xs"
  | "xxs"
  | "xxxs";

export interface HeadingProps {
  /**
   * Text alignment of the Heading.
   */
  align?: "left" | "center" | "right";

  /**
   * Typographic casing of the Heading.
   */
  casing?: HeadingCasing;

  /**
   * Text and inline markup to display in the Heading.
   */
  children: ReactNode;

  /**
   * The color of the Heading.
   */
  color?: HeadingColor;

  /**
   * Id for the Heading.
   */
  id?: string;

  /**
   * HTML section heading level. If not provided, the Heading will render as
   * a span.
   */
  level?: HeadingLevel;

  /**
   * Typographic size of the Heading.
   */
  size?: HeadingSize;

  /**
   * Whether the Heading is displayed inline.
   */
  isInline?: boolean;

  /**
   * Whether long words should be wrapped.
   */
  isWordWrap?: boolean;

  /**
   * Determine if the heading should change size depending on the breakpoint. Default is `true`
   */
  isResponsive?: boolean;

  /**
   * Changes the Heading font family. Please note `dottee` fonts will only work when theme is set to `ee`
   */
  fontStyle?:
    | "default"
    | "display-standard"
    | "display-condensed"
    | "display-extended"
    | "overline";
}
