import React, { type ReactNode, useRef, useState } from "react";

import classNames from "classnames";

import { ArcSizeBreakpointsL } from "@arc-ui/tokens-arc";
import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { BtIconChevronRight2Px } from "@arc-ui/icons/BtIconChevronRight2Px";

import { useMediaQuery } from "../../../../hooks/public/use-media-query";
import { handleLinkClick } from "../../../../helpers/handle-link-click";

import { Icon } from "../../../Icon";

import {
  SiteHeaderV2Panel,
  SiteHeaderV2ViewAll,
} from "../SiteHeaderV2Panel/SiteHeaderV2Panel";

export const SiteHeaderV2NavItem = ({
  children,
  href,
  isCurrent,
  onClick,
  title,
  isPrimary,
  opensFirstWithPanel,
  subTitle,
  ...props
}: SiteHeaderV2NavItemProps) => {
  const navItem = useRef<HTMLLIElement | null>(null);
  const [panelOpen, setPanelOpen] = useState(false);
  const [openSecondaryWithSubNav, setOpenSecondaryWithSubNav] = useState(true);
  const isMinWidthArcBreakpointL = useMediaQuery(
    `(min-width: ${ArcSizeBreakpointsL})`,
  );

  return (
    <li
      className={classNames({
        [`arc-SiteHeaderV2NavItem-primary`]: isPrimary,
        [`arc-SiteHeaderV2NavItemWithSubNav-Secondary`]: !isPrimary,
        [`arc-SiteHeaderV2NavItem`]: !subTitle && !isPrimary,
        [`arc-SiteHeaderV2NavItem--linkSelected`]:
          (children && panelOpen) || (!children && href && isCurrent),
        [`arc-SiteHeaderV2NavItemWithSubNav-active`]:
          (!isPrimary && panelOpen) ||
          (opensFirstWithPanel && openSecondaryWithSubNav),
      })}
      ref={navItem}
      {...filterAttrs(props)}
    >
      {!children ? (
        href ? (
          <a
            onClick={handleLinkClick({
              handler: onClick,
            })}
            className="arc-SiteHeaderV2NavItem-link"
            href={href}
          >
            {title}
          </a>
        ) : null
      ) : (
        <>
          <div className="arc-SiteHeaderV2NavItemWithSubNav-buttonContainer">
            <button
              aria-expanded={panelOpen}
              role={"menuitem"}
              aria-haspopup="true"
              aria-label={title}
              className={classNames({
                [`arc-SiteHeaderV2NavItem-link`]: true,
                [`arc-SiteHeaderV2NavItem-horizontalPanelFocus`]: !isPrimary,
                [`arc-SiteHeaderV2NavItem-link--itemHasChildren`]: true,
                [`arc-SiteHeaderV2NavItem-link--itemHasChildren-closeFirstPanel`]:
                  !isPrimary && !opensFirstWithPanel,
                [`arc-SiteHeaderV2NavItem-link--itemHasChildren-hasFirstPanel`]:
                  opensFirstWithPanel,
                [`arc-SiteHeaderV2NavItem-horizontalPanelLink`]:
                  !isPrimary && !isMinWidthArcBreakpointL,
              })}
              onClick={(e) => {
                e.preventDefault();
                setPanelOpen(!panelOpen);
              }}
            >
              <div
                className={classNames({
                  [`arc-SiteHeaderV2NavItem-title`]: !subTitle,
                  [`arc-SiteHeaderV2NavItem-link--itemHasChildren-closeFirstPanel`]:
                    !isPrimary && !opensFirstWithPanel,
                  [`arc-SiteHeaderV2NavItem-link--itemHasChildren-hasFirstPanel`]:
                    opensFirstWithPanel,
                })}
              >
                {title}
              </div>
              <span className="arc-SiteHeaderV2-mobileChevron">
                <Icon icon={BtIconChevronRight2Px} />
              </span>

              {subTitle && !isPrimary && isMinWidthArcBreakpointL ? (
                <div
                  className={classNames({
                    [`arc-SiteHeaderV2NavItemWithSubNav-text`]: !isPrimary,
                    [`arc-SiteHeaderV2NavItem-link--itemHasChildren-closeFirstPanel`]:
                      !isPrimary && !opensFirstWithPanel,
                    [`arc-SiteHeaderV2NavItem-link--itemHasChildren-hasFirstPanel`]:
                      opensFirstWithPanel,
                  })}
                >
                  {subTitle}
                </div>
              ) : null}
              <div
                className={classNames({
                  [`arc-SiteHeaderV2NavItemWithSubNav-buttonUnderline`]:
                    panelOpen ||
                    (opensFirstWithPanel && openSecondaryWithSubNav),
                  [`arc-SiteHeaderV2NavItemWithSubNav-primaryButtonUnderline`]:
                    isPrimary && panelOpen,
                  [`arc-SiteHeaderV2NavItemWithSubNav-buttonUnderlineActive`]:
                    !isPrimary && (panelOpen || openSecondaryWithSubNav),
                  // [`arc-SiteHeaderV2NavItemWithSubNav-slideIn`]:
                  //   animation && !subTitle,
                })}
              ></div>
            </button>
          </div>

          <SiteHeaderV2Panel
            navItemRef={navItem}
            isNavItem={true}
            isPrimary={isPrimary}
            open={
              opensFirstWithPanel && isMinWidthArcBreakpointL
                ? openSecondaryWithSubNav
                : panelOpen
            }
            setOpenPanelOnFirstClick={setOpenSecondaryWithSubNav}
            setOpen={setPanelOpen}
            viewAll={
              href ? (
                <SiteHeaderV2ViewAll
                  href={href}
                  onClick={onClick}
                  title={`See all solutions`}
                  buttonStyle="primary"
                />
              ) : undefined
            }
          >
            {children}
          </SiteHeaderV2Panel>
        </>
      )}
    </li>
  );
};

export interface SiteHeaderV2NavItemProps {
  /**
   * Contents of the NavItem. Must be SiteHeaderV2ItemGroup or
   * SiteHeaderV2Column components.
   */
  children?: ReactNode;

  /**
   * A top-level URL for the NavItem to link to.
   *
   * When `children` are not present, the URL to link to when the NavItem is
   * clicked or touched.
   *
   * When `children` are present, the URL to link to when a top-level link
   * inside the NavItem panel is clicked or touched.
   */
  href?: string;

  /**
   * Should the NavItem be highlighted as the current item/page? Only applies if
   * `children` are not present (and `href` is present).
   */
  isCurrent?: boolean;

  /**
   * Top-level text to display in the NavItem.
   */
  title: string;

  /**
   * On click handler.
   */
  onClick?: () => void;
  isPrimary?: boolean;
  opensFirstWithPanel?: boolean;
  subTitle?: string;
}
