import React, { type ReactNode } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { type BreakpointVisibility } from "../../types/breakpoint-visibility";

/** Use `Visible` to show it's children at specific breakpoints */
export const Visible = ({
  children,
  xs,
  s,
  m,
  l,
  xl,
  xxl,
  ...props
}: VisibleProps) => (
  <div
    className={classNames("arc-Visible", {
      "arc-Visible--xs": xs,
      "arc-Visible--s": s,
      "arc-Visible--m": m,
      "arc-Visible--l": l,
      "arc-Visible--xl": xl,
      "arc-Visible--xxl": xxl,
    })}
    {...filterAttrs(props)}
  >
    {children}
  </div>
);

export interface VisibleProps extends BreakpointVisibility {
  /**
   * Content to display at specific breakpoints.
   */
  children: ReactNode;
}
