import React, { useContext } from "react";

import getMonth from "date-fns/getMonth";
import getYear from "date-fns/getYear";
import format from "date-fns/format";
import subMonths from "date-fns/subMonths";
import addMonths from "date-fns/addMonths";

import {
  dateWithoutTime,
  isMonthAfterMaxDate,
  isMonthBeforeMinDate,
} from "../../helpers";

import { CalendarDateSelect } from "../CalendarDateSelect";
import { CalendarDayGrid } from "../CalendarDayGrid";
import { CalendarNavButton } from "../CalendarNavButton";
import { ArcCalendarContext } from "../../Calendar.provider";
import { VisuallyHidden } from "../../../VisuallyHidden";
import { Heading } from "../../../Heading";

export const CalendarMonthYearView = ({
  isPreviousMonthDisabled,
  isNextMonthDisabled,
  onMonthChange,
  onYearChange,
  onNextMonthClick,
  onPreviousMonthClick,
}: CalendarMonthYearViewProps) => {
  const context = useContext(ArcCalendarContext);

  if (!context) {
    return null;
  }

  const { displayDate, minDate, maxDate } = context;

  const monthOptions = Array.from({ length: 12 })
    .map((_, i) => ({
      value: i,
      text: format(new Date(2023, i, 1), "MMMM"),
    }))
    .filter(({ value }) => {
      const currentDateYear = getYear(displayDate);

      const date = dateWithoutTime(new Date(currentDateYear, value, 1));

      return (
        (!minDate || !isMonthBeforeMinDate(date, minDate)) &&
        (!maxDate || !isMonthAfterMaxDate(date, maxDate))
      );
    });

  const yearOptions = Array.from({ length: 21 }, (_, i) => {
    const value = getYear(displayDate) - 10 + i;

    return {
      value: value,
      text: value,
    };
  }).filter(({ value }) => {
    return (
      (minDate ? value >= getYear(minDate) : true) &&
      (maxDate ? value <= getYear(maxDate) : true)
    );
  });

  return (
    <>
      <div className="arc-CalendarMonthYearView-header">
        <VisuallyHidden>
          <Heading level="2">
            <span aria-live="polite">
              showing {format(displayDate, "MMMM yyyy")}
            </span>
          </Heading>
        </VisuallyHidden>
        <div className="arc-CalendarMonthYearView-selectWrapper">
          <div>
            <CalendarDateSelect
              options={monthOptions}
              ariaLabel="month"
              onChange={(e) => onMonthChange(parseInt(e.target.value))}
              name="arc-CalendarMonthYearView-monthSelect"
              displayValue={format(displayDate, "MMM")}
              value={`${getMonth(displayDate)}`}
            />
          </div>
          <div className="arc-CalendarMonthYearView-yearSelectContainer">
            <CalendarDateSelect
              options={yearOptions}
              ariaLabel="year"
              onChange={(e) => onYearChange(parseInt(e.target.value))}
              name="arc-CalendarMonthYearView-yearSelect"
              value={getYear(displayDate)}
            />
          </div>
        </div>

        <div className="arc-CalendarMonthYearView-navButtonContainer">
          <CalendarNavButton
            direction="previous"
            ariaLabel={`Show ${format(subMonths(displayDate, 1), "MMMM yyyy")}`}
            isDisabled={isPreviousMonthDisabled}
            onClick={onPreviousMonthClick}
          />

          <CalendarNavButton
            direction="next"
            ariaLabel={`Show ${format(addMonths(displayDate, 1), "MMMM yyyy")}`}
            isDisabled={isNextMonthDisabled}
            onClick={onNextMonthClick}
          />
        </div>
      </div>

      <CalendarDayGrid displayRange={[displayDate]} />
    </>
  );
};

interface CalendarMonthYearViewProps {
  /**
   * Whether the previous month button is disabled
   */
  isPreviousMonthDisabled: boolean;
  /**
   * Whether the next month button is disabled
   */
  isNextMonthDisabled: boolean;
  /**
   * Handler for previous month button click
   */
  onPreviousMonthClick: () => void;
  /**
   * Handler for next month button click
   */
  onNextMonthClick: () => void;
  /**
   * Handler for month change
   */
  onMonthChange: (value: number) => void;
  /**
   * Handler for year change
   */
  onYearChange: (value: number) => void;
}
