import React, { useState } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { usePagination } from "../../hooks/private/use-pagination";
import { ThemeIcon } from "../ThemeIcon";

/**
 * Use `Pagination` to navigate through multiple pages of content.
 */
export const Pagination = ({
  pageCount,
  onPageChange,
  defaultSelectedPage = 1,
  ...props
}: PaginationProps) => {
  const [selectedPage, setSelectedPage] = useState(defaultSelectedPage);
  const pageRange = usePagination(pageCount, selectedPage);

  const handlePagechange = (pageToSelect: number) => () => {
    setSelectedPage(pageToSelect);
    onPageChange(pageToSelect);
  };

  const isPageNumber = (rangeValue: string) => !isNaN(parseInt(rangeValue));

  return (
    <nav
      aria-label="pagination navigation"
      className={classNames("arc-Pagination")}
      {...filterAttrs(props)}
    >
      <button
        aria-label="Go to previous page"
        className={classNames("arc-Pagination-navigationButton", {
          "arc-Pagination-navigationButton--hidden": selectedPage === 1,
        })}
        onClick={handlePagechange(selectedPage - 1)}
      >
        <div className="arc-Pagination-navigationButtonIcon arc-Pagination-navigationButtonIcon--left">
          <ThemeIcon icon="paginationPrevious" />
        </div>
      </button>
      <div className="arc-Pagination-pageNumberContainer">
        {pageRange.map((rangeValue, i) =>
          isPageNumber(rangeValue) ? (
            <button
              aria-current={parseInt(rangeValue) === selectedPage}
              key={`pagination-range-value-${rangeValue}`}
              aria-label={`Go to page ${rangeValue}`}
              className={classNames(
                "arc-Pagination-value arc-Pagination-value--number",
                {
                  "arc-Pagination-value--selected":
                    parseInt(rangeValue) === selectedPage,
                },
              )}
              onClick={handlePagechange(parseInt(rangeValue))}
            >
              {rangeValue}
            </button>
          ) : (
            <span
              key={`pagination-range-value-dot${i}`}
              className={classNames(
                "arc-Pagination-value arc-Pagination-value--dots",
              )}
            >
              {rangeValue}
            </span>
          ),
        )}
      </div>
      <button
        aria-label="Go to next page"
        className={classNames("arc-Pagination-navigationButton", {
          "arc-Pagination-navigationButton--hidden": selectedPage === pageCount,
        })}
        onClick={handlePagechange(selectedPage + 1)}
      >
        <div className="arc-Pagination-navigationButtonIcon arc-Pagination-navigationButtonIcon--right">
          <ThemeIcon icon="paginationNext" />
        </div>
      </button>
    </nav>
  );
};

export interface PaginationProps {
  /**
   * Number of pages for the pagination
   */
  pageCount: number;

  /**
   * Default page to be selected on render. If not provided defaults to 1.
   */
  defaultSelectedPage?: number;

  /**
   * Function to call when the page changes
   */
  onPageChange: (selectedPage: number) => void;
}
