import React, { type ReactNode } from "react";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { BrandLogo } from "../BrandLogo";
import { Section } from "../Section";
import { Surface } from "../Surface";
import { handleLinkClick } from "../../helpers/handle-link-click";
import { ThemeIcon } from "../ThemeIcon";
import { Visible } from "../Visible";

/**
 * Use `SiteFooter` to display information at the bottom of a page.
 */
export const SiteFooter = ({
  children,
  currentYear,
  logoLabel,
  main,
  siteName,
  ...props
}: SiteFooterProps) => {
  return (
    <>
      <footer className="arc-SiteFooter" {...filterAttrs(props)}>
        <Surface background="dark-brand-01" paddingVertical="24">
          {(siteName || main) && (
            <>
              <Section>
                {siteName && (
                  <div className="arc-SiteFooter-name">{siteName}</div>
                )}
                {main && <div className="arc-SiteFooter-main">{main}</div>}
              </Section>
              <hr className="arc-SiteFooter-rule" />
            </>
          )}
          <Section>
            <div className="arc-SiteFooter-secondary">
              {children && (
                <ul className="arc-SiteFooter-secondaryItems">{children}</ul>
              )}
              <div className="arc-SiteFooter-brand">
                <div className="arc-SiteFooter-copyright">
                  <span className="arc-SiteFooter-copyrightSymbol">©</span>
                  {` ${currentYear || new Date().getFullYear()}`}
                </div>
                <BrandLogo label={logoLabel} />
              </div>
            </div>
          </Section>
        </Surface>
      </footer>
    </>
  );
};

export const SiteFooterItemDisclosure = ({
  title,
  children,
  open,
  tabIndex,
}: SiteFooterItemDisclosureProps) => (
  <details className="arc-SiteFooter-disclosure" open={open}>
    <summary className="arc-SiteFooter-summary" tabIndex={tabIndex}>
      <span className="arc-SiteFooter-icon">
        <ThemeIcon icon="siteFooterExpand" />
      </span>
      <h2 className="arc-SiteFooter-title">{title}</h2>
    </summary>
    <ul className="arc-SiteFooter-mainItems">{children}</ul>
  </details>
);

export const SiteFooterItemGroup = (props: SiteFooterItemGroupProps) => (
  <>
    <Visible data-testid="mobile-disclosure" xs s>
      <SiteFooterItemDisclosure {...props} tabIndex={0} />
    </Visible>

    <Visible data-testid="desktop-disclosure" m l xl xxl>
      <SiteFooterItemDisclosure {...props} open tabIndex={-1} />
    </Visible>
  </>
);

export const SiteFooterItem = ({
  children,
  href,
  onClick,
  ...props
}: SiteFooterItemProps) => {
  return (
    <li className="arc-SiteFooter-item" {...filterAttrs(props)}>
      <a
        onClick={handleLinkClick({ handler: onClick })}
        className="arc-SiteFooter-link"
        href={href}
      >
        {children}
      </a>
    </li>
  );
};

export interface SiteFooterItemGroupProps {
  /**
   * Contents of the SiteFooterItemGroup Must be SiteFooterItem components.
   */
  children: ReactNode;

  /**
   * Title text for the SiteFooterItemGroup
   */
  title: string;
}

export interface SiteFooterItemDisclosureProps extends SiteFooterItemGroupProps {
  open?: boolean;
  tabIndex: number;
}

export interface SiteFooterItemProps {
  /**
   * Contents of the SiteFooterItem.
   */
  children: ReactNode;

  /**
   * A URL to link to when the Item is clicked or touched.
   */
  href: string;

  /**
   * On click handler.
   */
  onClick?: () => void;
}

export interface SiteFooterProps {
  /**
   * Secondary content of the SiteFooter Must be SiteFooterItem components.
   */
  children?: ReactNode;

  /**
   * Copyright year.
   */
  currentYear?: string;

  /**
   * Accessible text for the SiteFooter logo.
   */
  logoLabel?: string;

  /**
   * Main content of the SiteFooter Must be SiteFooterItemGroup components.
   */
  main?: ReactNode;

  /**
   * Text that appears at the top of the footer. Can be the name of the site, a
   * brand strapline, or similar.
   */
  siteName?: string;
}
