import React, { type MouseEvent, useContext } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { Text } from "../Text";
import { ThemeIcon, type ThemeIconNames } from "../ThemeIcon";
import { VerticalSpace } from "../VerticalSpace";
import { SurfaceContext } from "../Surface";
import { Heading } from "../Heading";

/** Use `Download` to provide users with a file download action. */
export const Download = ({
  name,
  onClick,
  description,
  href,
  type,
  size,
  icon = "downloadFile",
  isFullWidth = true,
  isCompact = false,
  ...props
}: DownloadProps) => {
  const { surface } = useContext(SurfaceContext);
  const linkProps: React.AnchorHTMLAttributes<HTMLAnchorElement> = href
    ? {
        href,
        download: true,
        target: "_blank",
        rel: "noreferrer",
      }
    : {
        role: "button",
      };

  const tileHoverIcon =
    icon === "downloadFile"
      ? "downloadFileHover"
      : "downloadAccessibilityHover";

  return (
    <a
      {...linkProps}
      className={classNames("arc-Download", {
        "arc-Download--maxContent": !isFullWidth,
        "arc-Download--onDarkSurface": surface === "dark",
        "arc-Download--isCompact": isCompact,
      })}
      aria-label={name}
      onClick={onClick}
      tabIndex={0}
      {...filterAttrs(props)}
    >
      <div className="arc-Download-iconWrapper">
        <div className="arc-Download-unfilledIconWrapper">
          <ThemeIcon icon={icon} color="auto" />
        </div>
        <div className="arc-Download-filledIconWrapper">
          <ThemeIcon icon={tileHoverIcon} color="auto" />
        </div>
      </div>
      <div className="arc-Download-contentContainer">
        <Heading>
          <span className="arc-Download-name">{name}</span>
        </Heading>
        <VerticalSpace size="4" />
        <Text tone="muted" size="xs">
          {type}&nbsp;{size && `| ${size}`}
        </Text>

        {description && (
          <>
            <VerticalSpace size="4" />
            <Text tone="supporting">
              <span className="arc-Download-description">{description}</span>
            </Text>
          </>
        )}
      </div>
    </a>
  );
};

export interface DownloadProps {
  /**
   * Name for `<Download />`
   */
  name: string;

  /**
   * File type for `<Download />`
   */
  type: string;

  /**
   * File url for `<Download />`
   */
  href?: string;

  /**
   * If false the width will be the same as the inner content
   */
  isFullWidth?: boolean;

  /**
   * Description for `<Download />`
   */
  description?: string;

  /**
   * File size for `<Download />`
   */
  size?: string;

  /**
   * Icon for `<Download />`
   */
  icon?: Extract<ThemeIconNames, "downloadFile" | "downloadAccessibility">;

  /**
   * Click handler for `<Download />`
   */
  onClick?: (e: MouseEvent<HTMLAnchorElement>) => void;

  /**
   * If true, the spacing will be reduced resulting in a tighter look and feel.
   */
  isCompact?: boolean;
}
