import React from "react";

import classNames from "classnames";

import { Text } from "../../../Text";
import { ThemeIcon } from "../../../ThemeIcon";

import { type ComboBoxOption } from "../../types/combobox-option";
import { ComboBoxListItemInner } from "../ComboBoxListItemInner";

export const ComboBoxRegularOption = ({
  option,
  isDisabled,
  isMultiSelectable,
  isHighlighted,
  isSingleSelected,
  isMultiSelected,
}: ComboBoxRegularOptionProps) => (
  <ComboBoxListItemInner
    isHighlighted={isHighlighted}
    isSingleSelected={isSingleSelected}
  >
    <div className="arc-ComboBoxRegularOption-container">
      {isMultiSelectable && (
        <div
          className={classNames(
            "arc-ComboBoxRegularOption-icon",
            "arc-ComboBoxRegularOption-icon--checkbox",
            {
              "arc-ComboBoxRegularOption-icon--checkboxSelected":
                isMultiSelected,
              "arc-ComboBoxRegularOption-icon--checkboxDisabled": isDisabled,
            },
          )}
        >
          <ThemeIcon size={24} icon="comboboxSelected" />
        </div>
      )}

      <div className="arc-ComboBoxRegularOption-text">
        <Text>{option.text}</Text>
      </div>

      {!isMultiSelectable && isSingleSelected && (
        <div className="arc-ComboBoxRegularOption-icon">
          <ThemeIcon size={24} icon="comboboxSelected" />
        </div>
      )}
    </div>
  </ComboBoxListItemInner>
);

interface ComboBoxRegularOptionProps {
  option: ComboBoxOption;
  isDisabled: boolean;
  isMultiSelectable: boolean;
  isHighlighted: boolean;
  isSingleSelected: boolean;
  isMultiSelected: boolean;
}
