import React from "react";

import classNames from "classnames";

export const SiteHeaderV2MenuButton = ({
  menuOpen,
  setMenuOpen,
}: SiteHeaderV2MenuButtonProps) => (
  <button
    aria-expanded={menuOpen}
    className={classNames({
      [`arc-SiteHeaderV2MenuButton`]: true,
      [`arc-SiteHeaderV2MenuButton--menuOpen`]: menuOpen,
    })}
    onClick={() => {
      setMenuOpen(!menuOpen);
    }}
    type="button"
  >
    <span className="arc-SiteHeaderV2MenuButton-box">
      <span className="arc-SiteHeaderV2MenuButton-inner"></span>
      <span className="arc-SiteHeaderV2MenuButton-text">Menu</span>
    </span>
  </button>
);

export interface SiteHeaderV2MenuButtonProps {
  /**
   * Whether the menu is currently open.
   */
  menuOpen: boolean;
  /**
   * Function to set the menu open state.
   */
  setMenuOpen: (arg0: boolean) => any;
}
