import React, { type ReactNode } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { BtIconChevronRightMid } from "@arc-ui/icons/BtIconChevronRightMid";

import { handleLinkClick } from "../../../../helpers/handle-link-click";
import { Icon } from "../../../Icon";

export const SiteHeaderV2Item = ({
  children,
  href,
  onClick,
  ...props
}: SiteHeaderV2ItemProps) => {
  return (
    <li
      className={classNames({
        [`arc-SiteHeaderV2Item`]: true,
        [`arc-SiteHeaderV2Item--emphasised`]: true,
      })}
      {...filterAttrs(props)}
      role="none"
    >
      <a
        onClick={handleLinkClick({ handler: onClick })}
        className="arc-SiteHeaderV2Item-link"
        href={href}
        role="menuitem"
      >
        {children}
        <span className="arc-SiteHeaderV2Item-linkIcon">
          <Icon icon={BtIconChevronRightMid} />
        </span>
      </a>
    </li>
  );
};

export interface SiteHeaderV2ItemProps {
  /**
   * Contents of the Item. Usually text to be displayed in the Item link.
   */
  children: ReactNode;

  /**
   * A URL to link to when the Item is clicked or touched.
   */
  href: string;

  /**
   * On click handler.
   */
  onClick?: () => void;
}
