import { useEffect } from "react";

import { checkElementVisibility } from "@arc-ui/helpers/check-element-visibility";

export const useTriggerHidden = ({
  onTriggerHidden,
  triggerEl,
}: UseTriggerHiddenParams) => {
  useEffect(() => {
    const resizeObserver = new ResizeObserver((entries) => {
      const [entry] = entries;

      if (!checkElementVisibility(entry.target)) {
        onTriggerHidden();
      }
    });

    if (triggerEl) {
      resizeObserver.observe(triggerEl);
    }

    return () => {
      if (triggerEl) {
        resizeObserver.unobserve(triggerEl);
      }
    };
  }, [onTriggerHidden, triggerEl]);
};

interface UseTriggerHiddenParams {
  triggerEl: HTMLElement;
  onTriggerHidden: () => void;
}
