import React from "react";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { FormControl, type FormControlProps } from "../FormControl/FormControl";

import { Provider } from "./context";

type EventType = React.ChangeEvent<HTMLInputElement>;

/**
 * Use `RadioGroup` to wrap and control radio buttons and apply default values
 */
export const RadioGroup = ({
  children,
  checkedValue,
  isDisabled = false,
  id,
  errorMessage,
  isRequired = true,
  helper,
  label,
  name,
  onBlur,
  onChange,
  size = "l",
  ...props
}: RadioGroupProps) => {
  const hasNoSelection =
    checkedValue === null || checkedValue === undefined || checkedValue === "";
  return (
    <Provider
      value={{
        blurEvent: onBlur!,
        changeEvent: onChange!,
        groupDisabled: isDisabled,
        checkedValue,
        name: name,
        size: size,
      }}
    >
      <div className="arc-RadioGroup" {...filterAttrs(props)}>
        <FormControl
          elementType="fieldset"
          label={label}
          labelSize={size}
          helper={helper}
          id={id}
          requirementStatus={isRequired ? "required" : "optional"}
          helperUnderLabel
          errorMessage={isRequired && hasNoSelection ? errorMessage : ""}
        >
          <span className="arc-RadioGroup-radioButtonContainer">
            {children}
          </span>
        </FormControl>
      </div>
    </Provider>
  );
};

export interface RadioGroupProps extends Omit<
  FormControlProps,
  | "children"
  | "elementType"
  | "htmlFor"
  | "labelSize"
  | "requirementStatus"
  | "disclosureText"
  | "disclosureTitle"
  | "onClickDisclosure"
  | "supplementaryInfo"
  | "hideLabel"
  | "labelPosition"
> {
  /**
   * Contents of the RadioGroup Should only contain `RadioGroupInput`
   */
  children?: React.ReactNode;
  /**
   * Value of the RadioButton that should be checked by default.
   */
  checkedValue?: string;
  /**
   * Should all controls be disabled?
   */
  isDisabled?: boolean;
  /**
   * Helper message for the RadioGroup
   */
  helper?: string;
  /**
   * ID for the RadioGroup
   */
  id: string;
  /**
   * Label for the RadioGroup
   */
  label: string;
  /**
   * Name for the RadioGroup
   */
  name: string;
  /**
   * Function to call when the RadioGroup loses focus.
   */
  onBlur?: (e: EventType) => void;
  /**
   * Callback function to update the RadioGroup's controlled `checkedValue` prop,
   * for example `e => setCheckedValue(e.target.value)`.
   */
  onChange?: (event: EventType) => void;
  /**
   * Size of the RadioGroup
   */
  size?: "l" | "s";
  /**
   * Error message for the RadioGroup
   */
  errorMessage?: string;
  /**
   * Is RadioGroup required?
   */
  isRequired?: boolean;
}
