import React from "react";

import classNames from "classnames";

import { Icon } from "../../Icon";

import { Tooltip, type TooltipProps } from "../../Tooltip";

import { ThemeIcon, type ThemeIconNames } from "../../ThemeIcon";

export const InputIcon = ({
  isButton,
  isReadOnly,
  isDisabled,
  size = "m",
  tooltip,
  themeIcon,
  icon,
}: InputIconProps) => {
  const buttonIconSizeMap: Record<"s" | "m" | "l", number> = {
    s: 16,
    m: 24,
    l: 28,
  };

  // Static icons don't have padding
  const iconSizeMap: Record<"s" | "m" | "l", number> = {
    s: 24,
    m: 32,
    l: 36,
  };

  const iconSize = isButton ? buttonIconSizeMap[size] : iconSizeMap[size];

  const iconElement =
    icon && !themeIcon ? (
      <Icon icon={icon} size={iconSize} />
    ) : themeIcon ? (
      <ThemeIcon icon={themeIcon} size={iconSize} />
    ) : null;

  if (!isButton) {
    return <div className="arc-TextInput-iconSlot">{iconElement}</div>;
  }

  const button = (
    <button
      ref={isButton.ref}
      className={classNames({
        "arc-TextInput-inputIcon": true,
        "arc-TextInput-inputIcon--isReadOnly": isReadOnly,
        "arc-TextInput-inputIcon--isDisabled": isDisabled,
      })}
      disabled={isReadOnly || isDisabled}
      aria-label={isButton.label}
      onFocus={isButton.onFocus}
      onKeyDown={isButton.onKeyDown}
      onClick={(e) => {
        e.preventDefault();
        isButton.onClick?.();
      }}
    >
      {iconElement}
    </button>
  );

  return tooltip && !isDisabled && !isReadOnly ? (
    <Tooltip
      side={tooltip.side ?? "bottom"}
      title={tooltip.title}
      delayDuration={500}
      asChild
    >
      <div style={{ width: "fit-content", display: "flex" }}>{button}</div>
    </Tooltip>
  ) : (
    <div style={{ width: "fit-content", display: "flex" }}>{button}</div>
  );
};

export interface InputIconProps {
  /**
   * Sets the Icon to be a Button.
   */
  isButton?: {
    ref?: React.Ref<HTMLButtonElement>;
    onFocus?: React.FocusEventHandler<HTMLButtonElement>;
    onClick: () => void;
    label: string;
    onKeyDown?: (e: React.KeyboardEvent<HTMLButtonElement>) => void;
  };
  /**
   * Pass in TextInput isReadOnly state.
   */
  isReadOnly?: boolean;
  /**
   * Pass in TextInput isDisabled state.
   */
  isDisabled?: boolean;
  /**
   * Pass in TextInput size to Icon.
   */
  size?: "l" | "m" | "s";
  /**
   * Set a Tooltip to appear on hover.
   */
  tooltip?: TooltipProps;
  /**
   * Render any Icon in the slot.
   */
  icon?: string;
  /**
   * Render a ThemeIcon in the slot.
   */
  themeIcon?: ThemeIconNames;
}
