import React, {
  type ReactElement,
  type ReactNode,
  useEffect,
  useRef,
  useState,
} from "react";

import debounce from "lodash/debounce";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import {
  BreadcrumbsItem,
  type BreadcrumbsItemProps,
} from "./BreadcrumbsItem/BreadcrumbsItem";

/** Use `Breadcrumbs` to add a secondary navigation scheme that reveals the user’s location. Each item should be wrapped with `BreadcrumbsItem` */
export const Breadcrumbs = ({
  isLight,
  children,
  ...props
}: BreadcrumbsProps) => {
  const breadcrumbsList: any = useRef(null);
  const [isCompressed, setIsCompressed] = useState(false);
  const [showBackTrail, setShowBackTrail] = useState(false);

  useEffect(() => {
    const handleResize = debounce(() => {
      setShowBackTrail(false);
      setIsCompressed(false);

      const breadcrumbEl = breadcrumbsList.current;
      const parentEl = breadcrumbEl?.parentElement;
      const isMobileViewport = window.innerWidth < 426;
      const hasMultipleChildren = React.Children.count(children) > 2;

      if (isMobileViewport) {
        setShowBackTrail(true);
      }

      // null checks + checking if breadcrumbs has multiple children
      if (hasMultipleChildren && breadcrumbEl && parentEl) {
        const isOverflowingHorizontally =
          breadcrumbEl.offsetWidth === parentEl.offsetWidth;
        const isOverflowingVertically = breadcrumbEl.offsetHeight > 24;

        // if the breadcrumbs are overflowing. compress them.
        if (isOverflowingHorizontally || isOverflowingVertically) {
          setIsCompressed(true);
        }
      }
    }, 200);

    // initial check when component is mounted
    handleResize();

    window.addEventListener("resize", handleResize);

    return () => {
      window.removeEventListener("resize", handleResize);
      handleResize.cancel();
    };
  }, [children]);

  const items: any = React.Children.toArray(children);

  return (
    <nav
      aria-label="Breadcrumbs"
      className={classNames({
        "arc-Breadcrumbs": true,
        "arc-Breadcrumbs--light": isLight,
      })}
      {...filterAttrs(props)}
    >
      <ol className="arc-Breadcrumbs-list" ref={breadcrumbsList}>
        {showBackTrail ? (
          <>
            {items.length < 3 ? (
              <BreadcrumbsItem spacerIconBefore>
                {items[0].props.children}
              </BreadcrumbsItem>
            ) : (
              <BreadcrumbsItem spacerIconBefore>
                {items[items.length - 2].props.children}
              </BreadcrumbsItem>
            )}
          </>
        ) : (
          <>
            {isCompressed ? (
              <>
                <BreadcrumbsItem spacerIconAfter>
                  {items[0].props.children}
                </BreadcrumbsItem>
                <BreadcrumbsItem spacerIconAfter>
                  <button
                    className="arc-Breadcrumbs-expand arc-Breadcrumbs-text"
                    onClick={() => setIsCompressed(false)}
                    aria-label="Expand Breadcrumbs"
                    type="button"
                    data-testid="expand-ellipsis"
                  >
                    ...
                  </button>
                </BreadcrumbsItem>
                <BreadcrumbsItem>
                  {items[items.length - 1].props &&
                    items[items.length - 1].props.children &&
                    React.cloneElement(items[items.length - 1].props.children, {
                      isActive: true,
                    })}
                </BreadcrumbsItem>
              </>
            ) : (
              <>
                {items
                  .slice(0, items.length - 1)
                  .map(
                    (
                      item: ReactElement<BreadcrumbsItemProps>,
                      index: number,
                    ) => {
                      return (
                        <React.Fragment key={`listItem-${index}`}>
                          <BreadcrumbsItem spacerIconAfter>
                            {item.props.children}
                          </BreadcrumbsItem>
                        </React.Fragment>
                      );
                    },
                  )}
                <BreadcrumbsItem>
                  {items[items.length - 1].props &&
                    items[items.length - 1].props.children &&
                    React.cloneElement(items[items.length - 1].props.children, {
                      isActive: items.length > 1,
                    })}
                </BreadcrumbsItem>
              </>
            )}
          </>
        )}
      </ol>
    </nav>
  );
};

export interface BreadcrumbsProps {
  /**
   * Contents of the Breadcrumbs Should only contain `Breadcrumb.Item`.
   */
  children: ReactNode;

  /**
   * Select if you want the Nav items to be Light
   */
  isLight?: boolean;
}
