import React, { type ReactNode, useContext } from "react";

import classNames from "classnames";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";
import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { SurfaceContext } from "../Surface";

/**
 * Use `Text` to display text.
 */
export const Text = ({
  align = "left",
  children,
  id,
  isInline = false,
  isMeasured = false,
  size = "m",
  tone = "default",
  elementType = "span",
  ...props
}: TextProps) => {
  const { surface } = useContext(SurfaceContext);

  const Element = elementType;

  return (
    <Element
      id={id}
      className={classNames({
        "arc-Text": true,
        [suffixModifier("arc-Text--align", align)]: align !== "left",
        "arc-Text--inline": isInline,
        "arc-Text--measured": isMeasured,
        [`arc-Text--size${size && size.toUpperCase()}`]: size && size !== "m",
        [`arc-Text--${tone}`]: tone !== "default",
        "arc-Text--onDarkSurface": surface === "dark",
      })}
      {...filterAttrs(props)}
    >
      {children}
    </Element>
  );
};

export type Tone = "default" | "supporting" | "muted";
export type TextSize = "l" | "m" | "s" | "xs";

export interface TextProps {
  /**
   * Alignment of the Text.
   */
  align?: "left" | "center" | "right";

  /**
   * Text and inline markup to display.
   */
  children: ReactNode;

  /**
   * Should the Text component be styled as an inline element?
   */
  isInline?: boolean;

  /**
   * Should the Text width be constrained to a typographic measure?
   */
  isMeasured?: boolean;

  /**
   * Typographic Text size.
   */
  size?: TextSize;

  /**
   * Visual emphasis of the Text.
   */
  tone?: Tone;

  /**
   * Id for the Text.
   */
  id?: string;

  /**
   * Element type for text component. Default value is span
   */
  elementType?: "span" | "p";
}
