import React, { type ReactNode, useEffect, useState } from "react";

export const ClientSideVisible = ({ children }: ClientSideVisibleProps) => {
  const [canRender, setCanRender] = useState(false);

  useEffect(() => {
    if (typeof window !== "undefined") {
      setCanRender(true);
    }
  }, [setCanRender]);

  return (
    <div style={{ visibility: canRender ? "visible" : "hidden" }}>
      {children}
    </div>
  );
};

export interface ClientSideVisibleProps {
  /**
   * Content to render when client-side rendering is available.
   */
  children: ReactNode;
}
