import React, { type ReactNode, type Ref, useMemo, useState } from "react";

import { type ExtentableContainer } from "../../types/extendable-container";

import { Visible } from "../Visible";

import { NavigationHeaderContainer } from "./components/NavigationHeaderContainer";

import {
  NavigationHeaderLogo,
  type NavigationHeaderLogoProps,
} from "./components/NavigationHeaderLogo";

import { NavigationHeaderSideMenu } from "./components/NavigationHeaderSideMenu";

import { NavigationHeaderNavList } from "./components/NavigationHeaderNavList";

import { NavigationHeaderContext } from "./NavigationHeader.provider";
import { defaultHeaderVisibility } from "./constants/default-nav-visibility";

import {
  type NavigationHeaderExtraNavigationItem,
  type NavigationHeaderNavigationItem,
} from "./types/nav-item";

import { type ConfigurableHeaderVisibility } from "./types/header-visibility";
import { type MenuColorPathway } from "./types/menu-color-pathway";
import { type NavBarBackground } from "./types/navbar-background";
import { type SideMenuAction } from "./components/NavigationHeaderSideMenu/components/SideMenuActions";
import { defaultEmptyArray } from "./utils/default-empty-array";

/**
 *  Use `NavigationHeader` as a Top-level UI element that displays branding, page titles, and primary navigation actions.
 */
export const NavigationHeader = ({
  leftSlot,
  middleSlot,
  rightSlot,
  isPill,
  isExtended,
  isFluid,
  logo,
  navItems,
  extraNavItems,
  extraMenuTooltip,
  extraMenuAriaLabel,
  burgerMenuActions,
  burgerMenuFooter,
  burgerMenuHeader,
  burgerMenuVisibility,
  onBurgerMenuOpenChange,
  burgerMenuPathway,
  navMenuVisibility,
  background = "transparentOnLight",
  ref,
}: NavigationHeaderProps) => {
  const [navBarEl, setNavBarEl] = useState<HTMLDivElement>();

  const burgerMenuVisibilityProps = {
    ...defaultHeaderVisibility.burgerMenu,
    ...burgerMenuVisibility,
  };

  const navMenuVisibilityProps = {
    ...defaultHeaderVisibility.navItems,
    ...navMenuVisibility,
  };

  const setNavBarRef = (el: HTMLDivElement) => {
    el && setNavBarEl(el);
  };

  const contextValue = useMemo(
    () => ({
      navBarEl,
      isPill,
      isExtended,
      isFluid,
    }),
    [navBarEl, isPill, isExtended, isFluid],
  );

  const allNavItems = [
    ...defaultEmptyArray(navItems),
    ...defaultEmptyArray(extraNavItems),
  ];

  return (
    <NavigationHeaderContext.Provider value={contextValue}>
      <nav aria-label="primary">
        <NavigationHeaderContainer
          ref={setNavBarRef}
          isPill={isPill}
          isExtended={isExtended}
          isFluid={isFluid}
          backgroundColor={background}
          contentRef={ref}
        >
          <div className="arc-NavigationHeader-inner">
            <div className="arc-NavigationHeader-leftSlot">
              <NavigationHeaderLogo {...logo} />
              {leftSlot}
            </div>

            <div className="arc-NavigationHeader-navSlot">
              {navItems && (
                <Visible {...navMenuVisibilityProps}>
                  <NavigationHeaderNavList
                    navItems={navItems}
                    background={background}
                    extraNavItems={extraNavItems}
                    extraMenuAriaLabel={extraMenuAriaLabel}
                    extraMenuTooltip={extraMenuTooltip}
                  />
                </Visible>
              )}
              <div className="arc-NavigationHeader-middleSlot">
                {middleSlot}
              </div>
            </div>

            {rightSlot && (
              <div className="arc-NavigationHeader-rightSlot">{rightSlot}</div>
            )}

            <Visible {...burgerMenuVisibilityProps}>
              <div className="arc-NavigationHeader-burgerMenuSlot">
                <NavigationHeaderSideMenu
                  menuPosition="right"
                  logo={logo}
                  background={background}
                  pathway={burgerMenuPathway}
                  navItems={allNavItems}
                  actions={burgerMenuActions}
                  header={burgerMenuHeader}
                  footer={burgerMenuFooter}
                  onOpenChange={onBurgerMenuOpenChange}
                />
              </div>
            </Visible>
          </div>
        </NavigationHeaderContainer>
      </nav>
    </NavigationHeaderContext.Provider>
  );
};

export interface NavigationHeaderProps extends ExtentableContainer {
  /**
   * Set the background color of the navbar.
   */
  background?: NavBarBackground;

  /**
   * Set the nav bar to be a pill shape. It will only be visible when the background is either white or ghosted.
   */
  isPill?: boolean;

  /**
   * Set the nav bar contents to be 100% width.
   */
  isFluid?: boolean;

  /**
   * Open content slot on the left of the nav bar.
   */
  leftSlot?: ReactNode;

  /**
   * Open content slot on the middle of the nav bar, after the nav items.
   */
  middleSlot?: ReactNode;

  /**
   * Open content slot on the right of the nav bar.
   */
  rightSlot?: ReactNode;

  /**
   * Configuration for the logo. Logo Defaults to BT. Alternatively you can select one of the brands via the `brand` field, or supply your own svg via the `svg` field.
   * When supplying your own svg the root element must be an `svg` element that is implemented as follows: it has a `viewBox` attribute, no `height`, `width` or `preserveAspectRatio` attributes. It will also need
   * fills or strokes set to `currentColor` if you want it to work on both light and dark pathways.
   */
  logo?: NavigationHeaderLogoProps;

  /**
   * Additional links or buttons for the burger menu that sit below the nav items.
   */
  burgerMenuActions?: SideMenuAction[];

  /**
   * Additional content for the burger menu that sits below all the other content.
   */
  burgerMenuFooter?: ReactNode;

  /**
   * Additional content for the burger menu that sits between the logo and the nav items.
   */
  burgerMenuHeader?: ReactNode;

  /**
   * Sets the color pathway for the burger menu, by default it inverts the pathway the header is using for contrast.
   */
  burgerMenuPathway?: MenuColorPathway;

  /**
   * Configuration for the burger menu visibility. It is always visible below 636px but can also be configured to show at larger breakpoints.
   */
  burgerMenuVisibility?: ConfigurableHeaderVisibility;

  /**
   * Configuration for the nav menu. It is always hidden below 636px but can also be configured to show at larger breakpoints.
   */
  navMenuVisibility?: ConfigurableHeaderVisibility;

  /**
   * Nav items for `NavigationHeader`.
   */
  navItems?: Array<NavigationHeaderNavigationItem>;

  /**
   * extra menu items for `NavigationHeader`.
   */
  extraNavItems?: Array<NavigationHeaderExtraNavigationItem>;

  /**
   * extra menu trigger aria label.
   */
  extraMenuAriaLabel?: string;

  /**
   * extra menu tooltip text.
   */
  extraMenuTooltip?: string;

  /**
   * Fires when the open state of the burger menu changes.
   */
  onBurgerMenuOpenChange?: (isOpen: boolean) => void;
  /**
   * Ref to the underlying content element. Used to position floating elements (e.g. login dropdown) relative to the navigation header.
   */
  ref?: Ref<HTMLDivElement>;
}
