import React, { useContext } from "react";

import classNames from "classnames";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";
import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { Icon } from "../Icon";
import { SurfaceContext } from "../Surface";
import { ThemeIcon } from "../ThemeIcon";

export type ElementUnion = HTMLButtonElement | HTMLAnchorElement;
export type ButtonRef = React.Ref<ElementUnion> | null;
type AnchorElProps = React.AnchorHTMLAttributes<HTMLAnchorElement>;
type ButtonElProps = React.ButtonHTMLAttributes<HTMLButtonElement>;
type CommonElProps = AnchorElProps & ButtonElProps & { ref?: ButtonRef | null };

/**
 * Use `Button` to let a user complete an action like ‘Log in’ or ‘Register’.
 */
export const Button = ({
  ariaLabel,
  ariaControls,
  ariaExpanded,
  ariaHasPopup,
  fill = "solid",
  href,
  icon,
  iconPosition = "afterText",
  id,
  isDisabled = false,
  isDisplayBlock = false,
  isFullWidth = false,
  label,
  onClick,
  rel,
  size = "m",
  supportingText,
  target,
  type,
  form,
  ref,
  ...props
}: ButtonProps) => {
  const { surface } = useContext(SurfaceContext);

  const buttonClasses = classNames({
    "arc-Button": true,
    "arc-Button--displayBlock": isDisplayBlock,
    [suffixModifier("arc-Button--fill", fill)]: fill !== "solid",
    "arc-Button--fullWidth": isFullWidth,
    [suffixModifier("arc-Button--icon", iconPosition.replace("icon", ""))]:
      (icon || fill === "flat") && iconPosition,
    "arc-Button--hasSupportingText": supportingText,
    "arc-Button--onDarkSurface": surface === "dark",
    [`arc-Button--size${size && size.toUpperCase()}`]: size && size !== "m",
  });

  const commonProps: CommonElProps = {
    id,
    onClick,
    ref,
    ...filterAttrs(props),
  };

  const buttonText = supportingText ? (
    <span>
      <span className="arc-Button-text">{label}</span>
      <span className="arc-Button-supportingText">{supportingText}</span>
    </span>
  ) : (
    <span className="arc-Button-text">{label}</span>
  );

  const buttonIcon =
    icon || fill === "flat" ? (
      <ButtonIcon
        icon={icon}
        isChevron={!icon && fill === "flat"}
        isBeforeText={iconPosition === "beforeText"}
      />
    ) : null;

  if (href && !isDisabled) {
    return (
      <a
        {...(commonProps as AnchorElProps)}
        aria-label={ariaLabel}
        aria-haspopup={ariaHasPopup}
        aria-controls={ariaControls}
        aria-expanded={ariaExpanded}
        className={buttonClasses}
        href={href}
        rel={rel}
        target={target}
      >
        <span className="arc-Button-inner">
          {buttonText}
          {buttonIcon}
        </span>
      </a>
    );
  }

  return (
    <button
      {...(commonProps as ButtonElProps)}
      aria-label={ariaLabel}
      aria-haspopup={ariaHasPopup}
      aria-controls={ariaControls}
      aria-expanded={ariaExpanded}
      className={buttonClasses}
      disabled={isDisabled}
      type={type}
      form={form}
    >
      <span className="arc-Button-inner">
        {buttonText}
        {buttonIcon}
      </span>
    </button>
  );
};

const ButtonIcon = ({ icon, isChevron, isBeforeText }: ButtonIconProps) => (
  <span className="arc-Button-icon">
    {isChevron ? (
      <ThemeIcon icon={isBeforeText ? "buttonLeft" : "buttonRight"} />
    ) : (
      <Icon icon={icon} />
    )}
  </span>
);

export interface ButtonIconProps {
  /**
   * Icon variant.
   */
  icon?: string;

  /**
   * Should the icon be a default chevron?
   */
  isChevron?: boolean;

  /**
   * Should the icon be positioned before button text?
   */
  isBeforeText?: boolean;
}

interface ButtonElementProps {
  /**
   * Default behavior of the Button element. If not provided, 'submit' will
   * be inferred. Type 'reset' deliberately excluded.
   */
  type?: "button" | "submit";

  /**
   * Refers to the id of a form so it can be submitted if the button exists outside of it.
   */
  form?: string;
}

interface LinkElementProps {
  /**
   * URL to link to if Button elementType is 'a'.
   */
  href?: string;

  /**
   * Target window for the Button href URL.
   */
  target?: string;

  /**
   * Relationship between the Button href URL and the current page. See
   * [MDN](https://developer.mozilla.org/en-US/docs/Web/HTML/Attributes/rel).
   */
  rel?: string;
}

export interface ButtonProps extends ButtonElementProps, LinkElementProps {
  /**
   * Text to override `label` with additional, more precise information
   * specifically for screen reader users.
   */
  ariaLabel?: string;

  /**
   * Button fill.
   */
  fill?: "solid" | "outlined" | "flat";

  /**
   * Button icon variant.
   */
  icon?: string;

  /**
   * How should a Button icon be displayed?
   */
  iconPosition?: "afterText" | "beforeText" | "iconOnly";

  /**
   * HTML ID for the Button
   */
  id?: string;

  /**
   * Should the Button be disabled?
   */
  isDisabled?: boolean;

  /**
   * Should the Button’s CSS display property be set to block?
   */
  isDisplayBlock?: boolean;

  /**
   * Should the Button take up the full width of its container?
   */
  isFullWidth?: boolean;

  /**
   * Button text.
   */
  label: string;

  /**
   * Optional click handler for the Button.
   */
  onClick?: () => void;

  /**
   * Optional property to provide component Ref
   */
  ref?: ButtonRef;

  /**
   * How should a Button icon be displayed?
   */
  size?: "l" | "m" | "s";

  /**
   * Optional supporting text for the Button.
   */
  supportingText?: string;

  /**
   * Indicates the availability and type of a popup triggered by the button.
   */
  ariaHasPopup?: false | true | "menu" | "listbox" | "dialog" | "grid" | "tree";

  /**
   * Indicates whether the popup controlled by the button is expanded or collapsed.
   */
  ariaExpanded?: boolean;

  /**
   * Defines the ID of the element controlled by the button.
   */
  ariaControls?: string;
}
