import React from "react";

import classNames from "classnames";

import { Image, type ImageProps, type ImageSourceProps } from "../../Image";

export const BannerImage = ({
  sources,
  ariaHidden,
  isBorderRadius,
  onImageError,
  ...props
}: BannerImageProps) => (
  <div
    className={classNames("arc-TemplateBanner-imageWrapper", {
      "arc-TemplateBanner-image--borderRadius": isBorderRadius,
    })}
  >
    <Image
      aria-hidden={ariaHidden}
      onImageError={onImageError}
      fadeOnLoad
      {...props}
    >
      {sources &&
        sources.map((source) => <source key={source.srcSet} {...source} />)}
    </Image>
  </div>
);

export interface BannerImageProps extends Pick<
  ImageProps,
  | "src"
  | "alt"
  | "loading"
  | "sizes"
  | "srcSet"
  | "width"
  | "height"
  | "fadeOnLoad"
  | "fit"
  | "anchor"
  | "fetchPriority"
  | "onImageError"
> {
  /**
   * Whether the image should be hidden from screen readers.
   */
  ariaHidden?: boolean;
  /**
   * Array of source elements for responsive images.
   */
  sources?: Pick<ImageSourceProps, "media" | "sizes" | "srcSet">[];
  /**
   * Whether to apply border radius to the image. Use when the image fills the full extent of the slot (e.g. a JPEG with `fit="cover"`).
   */
  isBorderRadius?: boolean;
}
