import React, { type Ref, useContext } from "react";

import classNames from "classnames";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";

import { SurfaceContext } from "../../../Surface";
import { Text } from "../../../Text";
import { SemanticLink } from "../../../SemanticLink";

import { type NavLink } from "../../types/nav-link";

export const NavigationHeaderNavLink = ({
  ref,
  text,
  onClick,
  href,
  borderRadiusSize,
}: NavigationHeaderNavLinkProps) => {
  const { surface } = useContext(SurfaceContext);

  return (
    <SemanticLink
      ref={ref}
      href={href}
      onClick={onClick}
      className={classNames(
        "arc-NavigationHeaderNavLink",
        suffixModifier(
          "arc-NavigationHeaderNavLink--borderRadiusSize",
          borderRadiusSize,
        ),
        suffixModifier("arc-NavigationHeaderNavLink--on", surface),
      )}
    >
      <Text>{text}</Text>
    </SemanticLink>
  );
};

export interface NavigationHeaderNavLinkProps extends NavLink {
  /**
   * Ref to the underlying anchor element.
   */
  ref?: Ref<HTMLAnchorElement>;
  /**
   * Border radius size for the link.
   */
  borderRadiusSize: "m" | "s";
}
