import React, { type ReactNode, type RefObject, useEffect } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";
import { ArcSizeBreakpointsL } from "@arc-ui/tokens-arc";

import { Surface } from "../../../Surface";
import { SiteHeaderV2BackButton } from "../SiteHeaderV2BackButton";

export const SiteHeaderV2HorizontalPanel = ({
  children,
  navItemRef,
  open,
  setOpen,
  subNavItemRef,
  subNavLink = "",
  title,
  withSubNav,
  ...props
}: SiteHeaderV2HorizontalPanel) => {
  useEffect(() => {
    // Where appropriate, close the Panel when clicking outside of it,
    // by listening to clicks on the entire document and acting accordingly.
    const handleClick = (e: Event) => {
      // Close the Horizontal Panel…
      if (
        // The click is not inside the current NavItem
        !navItemRef?.current?.contains(e.target as Node) ||
        (e.target as Element).classList.contains(
          "arc-SiteHeaderV2HorizontalPanel--open",
        )
      ) {
        setOpen(false);
        return;
      }
    };

    document.addEventListener("click", handleClick);

    return () => {
      document.removeEventListener("click", handleClick);
    };
  }, [navItemRef, setOpen, subNavItemRef, subNavLink]);

  useEffect(() => {
    const handleKeydown = (e: KeyboardEvent) => {
      // Check the viewport width at time of press
      const isMinWidthArcBreakpointL = window.matchMedia(
        `(min-width: ${ArcSizeBreakpointsL})`,
      ).matches;

      if (e.key === "Escape" || e.keyCode === 27) {
        if (isMinWidthArcBreakpointL && subNavItemRef) {
          // Don't close Panels inside SubNavItems when viewport width is above
          // the "desktop" breakpoint.
          return false;
        }
        return setOpen(false);
      }
    };

    window.addEventListener("keydown", handleKeydown);

    return () => {
      window.removeEventListener("keydown", handleKeydown);
    };
  }, [setOpen, subNavItemRef]);

  return (
    <div
      className={classNames({
        [`arc-SiteHeaderV2HorizontalPanel`]: true,
        [`arc-SiteHeaderV2HorizontalPanel--open`]: open,
        [`arc-SiteHeaderV2HorizontalPanel--withSubNav`]: withSubNav,
      })}
      {...filterAttrs(props)}
    >
      <Surface background="light-neutral-02">
        <div
          className={classNames({
            [`arc-SiteHeaderV2HorizontalPanel-container`]: true,
          })}
        >
          <SiteHeaderV2BackButton
            setOpen={setOpen}
            setOpenPanelOnFirstClick={() => {}}
          />
          {title && (
            <div className="arc-SiteHeaderV2Panel-selectedTitle">{title}</div>
          )}
          <ul
            className={classNames({
              [`arc-SiteHeaderV2HorizontalPanel-items`]: true,
              //[`arc-SiteHeaderV2HorizontalPanel-fadeIn`]: animation,
            })}
          >
            {children}
          </ul>
        </div>
      </Surface>
    </div>
  );
};

export interface SiteHeaderV2HorizontalPanel {
  /**
   * Contents of the horizontal panel.
   */
  children: ReactNode;
  /**
   * Reference to the navigation item element.
   */
  navItemRef: RefObject<HTMLLIElement | null>;
  /**
   * Whether the panel is open.
   */
  open: boolean;
  /**
   * Function to set the open state of the panel.
   */
  setOpen: (arg0: boolean) => any;
  /**
   * Reference to the sub navigation item element.
   */
  subNavItemRef?: RefObject<HTMLElement>;
  /**
   * CSS class name for the sub navigation link.
   */
  subNavLink?: string;
  /**
   * Title to display in the panel.
   */
  title?: ReactNode;
  /**
   * Whether the panel has sub navigation.
   */
  withSubNav?: boolean;
}
