import React, { type ReactNode, useState, useContext } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { Text } from "../Text";
import { SurfaceContext } from "../Surface";
import { ThemeIcon } from "../ThemeIcon";

/**
 * Use `DisclosureMini` to show and hide sections of content.
 */
export const DisclosureMini = ({
  children,
  summary,
  onClick,
  id,
  isOpen = false,
  iconPosition = "left",
  size = "l",
  ...props
}: DisclosureMiniProps) => {
  const { surface } = useContext(SurfaceContext);
  const [disclousreState, setDisclosureState] = useState(false);

  const handleOnClick = () => {
    onClick && onClick();
    setDisclosureState((prevState) => !prevState);
  };

  return (
    <details
      data-testid="DisclosureMini"
      className={classNames("arc-DisclosureMini", {
        "arc-DisclosureMini--onDarkSurface": surface === "dark",
      })}
      open={isOpen}
      {...filterAttrs(props)}
    >
      <summary
        data-testid="DisclosureMiniSummary"
        className={classNames(
          `arc-DisclosureMini-summary arc-DisclosureMini-summary--icon-${iconPosition}`,
          {
            "arc-DisclosureMini-summary--small": size === "s",
          },
        )}
        onClick={handleOnClick}
        aria-expanded={disclousreState}
      >
        <div
          className={classNames("arc-DisclosureMini-summary-icon", {
            "arc-DisclosureMini-summary-icon--small": size === "s",
          })}
        >
          <ThemeIcon icon="disclosureMiniExpand" />
        </div>

        <Text size={size === "l" ? "m" : "s"}>{summary}</Text>
      </summary>

      <div className="arc-DisclosureMini-details">
        <Text size={size === "l" ? "m" : "s"}>
          <span id={id}>{children}</span>
        </Text>
      </div>
    </details>
  );
};

export interface DisclosureMiniProps {
  /**
   * Content to display in the DisclosureMini.
   */
  children: ReactNode;

  /**
   * DisclosureMini ID.
   */
  id?: string;

  /**
   * The DisclosureMini summary text.
   */
  summary: string;

  /**
   * Should the Disclosure content be open by default?
   */
  isOpen?: boolean;

  /**
   * Position of the DisclosureMini icon?
   */
  iconPosition?: "left" | "right";

  /**
   * On Click handler for DisclosureMini summary disclosure.
   */
  onClick?: () => void;

  /**
   * Disclosure size.
   */
  size?: "l" | "s";
}
