import React, { type ReactNode, useContext } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { SurfaceContext } from "../Surface/Surface";

/**
 * Use `Markup` to display HTML-formatted text.
 */
export const Markup = ({
  children,
  isMeasured = false,
  ...props
}: MarkupProps) => {
  const { surface } = useContext(SurfaceContext);

  return (
    <div
      className={classNames({
        "arc-Markup": true,
        "arc-Markup--measured": isMeasured,
        "arc-Markup--onDarkSurface": surface === "dark",
      })}
      {...filterAttrs(props)}
    >
      {children}
    </div>
  );
};

export interface MarkupProps {
  /**
   * HTML-formatted text to display in Markup.
   */
  children: ReactNode;

  /**
   * Should the Markup width be constrained to a typographic measure?
   */
  isMeasured?: boolean;
}
