import addMonths from "date-fns/addMonths";

import { getFocusDate } from "../../helpers";

import { type SHOW_NEXT_MONTH_ACTION } from "../types/actions";
import { type StateHandler } from "../types/state-handler";

export const showNextMonthHandler: StateHandler<SHOW_NEXT_MONTH_ACTION> = (
  payload,
  state,
) => {
  return {
    ...state,
    focusDate: getFocusDate({
      date: addMonths(state.focusDate, 1),
      maxDate: payload.maxDate,
    }),
    displayDate: addMonths(state.displayDate, 1),
  };
};
