import React from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import {
  TemplateBanner,
  type TemplateBannerProps,
} from "../TemplateBanner/TemplateBanner";

import { ConditionalWrapper } from "../ConditionalWrapper";

/** Use `HeroBanner` to promote key content or products with bold visuals and messaging. */
export const HeroBanner = ({
  heading,
  label,
  text,
  img,
  contentRatio = "1/1",
  contentRatios,
  children,
  minHeight,
  isReversed = false,
  isElevated = false,
  headingLevel = "2",
  extendBeyondContainer = false,
  type = "light",
  fontStyle = "default",
  headingWordWrap = false,
  headingColor,
  labelColor,
  ...props
}: HeroBannerProps) => {
  return (
    <ConditionalWrapper
      condition={extendBeyondContainer}
      wrapper={(children) => (
        <div
          className={classNames({
            "arc-HeroBanner--expanded": extendBeyondContainer,
          })}
        >
          {children}
        </div>
      )}
    >
      <TemplateBanner
        heading={heading}
        label={label}
        text={text}
        img={img}
        contentRatio={contentRatio}
        contentRatios={contentRatios}
        minHeight={minHeight}
        isReversed={isReversed}
        isElevated={isElevated}
        headingLevel={headingLevel}
        headingColor={headingColor}
        type={type}
        headingSize={"xl"}
        fontStyle={fontStyle}
        alignment="center"
        headingWordWrap={headingWordWrap}
        labelColor={labelColor}
        {...filterAttrs(props)}
      >
        {children}
      </TemplateBanner>
    </ConditionalWrapper>
  );
};

export interface HeroBannerProps extends Omit<
  TemplateBannerProps,
  "headingSize" | "alignment" | "additionalTopMargin"
> {
  /**
   * Extend HeroBanner 56px beyond its container on both sides at larger breakpoints (e.g., 1440px and above).
   */
  extendBeyondContainer?: boolean;
}
