import React, { useId, type ReactNode } from "react";

export const NavigationHeaderActionBar = ({
  children,
}: NavigationHeaderActionBarProps) => {
  const id = useId();

  const items = React.Children.map(children, (child, i) => (
    <li key={`${id}-navigation-header-bar-action-item-${i}`}>{child}</li>
  ));

  return <ul className="arc-NavigationHeaderActionBar">{items}</ul>;
};

export interface NavigationHeaderActionBarProps {
  /**
   * `NavigationHeaderAction` components to display in the action bar.
   */
  children: ReactNode;
}
