import React, { useContext, useEffect, useId, useRef, useState } from "react";

import classNames from "classnames";

import { getFocusableElements } from "@arc-ui/helpers/get-focusable-elements";
import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";

import { Heading } from "../../../Heading";
import { VerticalSpace } from "../../../VerticalSpace";
import { Rule } from "../../../Rule";
import { Text } from "../../../Text";
import { ThemeIcon } from "../../../ThemeIcon";
import { SurfaceContext } from "../../../Surface";

import { NavigationHeaderCta } from "../NavigationHeaderCta";
import { type NavigationHeaderCtaProps } from "../NavigationHeaderCta/NavigationHeaderCta";

export const NavigationHeaderCollapsingNavList = ({
  mainLink,
  description,
  category,
  links,
  revealLinkIconOnHover,
  isBottomSpacing = false,
  autoFocusOnExpand = true,
  background = "dark",
  defaultOpen = false,
}: NavigationHeaderCollapsingNavListProps) => {
  const id = useId();
  const { surface } = useContext(SurfaceContext);
  const [isOpen, setIsOpen] = useState(defaultOpen);
  const containerRef = useRef<HTMLDivElement | null>(null);

  const onClick = (e: React.ToggleEvent<HTMLDetailsElement>) => {
    setIsOpen(e.currentTarget.open);
  };

  useEffect(() => {
    if (
      containerRef.current &&
      containerRef.current.firstChild &&
      autoFocusOnExpand &&
      isOpen
    ) {
      getFocusableElements(containerRef.current as Node)[0].focus();
    }
  }, [isOpen, autoFocusOnExpand]);

  return (
    <details
      className={classNames(
        "arc-NavigationHeaderCollapsingNavList-disclosure",
        suffixModifier(
          "arc-NavigationHeaderCollapsingNavList-disclosure--on",
          surface,
        ),
        {
          "arc-NavigationHeaderCollapsingNavList-disclosure--open": isOpen,
        },
      )}
      open={isOpen}
      onToggle={onClick}
    >
      <summary
        className={classNames(
          "arc-NavigationHeaderCollapsingNavList-disclosureSummary",
          suffixModifier(
            "arc-NavigationHeaderCollapsingNavList-disclosureSummary--background",
            background,
          ),
        )}
        aria-expanded={isOpen}
      >
        <div className="arc-NavigationHeaderCollapsingNavList-disclosureSummaryHeading">
          <Heading level="3">{category}</Heading>
        </div>

        <span className="arc-NavigationHeaderCollapsingNavList-disclosureSummaryIcon">
          <ThemeIcon size={20} icon="navigationHeaderDisclosure" />
        </span>
      </summary>

      <div className="arc-NavigationHeaderCollapsingNavList-content">
        {description && (
          <div className="arc-NavigationHeaderCollapsingNavList-description">
            <VerticalSpace size="8" />
            <Text size="s" tone="muted">
              {description}
            </Text>
          </div>
        )}

        <div ref={containerRef}>
          <VerticalSpace size="16" />

          <ul className="arc-NavigationHeaderCollapsingNavList-list">
            {mainLink && (
              <li>
                <NavigationHeaderCta
                  {...mainLink}
                  revealLinkIconOnHover={revealLinkIconOnHover}
                />

                <div aria-hidden>
                  <VerticalSpace size="8" />
                  <Rule />
                  {Boolean(links?.length) && <VerticalSpace size="8" />}
                </div>
              </li>
            )}

            {links?.map((link, i) => (
              <li
                className="arc-NavigationHeaderCollapsingNavList-linkListItem"
                key={`${id}-NavigationHeader-megamenu-link-${i}`}
              >
                <NavigationHeaderCta
                  {...link}
                  revealLinkIconOnHover={revealLinkIconOnHover}
                />
              </li>
            ))}
          </ul>
        </div>
        {isBottomSpacing && <VerticalSpace />}
      </div>
    </details>
  );
};

interface NavigationHeaderCollapsingNavListProps {
  /**
   * Add bottom spacing to the contents when open.
   */
  isBottomSpacing?: boolean;
  /**
   * Category heading text.
   */
  category: string;
  /**
   * Whether to auto-focus the first element when expanded.
   */
  autoFocusOnExpand?: boolean;
  /**
   * Whether to reveal the link icon on hover.
   */
  revealLinkIconOnHover?: boolean;
  /**
   * Background color scheme.
   */
  background?: "light" | "dark";
  /**
   * Whether the disclosure is open by default.
   */
  defaultOpen?: boolean;
  /**
   * Description text for the category.
   */
  description?: string;
  /**
   * Main link for the category.
   */
  mainLink?: NavigationHeaderCtaProps;
  /**
   * Array of additional links.
   */
  links?: NavigationHeaderCtaProps[];
}
