import React from "react";

import { RadioGroup } from "@radix-ui/react-dropdown-menu";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

/**
 * Groups menu items allowing single selection from multiple options.
 */

export const MenuGroupSingleSelect = ({
  children,
  value,
  onValueChange,
  ...props
}: MenuGroupSingleSelectProps) => {
  return (
    <RadioGroup
      className="arc-MenuGroupSingleSelect"
      value={value}
      onValueChange={onValueChange}
      {...filterAttrs(props)}
    >
      {children}
    </RadioGroup>
  );
};

export interface MenuGroupSingleSelectProps {
  /**
   * The single select items inside the group.
   */
  children: React.ReactNode;

  /**
   * The current selected value of the single select group.
   */
  value?: string;

  /**
   * Callback fired when the selected value changes.
   */
  onValueChange?: (value: string) => void;
}
