import * as React from "react";
import { useMemo } from "react";

import classNames from "classnames";

import { type ScrimFadeSize } from "../types/scrim-fade-size";
import { type ScrimFadePosition } from "../types/scrim-fade-position";

export const ScrimFade = ({
  scrimFadeHeight,
  scrimFadeSize,
  scrimFadePosition,
}: ScrimFadeProps) => {
  const { totalHeight, fadeHeight } = useMemo(() => {
    const fadeModifier = 128;

    const defaultSizes: Record<
      ScrimFadeSize,
      { totalHeight: number; fadeHeight: number }
    > = {
      s: {
        totalHeight: 640,
        fadeHeight: 640 - fadeModifier,
      },
      m: {
        totalHeight: 1024,
        fadeHeight: 1024 - fadeModifier,
      },
      l: {
        totalHeight: 1408,
        fadeHeight: 1408 - fadeModifier,
      },
    };

    if (!scrimFadeHeight) {
      return defaultSizes[scrimFadeSize];
    }

    return {
      totalHeight: scrimFadeHeight,
      fadeHeight: scrimFadeHeight - fadeModifier,
    };
  }, [scrimFadeHeight, scrimFadeSize]);

  return (
    <svg
      width="1024"
      height={totalHeight}
      viewBox={`0 0 1024 ${totalHeight}`}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      preserveAspectRatio="none"
      className={classNames(
        "arc-GradientPageBackground-scrimFade",
        scrimFadePosition &&
          `arc-GradientPageBackground-scrimFade--${scrimFadePosition}`,
      )}
    >
      <rect
        y="128"
        width="1024"
        height={fadeHeight}
        fill="url(#paint0_linear_6538_9883)"
      />
      <g opacity="0.7">
        <rect
          width="1024"
          height={totalHeight}
          fill="url(#paint1_linear_6538_9883)"
          style={{ mixBlendMode: "soft-light" }}
        />
      </g>
      <defs>
        <linearGradient
          id="paint0_linear_6538_9883"
          x1="512"
          y1="128"
          x2="512"
          y2={totalHeight}
          gradientUnits="userSpaceOnUse"
        >
          <stop stopColor="white" stopOpacity="0" />
          <stop offset="0.0806874" stopColor="white" stopOpacity="0.01" />
          <stop offset="0.155366" stopColor="white" stopOpacity="0.0217837" />
          <stop offset="0.22496" stopColor="white" stopOpacity="0.04832" />
          <stop offset="0.290394" stopColor="white" stopOpacity="0.0846696" />
          <stop offset="0.352593" stopColor="white" stopOpacity="0.13037" />
          <stop offset="0.41248" stopColor="white" stopOpacity="0.18496" />
          <stop offset="0.470981" stopColor="white" stopOpacity="0.247976" />
          <stop offset="0.529019" stopColor="white" stopOpacity="0.318957" />
          <stop offset="0.58752" stopColor="white" stopOpacity="0.39744" />
          <stop offset="0.647407" stopColor="white" stopOpacity="0.482963" />
          <stop offset="0.709606" stopColor="white" stopOpacity="0.575064" />
          <stop offset="0.77504" stopColor="white" stopOpacity="0.67328" />
          <stop offset="0.844634" stopColor="white" stopOpacity="0.77715" />
          <stop offset="0.919313" stopColor="white" stopOpacity="0.88621" />
          <stop offset="1" stopColor="white" />
        </linearGradient>
        <linearGradient
          id="paint1_linear_6538_9883"
          x1="512"
          y1="0"
          x2="512"
          y2={totalHeight}
          gradientUnits="userSpaceOnUse"
        >
          <stop stopColor="white" stopOpacity="0" />
          <stop offset="1" stopColor="white" />
        </linearGradient>
      </defs>
    </svg>
  );
};

interface ScrimFadeProps extends React.SVGAttributes<SVGElement> {
  /**
   * Optional CSS class name
   */
  className?: string;
  /**
   * Custom height for the scrim fade
   */
  scrimFadeHeight?: number;
  /**
   * Position of the scrim fade
   */
  scrimFadePosition?: ScrimFadePosition;
  /**
   * Size of the scrim fade
   */
  scrimFadeSize: ScrimFadeSize;
}
