import React, {
  type ReactNode,
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from "react";

import classNames from "classnames";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";

import { Tooltip } from "../../../Tooltip";
import { ThemeIcon } from "../../../ThemeIcon";
import { VisuallyHidden } from "../../../VisuallyHidden";

import { DELAY_DURATION } from "../../constants/tooltip";

import { type NavigationHeaderNavigationItem } from "../../types/nav-item";
import { type NavBarBackground } from "../../types/navbar-background";

import {
  NavigationHeaderLogo,
  type NavigationHeaderLogoProps,
} from "../NavigationHeaderLogo";

import { NavigationHeaderButton } from "../NavigationHeaderButton";
import { type MenuColorPathway } from "../../types/menu-color-pathway";
import { type MenuPosition } from "../../types/menu-position";
import { type InteractionMode } from "../../types/interaction-mode";

import { getMenuColorConfig } from "../../utils/get-menu-color-config";

import { useTriggerHidden } from "../../hooks/use-trigger-hide";

import { SideMenuHeader } from "./components/SideMenuHeader";
import { SideMenuDrawer } from "./components/SideMenuDrawer";
import { SideMenuNavSection } from "./components/SideMenuNavSection";

import {
  type SideMenuAction,
  SideMenuActions,
} from "./components/SideMenuActions";

import { SideMenuNavItem } from "./components/SideMenuNavItem";
import { SideMenuNavList } from "./components/SideMenuNavList";

import { NavigationHeaderSideMenuContext } from "./NavigationHeaderSideMenu.provider";

export const NavigationHeaderSideMenu = ({
  navItems,
  children,
  actions,
  header,
  footer,
  logo,
  background,
  onOpenChange,
  trigger,
  menuPosition,
  showLogo = true,
  tooltip = "Menu",
  pathway = "invert",
  triggerAriaLabel = "Open menu",
}: NavigationHeaderSideMenuProps) => {
  const id = useId();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const mainContentRef = useRef<HTMLDivElement>(null);
  const [interactionMode, setInterActionMode] =
    useState<InteractionMode>("pointer");

  useEffect(() => {
    onOpenChange?.(isMenuOpen);
  }, [isMenuOpen, onOpenChange]);

  useTriggerHidden({
    triggerEl: triggerRef.current as HTMLElement,
    onTriggerHidden: () => {
      closeMenu();
    },
  });

  const closeMenu = useCallback(() => {
    setIsMenuOpen(false);
  }, [setIsMenuOpen]);

  const onEscapeKeyDown = useCallback(() => {
    setInterActionMode("keyboard");
    closeMenu();
  }, [closeMenu]);

  const onSideMenuMouseDown = () => {
    setInterActionMode("pointer");
  };

  const onSideMenuKeyDown = () => {
    setInterActionMode("keyboard");
  };

  const focusTriggerElement = () => {
    interactionMode === "keyboard" && triggerRef.current?.focus();
  };

  const menuColorConfig = getMenuColorConfig(background, pathway);

  const contextValue = useMemo(
    () => ({ menuPosition, menuColorConfig, onEscapeKeyDown, closeMenu }),
    [menuPosition, menuColorConfig, onEscapeKeyDown, closeMenu],
  );

  return (
    <NavigationHeaderSideMenuContext.Provider value={contextValue}>
      <div
        className="arc-NavigationHeaderSideMenu"
        onMouseDown={onSideMenuMouseDown}
        onKeyDown={onSideMenuKeyDown}
      >
        <Tooltip
          delayDuration={DELAY_DURATION}
          asChild
          title={tooltip}
          side="bottom"
        >
          <NavigationHeaderButton
            ref={triggerRef}
            isPadded={Boolean(trigger) || false}
            aria-expanded={isMenuOpen}
            aria-label={isMenuOpen ? "close menu" : triggerAriaLabel}
            onClick={() => setIsMenuOpen(!isMenuOpen)}
          >
            {trigger || (
              <div className="arc-NavigationHeaderSideMenu-trigger">
                {<ThemeIcon icon="siteHeaderBurger" size={24} />}
              </div>
            )}

            <VisuallyHidden>
              {isMenuOpen ? "close menu" : "open menu"}
            </VisuallyHidden>
          </NavigationHeaderButton>
        </Tooltip>

        <SideMenuDrawer
          drawerType="main"
          title="Navigation menu"
          menuPosition={menuPosition}
          isOpen={isMenuOpen}
          colorType={menuColorConfig.menuColorType}
          surface={menuColorConfig.surface}
          onCloseAutoFocus={focusTriggerElement}
          onEscapeKeyDown={onEscapeKeyDown}
          onInteractOutside={closeMenu}
        >
          <div className="arc-NavigationHeaderSideMenu-container">
            <div className="arc-NavigationHeaderSideMenu-mainContent">
              {showLogo && (
                <SideMenuHeader onCloseClick={closeMenu}>
                  <NavigationHeaderLogo {...logo} />
                </SideMenuHeader>
              )}

              <div ref={mainContentRef}>
                {header && (
                  <div
                    className={classNames(
                      "arc-NavigationHeaderSideMenu-topContent",
                      {
                        "arc-NavigationHeaderSideMenu-topContent--bottomSpacing":
                          !navItems,
                      },
                    )}
                  >
                    {header}
                  </div>
                )}

                {navItems && !children && (
                  <SideMenuNavSection>
                    <SideMenuNavList>
                      {navItems?.map((navItem, navItemIndex) => (
                        <React.Fragment
                          key={`${id}-side-nav-item-${navItemIndex}`}
                        >
                          <li
                            className={classNames(
                              {
                                "arc-NavigationHeaderSideMenu--separator":
                                  navItem.isSeparator,
                              },
                              suffixModifier(
                                "arc-NavigationHeaderSideMenu--separatorOn",
                                menuColorConfig.menuColorType,
                              ),
                            )}
                          >
                            <SideMenuNavItem navItem={navItem} />
                          </li>
                        </React.Fragment>
                      ))}
                    </SideMenuNavList>
                  </SideMenuNavSection>
                )}

                {children && (
                  <SideMenuNavSection>{children}</SideMenuNavSection>
                )}

                {actions && (
                  <SideMenuActions
                    showSeparator={Boolean(navItems || header)}
                    actions={actions}
                  />
                )}
              </div>
            </div>

            {footer && (
              <div className="arc-NavigationHeaderSideMenu-footer">
                {footer}
              </div>
            )}
          </div>
        </SideMenuDrawer>
      </div>
    </NavigationHeaderSideMenuContext.Provider>
  );
};

export interface NavigationHeaderSideMenuProps {
  /**
   * Position of the side menu.
   */
  menuPosition: MenuPosition;
  /**
   * Custom nav items for side menu.
   */
  children?: ReactNode;
  /**
   * Whether to show the logo in side menu.
   */
  showLogo?: boolean;
  /**
   * Trigger for the side menu.
   */
  trigger?: ReactNode;
  /**
   * trigger menu trigger aria label.
   */
  triggerAriaLabel?: string;
  /**
   * Tooltip for the trigger.
   */
  tooltip?: string;
  /**
   * Background color of the navigation bar.
   */
  background: NavBarBackground;
  /**
   * Logo configuration for the side menu.
   */
  logo?: NavigationHeaderLogoProps;
  /**
   * Additional content for the side menu header.
   */
  header?: ReactNode;
  /**
   * Additional actions for the side menu.
   */
  actions?: SideMenuAction[];
  /**
   * Additional content for the side menu footer.
   */
  footer?: ReactNode;
  /**
   * Color pathway for the side menu.
   */
  pathway?: MenuColorPathway;
  /**
   * Navigation items to display in the side menu.
   */
  navItems?: Array<NavigationHeaderNavigationItem>;
  /**
   * Callback when side menu open state changes.
   */
  onOpenChange?: (isOpen: boolean) => void;
}
