import React, { type ReactNode, useContext } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { type ExtentableContainer } from "../..//types/extendable-container";

import { SurfaceContext } from "../Surface";

/**
 * Use `Group` to arrange flexible items in a row.
 */
export const Group = ({
  children,
  grow = false,
  growEqual = false,
  gutterBorder = false,
  noWrap = false,
  isExtended = false,
  ...props
}: GroupProps) => {
  const { surface } = useContext(SurfaceContext);

  return (
    <div
      className={classNames({
        [`arc-Group`]: true,
        [`arc-Group--grow`]: grow,
        [`arc-Group--growEqual`]: growEqual,
        [`arc-Group--gutterBorder`]: gutterBorder,
        [`arc-Group--noWrap`]: noWrap,
        [`arc-Group--onDarkSurface`]: surface === "dark",
        [`arc-Group--regular`]: !isExtended,
        [`arc-Group--extended`]: isExtended,
      })}
      {...filterAttrs(props)}
    >
      <div className="arc-Group-inner">{children}</div>
    </div>
  );
};

export const GroupItem = ({
  children,
  grow = false,
  isDebugVisible = false,
  ...props
}: ItemProps) => {
  return (
    <div
      className={classNames({
        [`arc-Group-item`]: true,
        [`arc-Group-item--grow`]: grow,
        [`arc-Group-item--debugVisible`]: isDebugVisible,
      })}
      {...filterAttrs(props)}
    >
      {children}
    </div>
  );
};

export interface ItemProps {
  /**
   * Content to display in the GroupItem.
   */
  children?: ReactNode;

  /**
   * Should the GroupItem be visible for debugging and documentation
   * purposes?
   */
  isDebugVisible?: boolean;

  /**
   * Should the GroupItem stretch to fill the available space?
   */
  grow?: boolean;
}

export interface GroupProps extends ExtentableContainer {
  /**
   * Contents of the Group Should only contain `GroupItem`.
   */
  children: ReactNode;

  /**
   * Should all GroupItems in the Group stretch to fill the available space?
   */
  grow?: boolean;

  /**
   * Should all GroupItems in the Group stretch to fill the available space with equal widths?
   */
  growEqual?: boolean;

  /**
   * Should a border be shown between GroupItems? **Warning: Sets CSS property `overflow:hidden`.**
   */
  gutterBorder?: boolean;

  /**
   * Should wrapping of GroupItems in the Group be disabled?
   */
  noWrap?: boolean;
}
