import { type RANGE_SELECT_ACTION } from "../types/actions";
import { type StateHandler } from "../types/state-handler";

export const rangeSelectHandler: StateHandler<RANGE_SELECT_ACTION> = (
  payload,
  state,
) => {
  return {
    ...state,
    focusDate: payload.date,
    highlightedRange: payload.range,
  };
};
