import React from "react";

import classNames from "classnames";

import * as RadixToast from "@radix-ui/react-toast";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

/** Use `Toast` to display temporary messages at the bottom of the screen. */
export const Toast = ({
  children,
  colorScheme = "default",
  onDarkSurface = false,
  ...props
}: ToastProps) => (
  <RadixToast.Provider swipeDirection="right" duration={6000}>
    <RadixToast.Viewport asChild className="arc-Toast-viewport">
      <div
        className={classNames(`arc-Toast-pathway--${colorScheme}`, {
          "arc-Toast--onDarkSurface": onDarkSurface,
        })}
        {...filterAttrs(props)}
      >
        {children}
      </div>
    </RadixToast.Viewport>
  </RadixToast.Provider>
);

export interface ToastProps {
  /**
   * Content to display within `Toast`
   */
  children: React.ReactNode;

  /**
   * Colour scheme for `Toast` - Use 'default' in almost all cases.
   */
  colorScheme?: "default" | "alternative";

  /**
   * Change the focus colour for dark pathways.
   */
  onDarkSurface?: boolean;
}
