import React, { type Ref } from "react";

import classNames from "classnames";

/**
 * Use `SemanticHeading` to render accessible headings that preserve correct
 * document hierarchy.
 */

export const SemanticButton = ({
  children,
  className,
  ...props
}: SemanticButtonProps) => (
  <button className={classNames("arc-SemanticButton", className)} {...props}>
    {children}
  </button>
);

export interface SemanticButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /**
   * Ref for the Button.
   */
  ref?: Ref<HTMLButtonElement>;
  /**
   * Content to render within the Button.
   */
  children: React.ReactNode;
}
