import React, { useState, type ReactNode } from "react";

import { MenuContext, type StackItem } from "./MenuContext";

export const MenuProvider = ({
  isMobileMenu,
  defaultWidth,
  children,
}: MenuProviderProps) => {
  const [stack, setStack] = useState<StackItem[]>([]);

  const focusFirstMenuItem = () => {
    requestAnimationFrame(() => {
      const wrappers = document.querySelectorAll<HTMLElement>(
        "[data-radix-popper-content-wrapper]",
      );
      const latestWrapper = wrappers[wrappers.length - 1];
      if (!latestWrapper) return;

      const firstItem =
        latestWrapper.querySelector<HTMLElement>('[role="menuitem"]');
      firstItem?.focus();
    });
  };

  const goForward = (item: StackItem, navigatedViaKeyboard: boolean) => {
    setStack((prevStack) => [...prevStack, item]);
    if (navigatedViaKeyboard) {
      focusFirstMenuItem();
    }
  };

  const goBack = (navigatedViaKeyboard?: boolean) => {
    setStack((prevStack) => {
      const newStack = prevStack.slice(0, -1);
      if (navigatedViaKeyboard) {
        const last = prevStack[prevStack.length - 1];

        requestAnimationFrame(() => {
          const trigger = last?.triggerId
            ? document.querySelector<HTMLElement>(
                `[data-menu-trigger="${last.triggerId}"]`,
              )
            : null;

          if (trigger) {
            trigger.focus();
          } else {
            focusFirstMenuItem();
          }
        });
      }
      return newStack;
    });
  };

  const reset = () => {
    setStack([]);
  };

  return (
    <MenuContext.Provider
      value={{
        isMobileMenu,
        stack,
        goForward,
        goBack,
        reset,
        defaultWidth,
      }}
    >
      {children}
    </MenuContext.Provider>
  );
};

export interface MenuProviderProps {
  /**
   * Whether the menu is displayed in mobile mode.
   */
  isMobileMenu: boolean;
  /**
   * Default width for the menu.
   */
  defaultWidth?: string | number | "fluid";
  /**
   * Menu content to display.
   */
  children: ReactNode;
}
