import React, { type ReactNode } from "react";

import { BtIconChevronLeft2Px } from "@arc-ui/icons/BtIconChevronLeft2Px";
import { BtIconChevronRight2Px } from "@arc-ui/icons/BtIconChevronRight2Px";

import { Icon } from "../../Icon";

export const BreadcrumbsItem = ({
  spacerIconAfter,
  spacerIconBefore,
  children,
}: BreadcrumbsItemProps) => {
  return (
    <li className="arc-Breadcrumbs-item">
      {spacerIconBefore && (
        <div
          className={"arc-Breadcrumbs-spacerIcon"}
          data-testid="arc-chevron-left-2px"
          aria-hidden="true"
        >
          <Icon icon={BtIconChevronLeft2Px} />
        </div>
      )}

      {children}

      {spacerIconAfter && (
        <div className={"arc-Breadcrumbs-spacerIcon"} aria-hidden="true">
          <Icon icon={BtIconChevronRight2Px} />
        </div>
      )}
    </li>
  );
};

export interface BreadcrumbsItemProps {
  /**
   * Render child elements within `BreadcrumbsItem`
   */
  children?: ReactNode;
  /**
   * Use icon as a spacer that will be positioned after `BreadcrumbsItem`.
   */
  spacerIconAfter?: boolean;

  /**
   * Use icon as a spacer that will be positioned before `BreadcrumbsItem`.
   */
  spacerIconBefore?: boolean;
}
