import React, { useState, useRef } from "react";

import * as RadixDialog from "@radix-ui/react-dialog";

import { autoUpdate, offset, useFloating } from "@floating-ui/react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";
import { getFocusableElements } from "@arc-ui/helpers/get-focusable-elements";

import { VisuallyHidden } from "../../../VisuallyHidden";
import { Tooltip } from "../../../Tooltip";
import { ThemeIcon } from "../../../ThemeIcon";
import { useInteractionMode, useThemeElement } from "../../../../hooks";

import { NavigationHeaderButton } from "../NavigationHeaderButton";

import {
  NavigationHeaderActionLoginDropdown,
  type NavigationHeaderActionLoginDropdownProps,
} from "./components/NavigationHeaderActionLoginDropdown";

export const NavigationHeaderActionLogin = ({
  ariaLabel,
  isAttention,
  heading = "My Account",
  description = "Manage your BT products and services",
  tileOne,
  tileTwo,
  zIndexDropdown = 100,
  tooltip,
  navContainerRef,
  ...props
}: NavigationHeaderActionLoginProps) => {
  const [isOpen, setIsOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const dialogRef = useRef<HTMLDivElement>(null);
  const childContainerRef = useRef<HTMLDivElement>(null);
  const [themeElement, setThemeElement] = useThemeElement();
  const { interactionMode } = useInteractionMode();

  const { refs: floatingRefs, floatingStyles } = useFloating({
    whileElementsMounted: autoUpdate,
    elements: {
      reference: navContainerRef,
    },
    placement: "bottom-end",
    middleware: [offset(8)],
  });

  const onCloseAutoFocus = () => {
    if (
      document.activeElement?.tagName === "BODY" &&
      interactionMode === "keyboard"
    ) {
      triggerRef.current?.focus();
    }
  };

  const handleOutSideInteraction = (event: Event) => {
    if (!triggerRef.current?.contains(event.currentTarget as Node)) {
      setIsOpen(false);
    }
  };

  const focusOnFirstElement = () => {
    getFocusableElements(childContainerRef.current as Node)[0]?.focus({
      preventScroll: true,
    });
  };

  return (
    <div
      ref={setThemeElement}
      className={classNames("arc-NavigationHeaderActionLogin", {
        "arc-NavigationHeaderActionLogin--attention": isAttention,
      })}
      {...filterAttrs(props)}
    >
      <Tooltip
        title={tooltip?.title || "My Account"}
        side="bottom"
        supportingCopy={tooltip?.supportingCopy}
        asChild
      >
        <NavigationHeaderButton
          ref={triggerRef}
          isPadded={false}
          onClick={() => {
            setIsOpen(!isOpen);
          }}
        >
          <div
            className={classNames("arc-NavigationHeaderActionLogin-trigger", {
              "arc-NavigationHeaderActionLogin-trigger--active": isOpen,
            })}
          >
            <ThemeIcon
              aria-hidden
              icon={
                isOpen ? "navigationHeaderUserFill" : "navigationHeaderUser"
              }
              size={24}
            />
            <VisuallyHidden>{ariaLabel}</VisuallyHidden>
          </div>
        </NavigationHeaderButton>
      </Tooltip>
      <RadixDialog.Root open={isOpen}>
        <RadixDialog.Portal container={themeElement}>
          <div
            ref={floatingRefs.setFloating}
            style={{
              ...floatingStyles,
              zIndex: zIndexDropdown,
            }}
            className="arc-NavigationHeaderActionLogin-floating"
          >
            <RadixDialog.Content
              aria-modal
              className="arc-NavigationHeaderActionLogin-dialog"
              ref={dialogRef}
              onCloseAutoFocus={onCloseAutoFocus}
              onOpenAutoFocus={focusOnFirstElement}
              onEscapeKeyDown={handleOutSideInteraction}
              onFocusOutside={handleOutSideInteraction}
              onInteractOutside={handleOutSideInteraction}
              onPointerDownOutside={handleOutSideInteraction}
            >
              <VisuallyHidden>
                <RadixDialog.Title>{heading}</RadixDialog.Title>
                <RadixDialog.Description>{description}</RadixDialog.Description>
              </VisuallyHidden>

              <div ref={childContainerRef}>
                <NavigationHeaderActionLoginDropdown
                  heading={heading}
                  description={description}
                  tileOne={tileOne}
                  tileTwo={tileTwo}
                />
              </div>
            </RadixDialog.Content>
          </div>
        </RadixDialog.Portal>
      </RadixDialog.Root>
    </div>
  );
};

export interface NavigationHeaderActionLoginProps extends NavigationHeaderActionLoginDropdownProps {
  /**
   * The container element to align the dropdown with. Pass the element directly (e.g. from useState callback ref).
   */
  navContainerRef: HTMLDivElement | null;

  /**
   * Display a red dot next to the action to alert users.
   */
  isAttention?: boolean;

  /**
   * Label for action that is presented to screenreader.
   */
  ariaLabel: string;

  tooltip?: {
    /**
     * Title for action that is presented in a tooltip.
     */
    title?: string;

    /**
     * Supporting text for action that is presented in a tooltip.
     */
    supportingCopy?: string;
  };

  /**
   * zIndex value for login dropdown
   */
  zIndexDropdown?: number;
}
