import React, { type ReactNode, useContext, useState } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { Heading, type HeadingLevel } from "../Heading/Heading";
import { SurfaceContext } from "../Surface";
import { ThemeIcon } from "../ThemeIcon";

/**
 * Use `Disclosure` to show and hide sections of content.
 */
export const Disclosure = ({
  children,
  headingLevel,
  indentDetails = false,
  isOpen = false,
  summary,
  ...props
}: DisclosureProps) => {
  const { surface } = useContext(SurfaceContext);
  const [disclousreState, setDisclosureState] = useState(false);

  const handleOnClick = () => {
    setDisclosureState((prevState) => !prevState);
  };

  return (
    <details
      className={classNames({
        "arc-Disclosure": true,
        "arc-Disclosure--indentDetails": indentDetails,
        "arc-Disclosure--onDarkSurface": surface === "dark",
      })}
      open={isOpen}
      {...filterAttrs(props)}
    >
      <summary
        aria-expanded={disclousreState}
        onClick={handleOnClick}
        className="arc-Disclosure-summary"
      >
        <span className="arc-Disclosure-summary-icon">
          <ThemeIcon icon="disclosureExpand" />
        </span>
        <Heading level={headingLevel} size="s">
          {summary}
        </Heading>
      </summary>
      <div className="arc-Disclosure-details">{children}</div>
    </details>
  );
};

export interface DisclosureProps {
  /**
   * Content to display in the Disclosure.
   */
  children: ReactNode;

  /**
   * HTML section heading level of the Disclosure summary. If not provided, will
   * render as a span.
   */
  headingLevel?: HeadingLevel;

  /**
   * Should Disclosure details be indented to line-up with summary text?
   */
  indentDetails?: boolean;

  /**
   * Should the Disclosure content be open by default?
   */
  isOpen?: boolean;

  /**
   * The Disclosure summary text.
   */
  summary: string;
}
