export const parseRangeString = (value: string = "") => {
  const [start = "", end = ""] = value.replace(/\s/g, "").split("-");

  const [startDay, startMonth, startYear] = start.split("/");
  const [endDay, endMonth, endYear] = end.split("/");

  return {
    start: {
      date: start,
      day: startDay,
      month: startMonth,
      year: startYear,
    },
    end: {
      date: end,
      day: endDay,
      month: endMonth,
      year: endYear,
    },
  };
};
