import { type DAY_GRID_LEAVE_ACTION } from "../types/actions";
import { type StateHandler } from "../types/state-handler";

export const dayGridLeaveHandler: StateHandler<DAY_GRID_LEAVE_ACTION> = (
  payload,
  state,
) => {
  if (
    payload.selectionType === "range" &&
    payload.range.filter((date) => Boolean(date)).length === 1
  ) {
    return {
      ...state,
      highlightedRange: [],
    };
  }

  return { ...state };
};
