import React, { useContext } from "react";

import classNames from "classnames";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";

import { Icon } from "../../../Icon";
import { Text } from "../../../Text";
import { SurfaceContext } from "../../../Surface";
import { Hidden } from "../../../Hidden";
import { Visible } from "../../../Visible";

export const NavigationHeaderPage = ({
  icon,
  title,
  page,
}: NavigationHeaderPageProps) => {
  const { surface } = useContext(SurfaceContext);

  const iconToRender = (size: number) => <Icon size={size} icon={icon} />;

  return (
    <div
      className={classNames(
        "arc-NavigationHeaderPage",
        suffixModifier("arc-NavigationHeaderPage--on", surface),
      )}
    >
      {icon && (
        <div className="arc-NavigationHeaderPage-icon">
          <Visible xs>{iconToRender(20)}</Visible>
          <Hidden xs>{iconToRender(32)}</Hidden>
        </div>
      )}
      <span className="arc-NavigationHeaderPage-heading">{title}</span>
      {page && (
        <div className="arc-NavigationHeaderPage-pageSection">
          <div className="arc-NavigationHeaderPage-pageSectionText">
            <Text>{page}</Text>
          </div>
        </div>
      )}
    </div>
  );
};

export interface NavigationHeaderPageProps {
  /**
   * Icon URL to display with the page title.
   */
  icon?: string;
  /**
   * Page text to display.
   */
  page?: string;
  /**
   * Title text for the page.
   */
  title: string;
}
