import React from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

/**
 * Use `Spinner` to display a loading state.
 */
export const Spinner = ({ size = "m", color, ...props }: SpinnerProps) => {
  return (
    <svg
      className={classNames(
        "arc-Spinner",
        `arc-Spinner-${color}`,
        `arc-Spinner-size--${size}`,
      )}
      width={typeof size === "number" ? `${size}px` : undefined}
      data-testid="arc-Spinner"
      aria-label="loading"
      viewBox="0 0 48 48"
      xmlns="http://www.w3.org/2000/svg"
      {...filterAttrs(props)}
    >
      <circle
        cx="24"
        cy="24"
        fill="none"
        r="22"
        strokeWidth="4"
        strokeLinecap="round"
      />
    </svg>
  );
};

export type SpinnerSize = "xxl" | "xl" | "l" | "m" | "s";

export interface SpinnerProps {
  /**
   * Colour options. If no `color` option defined, the colour will use currentColor.
   */
  color?: "light" | "dark" | undefined;
  /**
   * Set sizes of spinner `s`, `m`, `l`, `xl`, `xxl` or a custom number value e.g. `100`px.
   */
  size?: SpinnerSize | number | null;
}
