import { type ComboBoxOption } from "../types/combobox-option";

import { canAddNewMultiSelectOptions } from "./canAddNewMultiSelectOptions";
import { getSelectedOptions } from "./getSelectedOptions";
import { multiSelectLimitReached } from "./multiSelectLimitReached";

export const getNewMultiSelectOptions = (
  selectedOption: ComboBoxOption,
  selectedOptions: ComboBoxOption[],
  multiSelectLimit?: number,
) => {
  const newSelectedOptions = getSelectedOptions(
    selectedOption,
    selectedOptions,
  );

  const limitReached = multiSelectLimitReached(
    newSelectedOptions,
    multiSelectLimit,
  );

  const canAddNewOptions = canAddNewMultiSelectOptions(
    newSelectedOptions,
    multiSelectLimit,
  );

  return {
    newOptions: canAddNewOptions ? newSelectedOptions : selectedOptions,
    limitReached,
  };
};
