import React from "react";

import { ThemeIcon } from "../../../ThemeIcon";

import { NavigationHeaderAction } from "../NavigationHeaderAction";

import { NavigationHeaderDropdown } from "../NavigationHeaderDropdown";

export const NavigationHeaderBasket = ({
  supportingCopy,
  onClick,
  href,
  popoverText = "No items in basket",
  title = "Basket",
  ariaLabel = "Basket, empty",
  isAttention = false,
}: NavigationHeaderBasketProps) => {
  return isAttention ? (
    <NavigationHeaderAction
      isAttention
      href={href}
      title={title}
      onClick={onClick}
      supportingCopy={supportingCopy}
      ariaLabel={ariaLabel}
      icon={<ThemeIcon icon="navigationHeaderBasket" size={24} />}
    />
  ) : (
    <NavigationHeaderDropdown
      tooltip={title}
      ariaLabel={ariaLabel}
      onClick={onClick}
      trigger={
        <div className="arc-NavigationHeaderBasket-trigger">
          <ThemeIcon icon="navigationHeaderBasket" size={24} />
        </div>
      }
    >
      {popoverText}
    </NavigationHeaderDropdown>
  );
};

export interface NavigationHeaderBasketProps {
  /**
   * Display a red dot next to the basket to alert users.
   */
  isAttention?: boolean;
  /**
   * Text to display in the basket popover.
   */
  popoverText?: string;
  /**
   * Supporting text for the basket tooltip.
   */
  supportingCopy?: string;
  /**
   * Title text for the basket tooltip.
   */
  title?: string;
  /**
   * Accessible label for the basket.
   */
  ariaLabel?: string;
  /**
   * Click handler for the basket.
   */
  onClick?: (e: React.MouseEvent<HTMLButtonElement>) => void;
  /**
   * URL for the basket link.
   */
  href?: string;
}
