import React, { type RefObject, useState, useId, useContext } from "react";

import classNames from "classnames";
import * as RadixSelect from "@radix-ui/react-select";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { useThemeElement, useAriaDescribedby } from "../../hooks";

import { FormControl } from "../FormControl";
import { type FormControlProps } from "../FormControl/FormControl";
import { SurfaceContext } from "../Surface";
import { ThemeIcon } from "../ThemeIcon";

/** Use `Select` to choose from a dropdown list of options. */
export const Select = ({
  ref,
  isRequired,
  isDisabled,
  placeholder,
  label,
  value,
  ariaLabel = label,
  options,
  onOpenChange,
  isDefaultOpen,
  defaultValue,
  errorMessage,
  id,
  size = "m",
  helper,
  hideLabel,
  name,
  width,
  isFluid,
  onBlur,
  onFocus,
  onChange,
  open,
  disclosureTitle,
  disclosureText,
  onClickDisclosure,
  ...props
}: SelectProps) => {
  const defaultId = useId();
  const [themeElement, setThemeElement] = useThemeElement();
  const { surface } = useContext(SurfaceContext);
  const [uncontrolledValue, setUncontrolledValue] = useState<
    string | undefined
  >(defaultValue);

  const { ariaDescribedby } = useAriaDescribedby({
    id,
    errorMessage,
    helper,
    disclosureText,
  });

  const isControlled = typeof value !== "undefined";
  const selectValue = isControlled ? value : uncontrolledValue;

  const onValueChange = (value: string) => {
    onChange && onChange(value);
    setUncontrolledValue(value);
  };

  const getSelectedValueName = (value?: string) => {
    return options.find((option) => option.value === value)?.name;
  };

  const getIconSize = (size: string) => {
    switch (size) {
      case "s":
        return 16;
      case "l":
        return 24;
      default:
        return 20;
    }
  };

  const componentId = id || defaultId;

  return (
    <FormControl
      errorMessage={errorMessage}
      helper={helper}
      htmlFor={componentId}
      label={label}
      hideLabel={hideLabel}
      labelSize={size}
      requirementStatus={isRequired ? "required" : "optional"}
      isDisabled={isDisabled}
      disclosureText={disclosureText}
      disclosureTitle={disclosureTitle}
      onClickDisclosure={onClickDisclosure}
    >
      <RadixSelect.Root
        name={name}
        required={isRequired}
        disabled={isDisabled}
        defaultOpen={isDefaultOpen}
        value={selectValue}
        open={open}
        onOpenChange={onOpenChange}
        onValueChange={(value) => onValueChange(value)}
      >
        <div ref={setThemeElement} className="arc-Select-wrapper">
          <RadixSelect.Trigger
            ref={ref}
            id={componentId}
            name={name}
            onBlur={onBlur}
            onFocus={onFocus}
            aria-label={ariaLabel}
            style={{ width, marginTop: hideLabel ? 0 : undefined }}
            className={classNames("arc-Select-trigger", {
              "arc-Select-trigger--constrained": !isFluid,
              "arc-Select-trigger--onDarkSurface": surface === "dark",
              "arc-Select-trigger--invalid": errorMessage,
              [`arc-Select-trigger--size${size && size.toUpperCase()}`]:
                size && size !== "m",
            })}
            aria-describedby={ariaDescribedby}
            {...filterAttrs(props)}
          >
            <RadixSelect.Value
              className="arc-Select-triggerText"
              placeholder={placeholder}
              aria-label={getSelectedValueName(uncontrolledValue)}
            />

            <RadixSelect.Icon className="arc-Select-triggerIcon">
              <ThemeIcon size={getIconSize(size)} icon="selectTrigger" />
            </RadixSelect.Icon>
          </RadixSelect.Trigger>

          <RadixSelect.Portal container={themeElement}>
            <RadixSelect.Content
              sideOffset={12}
              position="popper"
              className={classNames("arc-Select-content", {
                "arc-Select-content--onDarkSurface": surface === "dark",
              })}
            >
              <RadixSelect.Viewport className="arc-Select-content--scrollable">
                {options.map(({ name, value }, i) => (
                  <RadixSelect.Item
                    className="arc-Select-item"
                    key={`select-item-${i}`}
                    value={value}
                  >
                    <div className="arc-Select-itemTextWrapper">
                      <RadixSelect.ItemText asChild>
                        <span className="arc-Select-itemText">{name}</span>
                      </RadixSelect.ItemText>
                    </div>

                    <RadixSelect.ItemIndicator className="arc-Select-itemSelectIcon">
                      <ThemeIcon size={24} icon="selectIndicator" />
                    </RadixSelect.ItemIndicator>
                  </RadixSelect.Item>
                ))}
              </RadixSelect.Viewport>
            </RadixSelect.Content>
          </RadixSelect.Portal>
        </div>
      </RadixSelect.Root>
    </FormControl>
  );
};

export interface SelectProps extends Omit<
  FormControlProps,
  | "children"
  | "elementType"
  | "htmlFor"
  | "requirementStatus"
  | "helperUnderLabel"
  | "supplementaryInfo"
  | "labelSize"
  | "labelPosition"
> {
  /**
   * Name for the Select.
   */
  name: string;

  /**
   * Label for the Select.
   */
  label: string;

  /**
   * Aria label for the Select.
   */
  ariaLabel?: string;

  /**
   * Placeholder text for the Select.
   */
  placeholder: string;

  /**
   * Options for the Select.
   */
  options: { name: string; value: string }[];

  /**
   * value for the Select. Passing a value makes the Select a controlled component.
   */
  value?: string;

  /**
   * error message for the Select.
   */
  errorMessage?: string;

  /**
   * Default value for the Select.
   */
  defaultValue?: string;

  /**
   * onChange handler for the Select.
   */
  onChange?: (value: string) => void;

  /**
   * onBlur handler for the Select.
   */
  onBlur?: (e: React.FocusEvent<HTMLButtonElement>) => void;

  /**
   * onFocus handler for the Select.
   */
  onFocus?: (e: React.FocusEvent<HTMLButtonElement>) => void;

  /**
   * onOpenChange handler for the Select.
   */
  onOpenChange?: (isOpen: boolean) => void;

  /**
   * The controlled open state of the select. Must be used in conjunction with onOpenChange.
   */
  open?: boolean;

  /**
   * determine the size of the select.
   */
  size?: "l" | "m" | "s";

  /**
   * Sets the Select to 100% width.
   */
  isFluid?: boolean;

  /**
   * Sets the width of the Select.
   */
  width?: string;

  /**
   * Disables the Select.
   */
  isDisabled?: boolean;

  /**
   * Sets the Select to be open by default.
   */
  isDefaultOpen?: boolean;

  /**
   * Sets the Select to be open by default.
   */
  isRequired?: boolean;

  /**
   * Ref to the underlying input element.
   */
  ref?: RefObject<HTMLButtonElement | null>;
}
