import React from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { FormControl, type FormControlProps } from "../FormControl/FormControl";

import { Provider } from "./context";

type EventType = React.ChangeEvent<HTMLInputElement>;

/**
 * Use `RadioCardGroup` to wrap and control `RadioCard` buttons and apply default values
 */
export const RadioCardGroup = ({
  children,
  checkedValue,
  isDisabled = false,
  id,
  errorMessage,
  isRequired = true,
  helper,
  helperUnderLabel = true,
  label,
  labelSize = "l",
  hideLabel = false,
  name,
  onBlur,
  onChange,
  layout = "column",
  isFluid,
  width,
  ...props
}: RadioCardGroupProps) => {
  return (
    <Provider
      value={{
        blurEvent: onBlur!,
        changeEvent: onChange!,
        groupDisabled: isDisabled,
        checkedValue,
        name: name,
      }}
    >
      <div className="arc-RadioCardGroup--form" {...filterAttrs(props)}>
        <FormControl
          elementType="fieldset"
          label={label}
          labelSize={labelSize}
          helper={helper}
          id={id}
          isDisabled={isDisabled}
          requirementStatus={isRequired ? "required" : "optional"}
          helperUnderLabel={helperUnderLabel}
          errorMessage={isRequired && checkedValue === "" ? errorMessage : ""}
          hideLabel={hideLabel}
        >
          <span
            style={{ width: width }}
            className={classNames("arc-RadioCardGroup", {
              "arc-RadioCardGroup--row": layout === "row",
              "arc-RadioCardGroup--isConstrained": !isFluid,
            })}
          >
            {children}
          </span>
        </FormControl>
      </div>
    </Provider>
  );
};

export interface RadioCardGroupProps extends Omit<
  FormControlProps,
  | "children"
  | "elementType"
  | "htmlFor"
  | "requirementStatus"
  | "disclosureText"
  | "disclosureTitle"
  | "onClickDisclosure"
  | "supplementaryInfo"
  | "labelPosition"
> {
  /**
   * Contents of the `RadioCardGroup`. Should only contain `RadioCardGroupCard`
   */
  children: React.ReactNode;
  /**
   * Value of the `RadioCard` that should be checked by default.
   */
  checkedValue: string;
  /**
   * Should all `RadioCard` components be disabled?
   */
  isDisabled?: boolean;
  /**
   * Helper message for the `RadioCardGroup`.
   */
  helper?: string;
  /**
   * ID for the `RadioCardGroup`.
   */
  id: string;
  /**
   * Label for the `RadioCardGroup`.
   */
  label: string;
  /**
   * Label Size for the `RadioCardGroup`.
   */
  labelSize?: "l" | "s";
  /**
   * Name for the `RadioCardGroup`.
   */
  name: string;
  /**
   * Sets the `RadioCardGroup` to 100% width.
   */
  isFluid?: boolean;
  /**
   * Sets the `RadioCardGroup` width.
   */
  width?: number;
  /**
   * Function to call when the `RadioCardGroup` loses focus.
   */
  onBlur?: (e: EventType) => void;
  /**
   * Callback function to update the `RadioCardGroup`'s controlled `checkedValue` prop,
   * for example `e => setCheckedValue(e.target.value)`.
   */
  onChange?: (event: EventType) => void;
  /**
   * Error message for the `RadioCardGroup`.
   */
  errorMessage?: string;
  /**
   * Is `RadioCardGroup` required?
   */
  isRequired?: boolean;
  /**
   * Is `RadioCardGroup` layout orientation?
   */
  layout?: "column" | "row";
}
