import React, { type ReactElement, type ReactNode } from "react";

import { Sub } from "@radix-ui/react-dropdown-menu";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { useMenuContext } from "../MenuContext";

import { type MenuPortalProps } from "../MenuPortal/MenuPortal";

import { type InternalMenuItemMultiLevelTriggerProps } from "./MenuItemMultiLevelTrigger/MenuItemMultiLevelTrigger";

/**
 * Container for multi-level menu content within a dropdown menu.
 */

export const MenuItemMultiLevel = ({
  children,
  ...props
}: MenuItemMultiLevelProps) => {
  const { isMobileMenu } = useMenuContext();

  if (!isMobileMenu) {
    return <Sub {...filterAttrs(props)}>{children}</Sub>;
  }

  const arr = React.Children.toArray(children) as ReactElement[];

  // assuming that there will be two children in menu item multi level
  const trigger =
    arr[0] as ReactElement<InternalMenuItemMultiLevelTriggerProps>;
  const portal = arr[1] as ReactElement<MenuPortalProps>;

  let pairedContent: ReactNode | undefined;

  if (portal && portal.props?.children) {
    const portalChild = React.Children.toArray(
      portal.props.children,
    ) as ReactElement[];
    pairedContent = portalChild.find(
      (el: any) => el?.type?.displayName === "MenuItemMultiLevelContent",
    );
  }

  if (!trigger || !pairedContent) {
    console.warn("MenuItemMultiLevel requires both a Trigger and Portal");
  }

  // Inject content into the trigger, skip rendering the portal in mobile
  return React.cloneElement(trigger, { pairedContent });
};

export interface MenuItemMultiLevelProps {
  /**
   *  The content inside the multi-level menu.
   */
  children: ReactNode;
}
