import React, { useContext } from "react";

import classNames from "classnames";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { SurfaceContext } from "../Surface";

import { type iconNames } from "./icon-names";

/** Use `ThemeIcon` to display an icon that allows switching between theme-specific icons. */
export const ThemeIcon = ({
  size,
  icon,
  color = "auto",
  ...props
}: ThemeIconProps) => {
  const { surface } = useContext(SurfaceContext);

  return (
    <span
      style={{
        height: size,
        width: size,
      }}
      className={classNames("arc-ThemeIcon", `arc-ThemeIcon--${icon}`, {
        "arc-ThemeIcon--onDarkSurface": surface === "dark",
        [suffixModifier("arc-ThemeIcon--color", color)]: color !== "auto",
      })}
      {...filterAttrs(props)}
    />
  );
};

export interface ThemeIconProps {
  /**
   * Size of the Icon, in pixels.
   */
  size?: number;

  /**
   * Icon color
   */
  color?: "auto" | "brand" | "statusRed" | "statusAmber" | "statusGreen";

  /**
   * Icon
   */
  icon?: ThemeIconNames;
}

export type ThemeIconNames = (typeof iconNames)[number];
