import React from "react";

import { Text } from "../../../Text";
import { Rule } from "../../../Rule";
import { VerticalSpace } from "../../../VerticalSpace";
import { getMatchingOption } from "../../utils/getMatchingOption";
import { type ComboBoxOption } from "../../types/combobox-option";
import { ComboBoxListItemInner } from "../ComboBoxListItemInner";

export const ComboBoxCustomOption = ({
  option,
  selectedOptions,
  customOptionSupportingCopy,
  optionsLength,
  isHighlighted,
  isSelected,
}: ComboBoxCustomOptionProps) => {
  const prefixText = getMatchingOption(selectedOptions, option.text)
    ? "Remove"
    : "Add";

  return (
    <>
      <ComboBoxListItemInner
        isHighlighted={isHighlighted}
        isSingleSelected={isSelected}
      >
        <Text>
          {prefixText}: &quot;{option.text}&quot;
        </Text>

        {customOptionSupportingCopy && (
          <div>
            <VerticalSpace size="4" />
            <Text size="xs">{customOptionSupportingCopy}</Text>
          </div>
        )}
      </ComboBoxListItemInner>

      {optionsLength > 1 && (
        <>
          <div className="arc-ComboBoxCustomOption-rule">
            <div className="arc-ComboBoxCustomOption-ruleWrapper">
              <Rule />
            </div>
          </div>
          <VerticalSpace size="8" />
        </>
      )}
    </>
  );
};

interface ComboBoxCustomOptionProps {
  optionsLength: number;
  option: ComboBoxOption;
  isHighlighted: boolean;
  isSelected: boolean;
  customOptionSupportingCopy?: string;
  selectedOptions: ComboBoxOption[];
}
