import React from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { ConditionalWrapper } from "../ConditionalWrapper";

import { VisuallyHidden } from "../VisuallyHidden";

import { type AvatarImage } from "./types/avatar-image";
import { type AvatarSize } from "./types/avatar-size";
import { AvatarContent } from "./components/AvatarContent/AvatarContent";

/** Use `Avatar` to visually represent a user. */
export const Avatar = ({
  img,
  initials,
  href,
  title,
  ariaLabel,
  onClick,
  size = "xl",
  ...props
}: AvatarProps) => {
  const wrapperAttrs: React.HTMLAttributes<HTMLDivElement | HTMLAnchorElement> =
    {
      className: classNames("arc-Avatar", `arc-Avatar--${size}`, {
        "arc-Avatar--img": Boolean(img),
      }),
      ...filterAttrs(props),
    };

  return (
    <ConditionalWrapper
      condition={Boolean(href)}
      wrapper={(children) => (
        <a
          href={href}
          aria-label={ariaLabel}
          onClick={onClick}
          title={title}
          {...wrapperAttrs}
        >
          {children}
        </a>
      )}
      fallback={(children) => (
        <>
          <div {...wrapperAttrs}>{children}</div>
          {ariaLabel && <VisuallyHidden>{ariaLabel}</VisuallyHidden>}
        </>
      )}
    >
      <AvatarContent size={size} img={img} initials={initials} />
    </ConditionalWrapper>
  );
};

export interface AvatarProps {
  /**
   * Initials to display in the avatar (up to 3 characters).
   */
  initials?: string;
  /**
   * URL to link to when the avatar is clicked.
   */
  href?: string;
  /**
   * Title attribute for the avatar link.
   */
  title?: string;
  /**
   * Accessible label for the avatar.
   */
  ariaLabel?: string;
  /**
   * Click handler for the avatar link.
   */
  onClick?: (e: React.MouseEvent<HTMLAnchorElement, MouseEvent>) => void;
  /**
   * Image to display in the avatar.
   */
  img?: AvatarImage;
  /**
   * Size of the avatar.
   */
  size?: AvatarSize;
}
