import getMonth from "date-fns/getMonth";
import getYear from "date-fns/getYear";
import getAllDaysInMonth from "date-fns/getDaysInMonth";

import { dateWithoutTime } from "./date-without-time";

export const getDatesInMonth = (date: Date) => {
  const dateYear = getYear(date);
  const dateMonth = getMonth(date);

  return Array.from({ length: getAllDaysInMonth(date) }, (_, i) =>
    dateWithoutTime(new Date(dateYear, dateMonth, i + 1)),
  );
};
