import React, { type ReactNode, type Ref } from "react";

import classNames from "classnames";

import { Icon } from "../../../Icon";
import { VisuallyHidden } from "../../../VisuallyHidden";
import { Tooltip } from "../../../Tooltip";

import { DELAY_DURATION } from "../../constants/tooltip";

import { NavigationHeaderButton } from "../NavigationHeaderButton";

export const NavigationHeaderAction = ({
  ariaLabel,
  icon,
  onClick,
  title,
  supportingCopy,
  ref,
  href,
  isAttention = false,
}: NavigationHeaderActionProps) => {
  return (
    <div
      className={classNames("arc-NavigationHeaderAction", {
        "arc-NavigationHeaderAction--attention": isAttention,
      })}
    >
      <Tooltip
        asChild
        title={title}
        alignContent="center"
        supportingCopy={supportingCopy}
        delayDuration={DELAY_DURATION}
        side="bottom"
      >
        <NavigationHeaderButton
          href={href}
          ref={ref}
          isPadded={false}
          onClick={onClick}
        >
          <div className="arc-NavigationHeaderAction-content">
            {typeof icon === "string" ? (
              <Icon aria-hidden icon={icon} size={24} />
            ) : (
              icon
            )}
            <VisuallyHidden>{ariaLabel}</VisuallyHidden>
          </div>
        </NavigationHeaderButton>
      </Tooltip>
    </div>
  );
};

export interface NavigationHeaderActionProps {
  /**
   * Ref to the underlying button element.
   */
  ref?: Ref<HTMLButtonElement>;
  /**
   * Icon URL for the action.
   */
  icon: string | ReactNode;

  /**
   * Display a red dot next to the action to alert users.
   */
  isAttention?: boolean;

  /**
   * Label for action that is presented to screenreader.
   */
  ariaLabel: string;

  /**
   * Title for action that is presented in a tooltip.
   */
  title: string;

  /**
   * Supporting text for action that is presented in a tooltip.
   */
  supportingCopy?: string;

  /**
   * Href for the action.
   */
  href?: string;

  /**
   * Click handler for the action.
   */
  onClick?: (e: React.MouseEvent<HTMLButtonElement, MouseEvent>) => void;
}
