import React from "react";

import { Root } from "@radix-ui/react-dropdown-menu";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { MenuProvider } from "./MenuProvider";

/**
 * Use 'Menu' to display a list of selectable options, e.g. suggestions, presets or autocomplete results.
 */
export const Menu = ({
  defaultOpen,
  open,
  onOpenChange,
  modal = true,
  isMobileMenu = false,
  children,
  defaultWidth,
  ...props
}: MenuProps) => {
  return (
    <Root
      defaultOpen={defaultOpen}
      open={open}
      onOpenChange={onOpenChange}
      modal={modal}
      {...filterAttrs(props)}
    >
      <MenuProvider isMobileMenu={isMobileMenu} defaultWidth={defaultWidth}>
        {children}
      </MenuProvider>
    </Root>
  );
};

export interface MenuProps {
  /**
   * The content of the menu
   */
  children: React.ReactNode;

  /**
   * Whether the menu is open by default
   */
  defaultOpen?: boolean;

  /**
   * Controls whether the menu is open
   */
  open?: boolean;

  /**
   * Callback fired when the open state changes
   */
  onOpenChange?: (open: boolean) => void;

  /**
   * Whether the menu should behave like a modal, preventing interaction with elements outside
   */
  modal?: boolean;

  /**
   * Determine if the menu will act in a mobile state
   */
  isMobileMenu?: boolean;

  /**
   * Unified width applied to all MenuContent unless overridden.
   */
  defaultWidth?: string | number;
}
