import React from "react";

import classNames from "classnames";

import { Content } from "@radix-ui/react-dropdown-menu";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { BtIconChevronLeftMid } from "@arc-ui/icons";

import { useMenuContext } from "../MenuContext";

import { MenuItem } from "../MenuItem";

import { MenuSeparator } from "../MenuSeparator";

/**
 * The component that pops out when the dropdown menu is open.
 */
export const MenuContent = ({
  ref,
  children,
  width,
  minWidth,
  maxWidth,
  align = "start",
  alignOffset,
  side,
  initalTitle,
  isFluidToViewport,
  ...props
}: MenuContentProps) => {
  const { isMobileMenu, stack, goBack, defaultWidth, reset } = useMenuContext();

  if (!isMobileMenu) {
    return (
      <Content
        ref={ref}
        style={{ width: width ?? defaultWidth, minWidth, maxWidth }}
        className="arc-MenuContent"
        sideOffset={12}
        loop={true}
        collisionPadding={0}
        forceMount={true}
        align={align}
        alignOffset={alignOffset}
        side={side}
        {...filterAttrs(props)}
      >
        <div className="arc-MenuContent-content">{children}</div>
      </Content>
    );
  }

  const active = stack.length > 0 ? stack[stack.length - 1].content : children;

  const prevTitle: string =
    stack.length > 1 ? stack[stack.length - 2].title : initalTitle || "Back";

  return (
    <Content
      style={{ width: width ?? defaultWidth, minWidth, maxWidth }}
      sideOffset={12}
      collisionPadding={12}
      className={classNames("arc-MenuContent arc-MenuContent--mobile", {
        "arc-MenuContent--isFluid":
          isFluidToViewport || defaultWidth === "fluid",
      })}
      side="bottom"
      avoidCollisions
      onKeyDown={(e) => {
        if (stack.length > 0) {
          if (e.key === "ArrowLeft") {
            goBack(true);
          }
        }
      }}
      forceMount
      onPointerDownOutside={reset}
      onEscapeKeyDown={reset}
      {...filterAttrs(props)}
    >
      {stack.length > 0 && (
        <>
          <MenuItem onClick={goBack} leadingIcon={BtIconChevronLeftMid}>
            {prevTitle}
          </MenuItem>
          <MenuSeparator />
        </>
      )}
      <div
        key={stack.length}
        className="arc-MenuContent-content arc-MenuContent-fade"
      >
        {active}
      </div>
    </Content>
  );
};

export interface MenuContentProps {
  /**
   * Ref to the underlying div element
   */
  ref?: React.Ref<HTMLDivElement>;
  /**
   * The content inside the menu, typically `MenuItem`, `MenuGroup`, and other menu elements.
   */
  children: React.ReactNode;

  /**
   * The width of the menu content. Can be any valid CSS width value. This is `fit-content` by default and needs to be set to `auto` to use other properties.
   */
  width?: string | number | "auto";

  /**
   * The minimum width of the menu content.
   */
  minWidth?: string | number;

  /**
   * The maximum width of the menu content.
   */
  maxWidth?: string | number;

  /**
   * Horizontal alignment of the dropdown relative to the trigger.
   */
  align?: "start" | "center" | "end";

  /**
   * Pixel offset for horizontal alignment.
   */
  alignOffset?: number;

  /**
   * The side of the trigger to display the menu.
   */
  side?: "top" | "right" | "bottom" | "left";

  /**
   * Provide an inital title for the menu. This will then be used as a back button when the menu is 1 level deep.
   */
  initalTitle?: string;

  /**
   * Set to true if you want the menu to fill the viewport.
   */
  isFluidToViewport?: boolean;
}
