import React, { useContext } from "react";

import classNames from "classnames";

import { Trigger } from "@radix-ui/react-dropdown-menu";

import { SurfaceContext } from "../../Surface";

/**
 * The element that toggles the menu.
 */
export const MenuTrigger = ({
  children,
  asChild,
  ...props
}: MenuTriggerProps) => {
  const { surface } = useContext(SurfaceContext);

  return (
    <Trigger
      asChild={asChild}
      className={classNames("arc-MenuTrigger", {
        "arc-MenuTrigger--onDarkSurface": surface === "dark",
      })}
      {...props} // props not filtered for radix asChild behaviour
    >
      {children}
    </Trigger>
  );
};

export interface MenuTriggerProps {
  /**
   * The element that triggers the menu when clicked or interacted with.
   */
  children: React.ReactNode;
  /**
   * Change the default rendered element for the one passed as a child, merging their props and behavior.
   */
  asChild?: boolean;
}
