import React, { useEffect, useRef, useState } from "react";

import * as Popover from "@radix-ui/react-popover";

import format from "date-fns/format";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import {
  TextInputWithPlaceHolder,
  type TextInputWithPlaceholderProps,
} from "../../TextInput/TextInput";

import { InputIcon } from "../../TextInput/components/InputIcon";

import {
  type ArcCalendarRangeSelection,
  Calendar,
  type CalendarProps,
} from "../../Calendar";

import { useThemeElement } from "../../../hooks";

import {
  isRangeValid,
  convertRangeStringToDates,
  formatDate,
} from "../helpers";
import { DATE_FORMAT } from "../constants";

import { validateRangeOnBlur } from "../helpers/validate-range-on-blur";
import { convertRangeStringToDateTuple } from "../helpers/convert-range-string-to-date-tuple";

const lowerCaseDateFormat = DATE_FORMAT.toLowerCase();

export const DatePickerRange = ({
  inputStart,
  inputEnd,
  type = "month",
  minDate,
  maxDate,
  disabledDates,
  onRangeSelect,
  isFluid = false,
}: DatePickerRangeProps) => {
  // startInput States
  const [startAriaLabel, setStartAriaLabel] = useState("Choose start date");
  const startButtonRef = useRef<HTMLButtonElement | null>(null);
  const startInputRef = useRef<HTMLInputElement | null>(null);
  const [startValue, setStartValue] = useState<string>(inputStart.value ?? "");

  // endInput States
  const [endAriaLabel, setEndAriaLabel] = useState("Choose end date");
  const [endValue, setEndValue] = useState<string>(inputEnd.value ?? "");
  const endButtonRef = useRef<HTMLButtonElement | null>(null);
  const endInputRef = useRef<HTMLInputElement | null>(null);

  const previousValidValue = useRef<string>("");
  const [themeElement, setThemeElement] = useThemeElement();
  const [showCalendar, setShowCalendar] = useState<boolean>(false);
  const [activeInput, setActiveInput] = useState<"start" | "end" | null>(null);

  const getIsRequired = (input: SharedInputProps) => input.isRequired ?? true;
  const getLabel = (input: SharedInputProps, type: "start" | "end") =>
    input.label ?? `Select ${type === "start" ? "a" : "an"} ${type} date`;

  // sync external props with internal value (not typing)
  useEffect(() => {
    if (inputStart.value !== undefined && inputStart.value !== startValue) {
      setStartValue(inputStart.value);
    }

    if (inputEnd.value !== undefined && inputEnd.value !== endValue) {
      setEndValue(inputEnd.value);
    }
  }, [inputStart.value, inputEnd.value, endValue, startValue]);

  const handleIconClick = ({
    ref,
    isDisabled,
    isReadOnly,
    input,
  }: {
    ref: HTMLInputElement | null;
    isDisabled?: boolean;
    isReadOnly?: boolean;
    input: "start" | "end";
  }) => {
    if (
      ref &&
      !ref.contains(document.activeElement) &&
      !isDisabled &&
      !isReadOnly
    ) {
      setActiveInput(input);
      setShowCalendar(true);
    }
  };

  const handleRangeSelect = (rangeSelection: ArcCalendarRangeSelection) => {
    const { start, end, isSelectionComplete } = rangeSelection;

    const formattedStart = format(start, "dd/MM/yyyy");
    const formattedEnd = end ? format(end, "dd/MM/yyyy") : "";

    onRangeSelect?.({
      ...rangeSelection,
      formattedStart,
      formattedEnd,
    });

    if (isSelectionComplete) {
      const fullRange = `${formattedStart} - ${formattedEnd}`;
      previousValidValue.current = fullRange;
      setShowCalendar(false);
    }
  };

  const handleCalendarClose = () => {
    if (document.activeElement?.tagName === "BODY") {
      startButtonRef.current?.focus();
      endButtonRef.current?.focus();
    }
  };

  const handleIconFocus = ({ input }: { input: "start" | "end" }) => {
    if (isRangeValid(`${startValue} - ${endValue}`)) {
      const [start, end] = convertRangeStringToDates(
        `${startValue} - ${endValue}`,
      );

      const label = `Change dates, currently selected dates are ${format(
        start,
        "EEEE do MMMM, yyyy",
      )} to ${format(end, "EEEE do MMMM, yyyy")}`;

      input === "start" ? setStartAriaLabel(label) : setEndAriaLabel(label);
      return;
    }
  };

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement>,
    input: "start" | "end",
  ) => {
    if (input === "start") {
      inputStart.onChange && inputStart.onChange(e);
      setStartValue(e.target.value);
      setActiveInput("start");
    }

    if (input === "end") {
      inputEnd.onChange && inputEnd.onChange(e);
      setEndValue(e.target.value);
      setActiveInput("end");
    }
  };

  const handleBlur = (
    e: React.FocusEvent<HTMLInputElement>,
    input: "start" | "end",
  ) => {
    const value = `${startValue} - ${endValue}`;

    if (input === "start") {
      inputStart.onBlur && inputStart.onBlur(e);
    }

    if (input === "end") {
      inputEnd.onBlur && inputEnd.onBlur(e);
    }

    validateRangeOnBlur({
      value,
      minDate,
      maxDate,
      disabledDates,
      previousValidValue: previousValidValue.current,
      dispatchChangeEvent: (e, corrected) => {
        const [start, end] = convertRangeStringToDates(corrected);
        inputStart.onChange?.({
          ...e,
          target: { ...e.target, value: formatDate(start) },
        });
        inputEnd.onChange?.({
          ...e,
          target: { ...e.target, value: formatDate(end) },
        });

        previousValidValue.current = corrected;
      },
      blurEvent: e,
    });
  };

  const handleCalendarOpenChange = (isOpen: boolean) => {
    if (document.activeElement) setShowCalendar(isOpen);
  };

  const handleAutoFocus = (e: Event) => {
    e.preventDefault();
  };

  const setStartInputRef = (el: HTMLInputElement | null) => {
    startInputRef.current = el;
  };

  const setEndInputRef = (el: HTMLInputElement | null) => {
    endInputRef.current = el;
  };

  const onCancelClick = () => {
    setShowCalendar(false);
  };

  const getCalendarRange = () => {
    const [start, end] = convertRangeStringToDateTuple(
      `${startValue} - ${endValue}`,
    );

    // when inital or one date is set - allow user to pick start / end independently
    if (start && end) {
      if (activeInput === "start") {
        return end ? [end] : [];
      }

      if (activeInput === "end") {
        return start ? [start] : [];
      }
    }

    // removes all non date obj
    return [start, end].filter((d) => d instanceof Date);
  };

  return (
    <Popover.Root open={showCalendar} onOpenChange={handleCalendarOpenChange}>
      <div className="arc-DatePickerRange" ref={setThemeElement}>
        <div
          className={classNames("arc-DatePickerRange-input", {
            "arc-DatePickerRange-input--isFluid": isFluid,
          })}
        >
          <TextInputWithPlaceHolder
            ref={setStartInputRef}
            type="text"
            trailingSlot={
              <InputIcon
                themeIcon="datePickerCalendar"
                isButton={{
                  ref: startButtonRef,
                  onClick: () =>
                    handleIconClick({
                      ref: startInputRef.current,
                      isDisabled: inputStart.isDisabled,
                      isReadOnly: inputStart.isReadOnly,
                      input: "start",
                    }),
                  onFocus: () => handleIconFocus({ input: "start" }),
                  label: startAriaLabel,
                }}
              />
            }
            maxLength={23}
            onBlur={(e) => handleBlur(e, "start")}
            errorMessage={inputStart.errorMessage}
            helper={inputStart.helper}
            id={inputStart.id}
            isDisabled={inputStart.isDisabled}
            isReadOnly={inputStart.isReadOnly}
            isRequired={getIsRequired(inputStart)}
            label={getLabel(inputStart, "start")}
            hideLabel={inputStart.hideLabel}
            name={inputStart.name}
            onClickDisclosure={inputStart.onClickDisclosure}
            disclosureTitle={inputStart.disclosureTitle}
            disclosureText={inputStart.disclosureText}
            placeholder={lowerCaseDateFormat}
            value={startValue}
            onChange={(e) => handleChange(e, "start")}
            {...filterAttrs(inputStart)}
          />
          {activeInput === "start" && <Popover.Anchor />}
        </div>
        <div
          className={classNames("arc-DatePickerRange-input", {
            "arc-DatePickerRange-input--isFluid": isFluid,
          })}
        >
          <TextInputWithPlaceHolder
            ref={setEndInputRef}
            type="text"
            trailingSlot={
              <InputIcon
                themeIcon="datePickerCalendar"
                isButton={{
                  ref: endButtonRef,
                  onClick: () =>
                    handleIconClick({
                      ref: endInputRef.current,
                      isDisabled: inputEnd.isDisabled,
                      isReadOnly: inputEnd.isReadOnly,
                      input: "end",
                    }),
                  onFocus: () => handleIconFocus({ input: "end" }),
                  label: endAriaLabel,
                }}
              />
            }
            maxLength={23}
            onBlur={(e) => handleBlur(e, "end")}
            errorMessage={inputEnd.errorMessage}
            helper={inputEnd.helper}
            id={inputEnd.id}
            isDisabled={inputEnd.isDisabled}
            isReadOnly={inputEnd.isReadOnly}
            isRequired={getIsRequired(inputEnd)}
            label={getLabel(inputEnd, "end")}
            hideLabel={inputStart.hideLabel}
            name={inputEnd.name}
            onClickDisclosure={inputEnd.onClickDisclosure}
            disclosureTitle={inputEnd.disclosureTitle}
            disclosureText={inputEnd.disclosureText}
            placeholder={lowerCaseDateFormat}
            value={endValue}
            onChange={(e) => handleChange(e, "end")}
            {...filterAttrs(inputEnd)}
          />
          {activeInput === "end" && <Popover.Anchor />}
        </div>
      </div>

      <Popover.Portal container={themeElement}>
        <Popover.Content
          align="start"
          aria-modal="true"
          aria-label="Choose Date"
          className="arc-DatePicker-modal"
          onOpenAutoFocus={handleAutoFocus}
          onCloseAutoFocus={handleCalendarClose}
          sideOffset={12}
        >
          <Calendar
            autoFocusOnMount
            type={type}
            onCancelClick={onCancelClick}
            selectionType="range"
            selectedRange={getCalendarRange()}
            disabledDates={disabledDates}
            minDate={minDate}
            maxDate={maxDate}
            onRangeSelect={handleRangeSelect}
          />
        </Popover.Content>
      </Popover.Portal>
    </Popover.Root>
  );
};

interface DatePickerRangeSelection extends ArcCalendarRangeSelection {
  formattedStart: string;
  formattedEnd: string;
}

type SharedInputProps = Omit<
  TextInputWithPlaceholderProps,
  | "defaultValue"
  | "inputMode"
  | "minLength"
  | "maxLength"
  | "pattern"
  | "type"
  | "showPassword"
  | "placeholder"
  | "trailingInputIcon"
  | "prefix"
  | "suffix"
  | "label"
> &
  Partial<Pick<TextInputWithPlaceholderProps, "label">>;

export interface DatePickerRangeProps extends Pick<
  CalendarProps,
  "type" | "minDate" | "maxDate" | "disabledDates"
> {
  /**
   * Configuration for the start date input.
   */
  inputStart: SharedInputProps;
  /**
   * Configuration for the end date input.
   */
  inputEnd: SharedInputProps;
  /**
   * Callback when a date range is selected.
   */
  onRangeSelect?: (value: DatePickerRangeSelection) => void;

  /**
   * Enable to make the `DatePickerRange` fill its parent container
   */
  isFluid?: boolean;
}
