import React, { useId, type Ref } from "react";

import classNames from "classnames";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";

import { ThemeIcon } from "../../../ThemeIcon";
import { type InputSize } from "../../types";
import { type ComboBoxOption } from "../../types/combobox-option";

export const ComboBoxTags = ({
  ref,
  selectedOptions,
  showAllTags,
  isDisabled,
  isError,
  isDarkSurface,
  visibleTagCount,
  inputSize,
  isReadOnly,
  onTagBlur,
  onTagClick,
  onTagKeyDown,
  onShowAllTagsClick,
}: ComboBoxTagsProps) => {
  const id = useId();
  const tagLimit = !showAllTags ? visibleTagCount : undefined;
  const showHiddenTagCount =
    !showAllTags && selectedOptions.length > visibleTagCount;

  return (
    <div
      ref={ref}
      className={classNames(
        "arc-ComboBoxTags",
        suffixModifier("arc-ComboBoxTags--size", inputSize),
        {
          "arc-ComboBoxTags--disabled": isDisabled,
          "arc-ComboBoxTags--readOnly": isReadOnly,
          "arc-ComboBoxTags--invalid": isError,
          "arc-ComboBoxTags--onDarkSurface": isDarkSurface,
        },
      )}
    >
      {selectedOptions.slice(0, tagLimit).map((option, i) => (
        <button
          type="button"
          disabled={isDisabled}
          key={`${id}-selectedOption-${i}`}
          className="arc-ComboBoxTags-tag"
          aria-label={`${option.text}, press space or enter to remove`}
          onBlur={onTagBlur}
          onMouseDown={onTagClick(option)}
          onKeyDown={onTagKeyDown(option)}
        >
          <div aria-hidden className="arc-ComboBoxTags-tagInner">
            <span>{option.text}</span>
            <div className="arc-ComboBoxTags-tagIcon">
              <ThemeIcon icon="comboboxTagRemove" size={20} />
            </div>
          </div>
        </button>
      ))}
      {showHiddenTagCount && (
        <button
          type="button"
          disabled={isDisabled}
          onClick={onShowAllTagsClick}
          className="arc-ComboBoxTags-showHiddenButton"
          aria-label="Show all selected options"
        >
          <span className="arc-ComboBoxTags-showHiddenButtonContent">
            +&nbsp;{selectedOptions.length - visibleTagCount}&nbsp;more
          </span>
        </button>
      )}
    </div>
  );
};

interface ComboBoxTagsProps {
  ref?: Ref<HTMLDivElement>;
  showAllTags: boolean;
  isDisabled: boolean;
  isDarkSurface: boolean;
  isError: boolean;
  isReadOnly: boolean;
  inputSize: InputSize;
  selectedOptions: ComboBoxOption[];
  visibleTagCount: number;
  onTagBlur: (e: React.FocusEvent<HTMLButtonElement>) => void;
  onShowAllTagsClick: () => void;
  onTagClick: (
    option: ComboBoxOption,
  ) => (e: React.MouseEvent<HTMLButtonElement>) => void;
  onTagKeyDown: (
    option: ComboBoxOption,
  ) => (e: React.KeyboardEvent<HTMLButtonElement>) => void;
}
