import React, { useId, type Ref } from "react";

import classNames from "classnames";

import { ThemeIcon } from "../../ThemeIcon";

import { useSplitButton } from "../SplitButtonContext";

export const SplitButtonMenu = ({
  isMenuOpen,
  ariaLabel,
  ref,
  ...props
}: SplitButtonMenuProps) => {
  const { buttonStyle, size, isLoading, surface } = useSplitButton();
  const uniqueId = useId();

  const iconSize = {
    l: 36,
    m: 32,
    s: 24,
  };

  return (
    <button
      ref={ref}
      disabled={isLoading}
      aria-haspopup="true"
      aria-expanded={isMenuOpen ? "true" : "false"}
      aria-label={ariaLabel}
      id={`SplitButtonMenuMenuTrigger-${uniqueId}`}
      {...props} // props not filtered for radix asChild behaviour
      className={classNames(
        "arc-SplitButtonMenu",
        "arc-SplitButtonMenu--button",
        `arc-SplitButtonMenu--${size}`,
        `arc-SplitButtonMenu--${buttonStyle}`,
        {
          "arc-SplitButtonMenu--isOpen": isMenuOpen,
          "arc-SplitButtonMenu--isLoading": isLoading,
          "arc-SplitButtonMenu--onDarkSurface": surface === "dark",
        },
      )}
    >
      <ThemeIcon
        icon={isMenuOpen ? "splitButtonChevronUp" : "splitButtonChevronDown"}
        size={iconSize[size || "m"]}
      />
    </button>
  );
};

export interface SplitButtonMenuProps {
  /**
   * Optional property to provide component Ref
   */
  ref?: Ref<HTMLButtonElement>;
  /**
   * Whether the menu is currently open.
   */
  isMenuOpen: boolean;
  /**
   * Accessible label for screen readers describing the `SplitButtonMenu` trigger.
   */
  ariaLabel?: string;
}
