import React, {
  type ReactNode,
  useContext,
  useEffect,
  useRef,
  useState,
} from "react";

import classNames from "classnames";

import { ArcSizeBreakpointsL } from "@arc-ui/tokens-arc";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";
import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { BtIconChevronRight2Px } from "@arc-ui/icons/BtIconChevronRight2Px";

import { handleLinkClick } from "../../../../helpers/handle-link-click";
import { useMediaQuery } from "../../../../hooks/public/use-media-query";
import { Text } from "../../../Text";

import { NavItemContext } from "../SiteHeaderV2NavItemWithSubNav/SiteHeaderV2NavItemWithSubNav";
import {
  SiteHeaderV2Panel,
  SiteHeaderV2ViewAll,
} from "../SiteHeaderV2Panel/SiteHeaderV2Panel";

import { Icon } from "../../../Icon";

export const SiteHeaderV2SubNavItem = ({
  children,
  isDefaultItem = false,
  href,
  onClick,
  offsetXL,
  subTitle,
  title,
  viewAllTitle,
  icon,
  ...props
}: SiteHeaderV2SubNavItemProps) => {
  const { navItem } = useContext(NavItemContext);
  const subNavItem = useRef<HTMLLIElement | null>(null);
  const [panelOpen, setPanelOpen] = useState(false);
  const isMinWidthArcBreakpointL = useMediaQuery(
    `(min-width: ${ArcSizeBreakpointsL})`,
  );

  useEffect(() => {
    if (isDefaultItem && isMinWidthArcBreakpointL) {
      setPanelOpen(true);
    } else {
      setPanelOpen(false);
    }
  }, [isDefaultItem, isMinWidthArcBreakpointL]);

  const linkTitle = (
    <>
      <span className="arc-SiteHeaderV2SubNavItem-linkTitle">{title}</span>
      {children && panelOpen && (
        <span className="arc-SiteHeaderV2SubNavItem-linkIcon">
          <Icon icon={BtIconChevronRight2Px} />
        </span>
      )}
      {children && !isMinWidthArcBreakpointL && (
        <span className="arc-SiteHeaderV2SubNavItem-linkIcon">
          <Icon icon={BtIconChevronRight2Px} />
        </span>
      )}
      {subTitle ? (
        <span className="arc-SiteHeaderV2SubNavItem-linkSubTitle">
          {subTitle}
        </span>
      ) : null}
    </>
  );

  return (
    <li
      className={classNames({
        [`arc-SiteHeaderV2SubNavItem`]: true,
        [`arc-SiteHeaderV2SubNavItem--linkSelected`]: children && panelOpen,
        [`arc-SiteHeaderV2SubNavItem--linkNotSelected`]: children && !panelOpen,
        [suffixModifier(
          "arc-SiteHeaderV2SubNavItem--offsetXL",
          offsetXL || "",
        )]: offsetXL,
      })}
      ref={subNavItem}
      {...filterAttrs(props)}
      data-default-item={isDefaultItem || null}
    >
      {!children ? (
        href ? (
          <a
            className="arc-SiteHeaderV2SubNavItem-link"
            onClick={handleLinkClick({ handler: onClick })}
            href={href}
          >
            {linkTitle}
          </a>
        ) : null
      ) : (
        <>
          <button
            aria-expanded={panelOpen}
            className={classNames({
              [`arc-SiteHeaderV2SubNavItem-link`]: true,
              [`arc-SiteHeaderV2SubNavItem-link--itemHasChildren`]: children,
            })}
            onClick={(e) => {
              e.preventDefault();
              setPanelOpen(true);
            }}
          >
            <div className="arc-SiteHeaderV2SubNavItem-linkSlot">
              {icon && isMinWidthArcBreakpointL && (
                <div className="arc-SiteHeaderV2SubNavItem-linkSlotIcon">
                  <Icon icon={icon} size={48} />
                </div>
              )}

              <span
                data-cy="linkTitle"
                className="arc-SiteHeaderV2SubNavItem-linkSlotTitle"
              >
                {linkTitle}
              </span>
            </div>
          </button>
          <SiteHeaderV2Panel
            navItemRef={navItem}
            open={panelOpen}
            setOpen={setPanelOpen}
            subNavItemRef={subNavItem}
            setOpenPanelOnFirstClick={() => {}}
            subNavLink="arc-SiteHeaderV2SubNavItem-link"
            title={
              <span>
                {title}
                {subTitle && (
                  <Text size="xs" tone="supporting">
                    {subTitle}
                  </Text>
                )}
              </span>
            }
            viewAll={
              href ? (
                <SiteHeaderV2ViewAll
                  href={href}
                  onClick={onClick}
                  title={viewAllTitle || `See all ${title}`}
                  buttonStyle="secondary"
                />
              ) : undefined
            }
            isNavItem={false}
          >
            {children}
          </SiteHeaderV2Panel>
        </>
      )}
    </li>
  );
};

export interface SiteHeaderV2SubNavItemProps {
  /**
   * Contents of the SubNavItem. Must be SiteHeaderV2ItemGroup or
   * SiteHeaderV2Column components.
   */
  children?: ReactNode;

  /**
   * Should the SubNavItem be the default open item in a
   * SiteHeaderV2NavItemWithSubNav? If not specified, the default open item will
   * be set automatically.
   */
  isDefaultItem?: boolean;

  /**
   * Optionally shift the SubNavItem-link upwards (in "desktop" viewports only)
   * to close off any empty space between items due to content size.
   */
  offsetXL?: "24" | "48";

  /**
   * A URL to link to when the SubNavItem is clicked or touched. Only applies if
   * `children` are not present.
   */
  href?: string;

  /**
   * Optional subtitle text for the SubNavItem.
   */
  subTitle?: string;

  /**
   * Title text for the SubNavItem.
   */
  title: string;

  /**
   * Text to display in top-level link inside the SubNavItem panel. Only
   * applies if both `children` are present and `href` is true. If not
   * provided, top-level link text will be automatically generated from `title`.
   */
  viewAllTitle?: string;

  /**
   * Optional icon to display with the SubNavItem.
   */
  icon?: string;

  /**
   * On click handler.
   */
  onClick?: () => void;
}
