import React from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";
import { getVersionClassName } from "@arc-ui/helpers/get-version-classname";

/**
 * Use `Theme` component to apply a specific theme to its children.
 */
export const Theme = ({
  theme = "bt-enterprise",
  resetCssStyles = true,
  children,
  ...props
}: ThemeProps) => {
  const iconClass: Record<(typeof themes)[number], string> = {
    "bt-business": "arc-ds-sys-icons--bt",
    "bt-enterprise": "arc-ds-sys-icons--bt",
    ee: "arc-ds-sys-icons--ee",
  };

  return (
    <div className={getVersionClassName()}>
      <div
        data-theme={theme}
        className={classNames(
          `arc arc-ds-sys-theme arc-ds-sys-theme--${theme}`,
          iconClass[theme],
          {
            "arc--reset": resetCssStyles,
          },
        )}
        {...filterAttrs(props)}
      >
        {children}
      </div>
    </div>
  );
};

export const themes = ["bt-enterprise", "bt-business", "ee"] as const;

export type ThemeType = "bt-enterprise" | "bt-business" | "ee";

export interface ThemeProps {
  /**
   * Theme to apply to all children. Should be one of "bt-enterprise"
   */
  theme?: ThemeType;

  /**
   * Applies a style reset to everything within theme component, defaults to true.
   */
  resetCssStyles?: boolean;

  /**
   * Content to display inside Theme.
   */
  children: any;
}
