import React, { type Ref, useContext } from "react";

import classNames from "classnames";
import camelcase from "camelcase";

import { BtIconArrowAltRight } from "@arc-ui/icons/BtIconArrowAltRight";
import { BtIconArrowAltDown } from "@arc-ui/icons/BtIconArrowAltDown";
import { ArcIconPlay } from "@arc-ui/icons/ArcIconPlay";
import { ArcIconWarn } from "@arc-ui/icons/ArcIconWarn";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { Icon } from "../Icon";
import { SurfaceContext } from "../Surface";
import { Spinner } from "../Spinner";

export type ElementUnion = HTMLButtonElement | HTMLAnchorElement;
export type ButtonRef = Ref<ElementUnion> | null;
type AnchorElProps = React.AnchorHTMLAttributes<HTMLAnchorElement>;
type ButtonElProps = React.ButtonHTMLAttributes<HTMLButtonElement>;
type CommonElProps = AnchorElProps & ButtonElProps & { ref?: ButtonRef | null };

/**
 * Use `HeroButton` as the most prominent call-to-action. It should be used sparingly at the most important parts of a user journey only.
 */
export const HeroButton = ({
  label,
  buttonStyle = "primary",
  icon,
  ariaLabel,
  isLoading = false,
  onClick,
  href,
  id,
  rel,
  target,
  type,
  form,
  ref,
  ...props
}: HeroButtonProps) => {
  const { surface } = useContext(SurfaceContext);

  const HeroButtonClasses = classNames(
    "arc-HeroButton",
    [`arc-HeroButton--${camelcase(buttonStyle)}`],
    {
      "arc-HeroButton--onDarkSurface": surface === "dark",
      "arc-HeroButton--emptyLabel": !label,
      "arc-HeroButton--isLoading": isLoading,
      "arc-HeroButton--withIcon": icon,
      "arc-HeroButton--hasGradient": buttonStyle.includes("-gradient"),
    },
  );

  const HeroButtonIcons: { [key: string]: string } = {
    "arrow-right": BtIconArrowAltRight,
    "arrow-down": BtIconArrowAltDown,
    play: ArcIconPlay,
    warning: ArcIconWarn,
  };

  const commonProps: CommonElProps = {
    id,
    onClick,
    ref,
    ...filterAttrs(props),
  };

  if (href && !isLoading) {
    return (
      <a
        {...(commonProps as AnchorElProps)}
        className={HeroButtonClasses}
        href={href}
        rel={rel}
        aria-label={ariaLabel}
        target={target}
      >
        <span className={classNames("arc-HeroButton-inner")}>
          {label && <span className="arc-HeroButton-label">{label}</span>}
          {isLoading && (
            <span className="arc-HeroButton-icon">
              <Spinner size="xxl" />
            </span>
          )}
          {icon && !isLoading && (
            <span className="arc-HeroButton-icon">
              <Icon
                testId="hero-button-icon"
                size={48}
                icon={
                  buttonStyle === "warning"
                    ? HeroButtonIcons["warning"]
                    : HeroButtonIcons[icon]
                }
              />
            </span>
          )}
        </span>
      </a>
    );
  }
  return (
    <button
      {...(commonProps as ButtonElProps)}
      className={HeroButtonClasses}
      aria-label={ariaLabel}
      disabled={isLoading}
      type={type}
      form={form}
    >
      <span className={classNames("arc-HeroButton-inner")}>
        {label && <span className="arc-HeroButton-label">{label}</span>}
        {icon && !isLoading && (
          <span className="arc-HeroButton-icon">
            <Icon
              testId="hero-button-icon"
              size={48}
              icon={
                buttonStyle === "warning"
                  ? HeroButtonIcons["warning"]
                  : HeroButtonIcons[icon]
              }
            />
          </span>
        )}
        {isLoading && (
          <span className="arc-HeroButton-icon">
            <Spinner size="xxl" />
          </span>
        )}
      </span>
    </button>
  );
};

interface LinkElementProps {
  /**
   * URL to link to if `HeroButton` elementType is 'a'.
   */
  href?: string;

  /**
   * Target window for the `HeroButton` href URL.
   */
  target?: string;

  /**
   * Relationship between the Button href URL and the current page. See
   * [MDN](https://developer.mozilla.org/en-US/docs/Web/HTML/Attributes/rel).
   */
  rel?: string;
}

interface HeroButtonElementProps {
  /**
   * Default behavior of the Button element. If not provided, 'submit' will
   * be inferred. Type 'reset' deliberately excluded.
   */
  type?: "button" | "submit";

  /**
   * Refers to the id of a form so it can be submitted if the button exists outside of it.
   */
  form?: string;
}

export interface HeroButtonProps
  extends HeroButtonElementProps, LinkElementProps {
  /**
   * Label for `HeroButton`
   */
  label?: string;

  /**
   * Determine the buttonStyle for `HeroButton`. Default style is `primary`
   */
  buttonStyle?:
    | "primary"
    | "primary-gradient"
    | "secondary"
    | "secondary-gradient"
    | "warning";

  /**
   * Render icon within `HeroButton`. Warning icon will only render when buttonStyle = 'warning'
   */
  icon?: "arrow-right" | "arrow-down" | "play" | "warning";

  /**
   * Optional click handler for the `HeroButton`.
   */
  onClick?: () => void;

  /**
   * Optional property to provide component Ref
   */
  ref?: ButtonRef;

  /**
   * Text to override `label` with additional, more precise information
   * specifically for screen reader users.
   */
  ariaLabel?: string;

  /**
   * HTML ID for the `HeroButton`
   */
  id?: string;

  /**
   * `HeroButton` will be in a loading state. This will override / add a loading icon to the button in it's respective style
   */
  isLoading?: boolean;
}
