import React, { type Ref, type ReactNode } from "react";

import classNames from "classnames";

import { type ExtentableContainer } from "../../../../types/extendable-container";

import { Surface, type SurfaceBackgroundColor } from "../../../Surface";
import { type ContainerBackgroundColor } from "../../types/container-background-color";

export const NavigationHeaderContainer = ({
  isPill = false,
  isExtended = false,
  isFluid = false,
  ref,
  backgroundColor,
  children,
  contentRef,
}: NavigationHeaderContainerProps) => {
  const backgroundColors: Record<
    ContainerBackgroundColor,
    { surface: SurfaceBackgroundColor; classSuffix: string }
  > = {
    light: {
      surface: "light-white",
      classSuffix: "backgroundLight",
    },
    neutral: {
      surface: "light-white",
      classSuffix: "backgroundNeutral",
    },
    lightElevated: {
      surface: "light-white",
      classSuffix: "backgroundLightElevated",
    },
    lightElevatedTight: {
      surface: "light-white",
      classSuffix: "backgroundLighElevatedTight",
    },
    transparentOnDark: {
      surface: "dark-black",
      classSuffix: "backgroundTransparent",
    },
    transparentOnLight: {
      surface: "light-white",
      classSuffix: "backgroundTransparent",
    },
    ghostedOnLight: {
      surface: "light-white",
      classSuffix: "backgroundGhosted",
    },
    ghostedOnDark: {
      surface: "dark-black",
      classSuffix: "backgroundGhosted",
    },
  };

  return (
    <div
      data-testid="NavigationHeader-container"
      className={classNames(
        `arc-NavigationHeaderContainer--${backgroundColors[backgroundColor].classSuffix}`,

        {
          "arc-NavigationHeaderContainer--pill": isPill,
          "arc-NavigationHeaderContainer--fullWidth": !isPill,
          "arc-NavigationHeaderContainer--regular": !isExtended,
          "arc-NavigationHeaderContainer--extended": isExtended,
          "arc-NavigationHeaderContainer--fluid": isFluid,
        },
      )}
    >
      <div ref={ref} className="arc-NavigationHeaderContainer-outer">
        {/*
          This is only used to trigger the nested components to render correctly
          The background color is never applied as the surface is set to be transparent
        */}
        <Surface
          isTransparent
          background={backgroundColors[backgroundColor].surface}
        >
          <div className="arc-NavigationHeaderContainer-inner">
            <div
              className="arc-NavigationHeaderContainer-content"
              ref={contentRef}
            >
              {children}
            </div>
          </div>
        </Surface>
      </div>
    </div>
  );
};

export interface NavigationHeaderContainerProps extends ExtentableContainer {
  /**
   * Ref for the container.
   */
  ref?: Ref<HTMLDivElement>;
  /**
   * Ref for the content element. Used to position floating elements relative to the navigation header.
   */
  contentRef?: Ref<HTMLDivElement>;
  /**
   * Set the background color of the container.
   */
  backgroundColor: ContainerBackgroundColor;
  /**
   * Set the nav bar to be a pill shape. It will only be visible when the background is either white or ghosted.
   */
  isPill?: boolean;
  /**
   * Set the container contents to be 100% width.
   */
  isFluid?: boolean;

  /**
   * Content for the container.
   */
  children: ReactNode;
}
