import React, { createContext, type HTMLAttributes } from "react";

import classNames from "classnames";
import camelCase from "camelcase";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

export type SurfaceBackground = "light" | "dark";

const defaultContext: {
  surface: SurfaceBackground;
  background?: SurfaceBackgroundColor;
  isTransparent?: boolean;
} = { surface: "light" };

const Context = createContext(defaultContext);
const { Provider } = Context;

/**
 * Use `Surface` to compose content using the Arc system.
 */
export const Surface = ({
  background,
  children,
  growVertically = false,
  padding,
  paddingHorizontal,
  paddingVertical,
  isTransparent,
  ...props
}: SurfaceProps) => {
  let surface: "light" | "dark" = "light";

  if (
    background === "dark-black" ||
    background === "dark-brand-01" ||
    background === "dark-brand-02" ||
    background === "dark-neutral-01" ||
    background === "dark-neutral-02"
  ) {
    surface = "dark";
  }

  return (
    <Provider value={{ surface, background, isTransparent }}>
      <div
        data-testid="arc-surface"
        className={classNames({
          "arc-Surface": true,
          [`arc-Surface--${background && camelCase(background)}Background`]:
            background,
          [`arc-Surface--growVertically`]: growVertically,
          [`arc-Surface--padding${padding}`]: padding,
          [`arc-Surface--paddingHorizontal${paddingHorizontal}`]:
            paddingHorizontal,
          [`arc-Surface--paddingVertical${paddingVertical}`]: paddingVertical,
          "arc-Surface--isTransparent": isTransparent,
        })}
        {...filterAttrs(props)}
      >
        {children}
      </div>
    </Provider>
  );
};

const backgroundsShared = [
  "dark-black",
  "dark-brand-01",
  "dark-brand-02",
  "dark-neutral-01",
  "dark-neutral-02",
  "light-brand-01",
  "light-brand-02",
  "light-neutral-01",
  "light-neutral-02",
  "light-white",
] as const;

export const backgrounds = [...backgroundsShared] as const;
export const backgroundsBT = [...backgroundsShared] as const;

export type SurfacePadding = "8" | "12" | "16" | "24" | "32" | "48" | "64";
export type SurfaceBackgroundColor =
  | "dark-black"
  | "dark-brand-01"
  | "dark-brand-02"
  | "dark-neutral-01"
  | "dark-neutral-02"
  | "light-brand-01"
  | "light-brand-02"
  | "light-neutral-01"
  | "light-neutral-02"
  | "light-white";
export interface SurfaceProps extends HTMLAttributes<HTMLElement> {
  /**
   * Background colour of the Surface. Contents will change colour to meet
   * accessibility requirements.
   */
  background?: SurfaceBackgroundColor;

  /**
   * Should the Surface be transparent? When true, no background colour will be applied.
   */
  isTransparent?: boolean;

  /**
   * Content to display on the Surface.
   */
  children?: any;

  /**
   * Should the Surface grow to take up all the available vertical space? Most
   * of the time this should not be required, but useful to fix issues in
   * certain layout combinations.
   */
  growVertically?: boolean;

  /**
   * _Caution: This is an experimental property and may be removed at any time._
   *
   * Size of the padding applied to all sides of the Surface. Use to prevent margin collapsing issues.
   */
  padding?: SurfacePadding;

  /**
   * _Caution: This is an experimental property and may be removed at any time._
   *
   * Size of the horizontal padding applied to the left and right of the Surface.
   */
  paddingHorizontal?: SurfacePadding;

  /**
   * _Caution: This is an experimental property and may be removed at any time._
   *
   * Size of the vertical padding applied to the top and bottom of the Surface.
   */
  paddingVertical?: SurfacePadding;
}

export { Context as SurfaceContext };
