import React, {
  createContext,
  type ReactElement,
  type RefObject,
  useEffect,
  useRef,
  useState,
} from "react";

import classNames from "classnames";

import { ArcSizeBreakpointsL } from "@arc-ui/tokens-arc";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { BtIconChevronRight2Px } from "@arc-ui/icons/BtIconChevronRight2Px";

import { useMediaQuery } from "../../../../hooks/public/use-media-query";

import { Icon } from "../../../Icon";

import {
  SiteHeaderV2Panel,
  SiteHeaderV2ViewAll,
} from "../SiteHeaderV2Panel/SiteHeaderV2Panel";
import { SiteHeaderV2HorizontalPanel } from "../SiteHeaderV2HorizontalPanel";

import { type SiteHeaderV2SubNavItemProps } from "../SiteHeaderV2SubNavItem/SiteHeaderV2SubNavItem";

const defaultContext: {
  navItem: RefObject<HTMLLIElement | null> | null;
  subTitle: string | null;
} = { navItem: null, subTitle: null };
const Context = createContext(defaultContext);
const { Provider } = Context;

export const SiteHeaderV2NavItemWithSubNav = ({
  href,
  slot1,
  slot2,
  slot3,
  slot4,
  slot5,
  slot6,
  subTitle = null,
  title,
  onViewAllClick,
  isPrimary,
  opensFirstWithPanel,
  viewAllTitle,
  ...props
}: SiteHeaderV2NavItemWithSubNavProps) => {
  const navItem = useRef<HTMLLIElement>(null);
  const [defaultItem, setDefaultItem] = useState(true);
  const [panelOpen, setPanelOpen] = useState(false);
  const [horizontalPanelOpen, setHorizontalPanelOpen] = useState(false);
  const [openSecondaryWithSubNav, setOpenSecondaryWithSubNav] = useState(true);
  const isMinWidthArcBreakpointL = useMediaQuery(
    `(min-width: ${ArcSizeBreakpointsL})`,
  );

  useEffect(() => {
    React.Children.map(slot1, (item: any) => {
      if (item.props.isDefaultItem) {
        setDefaultItem(false);
      }
    });
    React.Children.map(slot2, (item: any) => {
      if (item.props.isDefaultItem) {
        setDefaultItem(false);
      }
    });
    React.Children.map(slot3, (item: any) => {
      if (item.props.isDefaultItem) {
        setDefaultItem(false);
      }
    });
    React.Children.map(slot4, (item: any) => {
      if (item.props.isDefaultItem) {
        setDefaultItem(false);
      }
    });
    React.Children.map(slot5, (item: any) => {
      if (item.props.isDefaultItem) {
        setDefaultItem(false);
      }
    });
  }, [slot1, slot2, slot3, slot4, slot5]);

  return (
    <Provider value={{ navItem, subTitle }}>
      <li
        className={classNames({
          [`arc-SiteHeaderV2NavItemWithSubNav`]: true,
          [`arc-SiteHeaderV2NavItemWithSubNav-Secondary`]: !isPrimary,
          [`arc-SiteHeaderV2NavItem-primary`]: isPrimary,
          [`arc-SiteHeaderV2NavItem--linkSelected`]: isPrimary
            ? horizontalPanelOpen
            : panelOpen,
          [`arc-SiteHeaderV2NavItemWithSubNav-active`]:
            panelOpen || (opensFirstWithPanel && openSecondaryWithSubNav),
        })}
        role="none"
        ref={navItem}
        {...filterAttrs(props)}
      >
        <div className="arc-SiteHeaderV2NavItemWithSubNav-buttonContainer">
          <button
            aria-expanded={horizontalPanelOpen || panelOpen}
            role={"menuitem"}
            aria-label={title}
            aria-haspopup="true"
            tabIndex={0}
            className={classNames({
              [`arc-SiteHeaderV2NavItem-link`]: true,
              [`arc-SiteHeaderV2NavItem-horizontalPanelFocus`]: !isPrimary,
              [`arc-SiteHeaderV2NavItem-link--itemHasChildren`]: true,
              [`arc-SiteHeaderV2NavItem-link--itemHasChildren-closeFirstPanel`]:
                !isPrimary && !opensFirstWithPanel,
              [`arc-SiteHeaderV2NavItem-link--itemHasChildren-hasFirstPanel`]:
                opensFirstWithPanel,
              [`arc-SiteHeaderV2NavItem-link--itemHasChildren-primary`]:
                isPrimary,
              [`arc-SiteHeaderV2NavItem-horizontalPanelLink`]:
                !isPrimary && !isMinWidthArcBreakpointL,
            })}
            onClick={(e) => {
              e.preventDefault();
              isPrimary
                ? setHorizontalPanelOpen(!horizontalPanelOpen)
                : setPanelOpen(!horizontalPanelOpen);
            }}
          >
            <div
              className={classNames({
                [`arc-SiteHeaderV2NavItem-title`]: isPrimary,
                [`arc-SiteHeaderV2NavItem-link--itemHasChildren-closeFirstPanel`]:
                  !isPrimary && !opensFirstWithPanel,
                [`arc-SiteHeaderV2NavItem-link--itemHasChildren-hasFirstPanel`]:
                  opensFirstWithPanel,
                [`arc-SiteHeaderV2NavItem-link--itemHasChildren-primary`]:
                  isPrimary,
              })}
            >
              {title}
            </div>
            <span className="arc-SiteHeaderV2-mobileChevron">
              <Icon icon={BtIconChevronRight2Px} />
            </span>

            {subTitle && !isPrimary && isMinWidthArcBreakpointL ? (
              <div
                className={classNames({
                  [`arc-SiteHeaderV2NavItemWithSubNav-text`]: !isPrimary,
                  [`arc-SiteHeaderV2NavItem-link--itemHasChildren-closeFirstPanel`]:
                    !isPrimary && !opensFirstWithPanel,
                  [`arc-SiteHeaderV2NavItem-link--itemHasChildren-hasFirstPanel`]:
                    opensFirstWithPanel,
                  [`arc-SiteHeaderV2NavItem-link--itemHasChildren-primary`]:
                    isPrimary,
                })}
              >
                {subTitle}
              </div>
            ) : null}
            <div
              className={classNames({
                [`arc-SiteHeaderV2NavItemWithSubNav-buttonUnderline`]: isPrimary
                  ? horizontalPanelOpen
                  : panelOpen ||
                    (opensFirstWithPanel && openSecondaryWithSubNav),
                [`arc-SiteHeaderV2NavItemWithSubNav-primaryButtonUnderline`]:
                  isPrimary && horizontalPanelOpen,
                [`arc-SiteHeaderV2NavItemWithSubNav-buttonUnderlineActive `]:
                  !isPrimary && (panelOpen || openSecondaryWithSubNav),
                // [`arc-SiteHeaderV2NavItemWithSubNav-slideIn`]:
                //   animation && isPrimary,
              })}
            ></div>
          </button>
        </div>

        {isPrimary && (
          <SiteHeaderV2HorizontalPanel
            navItemRef={navItem}
            open={horizontalPanelOpen}
            setOpen={setHorizontalPanelOpen}
            title={!isMinWidthArcBreakpointL && title}
          >
            {slot1}
            {slot2}
            {slot3}
            {slot4}
            {slot5}
          </SiteHeaderV2HorizontalPanel>
        )}
        <SiteHeaderV2Panel
          navItemRef={navItem}
          open={
            opensFirstWithPanel && isMinWidthArcBreakpointL
              ? openSecondaryWithSubNav
              : panelOpen
          }
          setOpenPanelOnFirstClick={setOpenSecondaryWithSubNav}
          setOpen={setPanelOpen}
          title={!isMinWidthArcBreakpointL && title}
          subtitle={subTitle}
          viewAll={
            href ? (
              <SiteHeaderV2ViewAll
                href={href}
                onClick={onViewAllClick}
                title={viewAllTitle}
                buttonStyle="primary"
              />
            ) : undefined
          }
          withSubNav
          isNavItem={false}
        >
          {defaultItem
            ? React.cloneElement(slot1, { isDefaultItem: defaultItem })
            : slot1}
          {slot2}
          {slot3}
          {slot4}
          {slot5}
          {slot6}
        </SiteHeaderV2Panel>
      </li>
    </Provider>
  );
};

type slotType = ReactElement<SiteHeaderV2SubNavItemProps>;

export interface SiteHeaderV2NavItemWithSubNavProps {
  /**
   * The URL to link to when a top-level link inside the NavItemWithSubNav panel
   * is clicked or touched.
   */
  href?: string;

  /**
   * Content to be displayed in the first slot of the NavItemWithSubNav. Must be
   * a single SiteHeaderV2SubNavItem component.
   */
  slot1: slotType;

  /**
   * Content to be displayed in the second slot of the NavItemWithSubNav. Must
   * be a single SiteHeaderV2SubNavItem component.
   */
  slot2?: slotType;

  /**
   * Content to be displayed in the third slot of the NavItemWithSubNav. Must be
   * a single SiteHeaderV2SubNavItem component.
   */
  slot3?: slotType;
  /**
   * Content to be displayed in the fourth slot of the NavItemWithSubNav. Must be
   * a single SiteHeaderV2SubNavItem component.
   */
  slot4?: slotType;
  slot5?: slotType;
  slot6?: slotType;
  /**
   * Title text to display inside the NavItemWithSubNav panel.
   */
  subTitle?: string | null;

  /**
   * Top-level text to display in the NavItemWithSubNav.
   */
  title: string;

  /**
   * Text to display in top-level link inside the NavItemWithSubNav panel. Only
   * applies if `href` is true. If not provided, text will be automatically
   * generated from `title`.
   */
  viewAllTitle?: string;

  /**
   * view all click handler.
   */
  onViewAllClick?: () => void;
  isPrimary?: boolean;
  opensFirstWithPanel?: boolean;
}

export { Context as NavItemContext };
