import { type RefObject } from "react";

import { createNavigationHeaderContext } from "../../utils/create-navigation-header-context";

interface SubNavContextValue {
  isOpen: boolean;
  id: string;
  setIsOpen: React.Dispatch<React.SetStateAction<boolean>>;
  rootRef: RefObject<HTMLDivElement | null>;
  triggerRef: RefObject<HTMLButtonElement | null>;
  onOpenChange?: (isVisble: boolean) => void;
}

const [SubNavContext, useSubNavContext] =
  createNavigationHeaderContext<SubNavContextValue>(
    "NavigationHeaderSubnav sub components must be used within NavigationHeaderSubnav",
  );

export { SubNavContext, useSubNavContext };
