import React, { type ReactNode } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

/**
 * Use `Elevation` to elevate what matters.
 */
export const Elevation = ({
  children,
  level = "5",
  isFullWidth = false,
  ...props
}: ElevationProps) => {
  return (
    <div
      className={classNames({
        [`arc-Elevation`]: true,
        [`arc-Elevation--fullWidth`]: isFullWidth,
        [`arc-Elevation--levelOne`]: level === "1",
        [`arc-Elevation--levelTwo`]: level === "2",
        [`arc-Elevation--levelThree`]: level === "3",
        [`arc-Elevation--levelFour`]: level === "4",
        [`arc-Elevation--levelFive`]: level === "5",
      })}
      {...filterAttrs(props)}
    >
      {children}
    </div>
  );
};

export interface ElevationProps {
  /**
   * Contents to Elevate.
   */
  children: ReactNode;

  /**
   * Shadow Elevation level.
   */
  level?: "1" | "2" | "3" | "4" | "5";

  /**
   * Should the Elevation be full width?
   */
  isFullWidth?: boolean;
}
