import React, { type ReactNode } from "react";

import classNames from "classnames";
import * as RadixPopover from "@radix-ui/react-popover";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { useThemeElement } from "../../hooks";
import { Surface } from "../Surface";

/**
 * Use `Popover` to display content in a portal, triggered by a button.
 */
export const Popover = ({
  align,
  ariaLabel,
  alignOffset,
  arrow = true,
  background = "light",
  children,
  content,
  asChild = false,
  maxWidth = 452,
  minHeight,
  onCloseAutoFocus,
  onEscapeKeyDown,
  onFocusOutside,
  onInteractOutside,
  onOpenAutoFocus,
  onPointerDownOutside,
  onOpenChange,
  open,
  constrainToViewport = true,
  side,
  sideOffset = 0,
  zIndex = 100,
  hideWhenDetached = false,
  useBespokeTrigger = false,
  isFluidToViewport = false,
  contentMargin = false,
  isFullBleed = false,
  className,
  ...props
}: PopoverProps) => {
  const [themeElement, setThemeElement] = useThemeElement();

  const alignOffsetDefault = align === "center" ? 0 : -16;

  return (
    <div className="arc-Popover" {...filterAttrs(props)}>
      <RadixPopover.Root open={open} onOpenChange={onOpenChange}>
        {useBespokeTrigger ? (
          <RadixPopover.Anchor className="arc-Popover-anchor">
            {children}
          </RadixPopover.Anchor>
        ) : (
          <RadixPopover.Trigger
            aria-label={ariaLabel}
            asChild={asChild}
            className="arc-Popover-trigger"
          >
            {children}
          </RadixPopover.Trigger>
        )}

        <div ref={setThemeElement}>
          <RadixPopover.Portal container={themeElement}>
            <div
              data-cy="z-index"
              style={{ position: "absolute", zIndex: zIndex }}
            >
              <RadixPopover.Content
                side={side}
                sideOffset={sideOffset}
                align={align}
                hideWhenDetached={hideWhenDetached}
                alignOffset={alignOffset ?? alignOffsetDefault}
                onOpenAutoFocus={onOpenAutoFocus}
                onCloseAutoFocus={onCloseAutoFocus}
                onEscapeKeyDown={onEscapeKeyDown}
                onPointerDownOutside={onPointerDownOutside}
                onFocusOutside={onFocusOutside}
                onInteractOutside={onInteractOutside}
                className={className}
              >
                <Surface
                  isTransparent
                  background={
                    background === "dark" || background === "brand"
                      ? "dark-black"
                      : "light-white"
                  }
                >
                  <div
                    className={classNames("arc-Popover-content", {
                      "arc-Popover-content--dark": background === "dark",
                      "arc-Popover-content--brand": background === "brand",
                      "arc-Popover-content--white": background === "white",
                      "arc-Popover-content--constrainToViewport":
                        constrainToViewport,
                      "arc-Popover-content--isFluidToViewport":
                        isFluidToViewport,
                      "arc-Popover-content--contentMargin": contentMargin,
                      "arc-Popover-content--isFullBleed": isFullBleed,
                    })}
                    style={{ maxWidth, minHeight }}
                    aria-labelledby="popover-content"
                  >
                    {content && <div id="popover-content">{content}</div>}

                    {arrow && (
                      <RadixPopover.PopoverArrow className="arc-Popover-arrow" />
                    )}
                  </div>
                </Surface>
              </RadixPopover.Content>
            </div>
          </RadixPopover.Portal>
        </div>
      </RadixPopover.Root>
    </div>
  );
};

export interface PopoverProps {
  /**
   * Content to render within Popover Trigger
   */
  children?: React.ReactNode;

  /**
   * The preferred side of the anchor to render against when open
   */
  side?: "left" | "right" | "bottom" | "top";

  /**
   * The distance in pixels from the anchor
   */
  sideOffset?: 0 | 4 | 8 | 12 | 16 | 32;

  /**
   * The arrow connecting the `Popover` content to the trigger
   */
  arrow?: boolean;

  /**
   * The preferred alignment against the anchor. May change when collisions occur.
   */
  align?: "start" | "center" | "end";

  /**
   * An offset in pixels from the "start" or "end" alignment options.
   */
  alignOffset?: number;

  /**
   * Label for the trigger to be announced by screen readers
   */
  ariaLabel?: string;

  /**
   * Content inside the Popover
   */
  content?: ReactNode;

  /**
   * Determine if the popover is open
   */
  open?: boolean;

  /**
   * Maximum width of the Popover
   */
  maxWidth?: number;

  /**
   * Background theme of the Popover
   */
  background?: "dark" | "light" | "brand" | "white";

  /**
   * Called when focus moves into the popover
   */
  onOpenAutoFocus?: (event: Event) => void;

  /**
   * Called when focus moves out of the popover
   */
  onCloseAutoFocus?: (event: Event) => void;

  /**
   * Called when the Escape key is pressed
   */
  onEscapeKeyDown?: (event: KeyboardEvent) => void;

  /**
   * Called when a pointer down event occurs outside the popover
   */
  onPointerDownOutside?: (event: Event) => void;

  /**
   * Called when focus moves outside the popover
   */
  onFocusOutside?: (event: Event) => void;

  /**
   * Called when any interaction happens outside the popover
   */
  onInteractOutside?: (event: Event) => void;

  /**
   * Called when the open state of the popover changes.
   */
  onOpenChange?: (open: boolean) => void;

  /**
   * Z-index for the `Popover`. Used to fine tune the overlapping of other page elements.
   */
  zIndex?: number;

  /**
   * Set to true if you want to use your own link or button for the trigger. If false it will wrap the children in a button.
   */
  asChild?: boolean;

  /**
   * Whether to hide the content when the trigger becomes fully occluded.
   */
  hideWhenDetached?: boolean;

  /**
   * This should never usually be needed, as the popover by default will either wrap the child element you pass in a button, or pass the props
   * to the root child element you provide if you set `asChild` to true. If you want to opt out of this behavior set this to true.
   */
  useBespokeTrigger?: boolean;

  /**
   * Constrains the popover height only when it would overflow the viewport.
   * Defaults to `fit-content`, but becomes scrollable if necessary.
   */
  constrainToViewport?: boolean;
  /**
   * Content components placed into Popovers to respond to the viewport.
   */
  isFluidToViewport?: boolean;

  /**
   * Use minHeight in conjunction with constrainToViewport to keep the popover legible. Value in px.
   */
  minHeight?: number;

  /**
   * Add margin to sides of the Popover Content. Margin to match the section margin values at each breakpoint.
   */
  contentMargin?: boolean;
  /**
   * Removes all default padding from the content section of the Popover.
   */
  isFullBleed?: boolean;
  /**
   * Used to add animations to the `RadixPopover.Content` .
   */
  className?: string;
}
