import { useMemo } from "react";

export const usePagination = (pageCount: number, selectedPage: number) => {
  const formatValues = (range: (string | number)[]) =>
    range.map((value) => value.toString());

  return useMemo(() => {
    if (pageCount > 7 && selectedPage < 5) {
      // show 1 - 5 the right dots are visible.
      return formatValues([
        ...Array.from({ length: 5 }, (_value, index) => index + 1),
        "...",
        pageCount,
      ]);
    }

    if (pageCount > 7 && selectedPage >= pageCount - 3) {
      // show numbers to the end but the left dots are visible
      return formatValues([
        1,
        "...",
        ...Array.from(
          { length: 5 },
          (_value, index) => pageCount - index,
        ).reverse(),
      ]);
    }

    if (pageCount > 7 && selectedPage >= 5 && selectedPage < pageCount - 3) {
      // show selected page with one number either side and both the left and the right dots are visible.
      return formatValues([
        1,
        "...",
        selectedPage - 1,
        selectedPage,
        selectedPage + 1,
        "...",
        pageCount,
      ]);
    }

    // show all pages from pageCount
    return formatValues(
      Array.from({ length: pageCount }, (_value, index) => index + 1),
    );
  }, [pageCount, selectedPage]);
};
