import React, { type ReactNode } from "react";

import classNames from "classnames";

import { Rule } from "../../Rule";

export const DrawerFooter = ({
  isFixed,
  isFullBleed = false,
  children,
}: DrawerFooterProps) => {
  return (
    <>
      <div
        className={classNames("arc-DrawerFooter", {
          "arc-DrawerFooter--isFixed": isFixed,
          "arc-DrawerFooter--isFullBleed": isFullBleed,
        })}
      >
        {isFixed && (
          <div className="arc-DrawerFooter-divider">
            <Rule />
          </div>
        )}
        {children}
      </div>
    </>
  );
};

export interface DrawerFooterProps {
  /**
   * Content to display within the DrawerFooter. This will typically be ButtonGroup
   */
  children?: ReactNode;

  /**
   * Determine if the `DrawerFooter` is fixed to the bottom of the `Drawer`
   */
  isFixed?: boolean;

  /**
   * Removes padding within the DrawerFooter
   */
  isFullBleed?: boolean;
}
