import React from "react";

import { Item } from "@radix-ui/react-dropdown-menu";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

/**
 * Provides a label to group related menu items.
 */

export const MenuLabel = ({ children, ...props }: MenuLabelProps) => {
  return (
    <Item
      asChild
      className="arc-MenuLabel"
      tabIndex={0}
      role="presentation"
      {...filterAttrs(props)}
      style={{ pointerEvents: "none" }}
    >
      <div>{children}</div>
    </Item>
  );
};

export interface MenuLabelProps {
  /**
   *  The text content of the label, typically used to group related menu items.
   */
  children: string;
}
