import React, { useContext } from "react";

import classNames from "classnames";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";

import { Heading } from "../../../Heading";
import { SemanticLink } from "../../../SemanticLink";
import { SurfaceContext } from "../../../Surface";

import { ArrowRightIcon } from "../../svg/ArrowRightIcon";

export const NavigationHeaderCta = ({
  href,
  onClick,
  text,
  revealLinkIconOnHover = false,
}: NavigationHeaderCtaProps) => {
  const { surface } = useContext(SurfaceContext);

  return (
    <SemanticLink
      className={classNames(
        "arc-NavigationHeaderCta",
        suffixModifier("arc-NavigationHeaderCta--on", surface),
      )}
      onClick={onClick}
      href={href}
    >
      <div className="arc-NavigationHeaderCta-heading">
        <Heading size="xxs">{text}</Heading>
      </div>
      <div
        className={classNames("arc-NavigationHeaderCta-linkIcon", {
          "arc-NavigationHeaderCta-linkIcon--revealLinkIconOnHover":
            revealLinkIconOnHover,
        })}
      >
        <ArrowRightIcon />
      </div>
    </SemanticLink>
  );
};

export interface NavigationHeaderCtaProps {
  /**
   * Whether to reveal the link icon on hover.
   */
  revealLinkIconOnHover?: boolean;
  /**
   * Text to display in the CTA.
   */
  text: string;
  /**
   * URL for the CTA.
   */
  href: string;
  /**
   * Click handler for the CTA.
   */
  onClick?: (event: React.MouseEvent<HTMLAnchorElement>) => void;
}
