import getDay from "date-fns/getDay";

import { WeekDays } from "../types/week-days";

export const isDay = (date: Date, day: WeekDays) => {
  const dayMap = {
    [WeekDays.MONDAY]: 1,
    [WeekDays.TUESDAY]: 2,
    [WeekDays.WEDNESDAY]: 3,
    [WeekDays.THURSDAY]: 4,
    [WeekDays.FRIDAY]: 5,
    [WeekDays.SATURDAY]: 6,
    [WeekDays.SUNDAY]: 0,
  };

  return getDay(date) === dayMap[day];
};
