import React from "react";

import { SubTrigger, Item } from "@radix-ui/react-dropdown-menu";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { BtIconChevronRightMid } from "@arc-ui/icons";

import { Icon } from "../../../Icon";
import { Text } from "../../../Text";
import { useMenuContext } from "../../MenuContext";
import { type MenuItemProps } from "../../MenuItem";
import { MenuItemContentTemplate } from "../../MenuItemContentTemplate";

/**
 * Trigger element that opens a multi-level menu when selected.
 */

export const MenuItemMultiLevelTrigger = ({
  children,
  isDisabled,
  leadingIcon,
  supportingText,
  keyCommands,
  ariaLabel,
  pairedContent,
  ...props
}: InternalMenuItemMultiLevelTriggerProps) => {
  const { isMobileMenu, goForward } = useMenuContext();

  const moveFoward = (e: any, navigatedViaKeyboard: boolean) => {
    e.preventDefault();

    if (pairedContent) {
      goForward(
        {
          title: String(children),
          content: pairedContent,
          triggerId: String(children),
        },
        navigatedViaKeyboard,
      );
    }
  };

  if (isMobileMenu) {
    return (
      <Item
        disabled={isDisabled}
        aria-label={ariaLabel}
        onKeyDown={(e) => {
          if (e.key === "ArrowRight") {
            moveFoward(e, true);
          }
        }}
        onClick={(e) => {
          moveFoward(e, false);
        }}
        className="arc-MenuItem"
        data-menu-trigger={children}
        {...filterAttrs(props)}
      >
        <MenuItemContentTemplate
          leadingIcon={leadingIcon}
          trailingIcon={BtIconChevronRightMid}
          supportingText={supportingText}
          keyCommands={keyCommands}
        >
          {`${children}`}
        </MenuItemContentTemplate>
      </Item>
    );
  }

  // desktop fallback
  return (
    <SubTrigger
      className="arc-MenuItem arc-MenuItem--trigger"
      disabled={isDisabled}
      aria-label={ariaLabel}
      {...filterAttrs(props)}
    >
      <div className="arc-MenuItem-content">
        {leadingIcon && (
          <div className="arc-MenuItem-leadingIcon">
            <Icon icon={leadingIcon} size={24} />
          </div>
        )}
        <div className="arc-MenuItem-text">
          <Text size="m">{children}</Text>
          {supportingText && <Text size="xs">{supportingText}</Text>}
        </div>
      </div>

      <div className="arc-MenuItem-actions">
        {keyCommands && (
          <div className="arc-MenuItem-keyCommands">{keyCommands}</div>
        )}
        <div className="arc-MenuItem-trailingIcon">
          <Icon icon={BtIconChevronRightMid} size={24} />
        </div>
      </div>
    </SubTrigger>
  );
};

export interface InternalMenuItemMultiLevelTriggerProps extends MenuItemMultiLevelTriggerProps {
  /**
   * The paired content to be displayed in the multi-level menu.
   */
  pairedContent?: React.ReactNode;
}

export interface MenuItemMultiLevelTriggerProps extends Pick<
  MenuItemProps,
  "keyCommands" | "leadingIcon" | "ariaLabel" | "supportingText"
> {
  /**
   * The trigger element for opening the multi-level menu.
   */
  children: React.ReactNode;

  /**
   * Disables the sub-trigger, preventing interaction.
   */
  isDisabled?: boolean;
}
