import React from "react";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { Heading } from "../Heading";

import { VerticalSpace } from "../VerticalSpace";
import { BannerImage } from "../TemplateBanner/components/BannerImage";
import { type TemplateBannerProps } from "../TemplateBanner";

/**
 *  Use `GhostedHeroBanner` to grab attention and convey the main message or purpose of a webpage
 */
export const GhostedHeroBanner = ({
  heading,
  headingLevel,
  label,
  text,
  img,
  children,
  fontStyle = "default",
  headingWordWrap = false,
  headingColor = "auto",
  labelColor = "auto",
  ...props
}: GhostedHeroBannerProps) => {
  return (
    <div className="arc-GhostedHeroBanner" {...filterAttrs(props)}>
      <div className="arc-GhostedHeroBanner-content">
        {label && (
          <>
            <Heading fontStyle="overline" color={labelColor}>
              {label}
            </Heading>
            <VerticalSpace size="8" />
          </>
        )}
        <Heading
          level={headingLevel}
          size={"xl"}
          fontStyle={fontStyle}
          isWordWrap={headingWordWrap}
          color={headingColor}
        >
          {heading}
        </Heading>

        {text && (
          <>
            <VerticalSpace size="16" />
            <span className="arc-TemplateBanner-text">{text}</span>
          </>
        )}

        {children && (
          <>
            <VerticalSpace size="32" />
            {children}
          </>
        )}
      </div>

      <div className="arc-GhostedHeroBanner-image ">
        {img && <BannerImage ariaHidden {...img} />}
      </div>
    </div>
  );
};

export type GhostedHeroBannerProps = Pick<
  TemplateBannerProps,
  | "heading"
  | "img"
  | "children"
  | "label"
  | "text"
  | "headingLevel"
  | "fontStyle"
  | "headingWordWrap"
  | "headingColor"
  | "labelColor"
>;
