import { type NavBarBackground } from "../types/navbar-background";
import { type MenuColorPathway } from "../types/menu-color-pathway";
import { type MenuColorType } from "../types/menu-color-type";
import { type MenuColorScheme } from "../types/menu-color-scheme";

export const getMenuColorConfig = (
  background: NavBarBackground,
  pathway: MenuColorPathway,
) => {
  const colorConfig: Record<MenuColorType, MenuColorScheme> = {
    light: {
      surface: "light-white",
      menuColorType: "light",
    },
    dark: {
      surface: "dark-black",
      menuColorType: "dark",
    },
  };

  switch (background) {
    case "transparentOnDark":
    case "ghostedOnDark":
      return pathway === "invert" ? colorConfig.light : colorConfig.dark;
    default:
      return pathway === "invert" ? colorConfig.dark : colorConfig.light;
  }
};
