import React from "react";

import { ThemeIcon } from "../../../ThemeIcon";
import { Image } from "../../../Image";
import { Heading } from "../../../Heading";

import { type AvatarImage } from "../../types/avatar-image";
import { type AvatarSize } from "../../types/avatar-size";
import { type AvatarTextSize } from "../../types/avatar-text-size";
import { type AvatarIconSize } from "../../types/avatar-icon-size";

export const AvatarContent = ({
  img,
  initials,
  size = "xl",
}: AvatarContentProps) => {
  const textSize: Record<AvatarSize, AvatarTextSize> = {
    s: "xxxs",
    m: "xxs",
    l: "xs",
    xl: "s",
  };

  const iconSize: Record<AvatarSize, AvatarIconSize> = {
    s: 16,
    m: 24,
    l: 32,
    xl: 40,
  };

  if (img) {
    return <Image fit="cover" {...img} />;
  }

  if (initials) {
    return (
      <Heading size={textSize[size]}>
        {initials.substring(0, 3).toUpperCase()}
      </Heading>
    );
  }

  return <ThemeIcon size={iconSize[size]} icon="avatarUser" />;
};

export interface AvatarContentProps {
  /**
   * Initials to display in the avatar (up to 3 characters).
   */
  initials?: string;
  /**
   * Image to display in the avatar.
   */
  img?: AvatarImage;
  /**
   * Size of the avatar.
   */
  size?: AvatarSize;
}
