import { type ArcBreakpointSizes } from "src/helpers/arc-breakpoints";

import { type ArcGradient } from "@arc-ui/gradients";

import { type GradientBreakpointConfig } from "../types/gradient-breakpoint-config";

// Inherit the last provided value when no value is provided
export const getResponsiveConfig = <T extends string | number | ArcGradient>(
  property?: GradientBreakpointConfig<T>,
  breakpoint?: ArcBreakpointSizes,
): T | undefined => {
  if (!property || !breakpoint) return;

  const breakpoints: ArcBreakpointSizes[] = ["xs", "s", "m", "l", "xl", "xxl"];

  return breakpoints.reduce<GradientBreakpointConfig<T>>(
    (acc, bp, index) => ({
      ...acc,
      [bp]: property[bp] || acc[breakpoints[index - 1]],
    }),
    {},
  )[breakpoint];
};
