import React, { useRef, useState, type ReactNode } from "react";

import classNames from "classnames";

import * as RadixDialog from "@radix-ui/react-dialog";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { useThemeElement } from "../../hooks";

import { ThemeIcon } from "../ThemeIcon";
import { VisuallyHidden } from "../VisuallyHidden";
import { Surface } from "../Surface";

export const Drawer = ({
  isOpen,
  children,
  onRequestClose,
  noOverlay = false,
  shouldReturnFocus = true,
  size = "m",
  height,
  width,
  position = "right",
  draggable = false,
  snapPoints = ["30%", "60%", "90%"],
  snapBehaviour = "nearest",
  dragDownToDismiss,
  onDragHandleClick,
  ariaDescription,
  isModal = true,
  ...props
}: DrawerProps) => {
  const [themeElement, setThemeElement] = useThemeElement();
  const triggerRef = useRef<HTMLElement | null>(null);
  const contentRef = useRef<HTMLDivElement | null>(null);
  const [drawerHeight, setDrawerHeight] = useState<number | undefined>(0);

  const normalisedSnapPoints =
    snapPoints && snapPoints.length > 0 ? snapPoints : ["30%", "60%", "90%"];

  const setTriggerElement = () =>
    shouldReturnFocus &&
    (triggerRef.current = document.activeElement as HTMLElement);

  const focusTriggerElement = () => {
    if (triggerRef.current) {
      triggerRef.current.focus();
    }
  };

  const dragRef = useRef<{
    active: boolean;
    deltaY: number;
    startY: number;
    startH: number;
  }>({
    active: false,
    startY: 0,
    deltaY: 0,
    startH: 0,
  });

  const sizingProperties = {
    ...(position !== "bottom" && { width }),
    ...(position === "bottom" && { height: drawerHeight || height }),
  };

  const onHandleUp = (e: React.PointerEvent) => {
    onHandleUpCore(e.nativeEvent);
  };

  const onHandleClick = (e: React.MouseEvent) => {
    onHandleUpCore(e.nativeEvent);
    onDragHandleClick?.(e);
  };

  const onHandleMove = (e: React.PointerEvent) => {
    if (!dragRef.current.active) return;
    dragRef.current.deltaY = e.clientY - dragRef.current.startY;
    const newHeight = dragRef.current.startH - dragRef.current.deltaY;
    setDrawerHeight(Math.round(newHeight));
  };

  const onHandleDown = (e: React.PointerEvent) => {
    if (!contentRef.current) return;
    dragRef.current.active = true;

    // record where the pointer was when dragging started
    dragRef.current.startY = e.clientY;

    // record inital height of drawer
    dragRef.current.startH = contentRef.current.clientHeight;

    // keep moving drawer even if cursor has left pill
    (e.target as HTMLDivElement).setPointerCapture(e.pointerId);
  };

  const resolveToPx = (input: number | string): number | undefined => {
    // if already a number, assume px
    if (typeof input === "number") return input;

    const str = input.trim().toLowerCase();

    if (str.endsWith("%")) {
      const percentValue = parseFloat(str);
      return (window.innerHeight * percentValue) / 100;
    }

    if (str.endsWith("px")) {
      const pixelValue = parseFloat(str);
      return pixelValue;
    }

    const numericValue = Number(str);
    return Number.isFinite(numericValue) ? numericValue : undefined;
  };

  const onHandleUpCore = (e?: Event, keyboardDeltaY?: number) => {
    if (!contentRef.current) return;

    // if the user scrolls down
    if (dragDownToDismiss && contentRef.current.clientHeight < 100) {
      dragRef.current.active = false;
      dragRef.current.deltaY = 0;

      if (e instanceof PointerEvent && e?.currentTarget) {
        (e.currentTarget as Element).releasePointerCapture(
          (e as PointerEvent).pointerId,
        );
      }

      setDrawerHeight(undefined);

      onRequestClose();

      return;
    }

    dragRef.current.active = false;

    if (e instanceof PointerEvent && e?.currentTarget) {
      (e.currentTarget as Element).releasePointerCapture(
        (e as PointerEvent).pointerId,
      );
    }

    const currentHeight = contentRef.current.clientHeight;

    // turn all snapPoints into px values. Order the values.
    const snapsPx = (normalisedSnapPoints ?? [])
      .map(resolveToPx)
      .filter((value): value is number => value !== undefined) // remove undefined values
      .sort((a, b) => a - b);

    let targetSnap: number | undefined = undefined;

    const deltaY = keyboardDeltaY || Math.sign(dragRef.current.deltaY);

    if (snapBehaviour === "next") {
      if (deltaY <= -1) {
        // User scrolled up
        for (let i = 0; i < snapsPx.length; i++) {
          if (snapsPx[i] > currentHeight) {
            targetSnap = snapsPx[i];
            break;
          } else if (currentHeight > snapsPx[snapsPx.length - 1]) {
            targetSnap = snapsPx[snapsPx.length - 1];
          }
        }
      } else if (deltaY >= 1) {
        // User scrolled down
        for (let i = 0; i < snapsPx.length; i++) {
          if (snapsPx[i] < currentHeight) {
            targetSnap = snapsPx[i];
          } else if (currentHeight < snapsPx[0]) {
            targetSnap = snapsPx[0];
          }
        }
      } else if (deltaY === 0) {
        // User clicked without moving go to next snap point
        for (let i = 0; i < snapsPx.length; i++) {
          if (snapsPx[i] > currentHeight) {
            targetSnap = snapsPx[i];
            break;
          }
        }

        // If no bigger snap was found → loop back to the first
        if (!targetSnap) {
          targetSnap = snapsPx[0];
        }
      }
    }

    if (snapBehaviour === "nearest") {
      targetSnap = Math.round(snapsPx[0]);
      let bestDiff = Math.abs(currentHeight - snapsPx[0]);
      for (let i = 0; i < snapsPx.length; i++) {
        const diff = Math.abs(currentHeight - snapsPx[i]);
        if (diff < bestDiff) {
          targetSnap = Math.round(snapsPx[i]);
          bestDiff = diff;
        }
      }
    }

    if (snapBehaviour === "none") {
      targetSnap = currentHeight;
    }
    setDrawerHeight(targetSnap);
  };

  return (
    <div ref={setThemeElement}>
      <RadixDialog.Root open={isOpen} modal={isModal}>
        <RadixDialog.Portal container={themeElement}>
          {isModal && (
            <RadixDialog.Overlay
              className={classNames("arc-Drawer-overlay", {
                "arc-Drawer-overlay--visible": !noOverlay,
              })}
            />
          )}
          <VisuallyHidden>
            <RadixDialog.Description>{ariaDescription}</RadixDialog.Description>
          </VisuallyHidden>
          <div className="arc-Drawer-container">
            <Surface background="light-brand-01" isTransparent>
              <RadixDialog.Content
                className={classNames(
                  "arc-Drawer-slider",
                  `arc-Drawer-slider--${size}`,
                  `arc-Drawer-slider--${position}`,
                  { "arc-Drawer-slider--draggable": draggable },
                  {
                    "arc-Drawer-slider--transition": !dragRef.current.active,
                  },
                )}
                style={{ ...sizingProperties }}
                onOpenAutoFocus={setTriggerElement}
                onCloseAutoFocus={focusTriggerElement}
                onEscapeKeyDown={onRequestClose}
                onInteractOutside={isModal ? onRequestClose : undefined}
                aria-modal={isModal}
                ref={contentRef}
                {...filterAttrs(props)}
              >
                <div className="arc-Drawer-closeButtonContainer">
                  <button
                    aria-label="close"
                    onClick={onRequestClose}
                    className="arc-Drawer-closeButton"
                  >
                    <ThemeIcon size={32} icon="drawerClose" />
                  </button>
                  {/* Drag handle and wrapper */}
                  {draggable && position === "bottom" && (
                    <div
                      className="arc-Drawer-dragHandle"
                      onPointerDown={onHandleDown}
                      onPointerUp={onHandleUp}
                      onPointerMove={onHandleMove}
                      onClick={onHandleClick}
                      role="separator"
                      aria-label="Drag to resize the drawer"
                    >
                      <div
                        className="arc-Drawer-dragHandlePill"
                        tabIndex={-1}
                        data-testid="arc-Drawer-dragHandlePill"
                      />
                    </div>
                  )}
                </div>

                {children}
              </RadixDialog.Content>
            </Surface>
          </div>
        </RadixDialog.Portal>
      </RadixDialog.Root>
    </div>
  );
};

export interface DrawerProps {
  /**
   * Show or hide page overlay.
   */
  noOverlay?: boolean;

  /**
   * Set the height of the Drawer. Position Bottom Only. Accepts string (px, %, em etc) or number.
   * If a number is provided, it will be treated as pixels.
   */
  height?: string | number;

  /**
   * Set the width of the Drawer. Position Left / Right Only. Accepts string (px, %, em etc) or number.
   * If a number is provided, it will be treated as pixels.
   */
  width?: string | number;

  /**
   * Function to be called when the Drawer has been requested to close by either the esc key being pressed, outside the dialog being clicked or the close button being clicked. The callback must set the open state of the Drawer to false.
   */
  onRequestClose: () => void;

  /**
   * Whether to return focus to the element that was focused before the Drawer opened. True by default.
   */
  shouldReturnFocus?: boolean;

  /**
   * Size preset for the drawer. These can be overridden by setting custom `height` (for Bottom position) or `width` (for 'Left, 'Right'). Use 'auto' to hug the `drawer` content.
   */
  size?: "l" | "m" | "s" | "auto";

  /**
   * Set Drawer open or closed.
   */
  isOpen?: boolean;

  /**
   * Content to include with in the `Drawer` This should typically be `DrawerHeader`, `DrawerFooter` and `DrawerFooter`. This can also have custom content.
   */
  children?: ReactNode;

  /**
   * Set the position of the `Drawer`
   */
  position?: "right" | "left" | "bottom";

  /**
   * Enable the drag handle & snapping (bottom position only).
   */
  draggable?: boolean;

  /**
   * Snap points for the bottom drawer height. Accepts numbers (px) or strings ('%','px').
   */
  snapPoints?: Array<number | string>;

  /**
   * Snap behaviour when releasing the drag:
   * - "nearest" → snap to the closest snap point
   * - "next"    → snap in the direction of the drag (up = next larger, down = next smaller)
   * Defaults to "nearest".
   */
  snapBehaviour?: "nearest" | "next" | "none";

  /**
   * Allow dismissing the bottom drawer by dragging it down
   */
  dragDownToDismiss?: boolean;

  /**
   * Invoke function when drag handle is clicked
   */
  onDragHandleClick?: (e: React.MouseEvent) => void;

  /**
   * Controls whether the drawer behaves as a modal
   */
  isModal?: boolean;

  /**
   * Describe the content of the Drawer
   */
  ariaDescription: string;
}
