import React, { type Ref, useEffect, useRef, useContext } from "react";

import classNames from "classnames";

import { ThemeIcon } from "../ThemeIcon";

import { SurfaceContext } from "../Surface";

import { FormControlContext } from "../FormControl";

/** Use `CheckboxIcon` to display a visual checkbox indicator that reflects a checked, unchecked, or indeterminate state. */
export const CheckboxIcon = ({
  id,
  name,
  checked,
  indeterminate = false,
  isDisabled,
  isRequired,
  size = "m",
  value,
  error,
  ariaDescribedBy,
  onBlur,
  onChange,
  ref,
  ...props
}: CheckboxIconProps) => {
  const { requirementStatus } = useContext(FormControlContext);
  const internalRef = useRef<HTMLInputElement | null>(null);
  const { surface } = useContext(SurfaceContext);

  const inputRef = (ref || internalRef) as React.RefObject<HTMLInputElement>;

  useEffect(() => {
    if (inputRef.current) {
      inputRef.current.indeterminate = indeterminate;
    }
  }, [indeterminate, checked, inputRef]);

  const tickSize = {
    s: 14,
    m: 18,
  };

  const isControlled =
    typeof checked !== "undefined" && typeof onChange === "function";

  const checkedProps: CheckedProps = isControlled
    ? { checked }
    : checked
      ? { defaultChecked: true }
      : {};

  if (!checked && onChange) {
    indeterminate = false;
  }

  if (requirementStatus === "required") {
    isRequired = true;
  }

  return (
    <label
      htmlFor={id}
      className={classNames({
        "arc-CheckboxIcon": true,
        "arc-CheckboxIcon--disabled": isDisabled,
        "arc-CheckboxIcon--invalid": error,
        "arc-CheckboxIcon--small": size === "s",
        "arc-CheckboxIcon--onDarkSurface": surface === "dark",
      })}
    >
      <input
        aria-describedby={
          ariaDescribedBy ? ariaDescribedBy : error ? "id-error" : undefined
        }
        aria-invalid={error}
        aria-checked={
          checked && !indeterminate
            ? true
            : indeterminate && checked
              ? "mixed"
              : false
        }
        className={classNames("arc-CheckboxIcon-input")}
        disabled={isDisabled}
        id={id}
        name={name}
        onBlur={onBlur}
        onChange={onChange}
        ref={inputRef}
        required={isRequired}
        type="checkbox"
        value={value}
        {...checkedProps}
        {...props}
      />
      <span className={classNames("arc-CheckboxIcon-box")}>
        {indeterminate ? (
          <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 16 16"
            fill="none"
          >
            <rect
              x="4"
              y="8"
              width="7.51"
              height="1"
              rx="0.5"
              fill="currentColor"
            />
          </svg>
        ) : (
          <ThemeIcon icon="checkboxChecked" size={tickSize[size]} />
        )}
      </span>
    </label>
  );
};

type CheckedProps = {
  /**
   * Is the input checked?
   */
  checked?: boolean;
  /**
   * The initial checked state of the Checkbox.
   */
  defaultChecked?: boolean;
  /**
   * sets the state of the Checkbox to be indeterminate
   */
  indeterminate?: boolean;
};

export interface CheckboxIconProps extends Omit<
  CheckedProps,
  "defaultChecked"
> {
  /**
   * Ref to the underlying input element.
   */
  ref?: Ref<HTMLInputElement>;
  /**
   * Error state for the Checkbox.
   */
  error?: boolean;
  /**
   * ID for the element description to be announced by screenreaders in addition to the title.
   */
  ariaDescribedBy?: string;
  /**
   * ID for the Checkbox.
   */
  id?: string;
  /**
   * `isDisabled` is a legacy property and not recommended from a UX usability best practice perspective.
   */
  isDisabled?: boolean;
  /**
   * Is the Checkbox required?
   */
  isRequired?: boolean;
  /**
   * Name for the Checkbox.
   */
  name?: string;
  /**
   * Function to call when the Checkbox loses focus.
   */
  onBlur?: (e: React.FocusEvent<HTMLInputElement>) => void;
  /**
   * Callback function to update the Checkbox's controlled `checked` prop, for
   * example `e => setChecked(e.target.checked)`.
   */
  onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;
  /**
   * Size of the Checkbox.
   */
  size?: "m" | "s";
  /**
   * Value for the Checkbox.
   */
  value?: string;
}
