import { useEffect, useMemo, useRef, useState } from "react";

export const useProgressStepperOverflow = ({
  onLoadStep,
  increment = 1,
  offsetLeft = 24,
}: UseProgressStepperOverflowParams = {}) => {
  const stepperRef = useRef<HTMLOListElement | null>(null);
  const [itemVisibility, setItemVisibility] = useState<VisibilityMap>({});

  useEffect(() => {
    const el = stepperRef.current?.parentElement;
    const stepperItems = Array.from(stepperRef.current?.children || []);

    const observer = new IntersectionObserver(
      (entries) => {
        const newEntries = entries.reduce<VisibilityMap>((acc, entry) => {
          const el = entry.target as HTMLElement;

          return {
            ...acc,
            [`${el.dataset.progressStepperItemId}`]: entry.intersectionRatio,
          };
        }, {});

        setItemVisibility((current) => ({ ...current, ...newEntries }));
      },
      {
        root: el,
        threshold: [0, 0.25, 0.5, 0.75, 1],
      },
    );

    stepperItems.forEach((item) => observer.observe(item as HTMLElement));

    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (onLoadStep) {
      const container = stepperRef.current?.parentElement;
      const stepperItems = Array.from(stepperRef.current?.children || []);
      const itemToScrollTo = stepperItems[
        Math.max(0, onLoadStep)
      ] as HTMLElement;

      container?.scrollTo({
        left: itemToScrollTo.offsetLeft - offsetLeft,
        behavior: "smooth",
      });
    }
  }, [onLoadStep, offsetLeft]);

  const { isFirstStepVisible, isLastStepVisible } = useMemo(() => {
    const visibilityRatios = Object.values(itemVisibility);
    const isFirstStepVisible = visibilityRatios[0] === 1;
    const isLastStepVisible =
      visibilityRatios[visibilityRatios.length - 1] === 1;

    return { isFirstStepVisible, isLastStepVisible };
  }, [itemVisibility]);

  const currentIndex = Math.max(
    Object.values(itemVisibility).findIndex((value) => value >= 0.5),
    0,
  );

  const scrollToStep = (index: number) => {
    const container = stepperRef.current?.parentElement;
    const stepperItems = Array.from(stepperRef.current?.children || []);
    const itemToScrollTo = stepperItems[Math.max(0, index)] as HTMLElement;

    container?.scrollTo({
      left: itemToScrollTo.offsetLeft - offsetLeft,
      behavior: "smooth",
    });
  };

  const onViewScroll = (direction: boolean) => {
    const container = stepperRef.current?.parentElement;

    if (!container) return;

    container.scrollBy({
      left: direction ? container.clientWidth : -container.clientWidth,
      behavior: "smooth",
    });
  };

  const onPreviousStep = () => {
    const newStep = Math.max(currentIndex - increment, 0);

    scrollToStep(newStep);
  };

  const onNextStep = () => {
    const stepperItems = Array.from(stepperRef.current?.children || []);
    const newStep = Math.min(currentIndex + increment, stepperItems.length);

    scrollToStep(newStep);
  };

  return {
    stepperRef,
    onNextStep,
    onPreviousStep,
    onViewScroll,
    currentIndex,
    scrollToStep,
    isFirstStepVisible,
    isLastStepVisible,
  };
};

type VisibilityMap = {
  [key: string]: number;
};

interface UseProgressStepperOverflowParams {
  increment?: number;
  onLoadStep?: number;
  offsetLeft?: 0 | 8 | 12 | 16 | 24 | 32 | 40;
}
