import React, { type ReactNode } from "react";

import classNames from "classnames";

import * as RadixDialog from "@radix-ui/react-dialog";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";

import { useThemeElement } from "../../../../../../hooks";

import { VisuallyHidden } from "../../../../../VisuallyHidden";
import { Surface, type SurfaceBackgroundColor } from "../../../../../Surface";

import { type MenuColorType } from "../../../../types/menu-color-type";
import { type MenuPosition } from "../../../../types/menu-position";
import { type MenuDrawerType } from "../../../../types/menu-drawer-type";

export const SideMenuDrawer = ({
  children,
  onCloseAutoFocus,
  onInteractOutside,
  onEscapeKeyDown,
  title,
  drawerType,
  isOpen,
  colorType,
  surface,
  menuPosition,
}: SideMenuDrawerProps) => {
  const [themeElement, setThemeElement] = useThemeElement();

  return (
    <div ref={setThemeElement}>
      <RadixDialog.Root open={isOpen}>
        <RadixDialog.Portal container={themeElement}>
          <RadixDialog.Overlay className="arc-SideMenuDrawer-overlay">
            <RadixDialog.Content
              aria-describedby={undefined}
              className={classNames(
                "arc-SideMenuDrawer-slider",
                suffixModifier(
                  "arc-SideMenuDrawer-slider--position",
                  menuPosition,
                ),
                suffixModifier("arc-SideMenuDrawer-slider--on", colorType),
                suffixModifier("arc-SideMenuDrawer-slider--type", drawerType),
              )}
              onCloseAutoFocus={onCloseAutoFocus}
              onEscapeKeyDown={onEscapeKeyDown}
              onInteractOutside={onInteractOutside}
              aria-modal="true"
            >
              <VisuallyHidden>
                <RadixDialog.Title>{title}</RadixDialog.Title>
              </VisuallyHidden>
              <Surface growVertically isTransparent background={surface}>
                {children}
              </Surface>
            </RadixDialog.Content>
          </RadixDialog.Overlay>
        </RadixDialog.Portal>
      </RadixDialog.Root>
    </div>
  );
};

export interface SideMenuDrawerProps {
  /**
   * Type of drawer to display.
   */
  drawerType: MenuDrawerType;
  /**
   * Whether the drawer is open.
   */
  isOpen: boolean;
  /**
   * Title for the drawer.
   */
  title: string;
  /**
   * Content to display in the drawer.
   */
  children: ReactNode;
  /**
   * Color type for the drawer.
   */
  colorType: MenuColorType;
  /**
   * Surface background color.
   */
  surface: SurfaceBackgroundColor;
  /**
   * Position of the side menu.
   */
  menuPosition: MenuPosition;
  /**
   * Callback when drawer closes and focus returns.
   */
  onCloseAutoFocus?: (e: Event) => void;
  /**
   * Callback when escape key is pressed.
   */
  onEscapeKeyDown?: (e: Event) => void;
  /**
   * Callback when user interacts outside the drawer.
   */
  onInteractOutside?: (e: Event) => void;
}
