import React, { type Ref } from "react";

import classNames from "classnames";

/**
 * Use `SemanticHeading` to render accessible headings that preserve correct
 * document hierarchy.
 */

export const SemanticLink = ({
  children,
  className,
  ...props
}: SemanticLinkProps) => (
  <a className={classNames("arc-SemanticLink", className)} {...props}>
    {children}
  </a>
);

export interface SemanticLinkProps extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  /**
   * Ref for the Button.
   */
  ref?: Ref<HTMLAnchorElement>;
  /**
   * Content to render within the Button.
   */
  children: React.ReactNode;
}
