import React, { useEffect, useState } from "react";

import classNames from "classnames";
import debounce from "lodash/debounce";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { ThemeIcon } from "../ThemeIcon";

/**
 * Use `ScrollToTop` to allow the user to scroll to the top of the page by clicking a button.
 */
export const ScrollToTop = ({
  appear = "always",
  isFixed = true,
  fill = "solid",
  zIndex = 100,
  focusColor = "primary",
  ...props
}: ScrollToTopProps) => {
  const [hasScrolled, setHasScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = debounce(() => {
      setHasScrolled(window.scrollY > 0);
    }, 100);

    window.addEventListener("scroll", handleScroll);

    return () => {
      window.removeEventListener("scroll", handleScroll);
      handleScroll.cancel();
    };
  });

  const onClick = () => {
    window.scrollTo({
      top: 0,
      behavior: "smooth",
    });
  };

  return (
    <button
      onClick={onClick}
      style={{
        zIndex,
      }}
      className={classNames("arc-ScrollToTop", `arc-ScrollToTop--${fill}`, {
        "arc-ScrollToTop--secondary": focusColor == "secondary",
        "arc-ScrollToTop--fixed": isFixed,
        "arc-ScrollToTop--visible":
          appear === "always" || (appear === "afterScroll" && hasScrolled),
      })}
      {...filterAttrs(props)}
    >
      <div className="arc-ScrollToTop-textWrapper">
        <span className="arc-ScrollToTop-text">Back to top</span>
      </div>
      <span className="arc-ScrollToTop-iconContainer">
        <div className="arc-ScrollToTop-icon">
          <ThemeIcon icon="scrollToTop" />
        </div>
      </span>
    </button>
  );
};

export interface ScrollToTopProps {
  /**
   * If true, the button will stick to the bottom right corner of the screen.
   */
  isFixed?: boolean;

  /**
   * Sets when the scroll button should appear. `always` will show the button all the time.
   * `afterScroll` will show the button when the user has stopped scrolling and have passed the fold.
   */
  appear?: "always" | "afterScroll";

  /**
   * Z-index for the button. Used to fine tune the overlapping of other page elements.
   */
  zIndex?: number;

  /**
   * Button fill.
   */
  fill?: "solid" | "outlined";

  /**
   * Determine the color of the focus ring.
   */
  focusColor?: "primary" | "secondary";
}
