import React, { type CSSProperties } from "react";

import cssEscape from "cssesc";

import kebabCase from "lodash/kebabCase";

import { getQuery } from "../../utils/get-query";
import { type MediaQuery } from "../../types/media-query";

export const NavigationHeaderStyleElement = ({
  css,
}: NavigationHeaderStyleElementProps) => {
  const generateCssStyles = (declarations: CSSProperties) =>
    Object.entries(declarations).reduce(
      (acc, [property, value]) => `${acc}${kebabCase(property)}:${value};`,
      "",
    );

  const styleStrings = css.map(({ declarations, className, mediaQuery }) => {
    const escapedClassName = cssEscape(className, { isIdentifier: true });
    const escapedStyles = cssEscape(generateCssStyles(declarations));

    const cssDeclarations = `.${escapedClassName} { ${escapedStyles} }`;

    return mediaQuery
      ? `${getQuery(mediaQuery)} { ${cssDeclarations} }`
      : cssDeclarations;
  });

  return <style>{styleStrings.join("").replace(/\s/g, "")}</style>;
};

export interface NavigationHeaderStyleElementCSS {
  /**
   * Optional media query for the CSS rule.
   */
  mediaQuery?: MediaQuery;
  /**
   * CSS class name to apply the styles to.
   */
  className: string;
  /**
   * CSS declarations to apply.
   */
  declarations: CSSProperties;
}

export interface NavigationHeaderStyleElementProps {
  /**
   * Array of CSS rules to generate.
   */
  css: NavigationHeaderStyleElementCSS[];
}
