import React, { useContext, useState, useEffect, useRef } from "react";

import classNames from "classnames";

import debounce from "lodash/debounce";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { BtIconArrowRight } from "@arc-ui/icons/BtIconArrowRight";

import { BtIconArrowRightFill } from "@arc-ui/icons/BtIconArrowRightFill";

import { Icon } from "../Icon/Icon";

import { Badge } from "../Badge/Badge";

import { Image, type ImageProps } from "../Image/Image";

import { Heading, type HeadingLevel } from "../Heading/Heading";

import { Text } from "../Text/Text";

import { ButtonV2, type ButtonV2Props } from "../ButtonV2/ButtonV2";

import { ArcBreakpoints } from "../../helpers/arc-breakpoints";

import { CardHeading } from "../CardHeading";

import { Surface, SurfaceContext } from "../Surface";

import { VerticalSpace } from "../VerticalSpace";

import { ConditionalWrapper } from "../ConditionalWrapper";

/** Use `InformationCard` for flexibility and the ability to focus and highlight product specific content. */
export const InformationCard = ({
  cardUrl,
  onClick,
  heading,
  text,
  label,
  footerLogo,
  button,
  image,
  badges,
  icon,
  minHeight,
  minHeights,
  headingLevel = "2",
  labelLevel = "3",
  preserveAspectRatios,
  headingWordWrap,
  ...props
}: InformationCardProps) => {
  const { surface } = useContext(SurfaceContext);

  const [showHoverState, setShowHoverState] = useState(false);

  const handleShowHoverState = (show: boolean) => () => setShowHoverState(show);

  const [minimumHeight, setMinimumHeight] = useState<number | undefined>(
    undefined,
  );

  const cardRef = useRef<HTMLDivElement>(null);

  const checkMinHeight = debounce(() => {
    for (const [key, value] of Object.entries(ArcBreakpoints) as [
      keyof typeof ArcBreakpoints,
      number,
    ][]) {
      if (window.innerWidth > value) {
        setMinimumHeight(minHeights?.[key]);
        return;
      }
    }

    setMinimumHeight(undefined);
  }, 100);

  useEffect(() => {
    checkMinHeight();
    window.addEventListener("resize", checkMinHeight);

    return () => {
      window.removeEventListener("resize", checkMinHeight);

      checkMinHeight.cancel();
    };
  }, [minHeights, checkMinHeight]);

  const aspectRatioClassNames = preserveAspectRatios
    ? Object.entries(preserveAspectRatios)
        .filter(([, value]) => value)
        .map(
          ([breakpoint, ratio]) =>
            `arc-InformationCard--preserveAspectRatio-${breakpoint}-${ratio}`,
        )
    : [];

  const CardText = ({ text }: { text: string }) => {
    const paragraphs = text.split(/\\n|\n/).filter((p) => p.trim());

    return (
      <div>
        {paragraphs.map((paragraph, index) => (
          <div key={`informationcard-text-${index}`}>
            {index > 0 && <VerticalSpace size="8" />}
            <Text>{paragraph}</Text>
          </div>
        ))}
      </div>
    );
  };

  const minHeightStyle = !preserveAspectRatios && {
    minHeight: minHeight ? minHeight : minimumHeight,
  };

  return (
    <ConditionalWrapper
      condition={Boolean(preserveAspectRatios)}
      wrapper={(children) => (
        <div className="arc-InformationCard--preserveAspectRatioWrapper">
          {children}
        </div>
      )}
    >
      <div
        ref={cardRef}
        style={{
          ...minHeightStyle,
        }}
        className={classNames("arc-InformationCard", ...aspectRatioClassNames, {
          "arc-InformationCard--isALink": cardUrl,
          "arc-InformationCard--outlined": cardUrl && showHoverState,
          "arc-InformationCard--onDarkSurface": surface === "dark",
        })}
        {...filterAttrs(props)}
      >
        <Surface growVertically background="light-white">
          <div className="arc-InformationCard-innerContainer">
            {image && (
              <div className="arc-InformationCard-img">
                <Image alt="" {...image} />
              </div>
            )}

            {icon && (
              <>
                <div className="arc-InformationCard-icon">
                  <Icon testId="information-card-icon" icon={icon} />
                </div>
              </>
            )}

            <div className="arc-InformationCard-contentContainer">
              {label && (
                <>
                  <div className="arc-InformationCard-label">
                    <Heading level={labelLevel} fontStyle="overline">
                      {label}
                    </Heading>
                  </div>
                </>
              )}

              <CardHeading
                heading={heading}
                headingLevel={headingLevel}
                href={cardUrl}
                onClick={onClick}
                onMouseEnter={handleShowHoverState(true)}
                onMouseLeave={handleShowHoverState(false)}
                onFocus={handleShowHoverState(true)}
                onBlur={handleShowHoverState(false)}
                headingWordWrap={headingWordWrap}
                isHovered={showHoverState}
              />
              {text && <CardText text={text} />}
            </div>

            {(button || badges || footerLogo) && (
              <div className="arc-InformationCard-footer">
                {badges && (
                  <>
                    <div className="arc-InformationCard-badgeContainer">
                      {badges.map(({ text, ...badgeProps }, i) => (
                        <div
                          className="arc-InformationCard-badge"
                          key={`information-card-badge-${i}`}
                        >
                          <Badge {...badgeProps}>{text}</Badge>
                        </div>
                      ))}
                    </div>
                  </>
                )}

                <div className="arc-InformationCard-footerItems">
                  {button && !cardUrl && (
                    <div className="arc-InformationCard-footerButtonContainer">
                      <ButtonV2
                        {...button}
                        size="m"
                        iconPosition="beforeText"
                        buttonStyle="compact"
                        icon={BtIconArrowRight}
                        iconActive={BtIconArrowRightFill}
                      />
                    </div>
                  )}
                  {footerLogo && (
                    <div className="arc-InformationCard-footerLogoContainer">
                      <Image {...footerLogo} />
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>
        </Surface>
      </div>
    </ConditionalWrapper>
  );
};

type InformationCardImage = Pick<
  ImageProps,
  | "alt"
  | "loading"
  | "width"
  | "height"
  | "src"
  | "fadeOnLoad"
  | "fetchPriority"
>;

type InformationCardButtonProps = Pick<
  ButtonV2Props,
  "label" | "onClick" | "href" | "ariaLabel"
>;

export interface minHeightsProps {
  xs?: number;
  s?: number;
  m?: number;
  l?: number;
  xl?: number;
  xxl?: number;
  xxxl?: number;
}

type AspectRatios = "3-4" | "10-16";

export interface InformationCardProps {
  /**
   * Heading for the InformationCard.
   */

  heading: string;

  /**
   * Heading level for the InformationCard heading.
   */
  headingLevel?: HeadingLevel;

  /**
   * Text content for the InformationCard. Use \n to create multiple paragraphs, up to 3 paragraphs.
   */
  text?: string;

  /**
   * Uppercase label for the InformationCard.
   */
  label?: string;

  /**
   * Url for the InformationCard. Makes the whole card a link and hides `button` if provided.
   */
  cardUrl?: string;

  /**
   * Click handler for the InformationCard. Only applied when a card url is provided.
   */
  onClick?: (e: React.MouseEvent<HTMLAnchorElement>) => void;

  /**
   * Footer logo for the InformationCard.
   */
  footerLogo?: InformationCardImage;

  /**
   * Header image for the InformationCard.
   */
  image?: InformationCardImage;

  /**
   * Header icon for the InformationCard.
   */
  icon?: string;

  /**
   * Sets a minimum height for the InformationCard. Overrules minHeights values.
   */
  minHeight?: number;

  /**
   * Badges for the InformationCard.
   */
  badges?: { text: string }[];

  /**
   * Cta button for the InformationCard. Hidden if there is a card url.
   */
  button?: InformationCardButtonProps;
  /**
   * Sets a minimum height for the InformationCard at each breakpoint (xs, s, m, l, xl, xxl). inherits from smaller breakpoints
   */
  minHeights?: minHeightsProps;
  /**
   * Heading level for the InformationCard label.
   */
  labelLevel?: HeadingLevel;
  /**
   * Whether long words in heading should be wrapped.
   */
  headingWordWrap?: boolean;
  /**
   * Preserve aspect ratio of the InformationCard. Set minHeight depending on Card width. Overwrites minHeight prop value.
   */
  preserveAspectRatios?: {
    xs?: AspectRatios;
    s?: AspectRatios;
    m?: AspectRatios;
    l?: AspectRatios;
    xl?: AspectRatios;
    xxl?: AspectRatios;
    xxxl?: AspectRatios;
  };
}
