import React from "react";

import classNames from "classnames";
import * as RadixToast from "@radix-ui/react-toast";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { ThemeIcon, type ThemeIconNames } from "../ThemeIcon";

/** Use `ToastNotification` to display brief, non-intrusive messages that inform users about system events, actions, or feedback. */
export const ToastNotification = ({
  link,
  title,
  isOpen,
  onOpenChange,
  isStatusIconVisible = true,
  isCloseButtonVisible = true,
  status = "general",
  ...props
}: ToastNotificationProps) => {
  const statusIcons: Record<
    ToastStatus,
    Extract<
      ThemeIconNames,
      "toastGeneral" | "toastSuccess" | "toastWarning" | "toastError"
    >
  > = {
    general: "toastGeneral",
    error: "toastError",
    warning: "toastWarning",
    success: "toastSuccess",
  };

  const handleLinkClick =
    (handler: () => void) => (event: React.MouseEvent<HTMLAnchorElement>) => {
      event.preventDefault();
      handler();
    };

  return (
    <RadixToast.Root
      className="arc-Toast-root"
      open={isOpen}
      onOpenChange={onOpenChange}
      {...filterAttrs(props)}
    >
      <div
        data-testid="toast-notification-wrapper"
        className={classNames("arc-Toast", `arc-Toast-status--${status}`)}
      >
        {isStatusIconVisible && (
          <div data-testid="status-icon" className="arc-Toast-icon">
            <ThemeIcon size={24} icon={statusIcons[status]} />
          </div>
        )}

        <RadixToast.Title className="arc-Toast-title">
          <span>{title}</span>
        </RadixToast.Title>

        {link && (
          <RadixToast.Action
            className="arc-Toast-action"
            asChild
            altText={link.text}
          >
            <a
              className="arc-Toast-link"
              href={link.href}
              aria-label={link.ariaLabel}
              {...(link.onClick && { onClick: handleLinkClick(link.onClick) })}
            >
              {link.text}
            </a>
          </RadixToast.Action>
        )}

        {isCloseButtonVisible && !link && (
          <RadixToast.Close className="arc-Toast-dismiss" aria-label="Close">
            <ThemeIcon icon="toastDismiss" size={24} />
          </RadixToast.Close>
        )}
      </div>
    </RadixToast.Root>
  );
};

type ToastStatus = "general" | "error" | "warning" | "success";

export interface ToastNotificationProps {
  /**
   * Title for `<Toast />`
   */
  title: string;

  /**
   * Set open state for `<Toast />`
   */
  isOpen: boolean;

  /**
   * Function to call when the open state of `<Toast />` changes. This needs to be supplied in order for the auto dismiss and the close button to work.
   */
  onOpenChange: (isOpen: boolean) => void;

  /**
   * Set whether close button shows
   */
  isCloseButtonVisible?: boolean;

  /**
   * Set whether to include a status icon
   */
  isStatusIconVisible?: boolean;

  /**
   * Link for `<Toast />`
   */
  link?: {
    text: string;
    ariaLabel?: string;
    href?: string;
    onClick?: () => void;
  };

  /**
   * Status of `<Toast />`
   */
  status?: ToastStatus;
}
