import React, { useId } from "react";

import { type NavigationHeaderNavigationItem } from "../../../../types/nav-item";

import { SideMenuLink } from "../SideMenuLink";
import { SideMenuDisclosure } from "../SideMenuDisclosure";
import { SideMenuCategoryLinksItem } from "../SideMenuCategoryLinksItem";
import { SideMenuMegaMenuItem } from "../SideMenuMegaMenuItem";
import { NavigationHeaderCta } from "../../../NavigationHeaderCta";

export const SideMenuNavItem = ({ navItem }: SideMenuNavItemProps) => {
  const id = useId();

  return (
    <>
      {navItem.type === "link" && (
        <SideMenuLink
          href={navItem.href}
          onClick={navItem.onClick}
          text={navItem.text}
        />
      )}

      {navItem.type === "levelTwo" && (
        <SideMenuDisclosure heading={navItem.text}>
          {navItem.items.map((link, linkIndex) => (
            <NavigationHeaderCta
              key={`${id}-side-menu-level-two-link-item-${linkIndex}`}
              href={link.href}
              onClick={link.onClick}
              text={link.text}
            />
          ))}
        </SideMenuDisclosure>
      )}

      {navItem.type === "categoryLinks" && (
        <SideMenuCategoryLinksItem {...navItem} />
      )}

      {navItem.type === "megamenu" && <SideMenuMegaMenuItem {...navItem} />}
    </>
  );
};

interface SideMenuNavItemProps {
  /**
   * Navigation item to render.
   */
  navItem: NavigationHeaderNavigationItem;
}
