import React, { cloneElement, isValidElement } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { Button, type ButtonProps } from "../Button/Button";
import { ButtonV2 } from "../ButtonV2/ButtonV2";

/**
 * Use `ButtonGroup` to group multiple buttons together, ensuring consistent sizing, spacing,
 * and alignment. Only accepts `Button` or `ButtonV2` components as children.
 */

export const ButtonGroup = ({
  children,
  size,
  align = "flex-start",
  orientation = "horizontal",
  gap = 16,
  ariaLabel,
  isFullWidth,
  ...props
}: ButtonGroupProps) => {
  const isArcButton = (
    type: React.JSXElementConstructor<any> | string,
  ): type is typeof Button | typeof ButtonV2 => {
    return type === Button || type === ButtonV2;
  };

  return (
    <div
      style={{
        gap,
        justifyContent: align,
      }}
      className={classNames("arc-ButtonGroup", {
        "arc-ButtonGroup--vertical": orientation === "vertical",
      })}
      role="group"
      aria-label={ariaLabel}
      {...filterAttrs(props)}
    >
      {React.Children.map(children, (child) => {
        if (isValidElement(child) && isArcButton(child.type)) {
          return cloneElement(child, {
            size,
            isFullWidth,
          } as Partial<ButtonProps>);
        }

        return null;
      })}
    </div>
  );
};

export interface ButtonGroupProps {
  /**
   * Components to appear within the ButtonGroup
   * Can be Button, ButtonV2 only.
   */
  children: React.ReactNode;

  /**
   * Size of the buttons in the ButtonGroup This will override the size prop for each individual button.
   */
  size?: ButtonProps["size"];

  /**
   * Determines the alignment of the buttons within the ButtonGroup
   */
  align?: "flex-start" | "center" | "flex-end";

  /**
   * Orientation of the ButtonGroup Defaults to 'horizontal'. 'vertical' Persists on mobile.
   */
  orientation?: "horizontal" | "vertical";

  /**
   * Spacing between buttons in the group.
   */
  gap?: 4 | 8 | 12 | 16;

  /**
   * Accessible label for the ButtonGroup, improving screen reader support.
   */
  ariaLabel?: string;

  /**
   * Should the buttons within `ButtonGroup` take up the full width of its container?
   */
  isFullWidth?: boolean;
}
