import React from "react";

import { Portal } from "@radix-ui/react-dropdown-menu";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { useThemeElement } from "../../../hooks";

/**
 * When used, portals the content part into the body. By default it's arc's theme element
 */
export const MenuPortal = ({ children, ...props }: MenuPortalProps) => {
  const [themeElement, setThemeElement] = useThemeElement();
  return (
    <span ref={setThemeElement} style={{ display: "none" }}>
      <Portal container={themeElement} {...filterAttrs(props)}>
        {children}
      </Portal>
    </span>
  );
};

export interface MenuPortalProps {
  /**
   * The content to be portalled.
   */
  children: React.ReactNode;
}
