import isBefore from "date-fns/isBefore";
import isAfter from "date-fns/isAfter";
import addYears from "date-fns/addYears";
import getYear from "date-fns/getYear";

import { getFocusDate } from "../../helpers";

import { type DROPDOWN_CHANGE_YEAR_ACTION } from "../types/actions";
import { type StateHandler } from "../types/state-handler";

export const dropDownChangeYearHandler: StateHandler<
  DROPDOWN_CHANGE_YEAR_ACTION
> = (payload, state) => {
  const { year, minDate, maxDate } = payload;
  const yearsToAdd = year - getYear(state.displayDate);

  const newDisplayDate = addYears(state.displayDate, yearsToAdd);

  const focusDate = getFocusDate({
    date: addYears(state.focusDate, yearsToAdd),
    minDate: payload.minDate,
    maxDate: payload.maxDate,
  });

  if (minDate && isBefore(newDisplayDate, minDate)) {
    return {
      ...state,
      focusDate,
      displayDate: minDate,
    };
  }

  if (maxDate && isAfter(newDisplayDate, maxDate)) {
    return {
      ...state,
      focusDate,
      displayDate: maxDate,
    };
  }

  return {
    ...state,
    focusDate,
    displayDate: newDisplayDate,
  };
};
