import React, { type ReactNode, useEffect, useRef, useState } from "react";

import debounce from "lodash/debounce";
import classNames from "classnames";

import { List } from "@radix-ui/react-tabs";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { type ContentSwitcherTabProps } from "../ContentSwitcherTab";

export const ContentSwitcherList = ({
  children,
  type,
  isJustified,
  ariaLabel,
  isInset,
  ...props
}: ContentSwitcherListProps) => {
  const [rightOverflow, setRightOverflow] = useState<boolean>(false);
  const [leftOverflow, setLeftOverflow] = useState<boolean>(false);
  const [contentSwitcherListWidth, setContentSwitcherListWidth] =
    useState<number>(0);

  const tabRefs = useRef<(HTMLButtonElement | null)[]>([]);

  const listRef = useRef<HTMLDivElement>(null);

  const scrollTabIntoView = (tabRef: React.RefObject<HTMLButtonElement>) => {
    if (tabRef.current && listRef.current) {
      const scrollLeft =
        tabRef.current.offsetLeft -
        listRef.current.clientWidth / 2 +
        tabRef.current.clientWidth / 2;

      listRef.current.scrollTo({
        left: scrollLeft,
        behavior: "smooth",
      });
    }
  };

  const handleResize = debounce(() => {
    if (listRef.current) {
      setContentSwitcherListWidth(listRef.current.clientWidth);
    }
  }, 100);

  useEffect(() => {
    const list = listRef.current;
    const checkOverflow = () => {
      if (listRef.current) {
        setRightOverflow(
          listRef.current.scrollLeft + listRef.current.clientWidth <
            listRef.current.scrollWidth - 1,
        );
        setLeftOverflow(listRef.current.scrollLeft > 0);
      }
    };

    const updateLayout = () => {
      checkOverflow();
      handleResize();
    };

    // Initial check on mount
    updateLayout();

    if (list) {
      list.addEventListener("scroll", checkOverflow);
      window.addEventListener("resize", updateLayout);
    }

    return () => {
      if (list) {
        list.removeEventListener("scroll", checkOverflow);
      }
      window.removeEventListener("resize", updateLayout);
      handleResize.cancel();
    };
  }, [children, handleResize]);

  return (
    <span
      className={classNames("arc-ContentSwitcherList-wrapper", {
        "arc-ContentSwitcherList-wrapper--isInset": isInset,
      })}
      tabIndex={-1}
    >
      <List
        className={classNames("arc-ContentSwitcherList", {
          "arc-ContentSwitcherList--contained": type === "contained",
          "arc-ContentSwitcherList--isJustified": isJustified,
        })}
        ref={listRef}
        aria-label={ariaLabel}
        {...filterAttrs(props)}
      >
        <div className="arc-ContentSwitcherList-inner">
          {React.Children.map(children, (child, index) => {
            if (!React.isValidElement<ContentSwitcherTabProps>(child)) {
              return null;
            }
            if (tabRefs.current[index] !== null) {
              return React.cloneElement(child, {
                ref: (el: HTMLButtonElement) => {
                  tabRefs.current[index] = el;
                },
                onClick: () => {
                  const el = tabRefs.current[index];
                  if (el) scrollTabIntoView({ current: el });
                },
                onFocus: () => {
                  const el = tabRefs.current[index];
                  if (el) scrollTabIntoView({ current: el });
                },
              });
            } else {
              return null;
            }
          })}
        </div>
      </List>
      <span
        className="arc-ContentSwitcherList-overflowWrapper"
        style={{ width: contentSwitcherListWidth }}
      >
        {leftOverflow && (
          <div
            className="arc-ContentSwitcherList--leftOverflow"
            data-testid="arc-ContentSwitcherList--leftOverflow"
          />
        )}
        {rightOverflow && (
          <div
            className="arc-ContentSwitcherList--rightOverflow"
            data-testid="arc-ContentSwitcherList--rightOverflow"
          />
        )}
      </span>
    </span>
  );
};

export interface ContentSwitcherListProps {
  /**
   * Contents of the `ContentSwitcherList` Should contain `Tab`
   */
  children: ReactNode;

  /**
   * Determine if `ContentSwitcherList` should be justified
   */
  isJustified?: boolean;

  /**
   * Determine the type of `ContentSwitcherList`. Default is standard
   */
  type?: "standard" | "contained";

  /**
   * Determine a accessible label for `ContentSwitcherList`
   */
  ariaLabel?: string;

  /**
   * Determines if the `ContentSwitcherList` should be inset within the content panel.
   */
  isInset?: boolean;
}
