import React, {
  type ReactElement,
  type ReactNode,
  type RefObject,
  useEffect,
} from "react";

import classNames from "classnames";

import { ArcSizeBreakpointsL } from "@arc-ui/tokens-arc";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { Surface } from "../../../Surface";
import { SiteHeaderV2BackButton } from "../SiteHeaderV2BackButton";
import { ButtonV2 } from "../../../ButtonV2";
import { useMediaQuery } from "../../../../hooks/public/use-media-query";
import { handleLinkClick } from "../../../../helpers/handle-link-click";
import { useHeaderV2Context } from "../../SiteHeaderV2";

export const SiteHeaderV2Panel = ({
  children,
  navItemRef,
  isNavItem,
  open,
  setOpen,
  setOpenPanelOnFirstClick,
  subNavItemRef,
  subNavLink = "",
  title,
  subtitle,
  viewAll,
  withSubNav,
  isPrimary,
  ...props
}: SiteHeaderV2PanelProps) => {
  const isMinWidthArcBreakpointL = useMediaQuery(
    `(min-width: ${ArcSizeBreakpointsL})`,
  );
  const { menubarRef } = useHeaderV2Context();
  useEffect(() => {
    // Where appropriate, close the Panel when clicking outside of it,
    // by listening to clicks on the entire document and acting accordingly.
    const handleClick = (e: Event) => {
      // null check for navItemRef
      if (!navItemRef?.current) return;
      menubarRef?.current?.classList?.add("noFocus");
      // Don't close the Panel…
      if (
        // The click is inside the current SubNavItem.
        subNavItemRef?.current?.contains(e.target as Node) ||
        // The click is inside the current NavItem
        // and the Panel is not inside a SubNavItem.
        // and the target is not a link
        (navItemRef?.current?.contains(e.target as Node) &&
          !subNavItemRef &&
          !(e.target as Element).getAttribute("href")) ||
        // The Panel is inside a SubNavItem
        // and the click is not on a SubNavItem-link.
        // This ensures that one SubNavItem Panel per NavItem always remains open.
        (subNavItemRef &&
          !(e.target as Element).classList.contains(subNavLink) &&
          !(e.target as Element).classList.contains(`${subNavLink}Title`) &&
          !(e.target as Element).classList.contains(`${subNavLink}SubTitle`) &&
          !(e.target as Element).classList.contains(`${subNavLink}Slot`) &&
          !(e.target as Element).classList.contains(
            `${subNavLink}SlotTitle`,
          )) ||
        // Panel is inside a SubNavItem
        // and the click is not inside the Panel's NavItem parent.
        // This prevents SubNavItem Panels in sibling NavItems from being closed.
        (subNavItemRef && !navItemRef?.current.contains(e.target as Node))
      ) {
        return;
      }
      // Close the panel.
      setOpen(false);
      setOpenPanelOnFirstClick(false);
    };

    document.addEventListener("click", handleClick);

    return () => {
      document.removeEventListener("click", handleClick);
    };
  }, [
    navItemRef,
    setOpen,
    subNavItemRef,
    subNavLink,
    setOpenPanelOnFirstClick,
    menubarRef,
  ]);

  useEffect(() => {
    const handleClick = (e: Event) => {
      menubarRef?.current?.classList?.add("noFocus");
      // Close the Panel…
      if (
        (e.target as Element).classList.contains(
          "arc-SiteHeaderV2NavItem-link--itemHasChildren-closeFirstPanel",
        )
      ) {
        setOpenPanelOnFirstClick(false);
        return;
      }
      if (
        (e.target as Element).classList.contains(
          "arc-SiteHeaderV2NavItem-link--itemHasChildren-hasFirstPanel",
        ) ||
        (e.target as Element).classList.contains(
          "arc-SiteHeaderV2NavItem-link--itemHasChildren-primary",
        )
      ) {
        setOpenPanelOnFirstClick(true);
        return;
      }
    };
    document.addEventListener("click", handleClick);

    return () => {
      document.removeEventListener("click", handleClick);
    };
  }, [navItemRef, setOpenPanelOnFirstClick, menubarRef]);

  useEffect(() => {
    const handleKeydown = (e: KeyboardEvent) => {
      // Check the viewport width at time of press
      const isMinWidthArcBreakpointL = window.matchMedia(
        `(min-width: ${ArcSizeBreakpointsL})`,
      ).matches;

      if (e.key === "Escape" || e.keyCode === 27) {
        if (isMinWidthArcBreakpointL && subNavItemRef) {
          // Don't close Panels inside SubNavItems when viewport width is above
          // the "desktop" breakpoint.
          return false;
        }
        return setOpen(false);
      }
      if (e.key === "Tab") {
        menubarRef?.current?.classList?.remove("noFocus");
      }
    };

    window.addEventListener("keydown", handleKeydown);

    return () => {
      window.removeEventListener("keydown", handleKeydown);
    };
  }, [setOpen, subNavItemRef, menubarRef]);

  return (
    <div style={{ display: "flex" }}>
      <div
        className={classNames({
          [`arc-SiteHeaderV2Panel`]: true,
          [`arc-SiteHeaderV2Panel--open`]: open,
          [`arc-SiteHeaderV2Panel--withSubNav`]: withSubNav,
          [`arc-SiteHeaderV2Panel-onlyPanel`]: isPrimary && isNavItem,
          // [`arc-SiteHeaderV2Panel-slideUp`]: isPrimary && fade,
        })}
        {...filterAttrs(props)}
      >
        <Surface background="light-white">
          <SiteHeaderV2BackButton
            setOpen={setOpen}
            setOpenPanelOnFirstClick={setOpenPanelOnFirstClick}
          />
          <div
            className={classNames({
              [`arc-SiteHeaderV2Panel-inner`]: !isNavItem && withSubNav,
              [`arc-SiteHeaderV2Panel-innerWithoutSubNav`]:
                !isNavItem && !withSubNav,
              [`arc-SiteHeaderV2NavItemWithSubNav-fadeIn`]:
                !isNavItem && !withSubNav,
              [`arc-SiteHeaderV2Panel-innerNavItems`]: isNavItem,
            })}
          >
            <div
              className={classNames({
                [`arc-SiteHeaderV2Panel-main`]: !isNavItem && !withSubNav,
              })}
            >
              <div
                className={classNames({
                  [`arc-SiteHeaderV2Panel-mainInnerWithoutSubNav`]:
                    !isNavItem && !withSubNav,
                  [`arc-SiteHeaderV2Panel-mainInner`]: !isNavItem,
                  [`arc-SiteHeaderV2Panel-mainInnerNavItems`]: isNavItem,
                })}
              >
                {withSubNav && (
                  <div className="arc-SiteHeaderV2Panel-subNavArea"></div>
                )}
                {!isMinWidthArcBreakpointL && title && (
                  <div className="arc-SiteHeaderV2Panel-mobileTitleBlock">
                    <div className="arc-SiteHeaderV2Panel-mobileTitle">
                      {title && (
                        <div className="arc-SiteHeaderV2Panel-title">
                          {title}
                        </div>
                      )}
                      <div className="arc-SiteHeaderV2Panel-subTitle">
                        {subtitle}
                      </div>
                    </div>
                  </div>
                )}
                <ul
                  className={classNames({
                    [`arc-SiteHeaderV2Panel-items`]: !isNavItem,
                    [`arc-SiteHeaderV2Panel-itemsNavItems`]: isNavItem,
                    [`arc-SiteHeaderV2NavItemWithSubNav-fadeIn`]:
                      open && isNavItem,
                  })}
                >
                  {children}
                </ul>
                {!withSubNav && viewAll}
              </div>
            </div>
            {withSubNav && viewAll}
          </div>
        </Surface>
      </div>
    </div>
  );
};

export const SiteHeaderV2ViewAll = ({
  href,
  title,
  onClick,
  buttonStyle,
}: SiteHeaderV2ViewAllProps) => {
  const isMinWidthArcBreakpointL = useMediaQuery(
    `(min-width: ${ArcSizeBreakpointsL})`,
  );
  if (buttonStyle === "secondary") {
    return isMinWidthArcBreakpointL ? (
      <div className="arc-SiteHeaderV2Panel-viewAllOutlined">
        <ButtonV2
          buttonStyle={buttonStyle}
          label={title ?? ""}
          href={href}
          onClick={onClick}
        />
      </div>
    ) : (
      <div className="arc-SiteHeaderV2Panel-mobileViewAll arc-SiteHeaderV2Panel-mobileViewAllOutlined">
        <a
          className="arc-SiteHeaderV2Item-link"
          onClick={handleLinkClick({
            handler: onClick,
          })}
          href={href}
        >
          {title}
        </a>
      </div>
    );
  } else {
    return isMinWidthArcBreakpointL ? (
      <div className="arc-SiteHeaderV2Panel-viewAll">
        <ButtonV2
          buttonStyle={buttonStyle}
          label={title ?? ""}
          isFullWidth={true}
          href={href}
          onClick={onClick}
        />
      </div>
    ) : (
      <div className="arc-SiteHeaderV2Panel-mobileViewAll">
        <a
          className="arc-SiteHeaderV2Item-link"
          onClick={handleLinkClick({
            handler: onClick,
          })}
          href={href}
        >
          {title}
        </a>
      </div>
    );
  }
};

export interface SiteHeaderV2ViewAllProps {
  /**
   * URL to link to when the view all button is clicked.
   */
  href: string;
  /**
   * Title text for the view all button.
   */
  title?: string;
  /**
   * Click handler for the view all button.
   */
  onClick?: () => void;
  /**
   * Button style variant.
   */
  buttonStyle: "primary" | "secondary" | "tertiary" | "warning" | undefined;
}

export interface SiteHeaderV2PanelProps {
  /**
   * Contents of the panel.
   */
  children: ReactNode;
  /**
   * Reference to the navigation item element.
   */
  navItemRef: RefObject<HTMLLIElement | null> | null;
  /**
   * Whether this is a navigation item panel.
   */
  isNavItem: boolean;
  /**
   * Whether the panel is open.
   */
  open: boolean;
  /**
   * Function to set the open state of the panel.
   */
  setOpen: (arg0: boolean) => any;
  /**
   * Function to set whether the panel should open on first click.
   */
  setOpenPanelOnFirstClick: (arg0: boolean) => any;
  /**
   * Reference to the sub navigation item element.
   */
  subNavItemRef?: RefObject<HTMLElement | null>;
  /**
   * CSS class name for the sub navigation link.
   */
  subNavLink?: string;
  /**
   * Title to display in the panel.
   */
  title?: ReactNode;
  /**
   * View all button element to display in the panel.
   */
  viewAll?: ReactElement;
  /**
   * Whether the panel has sub navigation.
   */
  withSubNav?: boolean;
  /**
   * Subtitle to display in the panel.
   */
  subtitle?: ReactNode;
  /**
   * Whether this is a primary panel.
   */
  isPrimary?: boolean;
}
