"use client";

import React, { type ReactNode } from "react";

import { isDate, format } from "date-fns";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { ArcIconSocialLinkedin } from "@arc-ui/icons/ArcIconSocialLinkedin";

import { ArcIconSocialYouTube } from "@arc-ui/icons/ArcIconSocialYouTube";

import { ArcIconSocialX } from "@arc-ui/icons/ArcIconSocialX";

import { ArcIconSocialInstagram } from "@arc-ui/icons/ArcIconSocialInstagram";

import { ArcIconSocialFacebook } from "@arc-ui/icons/ArcIconSocialFacebook";

import { BrandLogo } from "../../../BrandLogo";

import { Icon } from "../../../Icon";

import { handleLinkClick } from "../../../../helpers/handle-link-click";

/**
 * Use `SiteFooterV2.Utility` to display information at the bottom of a page.
 */
export const SiteFooterV2Utility = ({
  copyrightYear,
  children,
  socialLinks,
  brand = {
    logoLabel: "BT",
    href: "/",
  },
  contentSlot,
  ...props
}: SiteFooterV2UtilityProps) => {
  return (
    <div
      className="arc-SiteFooterV2-utility"
      aria-label="Footer utility bar"
      {...filterAttrs(props)}
    >
      <div className="arc-SiteFooterV2-brand">
        {!contentSlot && (
          <>
            <a
              className="arc-SiteFooterV2-brandLogo"
              onClick={handleLinkClick({ handler: brand.onClick })}
              href={brand.href}
              tabIndex={brand.href ? 0 : -1}
            >
              <BrandLogo
                label={brand.logoLabel}
                aria-label={brand.logoLabel}
                color="brand"
                subBrand={brand.subBrand}
              />
            </a>
            <div className="arc-SiteFooterV2-copyright">
              <span className="arc-SiteFooterV2-copyrightSymbol">©</span>{" "}
              {brand.logoLabel}{" "}
              {isDate(copyrightYear) ? (
                <time dateTime={format(copyrightYear as Date, "yyyy")}>
                  {format(copyrightYear as Date, "yyyy")}
                </time>
              ) : (
                <span>{copyrightYear as string}</span>
              )}
              {!copyrightYear && `${new Date().getFullYear()}`}
            </div>
          </>
        )}
        {contentSlot && (
          <div className="arc-SiteFooterV2-contentSlot">{contentSlot}</div>
        )}
      </div>
      {children && (
        <nav aria-label="Footer utility links">
          <ul className="arc-SiteFooterV2-utilityItems">{children}</ul>
        </nav>
      )}
      {socialLinks && (
        <ul
          className="arc-SiteFooterV2-utilitySocials"
          aria-label="Footer social media links"
        >
          {socialLinks.map(({ href, icon, ariaLabel }, index) => (
            <li
              key={index}
              tabIndex={0}
              className="arc-SiteFooterV2-utilitySocialsLink"
            >
              <a
                className="arc-SiteFooterV2-link"
                href={href}
                tabIndex={-1}
                aria-label={ariaLabel}
              >
                <Icon icon={icon} size={16} />{" "}
              </a>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export const socialIcons = [
  ArcIconSocialFacebook,
  ArcIconSocialInstagram,
  ArcIconSocialLinkedin,
  ArcIconSocialX,
  ArcIconSocialYouTube,
] as const;

export const subBrands = ["redcare", "wholesale", "ee"] as const;

export interface SiteFooterV2UtilityProps {
  /**
   * T&C links of the SiteFooterV2Utility. Must be SiteFooterV2Item components.
   */
  children?: ReactNode;

  /**
   * Date to show adjacent to the copyright symbol, can be either a date or text. Its recommended to pass dates as Date objects so the component can render them correctly.
   */
  copyrightYear?: string | Date;

  /**
   * Options for other brands and label.
   */
  brand?: {
    subBrand?: (typeof subBrands)[number];
    logoLabel?: string;
    onClick?: () => void;
    href?: string;
  };

  /**
   * Add social media links and desired Icons (Facebook, X (Twitter), LinkedIn, Instagram and Youtube).
   */
  socialLinks?: {
    href: string;
    icon: (typeof socialIcons)[number];
    ariaLabel: string;
  }[];

  /**
   * A content slot to accept react node. Will override the brand logo.
   */
  contentSlot?: ReactNode;
}
