import React, { useContext } from "react";

import classNames from "classnames";

import { Icon, type IconColor } from "../Icon";
import { SurfaceContext } from "../Surface";
import { Spinner } from "../Spinner";

export type ElementUnion = HTMLButtonElement | HTMLAnchorElement;
export type ButtonRef = React.Ref<ElementUnion> | null;
type AnchorElProps = React.AnchorHTMLAttributes<HTMLAnchorElement>;
type ButtonElProps = React.ButtonHTMLAttributes<HTMLButtonElement>;
type CommonElProps = AnchorElProps & ButtonElProps & { ref?: ButtonRef | null };

/**
 * Use `ButtonV2` for our most up to date Call To Action button, offering Primary, Secondary, Tertiary, Compact and Error states.
 */
export const ButtonV2 = ({
  label,
  buttonStyle = "primary",
  icon,
  iconActive,
  iconPosition = "beforeText",
  size = "m",
  ariaLabel,
  ariaControls,
  ariaExpanded,
  ariaHasPopup,
  isFullWidth = false,
  isLoading = false,
  isSpan,
  onClick,
  href,
  id,
  rel,
  target,
  type,
  form,
  ref,
  ...props
}: ButtonV2Props) => {
  const { surface } = useContext(SurfaceContext);

  const ButtonElement = isSpan ? "span" : "button";

  const iconSizes = {
    s: 16,
    m: 32,
    l: 40,
  };

  const ButtonV2Classes = classNames(
    "arc-ButtonV2",
    [`arc-ButtonV2--${buttonStyle}`],
    [`arc-ButtonV2--${size}`],
    {
      "arc-ButtonV2--onDarkSurface": surface === "dark",
      "arc-ButtonV2--emptyLabel": !label,
      "arc-ButtonV2--isLoading": isLoading,
      "arc-ButtonV2--isFullWidth": isFullWidth,
      "arc-ButtonV2--withIcon": icon || isLoading,
      "arc-ButtonV2--withIconBeforeText":
        iconPosition === "beforeText" && (icon || isLoading),
    },
  );

  const commonProps: CommonElProps = {
    id,
    onClick,
    ref,
    ...props, // props not filtered for radix asChild behaviour
  };

  const getIconColor = (buttonStyle: ButtonStyle): IconColor => {
    switch (buttonStyle) {
      case "compact":
      case "secondary":
      case "tertiary":
        return "brand-alt";

      default:
        return "auto";
    }
  };

  const renderButtonContent = () => (
    <span
      className={classNames("arc-ButtonV2-inner", {
        "arc-ButtonV2-inner--iconBeforeText": iconPosition === "beforeText",
      })}
    >
      {label && <span className="arc-ButtonV2-label">{label}</span>}
      {isLoading && (
        <span className="arc-ButtonV2-icon">
          <Spinner size={size} />
        </span>
      )}
      {icon && !isLoading && (
        <>
          <span
            className={classNames("arc-ButtonV2-icon", {
              "arc-ButtonV2-icon--hasActive": iconActive,
            })}
          >
            <Icon
              color={getIconColor(buttonStyle)}
              size={iconSizes[size]}
              icon={icon}
            />
          </span>
          {iconActive && (
            <span className="arc-ButtonV2-icon--active">
              <Icon
                color={getIconColor(buttonStyle)}
                size={iconSizes[size]}
                icon={iconActive}
              />
            </span>
          )}
        </>
      )}
    </span>
  );

  if (href && !isLoading) {
    return (
      <a
        {...(commonProps as AnchorElProps)}
        className={ButtonV2Classes}
        href={href}
        rel={rel}
        aria-haspopup={ariaHasPopup}
        aria-controls={ariaControls}
        aria-expanded={ariaExpanded}
        aria-label={ariaLabel}
        target={target}
      >
        {renderButtonContent()}
      </a>
    );
  }
  return (
    <ButtonElement
      {...(commonProps as ButtonElProps)}
      className={ButtonV2Classes}
      aria-label={ariaLabel}
      aria-haspopup={ariaHasPopup}
      aria-controls={ariaControls}
      aria-expanded={ariaExpanded}
      disabled={isLoading}
      type={type}
      form={form}
    >
      {renderButtonContent()}
    </ButtonElement>
  );
};

interface LinkElementProps {
  /**
   * URL to link to if `ButtonV2` elementType is 'a'.
   */
  href?: string;

  /**
   * Target window for the `ButtonV2` href URL.
   */
  target?: string;

  /**
   * Relationship between the Button href URL and the current page. See
   * [MDN](https://developer.mozilla.org/en-US/docs/Web/HTML/Attributes/rel).
   */
  rel?: string;
}

interface ButtonV2ElementProps {
  /**
   * Default behavior of the Button element. If not provided, 'submit' will
   * be inferred. Type 'reset' deliberately excluded.
   */
  type?: "button" | "submit";

  /**
   * Refers to the id of a form so it can be submitted if the button exists outside of it.
   */
  form?: string;
}

type ButtonStyle = "primary" | "secondary" | "tertiary" | "warning" | "compact";

export interface ButtonV2Props extends ButtonV2ElementProps, LinkElementProps {
  /**
   * Label for `ButtonV2`
   */
  label?: string;

  /**
   * Determine the buttonStyle for `ButtonV2`. Default style is `primary`
   */
  buttonStyle?: ButtonStyle;

  /**
   * Render icon within `ButtonV2`
   */
  icon?: string;

  /**
   * Render icon within `ButtonV2` when the button is active.
   */
  iconActive?: string;

  /**
   * Determine the style position for the icon. Default is `afterText`
   */
  iconPosition?: "beforeText" | "afterText";

  /**
   * Optional click handler for the `ButtonV2`.
   */
  onClick?: () => void;

  /**
   * Optional property to provide component Ref
   */
  ref?: ButtonRef;

  /**
   * Should the `ButtonV2` take up the full width of its container?
   */
  isFullWidth?: boolean;

  /**
   * Text to override `label` with additional, more precise information
   * specifically for screen reader users.
   */
  ariaLabel?: string;

  /**
   * Size of `ButtonV2`
   */
  size?: "l" | "m" | "s";

  /**
   * HTML ID for the `ButtonV2`
   */
  id?: string;

  /**
   * `ButtonV2` will be in a loading state. This will override / add a loading icon to the button in it's respective style
   */
  isLoading?: boolean;

  /**
   * Indicates the availability and type of a popup triggered by the button.
   */
  ariaHasPopup?: false | true | "menu" | "listbox" | "dialog" | "grid" | "tree";

  /**
   * Indicates whether the popup controlled by the button is expanded or collapsed.
   */
  ariaExpanded?: boolean;

  /**
   * Defines the ID of the element controlled by the button.
   */
  ariaControls?: string;

  /**
   * Render `ButtonV2` as a span
   */
  isSpan?: boolean;
}
