import React from "react";

import classNames from "classnames";

import { Surface } from "../../../Surface";

export const CalendarWrapper = ({
  uncontained,
  children,
}: CalendarWrapperProps) => (
  <div
    className={classNames("arc-CalendarWrapper", {
      "arc-CalendarWrapper--uncontained": uncontained,
    })}
  >
    <Surface background="light-white">
      <div className="arc-CalendarWrapper-inner">{children}</div>
    </Surface>
  </div>
);

export interface CalendarWrapperProps {
  /**
   * Content to display in the wrapper
   */
  children: React.ReactNode;
  /**
   * Whether the wrapper should be uncontained
   */
  uncontained?: boolean;
}
