import { createContext, useContext } from "react";

interface SplitButtonContextValue {
  /**
   * Whether the button is in a loading state
   */
  isLoading?: boolean;
  /**
   * The size of the button
   */
  size?: "s" | "m" | "l";
  /**
   * The visual style variant of the `SplitButton`.
   */
  buttonStyle?: "primary" | "secondary" | "tertiary" | "compact";
  /**
   * Set the `SplitButtonPrimary` to fill the width of the `SplitButton`'s container.
   */
  isFullWidth?: boolean;
  /**
   * The surface context for styling the button appropriately
   */
  surface?: "light" | "dark";
}

const SplitButtonContext = createContext<SplitButtonContextValue>({});

export const useSplitButton = () => useContext(SplitButtonContext);
export { SplitButtonContext };
