import React, { useId } from "react";

import * as RadixTabs from "@radix-ui/react-tabs";

import classNames from "classnames";

import { Heading } from "../../../Heading";
import { VerticalSpace } from "../../../VerticalSpace";

import { type NavigationHeaderMegaMenuNavItem } from "../../types/nav-item";

import { NavigationHeaderPanelHeading } from "../NavigationHeaderPanelHeading";
import { NavigationHeaderFeatureCard } from "../NavigationHeaderFeatureCard";
import { NavigationHeaderCollapsingNavList } from "../NavigationHeaderCollapsingNavList";

import {
  NavigationHeaderSubnav,
  NavigationHeaderSubnavContent,
  NavigationHeaderSubnavTrigger,
} from "../NavigationHeaderSubnav";

import { NavigationHeaderPanelLink } from "../NavigationHeaderPanelLink";

import { type MegaMenuTab } from "../../types/mega-menu-tab";

export const NavigationHeaderMegaMenu = ({
  tabs,
  panelHeading,
  featureCards,
  onClick,
  onOpenChange,
  ariaLabel,
  text,
}: NavigationHeaderMegaMenuProps) => {
  const id = useId();

  const getColumns = (tab: MegaMenuTab) => [
    tab.items.filter((_, i) => i % 2 === 0),
    tab.items.filter((_, i) => i % 2 === 1),
  ];

  return (
    <NavigationHeaderSubnav onOpenChange={onOpenChange}>
      <NavigationHeaderSubnavTrigger ariaLabel={ariaLabel} onClick={onClick}>
        {text}
      </NavigationHeaderSubnavTrigger>

      <NavigationHeaderSubnavContent
        background="lightElevatedTight"
        description="Use tab and arrow keys to navigate. Press Escape to close."
        menuTitle={text}
      >
        <div className="arc-NavigationHeaderMegaMenu">
          <div className="arc-NavigationHeaderMegaMenu-navCol">
            <NavigationHeaderPanelHeading {...panelHeading} />
            <RadixTabs.Root
              orientation="vertical"
              className="arc-NavigationHeaderMegaMenu-nav"
              defaultValue={`${tabs[0].triggerText}-${0}`}
            >
              <div className="arc-NavigationHeaderMegaMenu-tabs">
                <RadixTabs.List className="arc-NavigationHeaderMegaMenu-tabList">
                  {tabs.map((item, i) => (
                    <RadixTabs.Trigger
                      key={`${id}-NavigationHeader-megamenu-trigger-${i}`}
                      id={`${id}-NavigationHeader-megamenu-trigger-${i}`}
                      className="arc-NavigationHeaderMegaMenu-tab"
                      aria-label={item.triggerText}
                      value={`${item.triggerText}-${i}`}
                      onClick={item.onClick}
                    >
                      <Heading size="xs">{item.triggerText}</Heading>
                    </RadixTabs.Trigger>
                  ))}
                </RadixTabs.List>
              </div>

              <div className="arc-NavigationHeaderMegaMenu-mainContent">
                <div className="arc-NavigationHeaderMegaMenu-linksPanel">
                  {tabs.map((tab, i) => (
                    <RadixTabs.Content
                      tabIndex={-1}
                      className="arc-NavigationHeaderMegaMenu-content"
                      key={`${id}-NavigationHeader-megamenu-content-${i}`}
                      value={`${tab.triggerText}-${i}`}
                      aria-labelledby={`${id}-NavigationHeader-megamenu-trigger-${i}`}
                    >
                      <NavigationHeaderPanelLink
                        {...tab.panelLink}
                        icon={tab.icon}
                      />

                      <VerticalSpace size="32" />

                      <div className="arc-NavigationHeaderMegaMenu-linksContainer">
                        {getColumns(tab).map((items, itemIndex) => (
                          <div
                            className="arc-NavigationHeaderMegaMenu-linksColumn"
                            key={`column-${itemIndex}`}
                          >
                            {items.map((item, i) => (
                              <NavigationHeaderCollapsingNavList
                                {...item}
                                defaultOpen
                                revealLinkIconOnHover
                                autoFocusOnExpand={false}
                                background="light"
                                key={`${id}-NavigationHeader-megamenu-item-${i}`}
                              />
                            ))}
                          </div>
                        ))}
                      </div>
                    </RadixTabs.Content>
                  ))}
                </div>
              </div>
            </RadixTabs.Root>
          </div>
          <div className="arc-NavigationHeaderMegaMenu-featureCol">
            {featureCards && (
              <div
                className={classNames(
                  "arc-NavigationHeaderMegaMenu-featureCardsPanel",
                  {
                    "arc-NavigationHeaderMegaMenu-featureCardsPanel--equalWidthColumns":
                      featureCards.length <= 3,
                    "arc-NavigationHeaderMegaMenu-featureCardsPanel--manyColumns":
                      featureCards.length > 3,
                  },
                )}
              >
                {featureCards.map((card, i) => (
                  <NavigationHeaderFeatureCard
                    key={`${id}-NavigationHeader-megamenu-featureCard-${i}`}
                    {...card}
                  />
                ))}
              </div>
            )}
          </div>
        </div>
      </NavigationHeaderSubnavContent>
    </NavigationHeaderSubnav>
  );
};

type NavigationHeaderMegaMenuProps = Omit<
  NavigationHeaderMegaMenuNavItem,
  "type" | "visibleFrom"
>;
