import React, { useContext, useState } from "react";

import classNames from "classnames";
import {
  Root,
  Thumb,
  type SwitchProps as RadixSwitchProps,
} from "@radix-ui/react-switch";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { SurfaceContext } from "../Surface/Surface";
import { FormControl } from "../FormControl";
import { type FormControlProps } from "../FormControl/FormControl";
import { VerticalSpace } from "../VerticalSpace";
import { ThemeIcon } from "../ThemeIcon";

/** Use `Switch` to allow users to immediately toggle between two states. */
export const Switch = ({
  defaultChecked,
  onCheckedChange,
  label,
  labelPosition = "top",
  name,
  onBlur,
  value,
  isDisabled = false,
  errorMessage,
  id,
  size = "m",
  onStatusText,
  offStatusText,
  hideLabel = false,
  ariaLabel,
  ...props
}: SwitchProps) => {
  const [switchState, setSwitchState] = useState(defaultChecked);
  const { surface } = useContext(SurfaceContext);

  if (!onStatusText) {
    onStatusText = offStatusText;
  }
  if (!offStatusText) {
    offStatusText = onStatusText;
  }

  const onCheckedHandler = (checked: boolean) => {
    setSwitchState((previous) => !previous);
    onCheckedChange && onCheckedChange(checked);
  };

  return (
    <FormControl
      errorMessage={errorMessage}
      htmlFor={id}
      isDisabled={isDisabled}
      label={label}
      hideLabel={hideLabel}
      labelSize={size}
      labelPosition={labelPosition}
      requirementStatus={"not-applicable"}
    >
      {!hideLabel && <VerticalSpace size="12" />}
      <div className="arc-Switch-container">
        <Root
          id={id}
          defaultChecked={defaultChecked}
          name={name}
          value={value}
          onBlur={onBlur}
          onCheckedChange={onCheckedHandler}
          checked={switchState}
          disabled={isDisabled}
          className={classNames("arc-Switch", {
            "arc-Switch--medium": size === "m",
            "arc-Switch--isDisabled": isDisabled,
            "arc-Switch--onDarkSurface": surface === "dark",
          })}
          aria-label={ariaLabel}
          {...filterAttrs(props)}
        >
          <div className="arc-Switch-wrapper">
            <Thumb className="arc-Switch-thumb">
              <div className="arc-Switch-thumbIcon">
                <div
                  className="arc-Switch-icon"
                  data-testid="arc-switch-thumb-icon"
                >
                  <ThemeIcon
                    icon="switchToggle"
                    size={size === "m" ? 32 : 24}
                  ></ThemeIcon>
                </div>
              </div>
            </Thumb>
          </div>
          {(onStatusText || offStatusText) && (
            <div
              className={classNames("arc-Switch-statusText", {
                "arc-Switch-statusText--isDisabled": isDisabled,
                "arc-Switch-statusText--onDarkSurface": surface === "dark",
                [`arc-Switch-statusText--${size}`]: size === "m",
              })}
            >
              <p aria-hidden>{switchState ? onStatusText : offStatusText}</p>
            </div>
          )}
        </Root>
      </div>
    </FormControl>
  );
};

export interface SwitchProps extends Omit<
  FormControlProps,
  | "children"
  | "elementType"
  | "htmlFor"
  | "requirementStatus"
  | "disclosureText"
  | "disclosureTitle"
  | "onClickDisclosure"
  | "helper"
  | "helpUnderLabel"
  | "supplementaryInfo"
  | "labelSize"
> {
  /**
   * Hide Label above toggle?
   */
  hideLabel?: boolean;

  /**
   * Position of Label
   */
  labelPosition?: "top" | "left";

  /**
   * Text to display next to `Switch` when checked. If no value is provided onStatusText will equal offStatusText.
   */
  onStatusText?: string;

  /**
   * Text to display next to `Switch` when unchecked. If no value is provided offStatusText will equal onStatusText.
   */
  offStatusText?: string;

  /**
   * Should the `Switch` be disabled?
   */
  isDisabled?: FormControlProps["isDisabled"];

  /**
   * handler for blur
   */
  onBlur?: RadixSwitchProps["onBlur"];
  /**
   * Size of the Switch.
   */
  size?: "m" | "s";

  /**
   * set the switch to be checked by default
   */
  defaultChecked?: RadixSwitchProps["defaultChecked"];

  /**
   * value for the switch, is applied to a hidden checkbox if within a form
   */
  value?: RadixSwitchProps["value"];

  /**
   * name for the hidden checkbox if within a form
   */
  name?: RadixSwitchProps["name"];

  /**
   * Aria label to add a description to the switch button
   */
  ariaLabel?: string;

  /**
   * callback for when the switch is toggled
   */
  onCheckedChange?: RadixSwitchProps["onCheckedChange"];
}
