import React from "react";

import * as RadixTooltip from "@radix-ui/react-tooltip";

import { useThemeElement } from "../../hooks";
import { Surface } from "../Surface";

import { Icon } from "../Icon";
import { Text } from "../Text";

/** Use `Tooltip` to display information related to an element when the element receives keyboard focus or the mouse hovers over it */
export const Tooltip = ({
  children,
  side,
  sideOffset,
  align,
  alignContent,
  title,
  supportingCopy,
  icon,
  ariaLabel,
  maxWidth = "450px",
  delayDuration = 300,
  open,
  onOpenChange,
  asChild = false,
  zIndex = 100,
  ...props
}: TooltipProps) => {
  const [themeElement, setThemeElement] = useThemeElement();

  return (
    <RadixTooltip.TooltipProvider>
      <RadixTooltip.Root
        delayDuration={delayDuration}
        open={open}
        onOpenChange={onOpenChange}
        {...props} // props not filtered for radix asChild behaviour
      >
        <RadixTooltip.Trigger
          asChild={asChild}
          aria-label={ariaLabel}
          className="arc-Tooltip-trigger"
        >
          {children}
        </RadixTooltip.Trigger>
        <div ref={setThemeElement}>
          <RadixTooltip.Portal container={themeElement}>
            <RadixTooltip.Content
              side={side}
              sideOffset={sideOffset}
              align={align}
              alignOffset={
                align === "start" ? -4 : align === "end" ? -4 : undefined
              }
              style={{ zIndex: zIndex }}
              {...props}
            >
              <Surface background="dark-neutral-01" isTransparent>
                <div
                  className="arc-Tooltip-content"
                  style={{ maxWidth: maxWidth }}
                >
                  <div
                    className="arc-Tooltip-title"
                    style={{
                      display: "flex",
                      gap: 4,
                      alignItems: "center",
                      justifyContent: alignContent,
                    }}
                  >
                    {icon && (
                      <div style={{ flexShrink: 0 }}>
                        <Icon icon={icon} size={24} />
                      </div>
                    )}
                    <Text size="s">{title}</Text>
                  </div>
                  <div
                    style={{
                      display: "flex",
                      justifyContent: alignContent || "center",
                    }}
                  >
                    <Text tone="supporting" size="s">
                      {supportingCopy}
                    </Text>
                  </div>

                  <RadixTooltip.Arrow className="arc-Tooltip-arrow" />
                </div>
              </Surface>
            </RadixTooltip.Content>
          </RadixTooltip.Portal>
        </div>
      </RadixTooltip.Root>
    </RadixTooltip.TooltipProvider>
  );
};

export interface TooltipProps {
  /**
   * Content to render within Tooltip
   */
  children?: React.ReactNode;

  /**
   * The preferred side of the anchor to render against when open
   */
  side?: "left" | "right" | "bottom" | "top";

  /**
   * The distance in pixels from the anchor
   */
  sideOffset?: 8 | 16 | 32;

  /**
   * The preferred alignment against the anchor. May change when collisions occur.
   */
  align?: "start" | "center" | "end";

  /**
   * Alignment for content within the tooltip
   */
  alignContent?: "start" | "center" | "end";

  /**
   * Aria label for accessibility
   */
  ariaLabel?: string;

  /**
   * The main title text displayed within the tooltip.
   */
  title: string;

  /**
   * Additional supporting text displayed below the title, if provided.
   */
  supportingCopy?: string;

  /**
   * Icon displayed next to the tooltip title or content.
   */
  icon?: string;

  /**
   * Delay in milliseconds before the tooltip appears.
   */
  delayDuration?: number;

  /**
   * Maximum width for the tooltip container.
   */
  maxWidth?: string;

  /**
   * The controlled open state of the tooltip. Must be used in conjunction with `onOpenChange`.
   */
  open?: boolean;

  /**
   * Event handler called when the open state of the tooltip changes.
   */
  onOpenChange?: (open: boolean) => void;

  /**
   * Z-index for the `Tooltip`. Used to fine tune the overlapping of other page elements.
   */
  zIndex?: number;

  /**
   * Set to true if you want to use your own link or button for the trigger. If false it will wrap the children in a button.
   */
  asChild?: boolean;
}
