import React, {
  type KeyboardEvent,
  useCallback,
  useContext,
  useRef,
} from "react";

import classNames from "classnames";

import addDays from "date-fns/addDays";
import isSameMonth from "date-fns/isSameMonth";
import startOfMonth from "date-fns/startOfMonth";
import endOfMonth from "date-fns/endOfMonth";
import eachWeekOfInterval from "date-fns/eachWeekOfInterval";
import eachDayOfInterval from "date-fns/eachDayOfInterval";

import { dateWithoutTime } from "../../helpers";

import { KeyNames } from "../../types";

import { Text } from "../../../Text";
import { DAY_NAMES } from "../../constants";
import { CalendarDayNumber } from "../CalendarDayNumber";
import { ArcCalendarContext } from "../../Calendar.provider";
import { VisuallyHidden } from "../../../VisuallyHidden";

export const CalendarDayGrid = ({ displayRange }: CalendarDayGridProps) => {
  const hasAutoFocused = useRef<boolean>(false);
  const dayNumberGridRef = useRef<HTMLDivElement | null>(null);
  const context = useContext(ArcCalendarContext);
  const autoFocusRef = useCallback(
    (el: HTMLTableCellElement) => {
      if (
        el &&
        el.tabIndex === 0 &&
        context?.autoFocusOnMount &&
        !hasAutoFocused.current
      ) {
        el.focus();
      }

      if (document.activeElement === el) {
        hasAutoFocused.current = true;
      }
    },
    [context?.autoFocusOnMount],
  );

  if (!context) {
    return null;
  }

  const { onKeyboardNavigate, onDayNumberClick, onDayGridLeave } = context;

  const isFocusWithinDayGrid = Boolean(
    dayNumberGridRef &&
    dayNumberGridRef.current &&
    dayNumberGridRef.current.contains(document.activeElement),
  );

  const handleKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    const key = e.key as KeyNames;
    const newDate = (e.target as HTMLDivElement).getAttribute("data-date");

    if (key === KeyNames.Tab) {
      return;
    }

    if (Object.values(KeyNames).includes(key)) {
      e.preventDefault();
    }

    if ([KeyNames.Space, KeyNames.Enter].includes(key) && newDate) {
      onDayNumberClick(dateWithoutTime(new Date(parseInt(newDate))))();
    } else {
      onKeyboardNavigate(e.key, e.shiftKey);
    }
  };

  const getWeeksInMonth = (month: Date) =>
    eachWeekOfInterval(
      { start: startOfMonth(month), end: endOfMonth(month) },
      { weekStartsOn: 1 },
    ).map((week) => eachDayOfInterval({ start: week, end: addDays(week, 6) }));

  return (
    <div
      ref={dayNumberGridRef}
      onMouseLeave={onDayGridLeave}
      className={classNames("arc-CalendarDayGrid", {
        "arc-CalendarDayGrid--dual": displayRange.length > 1,
      })}
    >
      {displayRange.map((month) => (
        <div key={month.getTime()} className="arc-CalendarDayGrid-month">
          <table className="arc-CalendarDayGrid-table">
            <thead>
              <tr>
                {DAY_NAMES.map((dayName) => (
                  <th key={`${month.getTime()}-${dayName.displayValue}`}>
                    <Text key={dayName.displayValue} size="s">
                      <b aria-hidden>{dayName.displayValue}</b>
                    </Text>

                    <VisuallyHidden>{dayName.value}</VisuallyHidden>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody onKeyDown={handleKeyDown}>
              {getWeeksInMonth(month).map((week, i) => (
                <tr key={`${month.getTime()}-week-${i}`}>
                  {week.map((day) => (
                    <CalendarDayNumber
                      ref={autoFocusRef}
                      shouldRender={isSameMonth(month, day)}
                      key={day.getTime()}
                      date={day}
                      isFocusWithinDayGrid={isFocusWithinDayGrid}
                    />
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ))}
    </div>
  );
};

interface CalendarDayGridProps {
  /**
   * Array of dates to display in the grid
   */
  displayRange: Date[];
}
