import { createContext, useContext, type ChangeEvent } from "react";

type EventType = ChangeEvent<HTMLInputElement>;

export type ContextProps = {
  blurEvent: (event: EventType) => void;
  changeEvent: (event: EventType) => void;
  groupDisabled: boolean;
  checkedValue?: string;
  name: string;
  size: "l" | "s";
};

const RadioContext = createContext({} as ContextProps);

export const { Provider } = RadioContext;

export const useRadioContext = () => {
  const context = useContext(RadioContext);

  return context;
};
