import compareAsc from "date-fns/compareAsc";

import eachDayOfInterval from "date-fns/eachDayOfInterval";

import { type RangeSelection } from "../types";

import { containsDate } from "./contains-date";

export const processSelectedRange = ({
  range,
  value,
  disabledDates,
}: {
  range: Date[];
  value: Date;
  disabledDates?: Date[];
}) => {
  const exisitingRange = range.filter((date) => Boolean(date));

  const newRange = [
    ...(exisitingRange.length === 2 ? [] : exisitingRange),
    value,
  ].sort(compareAsc);

  const isSelectionComplete = newRange.length === 2;

  const allDaysInRange = isSelectionComplete
    ? eachDayOfInterval({
        start: newRange[0],
        end: newRange[1],
      })
    : [];

  const rangeOnChangeValue: RangeSelection = {
    dates: allDaysInRange.map((date) => ({
      value: date,
      disabled: disabledDates ? containsDate(disabledDates, date) : false,
    })),
    selectedDate: value,
    start: newRange[0],
    end: newRange[1],
    isSelectionComplete,
  };

  return {
    rangeValue: newRange,
    rangeOnChangeValue,
  };
};
