import React from "react";

import { RadioItem } from "@radix-ui/react-dropdown-menu";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { BtIconTickAlt2Px } from "@arc-ui/icons";

import {
  MenuItemContentTemplate,
  type MenuItemContentTemplateProps,
} from "../MenuItemContentTemplate/MenuItemContentTemplate";

/**
 * A selectable menu item used within a radio group.
 */

export const MenuItemSingleSelect = ({
  children,
  value,
  disabled = false,
  onSelect,
  leadingIcon,
  supportingText,
  shouldKeepOpen = true,
  ...props
}: MenuItemSingleSelectProps) => {
  return (
    <RadioItem
      className="arc-MenuItem arc-MenuItemSingleSelect"
      value={value}
      disabled={disabled}
      onSelect={(event) => {
        if (shouldKeepOpen) {
          event.preventDefault();
        }

        onSelect?.();
      }}
      {...filterAttrs(props)}
    >
      <MenuItemContentTemplate
        leadingIcon={leadingIcon}
        supportingText={supportingText}
        trailingIcon={BtIconTickAlt2Px}
      >
        {children}
      </MenuItemContentTemplate>
    </RadioItem>
  );
};

export interface MenuItemSingleSelectProps extends Omit<
  MenuItemContentTemplateProps,
  "trailingIcon"
> {
  /**
   * The value assigned to this radio item.
   */
  value: string;

  /**
   * Whether the radio item is disabled.
   */
  disabled?: boolean;

  /**
   * Callback function triggered when the item is selected.
   */
  onSelect?: () => void;
  /**
   * Prevents the menu from closing when this item is selected.
   */
  shouldKeepOpen?: boolean;
}
