import React, { useId } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { Avatar } from "../Avatar";

import { ConditionalWrapper } from "../ConditionalWrapper";

import { type AvatarSize } from "../Avatar/types/avatar-size";

import { getAvatars } from "./utils/get-avatars";

import { type GroupAvatar } from "./types/group-avatar";

/** Use `AvatarGroup` to visually represent a group of users. */
export const AvatarGroup = ({
  title,
  ariaLabel = "avatar group",
  href,
  avatars,
  onClick,
  max,
  size = "xl",
  ...props
}: AvatarGroupProps) => {
  const id = useId();
  const wrapperAttrs: React.HTMLAttributes<HTMLDivElement | HTMLAnchorElement> =
    {
      className: "arc-AvatarGroup",
      ...filterAttrs(props),
    };

  return (
    <ConditionalWrapper
      condition={Boolean(href)}
      wrapper={(children) => (
        <a
          href={href}
          aria-label={ariaLabel}
          onClick={onClick}
          title={title}
          {...wrapperAttrs}
        >
          {children}
        </a>
      )}
      fallback={(children) => (
        <div {...wrapperAttrs} aria-label={ariaLabel}>
          {children}
        </div>
      )}
    >
      <div className="arc-AvatarGroup-avatarContainer">
        {getAvatars(avatars, max).map((props, i) => (
          <div
            key={`${id}-avatar-${i}`}
            className={classNames(
              "arc-AvatarGroup-avatar",
              `arc-AvatarGroup-avatar--${size}`,
            )}
          >
            <Avatar size={size} {...props} />
          </div>
        ))}
      </div>
    </ConditionalWrapper>
  );
};

export interface AvatarGroupProps {
  /**
   * Array of avatars to display in the group.
   */
  avatars: GroupAvatar[];
  /**
   * Size of the avatars in the group.
   */
  size?: AvatarSize;
  /**
   * Maximum number of avatars to display before showing a count.
   */
  max?: number;
  /**
   * Title attribute for the avatar group link.
   */
  title?: string;
  /**
   * Accessible label for the avatar group.
   */
  ariaLabel?: string;
  /**
   * URL to link to when the avatar group is clicked.
   */
  href?: string;
  /**
   * Click handler for the avatar group link.
   */
  onClick?: (e: React.MouseEvent<HTMLAnchorElement, MouseEvent>) => void;
}
