import isWithinInterval from "date-fns/isWithinInterval";
import getYear from "date-fns/getYear";
import setYear from "date-fns/setYear";
import startOfMonth from "date-fns/startOfMonth";
import endOfMonth from "date-fns/endOfMonth";
import isEqual from "date-fns/isEqual";

import {
  getFocusDate,
  getHighlightRange,
  getKeyDownDate,
  getDoubleMonthDisplayRange,
} from "../../helpers";

import { type CALENDAR_KEYDOWN_ACTION } from "../types/actions";
import { type StateHandler } from "../types/state-handler";
import { KeyNames } from "../../types";

export const calendarKeydownHandler: StateHandler<CALENDAR_KEYDOWN_ACTION> = (
  payload,
  state,
) => {
  const { displayDate, focusDate, highlightedRange } = state;
  const {
    minDate,
    maxDate,
    calendarType,
    key,
    shiftKey,
    range,
    selectionType,
  } = payload;

  const isNavigatingByYear =
    shiftKey && [KeyNames.PageUp, KeyNames.PageDown].includes(key);

  const keyDownDate = getKeyDownDate({
    focusDate: focusDate,
    key,
    shiftKey,
  });

  const newFocusDate = getFocusDate({
    minDate,
    maxDate,
    date: keyDownDate,
  });

  const newHighlightedRange =
    selectionType === "range"
      ? getHighlightRange({
          date: keyDownDate,
          range: range,
          minDate,
          maxDate,
        })
      : highlightedRange;

  const focusDateIsMinOrMax =
    (maxDate && isEqual(newFocusDate, maxDate)) ||
    (minDate && isEqual(newFocusDate, minDate));

  const [doubleMonthFirstMonth, doubleMonthSecondMonth] =
    getDoubleMonthDisplayRange(displayDate);

  const doubleMonthVisibleRange = {
    start: startOfMonth(doubleMonthFirstMonth),
    end: endOfMonth(doubleMonthSecondMonth),
  };

  const singleMonthVisibleRange = {
    start: startOfMonth(displayDate),
    end: endOfMonth(displayDate),
  };

  const isNewFocusDateVisible = isWithinInterval(
    newFocusDate,
    calendarType === "double"
      ? doubleMonthVisibleRange
      : singleMonthVisibleRange,
  );

  const commonState = {
    ...state,
    focusDate: newFocusDate,
    highlightedRange: newHighlightedRange,
  };

  if (
    !isNewFocusDateVisible &&
    !focusDateIsMinOrMax &&
    isNavigatingByYear &&
    calendarType === "double"
  ) {
    return {
      ...commonState,
      displayDate: setYear(displayDate, getYear(newFocusDate)),
    };
  }

  if (!isNewFocusDateVisible) {
    return {
      ...commonState,
      displayDate: startOfMonth(newFocusDate),
    };
  }

  return commonState;
};
