import { isDateValid } from "./is-date-valid";
import { parseDateString } from "./parse-date-string";

export const convertDateStringToDate = (value: string = "") => {
  const { day, month, year } = parseDateString(value);
  const isValidDate = isDateValid(value);

  return isValidDate ? new Date(`${year}-${month}-${day}`) : new Date();
};
