import React, { useContext } from "react";

import classNames from "classnames";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";
import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { SurfaceContext } from "../Surface";

/**
 * Use `BrandLogo` to display the brand logo.
 */
export const BrandLogo = ({
  color = "auto",
  label,
  size = 34,
  subBrand,
  ...props
}: BrandLogoProps) => {
  const { surface } = useContext(SurfaceContext);

  return (
    <div
      className={classNames({
        "arc-BrandLogo": true,
        "arc-BrandLogo--colorBrand": color === "brand",
        "arc-BrandLogo--onDarkSurface": surface === "dark",
        [suffixModifier("arc-BrandLogo--subBrand", subBrand || "")]: subBrand,
      })}
      style={{
        width: size !== 34 ? size : undefined,
      }}
      {...filterAttrs(props)}
    >
      {label ? <span className="arc-BrandLogo-text">{label}</span> : null}
    </div>
  );
};

export const colors = ["auto", "brand"] as const;
export const subBrands = ["redcare", "wholesale", "ee"] as const;

export interface BrandLogoProps {
  /**
   * Color of the BrandLogo. The `brand` color only shows on light surfaces.
   */
  color?: (typeof colors)[number];

  /**
   * Accessible text for the BrandLogo.
   */
  label?: string;

  /**
   * Size of the BrandLogo, in pixels.
   */
  size?: number;

  /**
   * Optional sub-brand variant.
   */
  subBrand?: (typeof subBrands)[number];
}
