import { ArcBreakpoints } from "../../../helpers/arc-breakpoints";
import { type MediaQuery } from "../types/media-query";

export const getQuery = ({
  breakpoint,
  type,
  isMatchMedia = false,
}: MediaQuery) => {
  const breakpointValue =
    typeof breakpoint === "number" ? breakpoint : ArcBreakpoints[breakpoint];

  return `${isMatchMedia ? "" : "@media"}(${type}-width: ${breakpointValue}px)`;
};
