import React from "react";

import classNames from "classnames";

/**
 * Use `SemanticHeading` to render accessible headings that preserve correct
 * document hierarchy.
 */

export const SemanticHeading = ({
  children,
  level,
  className,
  ...props
}: SemanticHeadingProps) =>
  React.createElement(
    level && level !== "span" ? `h${level}` : "span",
    { className: classNames("arc-SemanticHeading", className), ...props },
    children,
  );

export type SemanticHeadingLevel = "1" | "2" | "3" | "4" | "5" | "6" | "span";

export interface SemanticHeadingProps extends React.HTMLAttributes<HTMLHeadingElement> {
  /**
   * The semantic heading level (1-6).
   */
  level?: SemanticHeadingLevel;
  /**
   * Content to render within the heading.
   */
  children: React.ReactNode;
}
