import React, { type ReactNode } from "react";

import classNames from "classnames";

export const FilterItems = ({
  children,
  error,
  displayType = "grid",
}: FilterItemsProps) => {
  return React.Children.toArray(children).length > 0 ? (
    <div>
      <div className="arc-FilterItems-offscreen" aria-live="assertive">
        {React.Children.toArray(children).length > 0
          ? `${React.Children.toArray(children).length} records listed.`
          : null}
      </div>
      <div
        className={classNames("arc-FilterItems", {
          "arc-FilterItems--list": displayType === "list",
          "arc-FilterItems--grid": displayType === "grid",
        })}
      >
        {displayType === "list"
          ? React.Children.toArray(children).map((child, index, array) => (
              <React.Fragment key={index}>
                {child}
                {index !== array.length - 1 && (
                  <>
                    <div
                      className="arc-FilterItems-separator"
                      data-testid="arc-FilterItems-separator"
                    />
                  </>
                )}
              </React.Fragment>
            ))
          : children}
      </div>
    </div>
  ) : (
    <div aria-live="assertive">{error}</div>
  );
};

export interface FilterItemsProps {
  /**
   * Render children of `<FilterItems />`. This should only use `<FilterItem />`
   */
  children: ReactNode;

  /**
   * Error to display for `<FilterItem />`
   */
  error?: ReactNode;

  /**
   * Determine the display style of `<FilterItem />`
   */
  displayType?: "grid" | "list";
}
