import React, { type ReactNode } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { type ExtentableContainer } from "../../types/extendable-container";

/**
 * Use `Section` to compose content into vertical page layouts.
 */
export const Section = ({
  children,
  isFullWidth = false,
  isDebugVisible = false,
  isExtended = false,
  id,
  ...props
}: SectionProps) => {
  return (
    <div
      id={id}
      className={classNames({
        "arc-Section": true,
        "arc-Section--regular": !isExtended,
        "arc-Section--extended": isExtended,
        "arc-Section--fullWidth": isFullWidth,
        "arc-Section--debugVisible": isDebugVisible,
      })}
      {...filterAttrs(props)}
    >
      {children}
    </div>
  );
};

export interface SectionProps extends ExtentableContainer {
  /**
   * Content to display in the Section.
   */
  children: ReactNode;

  /**
   * Should the Section be visible for debugging and documentation
   * purposes?
   */
  isDebugVisible?: boolean;

  /**
   * Should the width of this Section be unconstrained (filling the viewport)?
   */
  isFullWidth?: boolean;

  /**
   * Id for the Section.
   */
  id?: string;
}
