import React, { type ReactNode } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

export const GroupItem = ({
  children,
  grow = false,
  isDebugVisible = false,
  ...props
}: GroupItemProps) => {
  return (
    <div
      className={classNames({
        [`arc-Group-item`]: true,
        [`arc-Group-item--grow`]: grow,
        [`arc-Group-item--debugVisible`]: isDebugVisible,
      })}
      {...filterAttrs(props)}
    >
      {children}
    </div>
  );
};

export interface GroupItemProps {
  /**
   * Content to display in the GroupItem.
   */
  children?: ReactNode;

  /**
   * Should the GroupItem be visible for debugging and documentation
   * purposes?
   */
  isDebugVisible?: boolean;

  /**
   * Should the GroupItem stretch to fill the available space?
   */
  grow?: boolean;
}
