import { type ComboBoxOption } from "../types/combobox-option";

import { getMatchingOption } from "./getMatchingOption";
import { isOptionValueMatch } from "./isOptionValueMatch";

export const getSelectedOptions = (
  option: ComboBoxOption,
  selectedOptions: ComboBoxOption[],
) => {
  const isOptionCurrentlySelected = getMatchingOption(
    selectedOptions,
    option.text,
  );

  return isOptionCurrentlySelected
    ? selectedOptions.filter(
        (selectedOption) => !isOptionValueMatch(selectedOption, option.text),
      )
    : [...selectedOptions, option];
};
