import React, { type Ref } from "react";

import { Trigger } from "@radix-ui/react-tabs";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { Text } from "../../../Text";

import { Surface } from "../../../Surface";

export const ContentSwitcherTab = ({
  label,
  value,
  onClick,
  onFocus,
  ref,
  ...props
}: ContentSwitcherTabProps) => {
  return (
    <Surface isTransparent>
      <Trigger
        className="arc-ContentSwitcherTab"
        value={value}
        ref={ref}
        onClick={onClick}
        onFocus={onFocus}
        {...filterAttrs(props)}
      >
        <Text size="m">{label}</Text>
      </Trigger>
    </Surface>
  );
};

export interface ContentSwitcherTabProps {
  /**
   * Ref to the underlying button element.
   */
  ref?: Ref<HTMLButtonElement>;
  /**
   * Label to display on the ContentSwitcherTab
   */
  label: string;

  /**
   * Value to link `ContentSwitcherTab` to `ContentSwitcherTabContent`
   */
  value: string;

  /**
   * Pass a onClick function to `ContentSwitcherTab`
   */
  onClick?: () => void;

  /**
   * Pass a focus function to `ContentSwitcherTab`
   */
  onFocus?: () => void;
}
