import { useState } from "react";

export const useThemeElement = (): [
  HTMLElement | undefined,
  (el: HTMLElement | null) => void,
] => {
  const [themeElement, setElement] = useState<HTMLElement | undefined>(
    undefined,
  );

  const setThemeElement = (el: HTMLElement | null) => {
    el &&
      setElement((el.closest(".arc-ds-sys-theme") as HTMLElement) || undefined);
  };

  return [themeElement, setThemeElement];
};
