import React, { useContext } from "react";

import classNames from "classnames";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";
import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { SurfaceContext } from "../Surface/Surface";

/**
 * Use `Icon` to display brand iconography.
 */
export const Icon = ({
  testId,
  icon,
  label,
  size,
  color = "auto",
  isInline = false,
  ...props
}: IconProps) => {
  const { surface } = useContext(SurfaceContext);
  const iconUrl = icon ? `url("${icon}")` : undefined;

  return (
    <span
      data-testid={testId}
      aria-label={label}
      role={label ? "img" : undefined}
      className={classNames({
        [`arc-Icon`]: true,
        [`arc-Icon--inline`]: isInline,
        [suffixModifier("arc-Icon--color", color)]: color !== "auto",
        "arc-Icon--onDarkSurface": surface === "dark",
      })}
      style={{
        height: size,
        width: size,
        maskImage: iconUrl,
        WebkitMaskImage: iconUrl,
      }}
      {...filterAttrs(props)}
    />
  );
};

export const colors = [
  "auto",
  "brand",
  "brand-alt",
  "statusRed",
  "statusAmber",
  "statusGreen",
] as const;

export type IconColor = (typeof colors)[number];

export interface IconProps {
  /**
   * Color of the Icon.
   */
  color?: IconColor;

  /**
   * Should the Icon component be styled as an inline element?
   */
  isInline?: boolean;

  /**
   * url for the svg. For BT and EE icons you can import these as data uri's from the @arc-ui/icons package.
   */
  icon?: string;

  /**
   * Alternative text label for the Icon.
   */
  label?: string;

  /**
   * Size of the Icon, in pixels.
   */
  size?: number;

  /**
   * value for data-testid
   */
  testId?: string;
}
