import React, { type Ref, type ReactNode, useContext } from "react";

import classNames from "classnames";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";

import { SemanticLink } from "../../../SemanticLink";
import { SemanticButton } from "../../../SemanticButton";
import { SurfaceContext } from "../../../Surface";

export const NavigationHeaderButton = ({
  ref,
  isActive,
  children,
  onClick,
  href,
  isPadded = true,
  ...props
}: NavigationHeaderButtonProps) => {
  const { surface } = useContext(SurfaceContext);

  const classes = classNames(
    "arc-NavigationHeaderButton",
    suffixModifier("arc-NavigationHeaderButton--on", surface),
    {
      "arc-NavigationHeaderButton--active": isActive,
      "arc-NavigationHeaderButton--padded": isPadded,
    },
  );

  const commonProps = {
    className: classes,
    onClick,
  };

  if (href) {
    return (
      <SemanticLink
        {...(props as React.AnchorHTMLAttributes<HTMLAnchorElement>)}
        {...commonProps}
        ref={ref as Ref<HTMLAnchorElement>}
        href={href}
      >
        {children}
      </SemanticLink>
    );
  }

  return (
    <SemanticButton
      {...props}
      {...commonProps}
      ref={ref as Ref<HTMLButtonElement>}
    >
      {children}
    </SemanticButton>
  );
};

export interface NavigationHeaderButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /**
   * Ref to the underlying button element.
   */
  ref?: Ref<HTMLButtonElement | HTMLAnchorElement>;
  /**
   * Whether the button is in an active state.
   */
  isActive?: boolean;
  /**
   * Whether the button should have padding.
   */
  isPadded?: boolean;
  /**
   * Click handler for the button.
   */
  onClick?: (
    e: React.MouseEvent<HTMLButtonElement | HTMLAnchorElement, MouseEvent>,
  ) => void;
  /**
   * Href for the button.
   */
  href?: string;
  /**
   * Content to display inside the button.
   */
  children: ReactNode;
}
