import React, {
  useContext,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from "react";

import classNames from "classnames";

import { getFocusableElements } from "@arc-ui/helpers/get-focusable-elements";
import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";

import { SurfaceContext } from "../../../../../Surface";
import { ThemeIcon } from "../../../../../ThemeIcon";

export const SideMenuDisclosure = ({
  heading,
  children,
}: SideMenuDisclosureProps) => {
  const [isOpen, setIsOpen] = useState(false);
  const { surface } = useContext(SurfaceContext);
  const containerRef = useRef<HTMLDivElement | null>(null);

  const handleOnClick = (e: React.MouseEvent<HTMLElement, MouseEvent>) => {
    e.preventDefault();
    setIsOpen((isOpen) => !isOpen);
  };

  useEffect(() => {
    if (containerRef.current && containerRef.current.firstChild && isOpen) {
      getFocusableElements(containerRef.current as Node)[0]?.focus();
    }
  }, [isOpen]);

  return (
    <details
      className={classNames(
        "arc-SideMenuDisclosure",
        suffixModifier("arc-SideMenuDisclosure--on", surface),
      )}
      open={isOpen}
    >
      <summary
        aria-expanded={isOpen}
        onClick={handleOnClick}
        className="arc-SideMenuDisclosure-summary"
      >
        <span className="arc-SideMenuDisclosure-heading">{heading}</span>

        <span className="arc-SideMenuDisclosure-icon">
          <ThemeIcon icon="navigationHeaderDisclosure" />
        </span>
      </summary>
      <div ref={containerRef} className="arc-SideMenuDisclosure-content">
        {children}
      </div>
    </details>
  );
};

interface SideMenuDisclosureProps {
  /**
   * Heading text for the disclosure.
   */
  heading: string;
  /**
   * Content to display when disclosure is expanded.
   */
  children: ReactNode;
}
