import React, { type ReactNode } from "react";

import classNames from "classnames";

import { type HeadingSize } from "src/components/Heading/Heading";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";

import { Text } from "../../../../../Text";
import { Heading } from "../../../../../Heading";
import { ThemeIcon } from "../../../../../ThemeIcon";
import { VerticalSpace } from "../../../../../VerticalSpace";
import { SemanticButton } from "../../../../../SemanticButton";

import { useNavigationHeaderSideMenuContext } from "../../NavigationHeaderSideMenu.provider";
import { SideMenuDrawer } from "../SideMenuDrawer";
import { SideMenuHeader } from "../SideMenuHeader";
import { SideMenuNavSection } from "../SideMenuNavSection";

export const SideMenuSubMenu = ({
  children,
  heading,
  isOpen,
  onBackClick,
  onCloseAutoFocus,
  supportingText,
  headingSize = "l",
  backButtonLabel = "Back",
  backButtonAriaLabel = "Back to main menu",
}: SideMenuSubMenuProps) => {
  const { menuColorConfig, menuPosition, onEscapeKeyDown, closeMenu } =
    useNavigationHeaderSideMenuContext();

  return (
    <>
      <SideMenuDrawer
        drawerType="sub"
        title={heading ?? "Secondary menu"}
        isOpen={isOpen}
        onCloseAutoFocus={onCloseAutoFocus}
        colorType={menuColorConfig.menuColorType}
        surface={menuColorConfig.surface}
        menuPosition={menuPosition}
        onEscapeKeyDown={onEscapeKeyDown}
        onInteractOutside={closeMenu}
      >
        <SideMenuHeader onCloseClick={closeMenu}>
          <SemanticButton
            className={classNames(
              "arc-SideMenuSubMenu-backButton",
              suffixModifier(
                "arc-SideMenuSubMenu-backButton--on",
                menuColorConfig.menuColorType,
              ),
            )}
            aria-label={backButtonAriaLabel}
            onClick={onBackClick}
          >
            <div className="arc-SideMenuSubMenu-backButtonIcon">
              <ThemeIcon icon="navigationHeaderSideMenuBack" size={32} />
            </div>

            <div className="arc-SideMenuSubMenu-backButtonText">
              {backButtonLabel}
            </div>
          </SemanticButton>
        </SideMenuHeader>

        <SideMenuNavSection>
          <div className="arc-SideMenuSubMenu-heading">
            <Heading size={headingSize} level="2">
              {heading}
            </Heading>
            {supportingText && (
              <>
                <VerticalSpace size="4" />

                <Text tone="muted" size="s">
                  {supportingText}
                </Text>
              </>
            )}
          </div>

          {children}
        </SideMenuNavSection>
      </SideMenuDrawer>
    </>
  );
};

export interface SideMenuSubMenuProps {
  /**
   * Whether the submenu is open.
   */
  isOpen: boolean;
  /**
   * Callback when back button is clicked.
   */
  onBackClick: () => void;
  /**
   * Callback when submenu closes and focus returns.
   */
  onCloseAutoFocus: () => void;
  /**
   * Content to display in the submenu.
   */
  children: ReactNode;
  /**
   * Label for the back button.
   */
  backButtonLabel?: string;
  /**
   * Accessible label for the back button.
   */
  backButtonAriaLabel?: string;
  /**
   * Heading text for the submenu.
   */
  heading: string;
  /**
   * Size of the heading.
   */
  headingSize?: Extract<HeadingSize, "l" | "s">;
  /**
   * Supporting text displayed below the heading.
   */
  supportingText?: string;
}
