import React, { type ReactNode, useId } from "react";

import { type NavLink } from "../../types/nav-link";

import { NavigationHeaderNavLink } from "../NavigationHeaderNavLink";

export const NavigationHeaderLevelTwoLinks = ({
  links,
  children,
}: NavigationHeaderLevelTwoLinksProps) => {
  const id = useId();

  return (
    <ul className="arc-NavigationHeaderLevelTwoLinks">
      {links.map((navLink, i) => (
        <li key={`${id}-NavigationHeader-subnav-item-${i}`}>
          <NavigationHeaderNavLink {...navLink} borderRadiusSize="s" />
        </li>
      ))}

      {children}
    </ul>
  );
};

interface NavigationHeaderLevelTwoLinksProps {
  /**
   * Array of navigation links to display.
   */
  links: NavLink[];
  /**
   * Additional content to display after the links.
   */
  children?: ReactNode;
}
