import React, { type ReactElement, type ReactNode, useState } from "react";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { FilterControl } from "./components/FilterControl/FilterControl";

import {
  FilterControls,
  type FilterControlsProps,
} from "./components/FilterControls/FilterControls";

import { type FilterItemProps } from "./components/FilterItem/FilterItem";

import {
  FilterItems,
  type FilterItemsProps,
} from "./components/FilterItems/FilterItems";

/** Use `Filter` to filter and categorise page content. */
export const Filter = ({
  children,
  onChange,
  controls,
  displayType,
  controlsAlignment,
  logicType = "OR",
  error,
  ...props
}: FilterProps) => {
  const [filterControls, setFilterControls] = useState(controls);

  const handleControlClick = (index: number) => {
    const updatedControls = filterControls.toSpliced(index, 1, {
      ...filterControls[index],
      isSelected: !filterControls[index].isSelected,
    });

    const selectedControlLabels = updatedControls
      .filter((control) => control.isSelected)
      .map((control) => control.label);

    filterControls[index].onClick && filterControls[index].onClick();
    onChange && onChange(selectedControlLabels);
    setFilterControls(updatedControls);
  };

  const selectedControls = filterControls.filter(
    ({ isSelected }) => isSelected,
  );

  const filterItems = React.Children.toArray(
    children,
  ) as ReactElement<FilterItemProps>[];

  const filteredItems = filterItems.filter((filteredItem) => {
    // If no tags are selected, show all items
    if (selectedControls.length === 0) {
      return true;
    }

    // If logicType is "AND", all selected tags should be present in the item's tags
    if (logicType === "AND") {
      return selectedControls.every((control) =>
        filteredItem.props.tags!.includes(control.label),
      );
    } else {
      // Check if item has tags property and if any selected tags are present in item's tags
      return selectedControls.some((control) =>
        filteredItem.props.tags!.includes(control.label),
      );
    }
  });

  return (
    <div className="arc-Filter" {...filterAttrs(props)}>
      <FilterControls controlsAlignment={controlsAlignment}>
        {filterControls.map(({ label, isSelected }, index) => (
          <FilterControl
            key={index}
            onClick={() => handleControlClick(index)}
            isSelected={isSelected}
          >
            {label}
          </FilterControl>
        ))}
      </FilterControls>

      <FilterItems displayType={displayType} error={error}>
        {filteredItems.map(
          (item: ReactElement<FilterItemProps>) => item.props.children,
        )}
      </FilterItems>
    </div>
  );
};

export interface FilterProps {
  /**
   * Contents of the `<Filter />` Should contain `<FilterItem />`
   */
  children?: ReactNode;

  /**
   * Array of filter control configurations
   */
  controls: { label: string; isSelected?: boolean; onClick?: () => void }[];

  /**
   * onChange handler called everytime `<FilterControl />` is pressed
   */
  onChange?: (selectedControls: string[]) => void;

  /**
   * Detmine how to display the content within `<FilterItems />`. Default is `grid`
   */
  displayType?: FilterItemsProps["displayType"];

  /**
   * Detmine how to align <FilterControls />. Default `center`
   */
  controlsAlignment?: FilterControlsProps["controlsAlignment"];

  /**
   * Detmine if the `<FilterControl />` have to partially match or match all
   */
  logicType?: "AND" | "OR";

  /**
   * Detmine what is display when no items match the filtering criteria
   */
  error?: ReactNode;
}
