import isBefore from "date-fns/isBefore";
import isAfter from "date-fns/isAfter";
import compareAsc from "date-fns/compareAsc";

import {
  formatDate,
  convertRangeStringToDates,
  isDisabledDate,
  isRangeValid,
} from "../helpers";

export function validateRangeOnBlur({
  value,
  minDate,
  maxDate,
  disabledDates,
  previousValidValue,
  dispatchChangeEvent,
  blurEvent,
}: validateRangeOnBlurProps) {
  if (!isRangeValid(value)) return;

  const [start, end] = convertRangeStringToDates(value);

  const isStartBeforeMin = minDate && isBefore(start, minDate);
  const isEndAfterMax = maxDate && isAfter(end, maxDate);
  const isStartDisabled = isDisabledDate(disabledDates, start);
  const isEndDisabled = isDisabledDate(disabledDates, end);

  if (isStartBeforeMin && isEndAfterMax) {
    return dispatchChangeEvent(
      blurEvent,
      `${formatDate(minDate!)} - ${formatDate(maxDate!)}`,
    );
  }

  if (isStartBeforeMin) {
    return dispatchChangeEvent(
      blurEvent,
      `${formatDate(minDate!)} - ${formatDate(end)}`,
    );
  }

  if (isEndAfterMax) {
    return dispatchChangeEvent(
      blurEvent,
      `${formatDate(start)} - ${formatDate(maxDate!)}`,
    );
  }

  if (isStartDisabled || isEndDisabled) {
    const [prevStart, prevEnd] = previousValidValue
      ? convertRangeStringToDates(previousValidValue)
      : [];

    return dispatchChangeEvent(
      blurEvent,
      prevStart && prevEnd
        ? `${formatDate(prevStart)} - ${formatDate(prevEnd)}`
        : "",
    );
  }

  if (isAfter(start, end)) {
    const [orderedStart, orderedEnd] = [start, end].sort(compareAsc);
    return dispatchChangeEvent(
      blurEvent,
      `${formatDate(orderedStart)} - ${formatDate(orderedEnd)}`,
    );
  }
}

export interface validateRangeOnBlurProps {
  value: string;
  minDate?: Date;
  maxDate?: Date;
  disabledDates?: Date[];
  previousValidValue?: string;
  dispatchChangeEvent: (
    e: React.FocusEvent<HTMLInputElement>,
    value: string,
  ) => void;
  blurEvent: React.FocusEvent<HTMLInputElement>;
}
