import React, { useId, useRef, useState } from "react";

import { SemanticButton } from "../../../SemanticButton";
import { Heading } from "../../../Heading";
import { Text } from "../../../Text";
import { ThemeIcon } from "../../../ThemeIcon";

import { NavigationHeaderAction } from "../NavigationHeaderAction";

import {
  NavigationHeaderSubnavContent,
  NavigationHeaderSubnav,
  NavigationHeaderSubnavTrigger,
} from "../NavigationHeaderSubnav";

import { NavigationHeaderCta } from "../NavigationHeaderCta";

import { SearchMenuCloseButton } from "./components/SearchMenuCloseButton";

export const NavigationHeaderSearchMenu = ({
  onSubmit,
  quickLinks,
  onInputChange,
  submitButtonAriaLabel = "Submit search",
  panelTitle = "Quick links",
  description = "Discover our products and how we can help your business grow",
  accessibleMenuTitle = "Search menu",
  label = "Search",
  triggerTooltip = "Search",
  triggerAriaLabel = "Open search menu",
  linkSlot,
}: NavigationHeaderSearchMenuProps) => {
  const id = useId();
  const [searchTerm, setSearchTerm] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);

  const onChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onInputChange?.(e.target.value);
    setSearchTerm(e.target.value);
  };

  const onFormSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    onSubmit && onSubmit(searchTerm);
  };

  const onOpenChange = (isOpen: boolean) => {
    if (!isOpen) {
      setSearchTerm("");
    }
  };

  const onClear = () => {
    setSearchTerm("");
    onInputChange?.("");
    inputRef.current?.focus();
  };

  return (
    <NavigationHeaderSubnav onOpenChange={onOpenChange}>
      <NavigationHeaderSubnavTrigger asChild>
        <NavigationHeaderAction
          title={triggerTooltip}
          ariaLabel={triggerAriaLabel}
          icon={<ThemeIcon icon="navigationHeaderSearch" size={24} />}
        />
      </NavigationHeaderSubnavTrigger>
      <NavigationHeaderSubnavContent
        background="lightElevatedTight"
        menuTitle={accessibleMenuTitle}
        description="Use tab keys to navigate. Press Escape to close."
      >
        <div className="arc-NavigationHeaderSearchMenu">
          <div className="arc-NavigationHeaderSearchMenu-labelContainer">
            <label htmlFor={id}>
              <Heading color="brand" size="m">
                {label}
              </Heading>
            </label>
            <Text>{description}</Text>
          </div>

          <form
            onSubmit={onFormSubmit}
            className="arc-NavigationHeaderSearchMenu-form"
          >
            <input
              id={id}
              role="searchbox"
              autoComplete="off"
              aria-autocomplete="none"
              ref={inputRef}
              value={searchTerm}
              onChange={onChange}
              className="arc-NavigationHeaderSearchMenu-input"
              type="text"
            />
            <div className="arc-NavigationHeaderSearchMenu-actions">
              {searchTerm && (
                <>
                  <button
                    type="button"
                    aria-label="Clear search"
                    className="arc-NavigationHeaderSearchMenu-clearButton"
                    onClick={(e) => {
                      e.stopPropagation();
                      onClear();
                    }}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") {
                        e.stopPropagation();
                      }
                    }}
                  >
                    <ThemeIcon icon="textInputClear" size={20} />
                  </button>
                  <span className="arc-NavigationHeaderSearchMenu-divider" />
                </>
              )}
              <SemanticButton
                aria-label={submitButtonAriaLabel}
                className="arc-NavigationHeaderSearchMenu-submitButton"
                type="submit"
              >
                <ThemeIcon icon="navigationHeaderSearch" />
              </SemanticButton>
            </div>
          </form>

          {linkSlot && (
            <div className="arc-NavigationHeaderSearchMenu-results">
              {linkSlot}
            </div>
          )}
          {quickLinks && !linkSlot && (
            <div className="arc-NavigationHeaderSearchMenu-results">
              <Heading level="3" size="xxxs">
                {panelTitle}
              </Heading>
              <ul className="arc-NavigationHeaderSearchMenu-resultsList">
                {quickLinks.map(({ text, href, onClick }, i) => (
                  <li key={`${id}-search-link-${text}-${i}`}>
                    <NavigationHeaderCta
                      revealLinkIconOnHover
                      href={href}
                      onClick={onClick}
                      text={text}
                    />
                  </li>
                ))}
              </ul>
            </div>
          )}
          <div className="arc-NavigationHeaderSearchMenu-closeButton">
            <SearchMenuCloseButton />
          </div>
        </div>
      </NavigationHeaderSubnavContent>
    </NavigationHeaderSubnav>
  );
};

export interface NavigationHeaderSearchMenuProps {
  /**
   * React Node intended for use with `InlineLinkGroup`.
   */
  linkSlot?: React.ReactNode;
  /**
   * Array of quick link items. If `linkSlot` is used that will take precident.
   */
  quickLinks?: {
    text: string;
    href: string;
    onClick?: (e: React.MouseEvent<HTMLAnchorElement>) => void;
  }[];
  /**
   * Callback when input value changes.
   */
  onInputChange?: (value: string) => void;
  /**
   * Callback when search form is submitted.
   */
  onSubmit?: (value: string) => void;
  /**
   * Label text for the search input.
   */
  label?: string;
  /**
   * Description text for the search menu.
   */
  description?: string;
  /**
   * Title text for the quick links panel.
   */
  panelTitle?: string;
  /**
   * Tooltip text for the trigger button.
   */
  triggerTooltip?: string;
  /**
   * Accessible label for the trigger button.
   */
  triggerAriaLabel?: string;
  /**
   * Accessible label for the submit button.
   */
  submitButtonAriaLabel?: string;
  /**
   * Accessible title for the menu dialog.
   */
  accessibleMenuTitle?: string;
}
