import React from "react";

import { Item } from "@radix-ui/react-dropdown-menu";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import {
  MenuItemContentTemplate,
  type MenuItemContentTemplateProps,
} from "../MenuItemContentTemplate/MenuItemContentTemplate";

/**
 * Renders a menu item, optionally as a link if `href` is provided.
 */
export const MenuItem = ({
  leadingIcon,
  supportingText,
  keyCommands,
  trailingIcon,
  children,
  onClick,
  shouldKeepOpen = true,
  isDisabled,
  href,
  ariaLabel,
  ...props
}: MenuItemProps) => {
  const Component = href ? "a" : "div";

  return (
    <Item
      className="arc-MenuItem"
      asChild
      aria-label={ariaLabel}
      onClick={isDisabled ? undefined : onClick}
      onSelect={(event) => {
        if (shouldKeepOpen) {
          event.preventDefault();
        }
      }}
      disabled={isDisabled}
      {...filterAttrs(props)}
    >
      <Component
        className={href && "arc-MenuItem--link"}
        href={href}
        {...props}
      >
        <MenuItemContentTemplate
          leadingIcon={leadingIcon}
          trailingIcon={trailingIcon}
          supportingText={supportingText}
          keyCommands={keyCommands}
        >
          {children}
        </MenuItemContentTemplate>
      </Component>
    </Item>
  );
};

export interface MenuItemProps extends MenuItemContentTemplateProps {
  /**
   * Click event handler triggered when the menu item is selected.
   */
  onClick?: () => void;
  /**
   * Optional URL that makes the menu item behave as a link.
   */
  href?: string;

  /**
   * ARIA label for accessibility, used to provide a descriptive label for screen readers.
   */
  ariaLabel?: string;

  /**
   * disables the menu item, preventing user interaction.
   */
  isDisabled?: boolean;

  /**
   * Prevents the dropdown menu from closing when the item is clicked.
   */
  shouldKeepOpen?: boolean;
}
