import React from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { Text } from "../Text";
import { Heading } from "../Heading";
import { VerticalSpace } from "../VerticalSpace";

import { ThemeIcon } from "../ThemeIcon";

import { PROGRESS_BAR_ICON_MAP } from "./constants/progress-bar-icon-map";
import { type ProgressBarState } from "./types/progress-bar-state";
import { type ProgressBarIcons } from "./types/progress-bar-icons";
import { getProgressBarProps } from "./utils/get-progress-bar-props";

/**
 * Use `ProgressBar` to show the progress of a specific task within a page.
 */
export const ProgressBar = ({
  state = "loading",
  value = 0,
  isIndeterminate = false,
  headline,
  ariaLabel,
  action,
  title,
  description,
  displayValue,
  headlineWordWrap = false,
  ...props
}: ProgressBarProps) => {
  const progressValue = Math.min(100, Math.max(0, value));

  const autoFocusRef = (canFocus?: boolean) => (el: HTMLButtonElement) => {
    canFocus && el && el.focus();
  };

  return (
    <div
      data-testid="progress"
      className={classNames(`arc-ProgressBar`, `arc-ProgressBar--${state}`)}
      {...filterAttrs(props)}
    >
      <div className="arc-ProgressBar-titleDisplayValueContainer">
        <div className="arc-ProgressBar-titleContainer">
          {headline && (
            <Heading size="s" isWordWrap={headlineWordWrap}>
              {headline}
            </Heading>
          )}
          {headline && title && <VerticalSpace size="4" />}
          {title && <Text>{title}</Text>}
        </div>
        {displayValue && (
          <div
            data-testid="display-value"
            className="arc-ProgressBar-displayValueContainer"
          >
            <Text>{displayValue}</Text>
          </div>
        )}
      </div>
      <div className="arc-ProgressBar-container">
        <div className="arc-ProgressBar-outerBar">
          <div
            {...getProgressBarProps(isIndeterminate, progressValue, ariaLabel)}
          />
        </div>

        {description && (
          <div className="arc-ProgressBar-description" role="status">
            <Text tone={state !== "error" ? "supporting" : "default"}>
              {description}
            </Text>
          </div>
        )}

        {action && (
          <>
            <VerticalSpace size="8" />
            <button
              ref={autoFocusRef(action.autofocusOnMount)}
              className="arc-ProgressBar-actionButton"
              onClick={action.action}
            >
              <div className="arc-ProgressBar-actionContainer">
                {action.icon && (
                  <div className="arc-ProgressBar-actionIcon">
                    <ThemeIcon
                      icon={PROGRESS_BAR_ICON_MAP[action.icon]}
                      size={24}
                    />
                  </div>
                )}
                <Text>{action.text}</Text>
              </div>
            </button>
          </>
        )}
      </div>
    </div>
  );
};

export interface ProgressBarProps {
  /**
   * Label for screen readers.
   */
  ariaLabel: string;

  /**
   * Headline for the progress bar.
   */
  headline?: string;

  /**
   * Title for the progress bar, (e.g. an uploading file's name).
   */
  title?: string;

  /**
   * Percentage value for the progress bar (negative numbers are rounded to 0, numbers over 100 are rounded to 100).
   */
  value?: number;

  /**
   * Provide an additional informative description for the progress bar, or brand building slot for secondary messaging which can change over time with progress.
   */
  description?: string;

  /**
   * Value to display for the progress bar. This is fully customisable, and can be a percentage (15%) Time remaining (1m 15s remaining), proportion of data uploaded/to upload (100KB out of 256KB).
   */
  displayValue?: string;

  /**
   * State of the progress bar.
   */
  state?: ProgressBarState;

  /**
   * Sets progress bar to infinitely animate. Use if the progress of a given task cannot be known. The value prop will have no effect if this prop is set to true.
   */
  isIndeterminate?: boolean;

  /**
   * Action for the progress bar.
   */
  action?: {
    autofocusOnMount?: boolean;
    text: string;
    action: () => void;
    icon?: ProgressBarIcons;
  };
  /**
   * Whether long words in headline should be wrapped.
   */
  headlineWordWrap?: boolean;
}
