import React from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { type ExtentableContainer } from "../../types/extendable-container";

/**
 * Use `Grid` to compose layouts on a 12-column grid. Aligns with sibling `Section` components.
 */
export const Grid = ({
  children,
  isFluid,
  isDebugVisible,
  isGutterless,
  isExtended = false,
  ...props
}: GridProps) => {
  return (
    <div
      className={classNames("arc-Grid", {
        "arc-Grid--regular": !isExtended,
        "arc-Grid--extended": isExtended,
        "arc-Grid--fluid": isFluid,
        "arc-Grid--debugVisible": isDebugVisible,
        "arc-Grid--gutterless": isGutterless,
      })}
      {...filterAttrs(props)}
    >
      <div className="arc-Grid-inner">{children}</div>
    </div>
  );
};

export interface GridProps extends ExtentableContainer {
  /**
   * `Grid` is set to 100% width if true.
   */
  isFluid?: boolean;

  /**
   * Removes gap between columns for an edge to edge layout if true.
   */
  isGutterless?: boolean;

  /**
   * Allows the rows and columns be visible for debugging.
   */
  isDebugVisible?: boolean;

  /**
   * Contents of the Grid Should only contain `GridRow`.
   */
  children: React.ReactNode;
}
