import React, { useContext } from "react";

import format from "date-fns/format";
import subMonths from "date-fns/subMonths";
import addMonths from "date-fns/addMonths";

import { Heading } from "../../../Heading";

import { CalendarDayGrid } from "../CalendarDayGrid";
import { CalendarNavButton } from "../CalendarNavButton";
import { getDoubleMonthDisplayRange } from "../../helpers";
import { ArcCalendarContext } from "../../Calendar.provider";
import { VisuallyHidden } from "../../../VisuallyHidden";

export const CalendarDoubleMonthView = ({
  isPreviousMonthDisabled,
  isNextMonthDisabled,
  onNextMonthClick,
  onPreviousMonthClick,
}: CalendarDoubleMonthViewProps) => {
  const context = useContext(ArcCalendarContext);

  if (!context) {
    return null;
  }

  const { displayDate } = context;
  const displayRange = getDoubleMonthDisplayRange(displayDate);

  const getAriaLabel = (date: Date) => {
    const months = getDoubleMonthDisplayRange(date);

    return `show ${format(months[0], "MMMM yyyy")} to ${format(
      months[1],
      "MMMM yyyy",
    )}`;
  };

  return (
    <>
      <VisuallyHidden>
        <Heading level="2">
          <span aria-live="polite">
            showing {format(displayRange[0], "MMMM yyyy")} to{" "}
            {format(displayRange[1], "MMMM yyyy")}
          </span>
        </Heading>
      </VisuallyHidden>
      <div className="arc-CalendarDoubleMonthView-header">
        <div className="arc-CalendarDoubleMonthView-headerMonth">
          <div className="arc-CalendarDoubleMonthView-headerMonthItem">
            <CalendarNavButton
              ariaLabel={getAriaLabel(subMonths(displayDate, 2))}
              direction="previous"
              isDisabled={isPreviousMonthDisabled}
              onClick={onPreviousMonthClick}
            />
          </div>
          <div
            aria-hidden
            className="arc-CalendarDoubleMonthView-headerMonthItem"
          >
            <Heading level="2" size="s">
              {format(displayRange[0], "MMM yyyy")}
            </Heading>
          </div>
        </div>
        <div className="arc-CalendarDoubleMonthView-headerMonth">
          <div
            aria-hidden
            className="arc-CalendarDoubleMonthView-headerMonthItem"
          >
            <Heading level="2" size="s">
              {format(displayRange[1], "MMM yyyy")}
            </Heading>
          </div>

          <div className="arc-CalendarDoubleMonthView-headerMonthItem">
            <CalendarNavButton
              ariaLabel={getAriaLabel(addMonths(displayDate, 2))}
              direction="next"
              isDisabled={isNextMonthDisabled}
              onClick={onNextMonthClick}
            />
          </div>
        </div>
      </div>

      <CalendarDayGrid displayRange={displayRange} />
    </>
  );
};

interface CalendarDoubleMonthViewProps {
  /**
   * Whether the previous month button is disabled
   */
  isPreviousMonthDisabled: boolean;
  /**
   * Whether the next month button is disabled
   */
  isNextMonthDisabled: boolean;
  /**
   * Handler for previous month button click
   */
  onPreviousMonthClick: () => void;
  /**
   * Handler for next month button click
   */
  onNextMonthClick: () => void;
}
