import React from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

/**
 * Use `VerticalSpace` to create vertical space between components.
 */
export const VerticalSpace = ({
  isDebugVisible = false,
  size = "24",
  sizeS,
  sizeM,
  sizeL,
  sizeXL,
  sizeXXL,
  ...props
}: VerticalSpaceProps) => {
  return (
    <div
      className={classNames({
        "arc-VerticalSpace": true,
        [`arc-VerticalSpace--size${size}`]: size,
        [`arc-VerticalSpace--sizeS${sizeS}`]: sizeS,
        [`arc-VerticalSpace--sizeM${sizeM}`]: sizeM,
        [`arc-VerticalSpace--sizeL${sizeL}`]: sizeL,
        [`arc-VerticalSpace--sizeXL${sizeXL}`]: sizeXL,
        [`arc-VerticalSpace--sizeXXL${sizeXXL}`]: sizeXXL,
        "arc-VerticalSpace--debugVisible": isDebugVisible,
      })}
      {...filterAttrs(props)}
    />
  );
};

export type VerticalSpaceSize =
  | "4"
  | "8"
  | "12"
  | "16"
  | "20"
  | "24"
  | "28"
  | "32"
  | "40"
  | "48"
  | "64"
  | "96"
  | "128";

export interface VerticalSpaceProps {
  /**
   * Should the VerticalSpace be visible for debugging and documentation
   * purposes?
   */
  isDebugVisible?: boolean;

  /**
   * Size of the VerticalSpace.
   */
  size?: VerticalSpaceSize;

  /**
   * Size of the VerticalSpace from the small breakpoint upwards.
   */
  sizeS?: VerticalSpaceSize;

  /**
   * Size of the VerticalSpace from the medium breakpoint upwards.
   */
  sizeM?: VerticalSpaceSize;

  /**
   * Size of the VerticalSpace from the large breakpoint upwards.
   */
  sizeL?: VerticalSpaceSize;

  /**
   * Size of the VerticalSpace from the extra large breakpoint upwards.
   */
  sizeXL?: VerticalSpaceSize;

  /**
   * Size of the VerticalSpace from the xxl breakpoint upwards.
   */
  sizeXXL?: VerticalSpaceSize;
}
