import React from "react";

import { CheckboxItem } from "@radix-ui/react-dropdown-menu";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import {
  MenuItemContentTemplate,
  type MenuItemContentTemplateProps,
} from "../MenuItemContentTemplate/MenuItemContentTemplate";

import { CheckboxIcon } from "../../CheckboxIcon";

export const MenuItemCheckbox = ({
  children,
  checked,
  onCheckedChange,
  isDisabled,
  onSelect,
  id,
  shouldKeepOpen = true,
  ...props
}: MenuItemCheckboxProps) => {
  return (
    <CheckboxItem
      className="arc-MenuItem arc-MenuItemCheckbox"
      checked={checked}
      onCheckedChange={onCheckedChange}
      disabled={isDisabled}
      onSelect={(event) => {
        if (shouldKeepOpen) {
          event.preventDefault();
          onCheckedChange?.(!checked);
        }

        onSelect?.(event);
      }}
      id={id}
      {...filterAttrs(props)}
    >
      <CheckboxIcon
        size="s"
        id={id}
        error={false}
        isDisabled={isDisabled}
        onChange={() => onCheckedChange}
        checked={checked}
        indeterminate={false}
      />

      <MenuItemContentTemplate>{children}</MenuItemContentTemplate>
    </CheckboxItem>
  );
};

export interface MenuItemCheckboxProps extends Pick<
  MenuItemContentTemplateProps,
  "supportingText" | "children"
> {
  /**
   * Controls whether the checkbox is checked, unchecked.
   */
  checked?: boolean;

  /**
   * Callback fired when the checked state changes.
   */
  onCheckedChange?: (checked: boolean) => void;

  /**
   * Disables the checkbox item, preventing interaction.
   */
  isDisabled?: boolean;

  /**
   * Callback fired when the item is selected.
   */
  onSelect?: (event: Event) => void;

  /**
   * ID for the MenuItemCheckbox.
   */
  id: string;

  /**
   * Prevents the menu from closing when this item is selected.
   */
  shouldKeepOpen?: boolean;
}
