import React from "react";

import classNames from "classnames";

import { Icon } from "../../Icon";
import { Spinner } from "../../Spinner";

import { useSplitButton } from "../SplitButtonContext";

export type ElementUnion = HTMLButtonElement | HTMLAnchorElement;
type AnchorElProps = React.AnchorHTMLAttributes<HTMLAnchorElement>;
type ButtonElProps = React.ButtonHTMLAttributes<HTMLButtonElement>;
type CommonElProps = AnchorElProps &
  ButtonElProps & { ref?: React.Ref<HTMLButtonElement> | null };

/*
 * For examples of the `SplitButtons` use with a drop down menu, see the examples section.
 */
export const SplitButtonPrimary = ({
  label,
  icon,
  iconActive,
  ariaLabel,
  onClick,
  ref,
  ariaControls,
  ariaExpanded,
  ariaHasPopup,
  type,
  form,
  ...props
}: SplitButtonPrimaryProps) => {
  const { buttonStyle, size, isLoading, isFullWidth, surface } =
    useSplitButton();

  const iconSize = {
    l: 40,
    m: 32,
    s: 24,
  };

  const commonProps: CommonElProps = {
    onClick,
    ref,
    ...props,
  };

  const SplitButtonPrimaryClasses = classNames(
    "arc-SplitButtonPrimary",
    "arc-SplitButtonPrimary--button",
    `arc-SplitButtonPrimary--${size}`,
    `arc-SplitButtonPrimary--${buttonStyle}`,
    {
      "arc-SplitButtonPrimary--onDarkSurface": surface === "dark",
      "arc-SplitButtonPrimary--isFullWidth": isFullWidth,
      "arc-SplitButtonPrimary--isLoading": isLoading,
      "arc-SplitButtonPrimary--isIconOnly": !label,
    },
  );

  return (
    <button
      {...props} // props not filtered for radix asChild behaviour
      {...(commonProps as ButtonElProps)}
      className={SplitButtonPrimaryClasses}
      aria-label={ariaLabel}
      aria-haspopup={ariaHasPopup}
      aria-controls={ariaControls}
      aria-expanded={ariaExpanded}
      disabled={isLoading}
      type={type}
      form={form}
    >
      {isLoading && <Spinner size={iconSize[size || "m"]} />}
      {!isLoading && icon && (
        <>
          <span
            className={classNames("arc-SplitButtonPrimary-icon", {
              "arc-SplitButtonPrimary-icon--hasActive": iconActive,
            })}
          >
            <Icon icon={icon} size={iconSize[size || "m"]} />
          </span>
          {iconActive && (
            <span className="arc-SplitButtonPrimary-icon--active">
              <Icon icon={iconActive} size={iconSize[size || "m"]} />
            </span>
          )}
        </>
      )}

      {label}
    </button>
  );
};

interface ButtonV2ElementProps {
  /**
   * Default behavior of the Button element. If not provided, 'submit' will
   * be inferred. Type 'reset' deliberately excluded.
   */
  type?: "button" | "submit";

  /**
   * Refers to the id of a form so it can be submitted if the button exists outside of it.
   */
  form?: string;
}

export interface SplitButtonPrimaryProps extends ButtonV2ElementProps {
  /**
   * Optional property to provide component Ref
   */
  ref?: React.Ref<HTMLButtonElement>;
  /**
   * The text label displayed on the primary action button
   */
  label?: string;
  /**
   * Callback function executed when the primary action is clicked
   */
  onClick?: () => void;
  /**
   * Accessible label for screen readers describing the primary action
   */
  ariaLabel: string;
  /**
   * The icon to display for the default action
   */
  icon?: string;
  /**
   * Render icon within `SplitButtonPrimary` when the button is active.
   */
  iconActive?: string;

  /**
   * Indicates the availability and type of a popup triggered by the button.
   */
  ariaHasPopup?: false | true | "menu" | "listbox" | "dialog" | "grid" | "tree";

  /**
   * Indicates whether the popup controlled by the button is expanded or collapsed.
   */
  ariaExpanded?: boolean;

  /**
   * Defines the ID of the element controlled by the button.
   */
  ariaControls?: string;
}
