import React, { type ReactNode } from "react";

import classNames from "classnames";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";
import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

/**
 * Use `Align` to align items horizontally or vertically.
 */
export const Align = ({
  children,
  horizontal = "left",
  isDebugVisible = false,
  vertical = "top",
  ...props
}: AlignProps) => {
  const wrappedChildren = React.Children.map(children, (child, i) => (
    <AlignItem key={i}>{child}</AlignItem>
  ));

  return (
    <div
      className={classNames({
        [`arc-Align`]: true,
        [suffixModifier("arc-Align--horizontal", horizontal)]:
          horizontal !== "left",
        [`arc-Align--debugVisible`]: isDebugVisible,
        [suffixModifier("arc-Align--vertical", vertical)]: vertical !== "top",
      })}
      {...filterAttrs(props)}
    >
      {wrappedChildren}
    </div>
  );
};

const AlignItem = ({ children }: AlignItemProps) => {
  return <div className="arc-Align-item">{children}</div>;
};

export interface AlignItemProps {
  /**
   * Contents of the AlignItem.
   */
  children?: ReactNode;
}

export interface AlignProps {
  /**
   * Contents of the Align. Each item will be wrapped in an AlignItem component.
   */
  children: ReactNode;

  /**
   * Horizontal alignment of the Align children.
   */
  horizontal?: "left" | "center" | "right";

  /**
   * Should the Align child wrappers be visible for debugging and documentation
   * purposes?
   */
  isDebugVisible?: boolean;

  /**
   * Vertical alignment of the Align children.
   */
  vertical?: "top" | "center" | "bottom";
}
