import React from "react";

import classNames from "classnames";

export const ComboBoxListItemInner = ({
  isHighlighted,
  isSingleSelected,
  children,
}: ComboBoxListItemInnerProps) => (
  <div
    className={classNames("arc-ComboBoxListItemInner", {
      "arc-ComboBoxListItemInner--highlighted": isHighlighted,
      "arc-ComboBoxListItemInner--singleSelected": isSingleSelected,
    })}
  >
    {children}
  </div>
);

interface ComboBoxListItemInnerProps {
  children: React.ReactNode;
  isHighlighted?: boolean;
  isSingleSelected?: boolean;
}
