import { type GroupAvatar } from "../types/group-avatar";

export const getAvatars = (
  avatars: GroupAvatar[],
  max?: number,
): GroupAvatar[] => {
  const maxAvatars = avatars.slice(0, max);
  const hasHiddenAvatars = maxAvatars.length < avatars.length;

  return [
    ...maxAvatars,
    ...(hasHiddenAvatars && max
      ? [{ initials: `+${avatars.length - max}` }]
      : []),
  ];
};
