import React, { type ReactNode } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { Heading } from "../../../../../Heading";
import { ButtonV2 } from "../../../../../ButtonV2";
import { VerticalSpace } from "../../../../../VerticalSpace";

export const NavigationHeaderActionLoginDropdownLoginTile = ({
  tileHeading,
  tileImage,
  primaryButton,
  tertiaryButton,
  isMobile = false,
  ...props
}: NavigationHeaderActionLoginDropdownLoginTileProps) => {
  const buttonSize = isMobile ? "s" : "m";

  return (
    <div
      className={classNames(
        "arc-NavigationHeaderActionLoginDropdownLoginTile",
        {
          "arc-NavigationHeaderActionLoginDropdownLoginTile--isDesktop":
            !isMobile,
        },
      )}
      {...filterAttrs(props)}
    >
      <div className="arc-NavigationHeaderActionLoginDropdownLoginTile-titleWrapper">
        <div className="arc-NavigationHeaderActionLoginDropdownLoginTile-headingWrapper">
          <Heading level="3" size={isMobile ? "xs" : "s"}>
            {tileHeading}
          </Heading>
          {isMobile && <VerticalSpace size="24" />}
        </div>
        <div
          className="arc-NavigationHeaderActionLoginDropdownLoginTile-iconWrapper"
          aria-hidden
        >
          {tileImage}
        </div>
      </div>
      {!isMobile && <VerticalSpace size="24" />}
      <div className="arc-NavigationHeaderActionLoginDropdownLoginTile-buttonWrapper">
        <ButtonV2
          buttonStyle="secondary"
          size={buttonSize}
          label={primaryButton.label ?? "Log in"}
          isFullWidth={!isMobile}
          ariaLabel={`log in ${tileHeading}`}
          onClick={primaryButton.onClick}
          href={primaryButton.href}
        />
        <ButtonV2
          buttonStyle="tertiary"
          size={buttonSize}
          label={tertiaryButton.label ?? "Register"}
          isFullWidth={!isMobile}
          ariaLabel={`register ${tileHeading}`}
          onClick={tertiaryButton.onClick}
          href={tertiaryButton.href}
        />
      </div>
    </div>
  );
};

export interface TileButtonProps {
  /** The text label displayed on the button */
  label?: string;
  /** The URL or path the button links to */
  href: string;
  /** Function called when the button is clicked */
  onClick: () => void;
}

export interface NavigationHeaderActionLoginDropdownLoginTileProps {
  /**
   * The heading text for the login tile.
   */
  tileHeading?: string;
  /**
   * The image for the login tile.
   */
  tileImage?: ReactNode;
  /** Primary button configuration for the login tile */
  primaryButton: TileButtonProps;
  /** Tertiary button configuration for the login tile */
  tertiaryButton: TileButtonProps;
  /** Whether the tile is being rendered in a mobile context */
  isMobile?: boolean;
}
