import React, { useContext, useId, useRef, useState } from "react";

import classNames from "classnames";

import { suffixModifier } from "@arc-ui/helpers/suffix-modifier";

import { Icon } from "../../../../../Icon";
import { Text } from "../../../../../Text";
import { SurfaceContext } from "../../../../../Surface";
import { ConditionalWrapper } from "../../../../../ConditionalWrapper";
import { SemanticButton } from "../../../../../SemanticButton";
import { SemanticLink } from "../../../../../SemanticLink";

import { SideMenuSubMenu, type SideMenuSubMenuProps } from "../SideMenuSubMenu";

const getCommonProps = ({ text, onClick }: SideMenuAction) => ({
  className: "arc-SideMenuActions-item",
  "aria-label": text,
  onClick,
});

export const SideMenuActions = ({
  showSeparator,
  actions,
}: SideMenuActionsProps) => {
  const id = useId();
  const { surface } = useContext(SurfaceContext);
  const [openSubMenuIndex, setOpenSubMenuIndex] = useState<number | null>(null);
  const triggerRefs = useRef<(HTMLButtonElement | null)[]>([]);

  const closeSubMenu = (i: number) => {
    setOpenSubMenuIndex(null);
    triggerRefs.current[i]?.focus();
  };

  return (
    <div
      className={classNames(
        "arc-SideMenuActions",
        suffixModifier("arc-SideMenuActions--on", surface),
      )}
    >
      <div
        className={classNames("arc-SideMenuActions-wrapper", {
          "arc-SideMenuActions--seperator": showSeparator,
        })}
      >
        {actions.map((action, i) => (
          <ConditionalWrapper
            key={`${id}-action-{${i}}`}
            condition={Boolean(action.href)}
            wrapper={(children) => (
              <SemanticLink {...getCommonProps(action)} href={action.href}>
                {children}
              </SemanticLink>
            )}
            fallback={(children) => (
              <SemanticButton
                {...getCommonProps(action)}
                ref={
                  action.subMenu
                    ? (el) => {
                        triggerRefs.current[i] = el;
                      }
                    : undefined
                }
                onClick={(e) => {
                  action.subMenu ? setOpenSubMenuIndex(i) : action.onClick?.(e);
                }}
              >
                {children}
              </SemanticButton>
            )}
          >
            <div className="arc-SideMenuActions-content">
              <div
                className={classNames("arc-SideMenuActions-icon", {
                  "arc-SideMenuActions-icon--attention": action.isAttention,
                })}
              >
                <Icon aria-hidden icon={action.icon} size={28} />
              </div>

              <Text size="l">{action.text}</Text>
            </div>
          </ConditionalWrapper>
        ))}
      </div>

      {actions.map(
        (action, i) =>
          action.subMenu && (
            <SideMenuSubMenu
              key={`${id}-submenu-${i}`}
              {...action.subMenu}
              isOpen={openSubMenuIndex === i}
              onBackClick={() => closeSubMenu(i)}
              onCloseAutoFocus={() => closeSubMenu(i)}
            />
          ),
      )}
    </div>
  );
};

export interface SideMenuAction {
  /**
   * Icon for the action.
   */
  icon: string;
  /**
   * Text label for the action.
   */
  text: string;
  /**
   * Display a red dot next to the action to alert users.
   */
  isAttention?: boolean;
  /**
   * URL for the action link.
   */
  href?: string;
  /**
   * Click handler for the action. Not used when subMenu is provided.
   */
  onClick?: (e: React.MouseEvent<HTMLElement, MouseEvent>) => void;
  /**
   * Sub menu to open when the action is clicked.
   */
  subMenu?: Omit<
    SideMenuSubMenuProps,
    "isOpen" | "onBackClick" | "onCloseAutoFocus"
  >;
}

interface SideMenuActionsProps {
  /**
   * Whether to show a separator above the actions.
   */
  showSeparator: boolean;
  /**
   * Array of actions to display.
   */
  actions: SideMenuAction[];
}
