import React, { type ReactNode, useMemo, useRef, useState } from "react";

import { useUniqueString } from "../../../../hooks";

import { SubNavContext } from "./NavigationHeaderSubnav.provider";

export const NavigationHeaderSubnav = ({
  children,
  onOpenChange,
}: NavigationHeaderSubnavProps) => {
  const id = useUniqueString("subnav");
  const rootRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const [isOpen, setIsOpen] = useState(false);

  const value = useMemo(
    () => ({ id, triggerRef, rootRef, isOpen, setIsOpen, onOpenChange }),
    [id, isOpen, onOpenChange],
  );

  return (
    <SubNavContext.Provider value={value}>
      <div ref={rootRef}>{children}</div>
    </SubNavContext.Provider>
  );
};

interface NavigationHeaderSubnavProps {
  /**
   * Content to display in the subnav.
   */
  children: ReactNode;
  /**
   * Callback when subnav visibility changes.
   */
  onOpenChange?: (isVisble: boolean) => void;
}
