import React from "react";

import { Icon } from "../../Icon";
import { Text } from "../../Text";

export const MenuItemContentTemplate = ({
  leadingIcon,
  supportingText,
  keyCommands,
  trailingIcon,
  children,
}: MenuItemContentTemplateProps) => {
  return (
    <>
      <div className="arc-MenuItem-content">
        {leadingIcon && (
          <div className="arc-MenuItem-leadingIcon">
            <Icon icon={leadingIcon} size={24} />
          </div>
        )}
        <div className="arc-MenuItem-text">
          <Text size="m">{children}</Text>
          {supportingText && <Text size="xs">{supportingText}</Text>}
        </div>
      </div>
      {keyCommands || trailingIcon ? (
        <div className="arc-MenuItem-actions">
          {keyCommands && (
            <div className="arc-MenuItem-keyCommands">{keyCommands}</div>
          )}
          {trailingIcon && (
            <div className="arc-MenuItem-trailingIcon">
              <Icon icon={trailingIcon} size={24} />
            </div>
          )}
        </div>
      ) : null}
    </>
  );
};

export interface MenuItemContentTemplateProps {
  /**
   * Optional supporting text that appears below the label for additional context.
   */
  supportingText?: string;

  /**
   * An optional leading icon displayed on the left side of the menu item.
   */
  leadingIcon?: string;

  /**
   * An optional trailing icon displayed on the right side of the menu item.
   */
  trailingIcon?: string;

  /**
   * The main label text displayed in the menu item.
   */
  children: string;

  /**
   * Optional keyboard shortcut text displayed next to the item (e.g., "⌘ + K").
   */
  keyCommands?: string;
}
