import React from "react";

import { Item } from "@radix-ui/react-dropdown-menu";

import { Rule } from "../../Rule";

import {
  MenuItemContentTemplate,
  type MenuItemContentTemplateProps,
} from "../MenuItemContentTemplate/MenuItemContentTemplate";

/**
 * Displays footer content at the bottom of the menu.
 */

export const MenuFooter = ({
  leadingIcon,
  trailingIcon,
  supportingText,
  keyCommands,
  children,
  onClick,
  isDisabled,
  ariaLabel,
}: MenuFooterProps) => {
  return (
    <div
      className="arc-MenuFooter"
      style={{
        position: "relative",
      }}
    >
      <div className="arc-MenuSeparator" style={{ paddingTop: 0 }}>
        <Rule />
      </div>

      <Item
        className="arc-MenuItem"
        aria-label={ariaLabel}
        onClick={onClick}
        disabled={isDisabled}
      >
        <MenuItemContentTemplate
          leadingIcon={leadingIcon}
          trailingIcon={trailingIcon}
          supportingText={supportingText}
          keyCommands={keyCommands}
        >
          {children}
        </MenuItemContentTemplate>
      </Item>
    </div>
  );
};

export interface MenuFooterProps extends MenuItemContentTemplateProps {
  /**
   * Click event handler triggered when the menu header is selected.
   */
  onClick?: () => void;

  /**
   * Optional URL that makes the menu item behave as a link.
   */
  href?: string;

  /**
   * ARIA label for accessibility, used to provide a descriptive label for screen readers.
   */
  ariaLabel?: string;

  /**
   * disables the menu item, preventing user interaction.
   */
  isDisabled?: boolean;
}
