import React from "react";

import { type Responsive } from "../types/responsive";
import { type ScreenSizes } from "../types/screen-sizes";
import { type SlideConfig } from "../types/slide-config";

export const getSlideWidth = ({
  screenSizes,
  itemsPerSlide,
  isPartialVisible,
  responsive,
  children,
}: getSlideWidthParams) => {
  const responsiveConfig =
    responsive &&
    (Object.keys(screenSizes) as Array<keyof typeof screenSizes>).find(
      (size) => {
        return responsive && screenSizes[size] && responsive[size];
      },
    );

  const slideConfig = responsiveConfig
    ? (responsive[responsiveConfig] as Required<SlideConfig>)
    : { itemsPerSlide, isPartialVisible };

  const totalItems = React.Children.count(children);

  const itemsPerView =
    slideConfig.itemsPerSlide > totalItems
      ? 1
      : Math.max(1, slideConfig.itemsPerSlide);

  const widthAdjustment = slideConfig.isPartialVisible ? 10 : 0;

  return (100 - widthAdjustment) / itemsPerView;
};

interface getSlideWidthParams {
  itemsPerSlide: number;
  isPartialVisible: boolean;
  screenSizes: ScreenSizes;
  responsive?: Responsive;
  children: React.ReactNode;
}
