import React from "react";

import classNames from "classnames";

import { BtIconFirstMid } from "@arc-ui/icons/BtIconFirstMid";
import { BtIconLastMid } from "@arc-ui/icons/BtIconLastMid";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { ThemeIcon } from "../ThemeIcon";
import { Icon } from "../Icon";

/**
 * TODO! Revise method of aligning svg's
 */

/**
 * Use `PaginationSimple` to navigate through multiple pages of content.
 */
export const PaginationSimple = ({
  hide,
  hrefs,
  onPageChange,
  isFluid,
  showEllipsis,
  ...props
}: PaginationSimpleProps) => {
  return (
    <nav
      className={classNames("arc-PaginationSimple", {
        "arc-PaginationSimple--fluid": isFluid,
        "arc-PaginationSimple--centered": !isFluid,
      })}
      {...filterAttrs(props)}
    >
      <ul className="arc-PaginationSimple-list">
        <li className="arc-PaginationSimple-listItem">
          <a
            tabIndex={0}
            href={hrefs?.first}
            role={!hrefs?.first ? "button" : undefined}
            className={classNames("arc-PaginationSimple-navigationButton", {
              "arc-PaginationSimple-navigationButton--hidden": hide?.first,
            })}
            onClick={(e) => onPageChange!(e, "first")}
          >
            <div className="arc-PaginationSimple-iconContainer">
              <Icon size={32} icon={BtIconFirstMid} />
            </div>

            <span className="arc-PaginationSimple-prevText">First</span>
          </a>

          <a
            tabIndex={0}
            href={hrefs?.prev}
            role={!hrefs?.prev ? "button" : undefined}
            className={classNames("arc-PaginationSimple-navigationButton", {
              "arc-PaginationSimple-navigationButton--hidden": hide?.prev,
            })}
            onClick={(e) => onPageChange!(e, "prev")}
          >
            <div className="arc-PaginationSimple-iconContainer arc-PaginationSimple-iconContainer--left ">
              <ThemeIcon size={32} icon="paginationSimplePrevious" />
            </div>

            <span className="arc-PaginationSimple-prevText">Prev</span>
          </a>
        </li>
        <li
          className={classNames(
            "arc-PaginationSimple-listItem arc-PaginationSimple-listItemEllipsis",
            {
              "arc-PaginationSimple-listItemEllipsis--hidden": !showEllipsis,
            },
          )}
        >
          ...
        </li>
        <li className="arc-PaginationSimple-listItem">
          <a
            tabIndex={0}
            href={hrefs?.next}
            role={!hrefs?.next ? "button" : undefined}
            className={classNames("arc-PaginationSimple-navigationButton", {
              "arc-PaginationSimple-navigationButton--hidden": hide?.next,
            })}
            onClick={(e) => onPageChange!(e, "next")}
          >
            <span className="arc-PaginationSimple-nextText">Next</span>
            <div className="arc-PaginationSimple-iconContainer arc-PaginationSimple-iconContainer--right ">
              <ThemeIcon size={32} icon="paginationSimpleNext" />
            </div>
          </a>
          <a
            tabIndex={0}
            href={hrefs?.last}
            role={!hrefs?.last ? "button" : undefined}
            className={classNames("arc-PaginationSimple-navigationButton", {
              "arc-PaginationSimple-navigationButton--hidden": hide?.last,
            })}
            onClick={(e) => onPageChange!(e, "last")}
          >
            <span className="arc-PaginationSimple-nextText">Last</span>

            <div className="arc-PaginationSimple-iconContainer">
              <Icon size={32} icon={BtIconLastMid} />
            </div>
          </a>
        </li>
      </ul>
    </nav>
  );
};

export interface PaginationSimpleProps {
  /**
   * hide buttons if true.
   */
  hide?: {
    first?: boolean;
    prev?: boolean;
    next?: boolean;
    last?: boolean;
  };

  /**
   * makes each button a link
   */
  hrefs?: {
    first?: string;
    prev?: string;
    next?: string;
    last?: string;
  };

  /**
   * if true buttons will hug either edge of the parent element
   */
  isFluid?: boolean;

  /**
   * if true ellipsis will show in-between previous and next
   */

  /**
   * Function to call when page is changed. This is called with type and event
   */
  showEllipsis?: boolean;

  /**
   * Function to call when page is changed. This is called with type and event
   */
  onPageChange?: (
    e: React.MouseEvent,
    type?: "prev" | "next" | "first" | "last",
  ) => void;
}
