import isBefore from "date-fns/isBefore";
import isAfter from "date-fns/isAfter";
import compareAsc from "date-fns/compareAsc";

export const getHighlightRange = ({
  date,
  minDate,
  maxDate,
  range,
}: {
  date: Date;
  minDate?: Date;
  maxDate?: Date;
  range: Date[];
}): Date[] => {
  const existingRange = range.filter((date) => Boolean(date));

  if (existingRange.filter((date) => Boolean(date)).length === 1) {
    const isDateBeforeMinDate = minDate && isBefore(date, minDate);
    const isDateAfterMaxDate = maxDate && isAfter(date, maxDate);

    if (isDateBeforeMinDate) {
      return [minDate, existingRange[0]].sort(compareAsc);
    }

    if (isDateAfterMaxDate) {
      return [maxDate, existingRange[0]].sort(compareAsc);
    }

    return [date, existingRange[0]].sort(compareAsc);
  }

  return existingRange;
};
