import React, { useEffect, useReducer, useState } from "react";

import addMonths from "date-fns/addMonths";
import subMonths from "date-fns/subMonths";
import startOfMonth from "date-fns/startOfMonth";

import { ArcSizeBreakpointsM } from "@arc-ui/tokens-arc";
import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { useMediaQuery } from "../../hooks";

import {
  dateWithoutTime,
  isMonthAfterMaxDate,
  isMonthBeforeMinDate,
  isDisabledDate,
  processSelectedRange,
  getCalendarType,
  getDoubleMonthDisplayRange,
} from "./helpers";

import {
  type CalendarType,
  type RangeSelection,
  type KeyNames,
  type SelectionType,
} from "./types";

import {
  CalendarDoubleMonthView,
  CalendarMonthView,
  CalendarMonthYearView,
} from "./components";

import { reducer } from "./state";
import { ArcCalendarContext } from "./Calendar.provider";
import { CalendarFooter } from "./components/CalendarFooter";
import { CalendarWrapper } from "./components/CalendarWrapper";

/** Use `Calendar` to clearly present available dates and allowing users to choose a way to enter information. */
export const Calendar = ({
  type = "month",
  selectionType = "single",
  autoFocusOnMount = false,
  selectedRange: rawSelectedRange = [],
  selectedDate: rawSelectedDate = new Date(),
  disabledDates: rawDisabledDates,
  minDate: rawMinDate,
  maxDate: rawMaxDate,
  onCancelClick,
  onDateSelect,
  onRangeSelect,
  uncontained = false,
  ...props
}: CalendarProps) => {
  const todayDate = dateWithoutTime(new Date());
  const selectedDate = dateWithoutTime(rawSelectedDate);
  const selectedRange = rawSelectedRange
    .filter((rangeDate) => Boolean(rangeDate))
    .map((rangeDate) => dateWithoutTime(rangeDate));

  const [isClientLoaded, setIsClientLoaded] = useState(false);

  const [{ displayDate, focusDate, highlightedRange }, dispatch] = useReducer(
    reducer,
    {
      displayDate:
        selectionType === "single"
          ? startOfMonth(selectedDate)
          : startOfMonth(selectedRange[0] || todayDate),
      focusDate:
        selectionType === "single"
          ? selectedDate
          : selectedRange[0] || todayDate,
      highlightedRange: selectedRange,
    },
  );

  const isMinWidthArcBreakpointM = useMediaQuery(
    `(min-width: ${ArcSizeBreakpointsM})`,
  );

  useEffect(() => {
    setIsClientLoaded(true);
  }, []);

  const disabledDates = rawDisabledDates?.map((date) => dateWithoutTime(date));
  const minDate = rawMinDate && dateWithoutTime(rawMinDate);
  const maxDate = rawMaxDate && dateWithoutTime(rawMaxDate);

  const calendarType = getCalendarType(type, isMinWidthArcBreakpointM);
  const doubleMonthDisplayRange = getDoubleMonthDisplayRange(displayDate);

  const isPreviousMonthDisabled = minDate
    ? isMonthBeforeMinDate(subMonths(displayDate, 1), minDate)
    : false;

  const isNextMonthDisabled = maxDate
    ? isMonthAfterMaxDate(addMonths(displayDate, 1), maxDate)
    : false;

  const isDoubleMonthPreviousDisabled = minDate
    ? isMonthBeforeMinDate(subMonths(doubleMonthDisplayRange[0], 1), minDate)
    : false;

  const isDoubleMonthNextDisabled = maxDate
    ? isMonthAfterMaxDate(addMonths(doubleMonthDisplayRange[1], 1), maxDate)
    : false;

  const setDateRange = (value: Date) => {
    const { rangeOnChangeValue, rangeValue } = processSelectedRange({
      value,
      range: selectedRange,
      disabledDates,
    });

    dispatch({
      type: "RANGE_SELECT",
      payload: {
        date: value,
        range: rangeValue,
      },
    });

    onRangeSelect && onRangeSelect(rangeOnChangeValue);
  };

  const setNewDate = (value: Date) => {
    dispatch({
      type: "DAY_NUMBER_SELECT",
      payload: value,
    });

    onDateSelect && onDateSelect(value);
  };

  const onDayNumberHover = (date: Date) => () => {
    selectionType === "range" &&
      dispatch({
        type: "HIGHLIGHT_RANGE",
        payload: {
          date,
          minDate,
          maxDate,
          range: selectedRange,
        },
      });
  };

  const handleDateSelection = (date: Date) => {
    const isDisabled = isDisabledDate(date, disabledDates, minDate, maxDate);

    if (isDisabled) return;

    selectionType === "single" ? setNewDate(date) : setDateRange(date);
  };

  const onDayNumberClick = (date: Date) => () => {
    handleDateSelection(date);
  };

  const onCancelButtonClick = () => {
    onCancelClick && onCancelClick();
  };

  const onDayGridLeave = () => {
    dispatch({
      type: "DAY_GRID_LEAVE",
      payload: {
        selectionType,
        range: selectedRange,
      },
    });
  };

  const onPreviousMonthClick = () => {
    dispatch({
      type: "SHOW_PREVIOUS_MONTH",
      payload: {
        minDate,
      },
    });
  };

  const onNextMonthClick = () => {
    dispatch({
      type: "SHOW_NEXT_MONTH",
      payload: {
        maxDate,
      },
    });
  };

  const onDoubleViewPreviousClick = () => {
    dispatch({
      type: "SHOW_PREVIOUS_DOUBLE_MONTH",
      payload: {
        minDate,
      },
    });
  };

  const onDoubleViewNextClick = () => {
    dispatch({
      type: "SHOW_NEXT_DOUBLE_MONTH",
      payload: {
        maxDate,
      },
    });
  };

  const onYearChange = (year: number) => {
    dispatch({
      type: "DROPDOWN_CHANGE_YEAR",
      payload: {
        year,
        minDate,
        maxDate,
      },
    });
  };

  const onMonthChange = (month: number) => {
    dispatch({
      type: "DROPDOWN_CHANGE_MONTH",
      payload: {
        month,
        minDate,
        maxDate,
      },
    });
  };

  const onKeyboardNavigate = (key: KeyNames, shiftKey: boolean) => {
    dispatch({
      type: "CALENDAR_KEYDOWN",
      payload: {
        minDate,
        maxDate,
        selectionType,
        calendarType,
        key,
        shiftKey,
        range: selectedRange,
      },
    });
  };

  return (
    <ArcCalendarContext.Provider
      value={{
        minDate,
        maxDate,
        focusDate,
        todayDate,
        displayDate,
        onDayGridLeave,
        disabledDates,
        selectedDate,
        selectionType,
        selectedRange,
        highlightedRange,
        onDayNumberClick,
        onDayNumberHover,
        onKeyboardNavigate,
        autoFocusOnMount,
      }}
      {...filterAttrs(props)}
    >
      <div style={{ display: isClientLoaded ? "block" : "none" }}>
        <CalendarWrapper uncontained={uncontained}>
          {calendarType === "year" && (
            <CalendarMonthYearView
              isPreviousMonthDisabled={isPreviousMonthDisabled}
              isNextMonthDisabled={isNextMonthDisabled}
              onPreviousMonthClick={onPreviousMonthClick}
              onNextMonthClick={onNextMonthClick}
              onMonthChange={onMonthChange}
              onYearChange={onYearChange}
            />
          )}

          {calendarType === "month" && (
            <CalendarMonthView
              isPreviousMonthDisabled={isPreviousMonthDisabled}
              isNextMonthDisabled={isNextMonthDisabled}
              onPreviousMonthClick={onPreviousMonthClick}
              onNextMonthClick={onNextMonthClick}
            />
          )}

          {calendarType === "double" && (
            <CalendarDoubleMonthView
              isPreviousMonthDisabled={isDoubleMonthPreviousDisabled}
              isNextMonthDisabled={isDoubleMonthNextDisabled}
              onPreviousMonthClick={onDoubleViewPreviousClick}
              onNextMonthClick={onDoubleViewNextClick}
            />
          )}

          {onCancelClick && (
            <CalendarFooter onCancelClick={onCancelButtonClick} />
          )}
        </CalendarWrapper>
      </div>
    </ArcCalendarContext.Provider>
  );
};

export interface CalendarProps {
  /**
   * Select single date or range
   */
  selectionType?: SelectionType;

  /**
   * Dates before this will be disabled.
   */
  minDate?: Date;

  /**
   * Dates after this will be disabled.
   */
  maxDate?: Date;

  /**
   * Selected Date for Calendar
   */
  selectedDate?: Date;

  /**
   * Selected range for Calendar
   */
  selectedRange?: Date[];

  /**
   * Called when cancel button is clicked.
   */
  onCancelClick?: () => void;

  /**
   * Called when a range is selected.
   */
  onRangeSelect?: (range: RangeSelection) => void;

  /**
   * Called when a date is selected.
   */
  onDateSelect?: (date: Date) => void;

  /**
   * Array of disabled dates
   */
  disabledDates?: Date[];

  /**
   * Calendar type.
   */
  type?: CalendarType;

  /**
   * Focus will be set on the selected day when the component mounts, defaults to false.
   */
  autoFocusOnMount?: boolean;

  /**
   * Whether the calendar should be uncontained
   */
  uncontained?: boolean;
}
