import React, { type ReactNode } from "react";

import { Root } from "@radix-ui/react-tabs";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

/** Use `ContentSwitcher` to allow users to navigate between different sections of relevant content. */
export const ContentSwitcher = ({
  children,
  defaultValue,
  onValueChange,
  activationMode,
  value,
  ...props
}: ContentSwitcherProps) => {
  return (
    <span className="arc-ContentSwitcher">
      <Root
        className="arc-ContentSwitcher-root"
        defaultValue={defaultValue}
        onValueChange={onValueChange}
        activationMode={activationMode}
        value={value}
        {...filterAttrs(props)}
      >
        {children}
      </Root>
    </span>
  );
};

export interface ContentSwitcherProps {
  /**
   * Render children
   */
  children: ReactNode;

  /**
   * Default to an inital value of a tab. If this is left blank it is possible for there to be no active tabs
   */
  defaultValue?: string;

  /**
   * Event handler called when the value changes.
   */
  onValueChange?: (value: string) => void;

  /**
   * When automatic, tabs are activated when receiving focus. When manual, tabs are activated when clicked.
   */
  activationMode?: "automatic" | "manual";

  /**
   * value for the `ContentSwitcher`. Passing a value makes the Select a controlled component.
   */
  value?: string;
}
