import React, { type Ref, useContext } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { FormControlContext } from "../FormControl";
import { useAriaDescribedby } from "../../hooks";
import { SurfaceContext } from "../Surface";
import { ThemeIcon } from "../ThemeIcon";
import { VisuallyHidden } from "../VisuallyHidden";
import { CheckboxIcon } from "../CheckboxIcon";

/**
 *  Use `Checkbox` to allow users to select individual options.
 */
export const Checkbox = ({
  checked = false,
  errorMessage,
  helper,
  id,
  isDisabled = false,
  isRequired = false,
  label,
  hideLabel = false,
  name,
  onBlur,
  onChange,
  size = "m",
  value,
  checkboxAlignment = "center",
  indeterminate = false,
  isError = false,
  isErrorAlert = false,
  ref,
  ...props
}: CheckboxProps) => {
  const { requirementStatus } = useContext(FormControlContext);
  const { surface } = useContext(SurfaceContext);
  const { idError } = useAriaDescribedby({
    id: id,
    errorMessage,
  });

  const idLabel = `${id}-label`;

  const isIndeterminate = checked ? indeterminate : false;

  if (requirementStatus === "required") {
    isRequired = true;
  }

  return (
    <div
      className={classNames({
        "arc-Checkbox": true,
        "arc-Checkbox--disabled": isDisabled,
        "arc-Checkbox--invalid": errorMessage || isError,
        "arc-Checkbox--small": size === "s",
        "arc-Checkbox--onDarkSurface": surface === "dark",
      })}
      ref={ref} // checkbox didn't have ref
      {...filterAttrs(props)}
    >
      <label
        id={idLabel}
        htmlFor={id}
        className={classNames("arc-Checkbox-label", {
          "arc-Checkbox-label--top": checkboxAlignment === "top",
        })}
      >
        <CheckboxIcon
          size={size}
          id={id}
          error={errorMessage || isError ? true : false}
          isDisabled={isDisabled}
          isRequired={isRequired}
          checked={checked}
          indeterminate={isIndeterminate}
          ariaDescribedBy={idError}
          name={name}
          onBlur={onBlur}
          onChange={onChange}
          value={value}
        />
        <span
          className="arc-Checkbox-content"
          {...(checkboxAlignment === "top" && {
            className: "arc-Checkbox-content--marginTop arc-Checkbox-content",
          })}
        >
          {hideLabel ? (
            <VisuallyHidden>
              {label}
              {!isRequired && requirementStatus !== "optional" ? (
                <span className="arc-Checkbox-labelOptional">(optional)</span>
              ) : null}
              {helper && <span className="arc-Checkbox-helper">{helper}</span>}
            </VisuallyHidden>
          ) : (
            <>
              {label}
              {!isRequired && requirementStatus !== "optional" ? (
                <span className="arc-Checkbox-labelOptional">(optional)</span>
              ) : null}
              {helper && <span className="arc-Checkbox-helper">{helper}</span>}
            </>
          )}
        </span>
      </label>

      {errorMessage && (
        <div
          id={idError}
          className="arc-Checkbox-error"
          role={isErrorAlert ? "alert" : undefined}
        >
          <span className="arc-Checkbox-error--icon" aria-label="Error. ">
            <ThemeIcon icon="checkboxError" />
          </span>
          {errorMessage}
        </div>
      )}
    </div>
  );
};

type CheckedProps = {
  /**
   * Is the input checked?
   */
  checked?: boolean;
  /**
   * The initial checked state of the Checkbox.
   */
  defaultChecked?: boolean;
  /**
   * sets the state of the Checkbox to be indeterminate
   */
  indeterminate?: boolean;
};

export interface CheckboxProps extends Omit<CheckedProps, "defaultChecked"> {
  /**
   * Optional property to provide component Ref
   */
  ref?: Ref<HTMLInputElement>;
  /**
   * Error message for the Checkbox.
   */
  errorMessage?: string;
  /**
   * Show error state for checkbox, useful if used within a group of checkboxes.
   */
  isError?: boolean;
  /**
   * Helper text for the Checkbox, shown below the label.
   */
  helper?: React.ReactNode;
  /**
   * Determine the alignment of the Checkbox.
   */
  checkboxAlignment?: "top" | "center";
  /**
   * ID for the Checkbox.
   */
  id: string;
  /**
   * `isDisabled` is a legacy property and not recommended from a UX usability best practice perspective.
   */
  isDisabled?: boolean;
  /**
   * Is the Checkbox required?
   */
  isRequired?: boolean;
  /**
   * Label for the Checkbox.
   */
  label: React.ReactNode;
  /**
   * Use `hideLabel` to visually hide the `Checkbox` label. This still allows screen readers to have access to labels. This is set to `false` by default.
   */
  hideLabel?: boolean;
  /**
   * Name for the Checkbox.
   */
  name?: string;
  /**
   * Function to call when the Checkbox loses focus.
   */
  onBlur?: (e: React.FocusEvent<HTMLInputElement>) => void;
  /**
   * Callback function to update the Checkbox's controlled `checked` prop, for
   * example `e => setChecked(e.target.checked)`.
   */
  onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;
  /**
   * Size of the Checkbox.
   */
  size?: "m" | "s";
  /**
   * Value for the Checkbox.
   */
  value?: string;

  /**
   * Provide the "alert" role to the errorMessage.
   */
  isErrorAlert?: boolean;
}
