import React, {
  type ReactNode,
  useContext,
  useRef,
  useState,
  useEffect,
} from "react";

import debounce from "lodash/debounce";
import classNames from "classnames";

import { List } from "@radix-ui/react-tabs";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { SurfaceContext } from "../../../Surface";
import { type TabsItemProps } from "../TabsItem";

export const TabsList = ({
  children,
  type = "standard",
  isJustified,
  ariaLabel,
  ...props
}: TabsListProps) => {
  const [rightOverflow, setRightOverflow] = useState(false);
  const [leftOverflow, setLeftOverflow] = useState(false);

  const { surface, background, isTransparent } = useContext(SurfaceContext);
  const tabsRef = useRef<HTMLDivElement>(null);
  const tabRefs = useRef<(HTMLButtonElement | null)[]>([]);

  const scrollTabIntoView = (tabRef: React.RefObject<HTMLButtonElement>) => {
    if (tabRef.current && tabsRef.current) {
      const scrollLeft =
        tabRef.current.offsetLeft -
        tabsRef.current.clientWidth / 2 +
        tabRef.current.clientWidth / 2;

      tabsRef.current.scrollTo({
        left: scrollLeft,
        behavior: "smooth",
      });
    }
  };

  const handleResize = debounce(() => {
    checkOverflow();
  }, 100);

  const checkOverflow = () => {
    if (tabsRef.current) {
      setRightOverflow(
        tabsRef.current.scrollLeft + tabsRef.current.clientWidth <
          tabsRef.current.scrollWidth - 1,
      );
      setLeftOverflow(tabsRef.current.scrollLeft > 0);
    }
  };

  useEffect(() => {
    const list = tabsRef.current;
    handleResize();

    if (list) {
      list.addEventListener("scroll", checkOverflow);
      window.addEventListener("resize", handleResize);
    }

    return () => {
      if (list) {
        list.removeEventListener("scroll", checkOverflow);
      }
      window.removeEventListener("resize", handleResize);
      handleResize.cancel();
    };
  }, [children, handleResize]);

  return (
    <span className="arc-TabsList-wrapper">
      <List
        className={classNames("arc-Tabs", {
          "arc-Tabs--contained": type === "contained",
          "arc-Tabs--isJustified": isJustified,
          "arc-Tabs--onDarkSurface": surface === "dark",
        })}
        ref={tabsRef}
        aria-label={ariaLabel}
        {...filterAttrs(props)}
      >
        {React.Children.map(children, (child, index) => {
          if (!React.isValidElement<TabsItemProps>(child)) {
            return child;
          }
          if (tabRefs.current[index] !== null) {
            return React.cloneElement(child, {
              ref: (el: HTMLButtonElement) => {
                tabRefs.current[index] = el;
              },
              onClick: () => {
                const el = tabRefs.current[index];
                if (el) scrollTabIntoView({ current: el });
              },
              onFocus: () => {
                const el = tabRefs.current[index];
                if (el) scrollTabIntoView({ current: el });
              },
            });
          } else {
            return child;
          }
        })}
      </List>
      {type === "standard" && (leftOverflow || rightOverflow) && (
        <span
          className={classNames(
            "arc-TabsList-overflowWrapper",
            background &&
              !isTransparent &&
              `arc-TabsList-overflowWrapper--background-${background}`,
            {
              "arc-TabsList-overflowWrapper--onDarkSurface": surface === "dark",
            },
          )}
        >
          {leftOverflow && <div className="arc-TabsList--leftOverflow" />}
          {rightOverflow && <div className="arc-TabsList--rightOverflow" />}
        </span>
      )}
    </span>
  );
};

export interface TabsListProps {
  /**
   * Contents of the `Tabs` Should contain `Tab`
   */
  children: ReactNode;

  /**
   * Determine if `Tabs` should be justified
   */
  isJustified?: boolean;

  /**
   * Determine the type of `Tabs`. Default is standard
   */
  type?: "standard" | "contained";

  /**
   * Determine a accessible label for `Tabs`
   */
  ariaLabel?: string;
}
