import React, { useState } from "react";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import {
  TemplateBanner,
  type TemplateBannerProps,
} from "../TemplateBanner/TemplateBanner";
import {
  ContentSwitcher,
  ContentSwitcherContent,
  ContentSwitcherList,
  ContentSwitcherTab,
} from "../ContentSwitcher";
import {
  ContentSwitcherDropdown,
  ContentSwitcherDropdownContent,
} from "../ContentSwitcherDropdown";

/** Use `TabbedBanner` to combine a banner layout with `ContentSwitcher` and `ContentSwitcherDropdown`, allowing users to switch between related content sections. */

export const TabbedBanner = ({
  tabs,
  defaultValue,
  minHeight,
  minHeightM,
  minHeightL,
  minHeightXL,
  ...props
}: TabbedBannerProps) => {
  const initialTab = defaultValue ?? tabs[0]?.value;
  const [selectedTab, setSelectedTab] = useState<string>(initialTab);

  return (
    <div className="arc-TabbedBanner" {...filterAttrs(props)}>
      <div className="arc-TabbedBanner--desktop">
        <ContentSwitcher
          value={selectedTab}
          onValueChange={(value: string) => setSelectedTab(value)}
        >
          <ContentSwitcherList isInset>
            {tabs.map(({ label, value }, index) => (
              <ContentSwitcherTab
                label={label}
                value={value}
                key={`${index}-${value}`}
              />
            ))}
          </ContentSwitcherList>
          {tabs.map(({ value, content }, index) => (
            <ContentSwitcherContent
              value={value}
              key={`${index}-${value}`}
              hidden={value !== selectedTab}
            >
              <TemplateBanner
                alignment="start"
                headingSize={"m"}
                additionalTopMargin
                minHeight={minHeight}
                minHeightM={minHeightM}
                minHeightL={minHeightL}
                minHeightXL={minHeightXL}
                {...content}
              />
            </ContentSwitcherContent>
          ))}
        </ContentSwitcher>
      </div>

      <div className="arc-TabbedBanner--mobile">
        <ContentSwitcherDropdown
          value={selectedTab}
          tabs={tabs}
          isInset
          isFluid
          onValueChange={(value: string) => setSelectedTab(value)}
        >
          {tabs.map(({ value, content }, index) => (
            <ContentSwitcherDropdownContent
              value={value}
              key={`${index}-${value}`}
            >
              <TemplateBanner
                alignment="start"
                headingSize={"m"}
                additionalTopMargin
                {...content}
              />
            </ContentSwitcherDropdownContent>
          ))}
        </ContentSwitcherDropdown>
      </div>
    </div>
  );
};

export interface TabbedBannerProps {
  /**
   * Determine what tabs to render. They need both a `value` and `label` prop
   */
  tabs: {
    value: string;
    label: string;
    content: TemplateBannerProps;
  }[];

  /**
   * Default to an inital value of a tab. If this is left blank it will default to first tab.
   */
  defaultValue?: string;

  /**
   * The minimum height of all banners at the M breakpoint and above.
   * Can be overridden by the specific breakpoint controls.
   */
  minHeight?: TemplateBannerProps["minHeight"];

  /**
   * The minimum height of the banner for the M breakpoint.
   * Active when viewport width is between 768px and 1023px.
   */
  minHeightM?: TemplateBannerProps["minHeightM"];

  /**
   * The minimum height of the banner for the L breakpoint.
   * Active when viewport width is between 1024px and 1279px.
   */
  minHeightL?: TemplateBannerProps["minHeightL"];

  /**
   * The minimum height of the banner for the XL breakpoint.
   * Active when viewport width is 1280px and above
   */
  minHeightXL?: TemplateBannerProps["minHeightXL"];
}
