import React, { useContext, type ReactNode } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { Heading, type HeadingProps } from "../Heading";
import { VerticalSpace } from "../VerticalSpace";

import { VideoPlayer, type VideoPlayerProps } from "../VideoPlayer";
import { Surface, SurfaceContext } from "../Surface";
import { type SurfaceBackgroundColor } from "../Surface/Surface";

import { type HeadingColor } from "../Heading/Heading";

const defaultHeadingProps: Partial<HeadingProps> = {
  isWordWrap: false,
  color: "auto",
  fontStyle: "default",
} as const;

/**
 * HeroVideoBanner is a component that displays a heading, text, and a video player in a banner.
 */
export const HeroVideoBanner = ({
  heading,
  label,
  text,
  video,
  labelColor = "auto",
  type = "contained",
  alignment,
  extendBeyondContainer,
  children,
  ...props
}: HeroVideoBannerProps) => {
  const { surface: parentSurface } = useContext(SurfaceContext);

  const baseType = baseTypes[type];
  const surfaceBackground = surfaceBackgrounds[type];

  return (
    <div
      className={classNames("arc-HeroVideoBanner", {
        [`arc-HeroVideoBanner--${baseType}`]: true,
        "arc-HeroVideoBanner--expanded":
          extendBeyondContainer && baseType === "contained",
      })}
      {...filterAttrs(props)}
    >
      <Surface
        background={surfaceBackground}
        {...(baseType === "uncontained" && {
          isTransparent: true,
          background: parentSurface === "dark" ? "dark-black" : "light-white",
        })}
      >
        <div
          className={classNames("arc-HeroVideoBanner-body", {
            [`arc-HeroVideoBanner-body--${alignment}`]: alignment === "center",
          })}
        >
          <div className="arc-HeroVideoBanner-content">
            {label && (
              <>
                <Heading fontStyle="overline" color={labelColor}>
                  {label}
                </Heading>
                <VerticalSpace size="8" />
              </>
            )}
            <Heading {...defaultHeadingProps} {...heading} size={"xl"}>
              {heading.children}
            </Heading>

            {text && (
              <>
                <VerticalSpace size="16" />
                <span className="arc-HeroVideoBanner-text">{text}</span>
              </>
            )}

            {children && (
              <>
                <VerticalSpace size="32" />
                {children}
              </>
            )}
          </div>

          <div className="arc-HeroVideoBanner-video">
            {video && (
              <VideoPlayer {...video} isBorderRadius isSupportingTextHidden />
            )}
          </div>
        </div>
      </Surface>
    </div>
  );
};

export type HeroVideoBannerVideoProps = Omit<
  VideoPlayerProps,
  "isBorderRadius" | "isSupportingTextHidden"
>;

export type HeroVideoBannerHeadingProps = Omit<HeadingProps, "size" | "align">;

type HeroVideoBannerBaseType = "contained" | "uncontained";

type HeroVideoBannerType =
  | "contained"
  | "uncontained"
  | "light-brand-02"
  | "light-neutral-01"
  | "dark-brand-01";

const baseTypes: Record<HeroVideoBannerType, HeroVideoBannerBaseType> = {
  contained: "contained",
  uncontained: "uncontained",
  "light-brand-02": "contained",
  "light-neutral-01": "contained",
  "dark-brand-01": "contained",
};

const surfaceBackgrounds: Record<HeroVideoBannerType, SurfaceBackgroundColor> =
  {
    contained: "light-white",
    uncontained: "light-white",
    "light-brand-02": "light-brand-02",
    "light-neutral-01": "light-neutral-01",
    "dark-brand-01": "dark-brand-01",
  };

export interface HeroVideoBannerProps {
  /**
   * Heading content and configuration.
   */
  heading: HeroVideoBannerHeadingProps;
  /**
   * Optional label displayed above the heading.
   */
  label?: string;
  /**
   * Video player configuration and props.
   */
  video: HeroVideoBannerVideoProps;
  /**
   * Optional text content displayed below the heading.
   */
  text?: ReactNode;
  /**
   * Optional children rendered below the text (typically buttons or CTAs).
   */
  children?: ReactNode;
  /**
   * Color of the label text.
   */
  labelColor?: HeadingColor;
  /**
   * Layout type for the banner.
   * `"contained"` uses `light-white` surface. `"uncontained"` has no background.
   * `"light-brand-02"`, `"light-neutral-01"`, `"dark-brand-01"` use contained layout with the specified surface background.
   */
  type?: HeroVideoBannerType;
  /**
   * Content alignment. Only applies to uncontained type at L breakpoint and above.
   */
  alignment?: "center" | "start";
  /**
   * Extends the banner 64px beyond its container on both sides at XXL breakpoint (1440px and above). Only works with contained type.
   */
  extendBeyondContainer?: boolean;
}
