import React, { type ReactNode } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import {
  Surface,
  type SurfaceBackgroundColor,
  type SurfacePadding,
} from "../Surface";

/**
 * Use `Box` as a simple way to group bespoke content and interactive elements together.
 */
export const Box = ({
  children,
  borderWidth,
  elevationLevel,
  padding,
  isFullHeight = false,
  isBorderRadius = false,
  surface = "light-white",
  isSurfaceTransparent,
  ...props
}: BoxProps) => {
  return (
    <div
      className={classNames("arc-Box", {
        [`arc-Box--fullHeight`]: isFullHeight,
        [`arc-Box--borderRadius`]: isBorderRadius,
        [`arc-Box--borderThin`]: borderWidth === "thin",
        [`arc-Box--borderMedium`]: borderWidth === "medium",
        [`arc-Box--elevation1`]: elevationLevel === "1",
        [`arc-Box--elevation2`]: elevationLevel === "2",
      })}
      {...filterAttrs(props)}
    >
      <Surface
        padding={padding}
        background={surface}
        isTransparent={isSurfaceTransparent}
      >
        {children}
      </Surface>
    </div>
  );
};

export interface BoxProps {
  /**
   * Contents of the Box.
   */
  children: ReactNode;

  /**
   * Set Box to fill parent element.
   */
  isFullHeight?: boolean;

  /**
   * Add rounded corners to the box.
   */
  isBorderRadius?: boolean;

  /**
   * The border width of the box.
   */
  borderWidth?: "thin" | "medium";

  /**
   * Box shadow for the box.
   */
  elevationLevel?: "1" | "2";

  /**
   * Padding for the box.
   */
  padding?: SurfacePadding;

  /**
   * Background color for the box.
   */
  surface?: SurfaceBackgroundColor;

  /**
   * Determine if the background color is transparent.
   */
  isSurfaceTransparent?: boolean;
}
