import React, { type ReactNode, useContext } from "react";

import classNames from "classnames";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";

import { type ExtentableContainer } from "../../types/extendable-container";

import { SurfaceContext } from "../Surface";

import { Section } from "../Section";

import { Rule } from "../Rule";

import { VerticalSpace } from "../VerticalSpace";

/**
 * Use `SiteFooterV2` to display information at the bottom of a page.
 */
export const SiteFooterV2 = ({
  children,
  slogan,
  hideTopBorder = false,
  isExtended = false,
  ...props
}: SiteFooterV2Props) => {
  const { surface } = useContext(SurfaceContext);

  return (
    <footer
      className={classNames("arc-SiteFooterV2", {
        "arc-SiteFooterV2--onDarkSurface": surface === "dark",
        "arc-SiteFooterV2--extended": isExtended,
      })}
      {...filterAttrs(props)}
    >
      {!hideTopBorder && <Rule />}
      <VerticalSpace size="24" />
      <Section isExtended={isExtended}>
        {slogan && (
          <>
            <span className="arc-SiteFooterV2-slogan">{slogan}</span>
            <VerticalSpace size="32" />
          </>
        )}
        <div className="arc-SiteFooterV2-main-utility">{children}</div>
      </Section>
      <VerticalSpace size="24" />
    </footer>
  );
};

export interface SiteFooterV2Props extends ExtentableContainer {
  /**
   * Content of the SiteFooterV2. Must include SiteFooterV2Utility component and optional SiteFooterV2Main.
   */
  children: ReactNode;

  /**
   * Text that appears at the top of the footer. Can be the name of the site, a
   * brand slogan, or similar.
   */
  slogan?: string;

  /**
   * Hide the top border.
   */
  hideTopBorder?: boolean;
}
