import React, { useEffect, useRef, type KeyboardEvent } from "react";

import classNames from "classnames";

export const CarouselDotButton = ({
  visibleSlideIndex,
  scrollSnapIndex,
  focusIndex,
  onKeyDown,
  onClick,
}: CarouselDotButtonProps) => {
  const ref = useRef<HTMLButtonElement | null>(null);

  const isSelected = visibleSlideIndex === scrollSnapIndex;

  useEffect(() => {
    if (focusIndex === scrollSnapIndex) {
      ref.current?.focus();
    }
  }, [focusIndex, scrollSnapIndex]);

  return (
    <button
      ref={ref}
      tabIndex={scrollSnapIndex === 0 ? 0 : -1}
      className={classNames("arc-Carousel-dot", {
        "arc-Carousel-dot--selected": isSelected,
      })}
      onKeyDown={onKeyDown(scrollSnapIndex)}
      onClick={() => onClick(scrollSnapIndex)}
      aria-selected={isSelected}
      role="tab"
      aria-label={`Show slide ${scrollSnapIndex + 1}`}
    />
  );
};

interface CarouselDotButtonProps {
  /**
   * Keyboard event handler for the dot button.
   */
  onKeyDown: (
    scrollSnapIndex: number,
  ) => (e: KeyboardEvent<HTMLButtonElement>) => void;
  /**
   * Click handler for the dot button.
   */
  onClick: (scrollSnapIndex: number) => void;
  /**
   * Index of the currently visible slide.
   */
  visibleSlideIndex: number;
  /**
   * Index of the scroll snap point this button represents.
   */
  scrollSnapIndex: number;
  /**
   * Index of the dot button that should receive focus.
   */
  focusIndex?: number;
}
