import React, {
  type ReactNode,
  isValidElement,
  useEffect,
  useState,
} from "react";

import classNames from "classnames";
import * as Select from "@radix-ui/react-select";

import { filterAttrs } from "@arc-ui/helpers/filter-attrs";
import { getTextWidth } from "@arc-ui/helpers/get-text-width";

import { ThemeIcon } from "../ThemeIcon";
import { useThemeElement } from "../../hooks";
import { VisuallyHidden } from "../VisuallyHidden";

/**
 * Use `ContentSwitcherDropdown` tab control used to toggle between related views or content sections, without navigating away from the current page.
 */
export const ContentSwitcherDropdown = ({
  defaultValue,
  tabs,
  onValueChange,
  children,
  isInset = false,
  value,
  ariaLabel,
  isFluid = false,
  width,
  ...props
}: ContentSwitcherDropdownProps) => {
  const initialValue = defaultValue || tabs[0].value;

  const [themeElement, setThemeElement] = useThemeElement();

  const [uncontrolledValue, setUncontrolledValue] = useState<
    string | undefined
  >(initialValue);

  const [longestLabelWidth, setLongestLabelWidth] = useState<number>(236);

  // compute longest width client side
  useEffect(() => {
    if (tabs.length === 0) return;

    const longestLabel = tabs.reduce(
      (longest, current) =>
        current.label.length > longest.length ? current.label : longest,
      "",
    );

    setLongestLabelWidth(getTextWidth(longestLabel));
  }, [tabs]);

  const isControlled = typeof value !== "undefined";
  const selectValue = isControlled ? value : uncontrolledValue;

  const onValueChangeHandler = (value: string) => {
    onValueChange && onValueChange(value);
    setUncontrolledValue(value);
  };

  return (
    <>
      <Select.Root
        defaultValue={defaultValue}
        onValueChange={onValueChangeHandler}
        value={selectValue}
      >
        <span
          className={classNames(
            "arc-ContentSwitcherDropdown-selectTriggerWrapper",
            {
              "arc-ContentSwitcherDropdown-selectTriggerWrapper--isInset":
                isInset,
              "arc-ContentSwitcherDropdown-selectTriggerWrapper--isFluid":
                isFluid,
            },
          )}
          ref={setThemeElement}
          {...(!isFluid && {
            style: {
              width: width ? width : longestLabelWidth + 84,
            },
          })}
          {...filterAttrs(props)}
        >
          <Select.Trigger
            className="arc-ContentSwitcherDropdown-selectTrigger"
            aria-label={ariaLabel}
          >
            <Select.Value />
            <Select.Icon className="arc-ContentSwitcherDropdown-selectTriggerIcon">
              <ThemeIcon size={24} icon="selectTrigger" />
            </Select.Icon>
            <VisuallyHidden>
              . This is a content switcher. Use the dropdown to select a
              section. The content below will update based on your selection.
            </VisuallyHidden>
          </Select.Trigger>
        </span>

        <Select.Portal container={themeElement}>
          <Select.Content
            className="arc-ContentSwitcherDropdown-selectContent"
            sideOffset={8}
            position="popper"
          >
            <Select.ScrollUpButton />
            <Select.Viewport>
              {tabs.map((item, index) => (
                <Select.Item
                  value={item.value}
                  key={index}
                  className="arc-ContentSwitcherDropdown-selectItem"
                  id={`arc-content-switcher-dropdown-trigger-${item.value}`}
                >
                  <Select.ItemText>{item.label}</Select.ItemText>
                  <Select.ItemIndicator>
                    <ThemeIcon size={24} icon="selectIndicator" />
                  </Select.ItemIndicator>
                </Select.Item>
              ))}
            </Select.Viewport>
            <Select.ScrollDownButton />
          </Select.Content>
        </Select.Portal>
      </Select.Root>

      {React.Children.map(children, (child) => {
        if (!isValidElement<ContentSwitcherDropdownContentProps>(child)) {
          return null;
        }

        const isActive = child.props.value === selectValue;

        return (
          <div
            role="tabpanel"
            className="arc-ContentSwitcherDropdown-content"
            id={`arc-content-switcher-dropdown-content-${child.props.value}`}
            aria-labelledby={`arc-content-switcher-dropdown-trigger-${child.props.value}`}
            data-state={isActive ? "active" : "inactive"}
            tabIndex={-1}
            hidden={!isActive}
            {...filterAttrs(child.props)}
          >
            {child}
          </div>
        );
      })}
    </>
  );
};

export const ContentSwitcherDropdownContent = ({
  children,
}: ContentSwitcherDropdownContentProps) => {
  return <>{children}</>;
};

export interface ContentSwitcherDropdownContentProps {
  /**
   * Content to display
   */
  children: ReactNode;

  /**
   * This value links the `ContentSwitcherDropdownContent` with `ContentSwitcherDropdown` property `Tabs`
   */
  value: string;
}

export interface ContentSwitcherDropdownProps {
  /**
   * Render children
   */
  children?: ReactNode;

  /**
   * Default to an inital value of a tab. If this is not set default to first tab.
   */
  defaultValue?: string;

  /**
   * Event handler called when the value changes. This can only be active when child elements are not present
   */
  onValueChange?: (value: string) => void;

  /**
   * Determine what tabs to render. They need both a `value` and `label` prop
   */
  tabs: { value: string; label: string }[];

  /**
   * Determines if the `ContentSwitcherDropdown` should be inset within the content panel.
   */
  isInset?: boolean;

  /**
   * value for the `ContentSwitcherDropdown`. Passing a value makes the Select a controlled component.
   */
  value?: string;

  /**
   * Aria label for the `ContentSwitcherDropdown`.
   */
  ariaLabel?: string;

  /**
   * Sets the `ContentSwitcherDropdown` to 100% width.
   */
  isFluid?: boolean;

  /**
   * Sets the width of the `ContentSwitcherDropdown`.
   */
  width?: string;
}
